def test_runner_enforces_wall_clock(env, tmp_path):
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    (run_dir / "prompt.md").write_text("x")
    (run_dir / "run.json").write_text(json.dumps({"argv": ["sleep", "60"], "env": {}, "cwd": str(tmp_path),
                                                  "timeout_s": 1, "provider": "fake"}))
    t0 = time.time()
    subprocess.run([sys.executable, "-m", "ttp.runner", str(run_dir)], cwd=str(RUNTIME),
                   env={**os.environ, "PYTHONPATH": str(RUNTIME)}, timeout=120)
    info = json.loads((run_dir / "exit.json").read_text())
    assert info["stopped"] == "timeout" and time.time() - t0 < 60


def _runner_dir(tmp_path, argv, timeout_s=600):
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    (run_dir / "prompt.md").write_text("x")
    (run_dir / "run.json").write_text(json.dumps({"argv": argv, "env": {}, "cwd": str(tmp_path),
                                                  "timeout_s": timeout_s, "provider": "fake"}))
    return run_dir


def _pid_gone(pid: int) -> bool:
    """Process pid has ended (a zombie waiting for its new parent to reap it counts as ended)."""
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return True
    try:
        return pathlib.Path(f"/proc/{pid}/stat").read_text().rsplit(")", 1)[1].split()[0] == "Z"
    except OSError:
        state = subprocess.run(["ps", "-o", "stat=", "-p", str(pid)], capture_output=True, text=True).stdout
        return not state.strip() or state.strip().startswith("Z")



def _load_scaled(seconds: float) -> float:
    """A subprocess timeout for a loaded host: `seconds` times TTP_TEST_TIMEOUT_SCALE, else times the
    one-minute load per core when that is over 1 (at most 8x). A busy host is slow, not broken."""
    try:
        factor = float(os.environ.get("TTP_TEST_TIMEOUT_SCALE") or 0)
    except ValueError:
        factor = 0
    if factor <= 0:
        try:
            factor = os.getloadavg()[0] / (os.cpu_count() or 1)
        except OSError:
            factor = 1
    return seconds * min(max(factor, 1.0), 8.0)

def _wait_for(pred, timeout=30.0) -> bool:
    deadline = time.time() + timeout
    while time.time() < deadline:
        if pred():
            return True
        time.sleep(0.05)
    return pred()


def test_runner_never_launches_an_agent_whose_stop_came_first(env, tmp_path):
    # A run stopped right after start_run (a cancel, or a test touching STOP) must not start its agent.
    launched = tmp_path / "launched"
    run_dir = _runner_dir(tmp_path, ["sh", "-c", f"touch {launched}; sleep 60"])
    (run_dir / "STOP").write_text("cancel")
    subprocess.run([sys.executable, "-m", "ttp.runner", str(run_dir)], cwd=str(RUNTIME),
                   env={**os.environ, "PYTHONPATH": str(RUNTIME)}, timeout=60)
    info = json.loads((run_dir / "exit.json").read_text())
    assert info["launched"] is False and info["stopped"] == "stopped"
    assert not launched.exists() and not (run_dir / "child.pid").exists()


def test_runner_ends_its_agent_when_the_run_dir_is_deleted(env, tmp_path):
    # Nobody can read a deleted run's output or hand-off: its agent must not run on unattended, and the
    # runner must not create the directory again for its exit record.
    pid_file = tmp_path / "agent.pid"
    run_dir = _runner_dir(tmp_path, ["sh", "-c", f"echo $$ > {pid_file}; exec sleep 120"])
    proc = subprocess.Popen([sys.executable, "-m", "ttp.runner", str(run_dir)], cwd=str(RUNTIME),
                            env={**os.environ, "PYTHONPATH": str(RUNTIME)})
    try:
        assert _wait_for(lambda: pid_file.exists() and pid_file.read_text().strip())
        agent = int(pid_file.read_text())
        # The runner may still be writing its launch files (child.pid, the first lease) into the dir.
        assert _wait_for(lambda: not shutil.rmtree(run_dir, ignore_errors=True) and not run_dir.exists())
        proc.wait(timeout=30)
        assert _wait_for(lambda: _pid_gone(agent), 10)
        assert not run_dir.exists()
    finally:
        if proc.poll() is None:
            proc.kill()
            proc.wait()


@pytest.mark.parametrize("pdeathsig", [True, False], ids=["pdeathsig", "watchdog"])
def test_agent_ends_when_its_runner_dies(env, tmp_path, pdeathsig):
    # A runner killed outright (OOM killer, kill -9) must not leave its agent or the agent's tools
    # running unattended: a watchdog ends the whole process group, also where the kernel already
    # signals the agent itself (PR_SET_PDEATHSIG, which reaches neither the tools nor a KILL).
    if pdeathsig and not sys.platform.startswith("linux"):
        pytest.skip("PR_SET_PDEATHSIG is Linux only")
    pid_file, tool_file = tmp_path / "agent.pid", tmp_path / "tool.pid"
    script = f"sleep 120 & echo $! > {tool_file}; echo $$ > {pid_file}; wait"
    run_dir = _runner_dir(tmp_path, ["sh", "-c", script])
    code = ("import sys; from pathlib import Path; from ttp import runner; "
            f"runner.PDEATHSIG = {pdeathsig}; sys.exit(runner.supervise(Path(sys.argv[1])))")
    proc = subprocess.Popen([sys.executable, "-c", code, str(run_dir)], cwd=str(RUNTIME),
                            env={**os.environ, "PYTHONPATH": str(RUNTIME)})
    agent = tool = None
    try:
        assert _wait_for(lambda: pid_file.exists() and pid_file.read_text().strip()
                         and tool_file.exists() and tool_file.read_text().strip())
        agent, tool = int(pid_file.read_text()), int(tool_file.read_text())
        proc.kill()
        proc.wait()
        assert _wait_for(lambda: _pid_gone(agent), 15), "the agent outlived its runner"
        assert _wait_for(lambda: _pid_gone(tool), 15), "the agent's tool outlived its runner"
    finally:
        if proc.poll() is None:
            proc.kill()
            proc.wait()
        for pid in (agent, tool):
            with contextlib.suppress(OSError, TypeError):
                os.kill(pid, signal.SIGKILL)


def test_runner_watchdog_leaves_the_group_alone_after_a_normal_end(env, tmp_path):
    # A run that ends normally tells its watchdog so: nothing of the group is signalled afterwards.
    tool_file = tmp_path / "tool.pid"
    run_dir = _runner_dir(tmp_path, ["sh", "-c", f"sleep 120 & echo $! > {tool_file}"])
    code = ("import sys; from pathlib import Path; from ttp import runner; "
            "runner.PDEATHSIG = False; sys.exit(runner.supervise(Path(sys.argv[1])))")
    tool = None
    try:
        assert subprocess.run([sys.executable, "-c", code, str(run_dir)], cwd=str(RUNTIME), timeout=60,
                              env={**os.environ, "PYTHONPATH": str(RUNTIME)}).returncode == 0
        tool = int(tool_file.read_text())
        time.sleep(1)
        assert not _pid_gone(tool)
    finally:
        with contextlib.suppress(OSError, TypeError):
            os.kill(tool, signal.SIGKILL)


def _unused_port() -> int:
    """A port the OS just handed out and nothing listens on."""
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


def _start_web(p) -> int:
    """Serve p's web app in a thread (as its daemon does) and return its port once bound.

    The server binds port 0 before its thread starts and keeps that socket: a port picked ahead of
    time and freed again can be taken by a parallel pytest run before serve binds it, and the test
    then talks to that run's server."""
    from ttp import web

    class Stub:
        pass
    stub = Stub()
    stub.p = p
    httpd = web.bind(stub, 0)
    port = httpd.server_address[1]
    p.set_config("web.port", port)
    threading.Thread(target=web.serve, args=(stub, httpd), daemon=True).start()
    return port


@needs_sockets
def test_web_servers_started_together_never_share_a_port(env):
    """Two web apps started at once each hold their own port and answer with their own project."""
    from ttp import web
    from ttp.cli import bootstrap
    a = make(env)
    repo2 = env["tmp"] / "repo2"
    subprocess.run(["git", "clone", "-q", str(env["repo"]), str(repo2)], check=True)
    b = bootstrap(repo2, "second", "Another project.", "fake")
    ports = [_start_web(a), _start_web(b)]
    assert ports[0] != ports[1]
    for p, port in zip((a, b), ports):
        req = urllib.request.Request(f"http://127.0.0.1:{port}/api/state", headers={"X-TTP-Token": web.token(p)})
        assert json.loads(urllib.request.urlopen(req, timeout=5).read())["project"]["name"] == p.name


@needs_sockets
def test_web_api_requires_the_token(env):
    p = make(env)
    from ttp import web
    port = _start_web(p)
    base = f"http://127.0.0.1:{port}"
    for _ in range(50):
        try:
            urllib.request.urlopen(base + "/", timeout=1)
            break
        except OSError:
            time.sleep(0.1)
    with pytest.raises(urllib.error.HTTPError) as e:
        urllib.request.urlopen(base + "/api/state", timeout=5)
    assert e.value.code == 401
    req = urllib.request.Request(base + "/api/state", headers={"X-TTP-Token": web.token(p)})
    data = json.loads(urllib.request.urlopen(req, timeout=5).read())
    assert data["project"]["name"] == "demo"


def test_broken_config_keeps_the_last_good_one(env):
    p = make(env)
    p.set_config("budget.daily_usd", 42)
    assert p.config()["budget"]["daily_usd"] == 42
    p.config_path.write_text("{ not json")
    assert p.config()["budget"]["daily_usd"] == 42


def test_missing_config_keeps_the_last_good_routing(env):
    """A project.json gone for a moment must not move the project onto the default models."""
    from ttp.project import Project
    p = make(env)
    p.set_config("providers.fake.tiers.standard.model", "pinned-model")
    assert p.config()["providers"]["fake"]["tiers"]["standard"]["model"] == "pinned-model"
    saved = p.config_path.read_text()
    p.config_path.unlink()
    assert p.config()["providers"]["fake"]["tiers"]["standard"]["model"] == "pinned-model"
    assert p.config_status == "fallback"
    (p.state / "project.last-good.json").unlink()
    assert p.config()["providers"]["fake"]["tiers"]["standard"]["model"] == "pinned-model", "kept in memory"
    fresh = Project(p.base)
    assert fresh.config()["core_provider"] == "claude" and fresh.config_status == "unavailable"
    with pytest.raises(RuntimeError):
        fresh.set_config("budget.daily_usd", 5)   # would write a project.json of that key alone
    assert not p.config_path.exists()
    p.config_path.write_text(saved)
    assert fresh.config()["providers"]["fake"]["tiers"]["standard"]["model"] == "pinned-model"
    assert fresh.config_status == "ok"


def test_malformed_config_uses_the_last_good_copy(env):
    from ttp.project import Project
    p = make(env)
    p.set_config("core_provider", "fake")
    p.config()
    for broken in ("{ not json", "[]", "null"):
        p.config_path.write_text(broken)
        fresh = Project(p.base)   # nothing in memory: the copy on disk decides
        assert fresh.config()["core_provider"] == "fake" and fresh.config_status == "fallback", broken


def test_unreadable_config_starts_no_model_work_and_alerts_once(env, monkeypatch):
    """Neither project.json nor a last good copy: no coordinator turn or worker run starts on the
    defaults; one alert says so and clears once the file reads again."""
    from ttp import alerts
    from ttp.daemon import Daemon
    p = make(env)
    saved = p.config_path.read_text()
    p.config_path.write_text("{ broken")
    (p.state / "project.last-good.json").unlink(missing_ok=True)
    p.db.add_task("user work", "s", kind="work", tier="light", origin="user")
    p.db.post("in", "hello", chat="web")
    d = Daemon(p.base)
    assert d.cfg_status == "unavailable"
    started = []
    monkeypatch.setattr(d, "start_run", lambda *a, **k: started.append(a[0]) or 0)
    for _ in range(2):
        d._last_cfg = 0
        d.tick()
    assert started == [], "no turn or run routes on the defaults"
    eps = p.db.q("SELECT * FROM alerts WHERE key='config' AND cleared IS NULL")
    assert len(eps) == 1 and p.db.one("SELECT COUNT(*) n FROM messages WHERE ref='config'")["n"] == 1
    assert alerts.active(p.db, "config", eps[0]["raised"], time.time())
    with pytest.raises(RuntimeError):
        Daemon.start_run(d, "worker", "x", "fake", "light", str(p.root))
    p.config_path.write_text(saved)
    d._load_config()
    d.sweep_alerts()
    assert d.cfg_status == "ok"
    assert p.db.one("SELECT cleared FROM alerts WHERE key='config'")["cleared"]
    assert p.db.one("SELECT id FROM messages WHERE ref='config' AND kind='resolved'")


@pytest.mark.parametrize("var", ["TTP_RUN_ID", "TTP_RUN_DIR"])
def test_config_refuses_user_only_keys_inside_a_run(env, capsys, monkeypatch, var):
    """A run can be steered by text it reads, so `ttp config` inside one refuses every setting only
    the user may change (coordinator.NEEDS_USER), directly, through a parent key or account-wide.
    Reading still works, other keys still set, and turning a SAFE_WHEN_OFF switch off is allowed."""
    from ttp import cli
    from ttp.coordinator import MERGE_KEY, NEEDS_USER, SAFE_WHEN_OFF
    p = make(env)
    p.set_config("delivery.code_tasks_may_push", True)
    p.set_config("delivery.mirror_remotes", ["backup"])
    before = p.raw_config()
    monkeypatch.setenv(var, "7")
    refused = [["config", "demo", k, json.dumps(["o/r"] if k == MERGE_KEY else 9)] for k in NEEDS_USER]
    refused += [["config", "demo", "budget", json.dumps({"daily_usd": 999})],          # parent key
                ["config", "demo", "delivery", json.dumps({})],                        # wipes a user-only key
                ["config", "demo", MERGE_KEY, "o/r"],                                   # plain string
                ["config", "demo", "delivery.mirror_remotes", json.dumps(["other"])],  # not the off direction
                ["config", "--account", "budget.global_daily_usd", "5000"],
                ["config", "--account", "budget.global_daily_usd", ""]]               # removes the cap
    for argv in refused:
        with pytest.raises(SystemExit) as e:
            cli.main(argv)
        assert e.value.code == 2, argv
        assert "only the user may change" in capsys.readouterr().err, argv
    assert p.raw_config() == before
    from ttp.project import load_account_settings
    assert "global_daily_usd" not in load_account_settings().get("budget", {})
    cli.main(["config", "demo", "budget.daily_usd"])                     # reading works
    cli.main(["config", "--account", "budget.global_daily_usd"])
    capsys.readouterr()
    cli.main(["config", "demo", "budget.max_pace_hold_s", "60"])         # not user-only
    cli.main(["config", "demo", "budget", json.dumps({**before.get("budget", {}), "max_pace_hold_s": 90})])
    for k in SAFE_WHEN_OFF:                                              # the safe direction
        cli.main(["config", "demo", k, json.dumps(False if k == "delivery.code_tasks_may_push" else [])])
    cfg = p.raw_config()
    assert cfg["budget"]["max_pace_hold_s"] == 90 and cfg["delivery"]["code_tasks_may_push"] is False
    assert cfg["delivery"]["mirror_remotes"] == []
    monkeypatch.delenv(var)
    cli.main(["config", "demo", "budget.daily_usd", "12"])               # outside a run: the user's own
    assert p.raw_config()["budget"]["daily_usd"] == 12


def test_config_defaults_to_the_runs_project_and_prints_effective_sections(env, capsys, monkeypatch):
    """Inside a run `ttp config KEY` reads the run's project (as `ttp stats` does), and a section or no
    key prints the effective config, defaults included."""
    from ttp import cli
    from ttp.project import DEFAULT_CONFIG
    p = make(env)
    monkeypatch.setenv("TTP_PROJECT", str(p.root))
    monkeypatch.setenv("TTP_RUN_ID", "7")
    cli.main(["config", "budget.split_reread_tokens"])
    assert json.loads(capsys.readouterr().out) == DEFAULT_CONFIG["budget"]["split_reread_tokens"]
    monkeypatch.delenv("TTP_RUN_ID")
    cli.main(["config", "demo", "budget"])
    budget = json.loads(capsys.readouterr().out)
    for k in ("split_reread_tokens", "bash_output_max_chars", "compact_window_tokens"):
        assert budget[k] == DEFAULT_CONFIG["budget"][k], k
    cli.main(["config", "demo"])
    assert "budget" in json.loads(capsys.readouterr().out)


def test_unreadable_config_refuses_settings_cleanly(env, capsys, monkeypatch):
    """With no project.json and no last good copy, `ttp config` set says why instead of a traceback,
    and the web app still opens (on a port it does not save)."""
    from ttp import cli, web
    p = make(env)
    p.config_path.unlink()
    (p.state / "project.last-good.json").unlink(missing_ok=True)
    with pytest.raises(SystemExit) as e:
        cli.main(["config", "demo", "budget.daily_usd", "5"])
    assert e.value.code == 2 and "no last good copy" in capsys.readouterr().err
    assert not p.config_path.exists()

    class Stop(Exception):
        pass

    def no_server(*a, **k):
        raise Stop()
    monkeypatch.setattr(web, "ThreadingHTTPServer", no_server)
    monkeypatch.setattr(web, "free_port", lambda start=0: 18700)   # no real socket: sandboxes may refuse one
    with pytest.raises(Stop):   # got past saving the port
        web.serve(type("D", (), {"p": p})())
    assert not p.config_path.exists()


def test_task_provider_override_routes_on_the_last_good_config(env, monkeypatch):
    """A task that names its provider still takes that provider's tier from the project's routing,
    the last good one while project.json is missing."""
    from ttp import daemon as dm
    p = make(env)
    _no_events(p)
    p.set_config("providers.fake.tiers.standard.model", "pinned-model")
    d = dm.Daemon(p.base)
    p.config_path.unlink()
    d._last_cfg = 0
    d._load_config()
    assert d.cfg_status == "fallback"
    tid = p.db.add_task("override", "s", kind="work", tier="standard", provider="fake", origin="user")
    seen = []

    class Stop(Exception):
        pass

    class Prov:
        def use(self, model, prices):
            seen.append(model)
            raise Stop()
    monkeypatch.setattr(dm, "get_provider", lambda name: Prov())
    d.dispatch()
    assert seen == ["pinned-model"], seen
    assert p.db.task(tid)["status"] != "running"


def test_slack_routing(env):
    from ttp.slack import projects_in_dm, route
    assert route({"text": "demo: hi", "ts": "1"}, "demo", set(), ["demo", "other"]) == "hi"
    assert route({"text": "other: hi", "ts": "1"}, "demo", set(), ["demo", "other"]) is None
    assert route({"text": "hi", "ts": "2", "thread_ts": "9"}, "demo", {"9"}, ["demo", "other"]) == "hi"
    assert route({"text": "hi", "ts": "3"}, "demo", set(), ["demo"]) == "hi"
    assert projects_in_dm([{"bot_id": "B", "text": "[demo] x"}, {"text": "[fake] y"}]) == ["demo"]


class FakeSlackHTTP:
    """Stands in for the Slack Web API at the urlopen level. `fail(text)` decides how a
    chat.postMessage of `text` fails: None (delivered), an error code, an HTTP status or 'net'."""

    def __init__(self, fail):
        self.fail = fail
        self.delivered: list[str] = []

    def __call__(self, req, timeout=None):
        import io
        import urllib.parse
        method = req.full_url.rsplit("/", 1)[-1]
        params = urllib.parse.parse_qs(req.data.decode(), keep_blank_values=True)
        if method == "conversations.open":
            body = {"ok": True, "channel": {"id": "D1"}}
        else:
            text = params["text"][0]
            why = self.fail(text)
            if why == "net":
                raise urllib.error.URLError("connection refused")
            if isinstance(why, int):
                raise urllib.error.HTTPError(req.full_url, why, "err", {"Retry-After": "0"}, None)
            if why:
                body = {"ok": False, "error": why}
            else:
                self.delivered.append(text)
                body = {"ok": True, "ts": f"{len(self.delivered)}.0"}
        return io.BytesIO(json.dumps(body).encode())


def slack_daemon(env, monkeypatch, fake):
    import ttp.slack
    from ttp.daemon import Daemon
    from ttp.slack import Slack
    p = make(env)
    monkeypatch.setattr(ttp.slack.urllib.request, "urlopen", fake)
    monkeypatch.setattr(ttp.slack.time, "sleep", lambda s: None)
    d = Daemon(p.base)
    d._slack = Slack("test-bot-token", user_id="U1")
    d.slack = lambda: d._slack
    return p, d


def test_slack_outbound_skips_a_message_slack_keeps_rejecting(env, monkeypatch):
    fake = FakeSlackHTTP(lambda text: "no_text" if not text.strip() else None)
    p, d = slack_daemon(env, monkeypatch, fake)
    p.db.post("in", "hi", chat="slack", channel="slack", kind="user", ref="9.0")
    bad = p.db.post("out", "", chat="slack", ref="9.0")          # a thread reply with no text
    good = p.db.post("out", "second", chat="slack", ref="9.0")
    d.deliver_outbound()
    d.deliver_outbound()
    assert fake.delivered == [] and int(p.db.kv("slack_last_out", 0)) < bad   # retried before skipping
    for _ in range(8):
        d.deliver_outbound()
    assert fake.delivered == ["second"]
    assert int(p.db.kv("slack_last_out", 0)) == good
    assert f"skipped message {bad}" in (p.logs / "daemon.log").read_text()


@pytest.mark.parametrize("why", ["net", 500, 503, 429, "invalid_auth", "token_revoked", "ratelimited"])
def test_slack_outbound_never_skips_on_outages(env, monkeypatch, why):
    down = {"on": True}
    fake = FakeSlackHTTP(lambda text: why if down["on"] else None)
    p, d = slack_daemon(env, monkeypatch, fake)
    first = p.db.post("out", "first", kind="alert", severity="high")
    second = p.db.post("out", "second", kind="alert", severity="high")
    for _ in range(10):
        d.deliver_outbound()
    assert fake.delivered == [] and int(p.db.kv("slack_last_out", 0)) < first
    down["on"] = False
    d.deliver_outbound()
    assert fake.delivered == ["[demo] first", "[demo] second"]
    assert int(p.db.kv("slack_last_out", 0)) == second


def test_logged_out_provider_is_detected_not_retried_as_failure(env, tmp_path):
    from ttp.providers import get_provider
    out = tmp_path / "o.jsonl"
    out.write_text("\n".join(json.dumps(x) for x in [
        {"type": "assistant", "error": "authentication_failed", "message": {"content": [
            {"type": "text", "text": "Failed to authenticate: OAuth session expired and could not be refreshed"}]}},
        {"type": "result", "subtype": "success", "is_error": True, "total_cost_usd": 0,
         "result": "Failed to authenticate: OAuth session expired", "usage": {}},
    ]) + "\n")
    u = get_provider("claude").parse(out)
    assert u.auth_failed and not u.limited


def test_killed_run_discussing_a_401_is_not_logged_out(env, tmp_path):
    from ttp.providers import get_provider
