def test_claude_workers_get_a_lean_context_but_keep_plugin_skills(env):
    from ttp.providers import get_provider
    build = get_provider("claude").build
    worker, _ = build(role="worker", model="opus", effort="low", cwd=".", budget_usd=None, read_only=False,
                      schema=None, restrictions={"no_internet": True})
    settings = json.loads(worker[worker.index("--settings") + 1])
    skills = settings["skillOverrides"]
    assert {"dataviz", "workflow-authoring", "loop", "schedule", "security-review"} <= set(skills)
    assert set(skills.values()) == {"name-only"}, "'off' adds tokens; bundled skills stay callable by name"
    assert "disableBundledSkills" not in settings
    assert settings["autoMemoryEnabled"] is False
    assert worker.count("--disallowedTools") == 1, "a second flag would hide part of the deny list"
    i = worker.index("--disallowedTools") + 1
    denied = worker[i:worker.index("--settings", i)]
    assert {"Workflow", "ScheduleWakeup", "CronCreate", "CronDelete", "CronList", "RemoteTrigger",
            "PushNotification", "DesignSync", "NotebookEdit", "EnterWorktree", "ExitWorktree", "ListAgents",
            "ReportFindings", "Task", "Agent", "SendMessage", "WebFetch", "WebSearch"} == set(denied)
    # The tools workers do use stay, ToolSearch included (it loads deferred and MCP tools).
    assert not {"Bash", "Read", "Edit", "Write", "Skill", "ToolSearch", "Monitor", "TaskStop"} & set(denied)
    online, _ = build(role="worker", model="opus", effort="low", cwd=".", budget_usd=None, read_only=False,
                      schema=None, restrictions={})
    assert "WebFetch" not in online and "Workflow" in online
    # Plugin-dir skills are namespaced by their plugin and never overridden.
    argv = online + get_provider("claude").plugin_args(["/p/plugin"])
    assert all(":" not in name for name in skills) and "--plugin-dir" in argv
    turn, _ = build(role="coordinator", model="opus", effort="low", cwd=".", budget_usd=1.0, read_only=True,
                    schema=None, restrictions={})
    assert "Workflow" not in turn and "skillOverrides" not in " ".join(turn)


def _fake_venv(path, python=True):
    (path / "bin").mkdir(parents=True)
    (path / "pyvenv.cfg").write_text("home = /usr/bin\n")
    if python:
        (path / "bin" / "python").write_text("")
    return path


def test_workers_in_a_fresh_worktree_reuse_the_project_venv(env):
    p = make(env)
    from ttp import worktree
    from ttp.daemon import Daemon
    from ttp.prompts import worker_task
    d = Daemon(p.base)
    tid = p.db.add_task("build it", "s", kind="code", tier="light", origin="user")
    cwd, _ = d._workdir_for(p.db.task(tid))

    def run(role="worker", where=cwd):
        rid = d.start_run(role, "go", "claude", "light", where, task=p.db.task(tid), read_only=role == "coordinator")
        (p.runs / str(rid) / "STOP").touch()
        return json.loads((p.runs / str(rid) / "run.json").read_text())["env"]

    # No venv anywhere: the run starts as before and the prompt says nothing.
    assert "VIRTUAL_ENV" not in run() and "python venv" not in worker_task(p, p.db.task(tid), cwd, None)
    venv = _fake_venv(p.root / ".venv")
    e = run()
    assert e["VIRTUAL_ENV"] == str(venv.resolve())
    assert e["PATH"].split(":")[:2] == [str(p.harness / "bin"), str(venv.resolve() / "bin")], "ttp must stay first"
    assert run("reviewer", str(p.root))["VIRTUAL_ENV"] == str(venv.resolve())
    assert f"python venv: {venv.resolve()}" in worker_task(p, p.db.task(tid), cwd, None)
    assert "VIRTUAL_ENV" not in run("coordinator", str(p.base))
    # A worktree with a venv of its own keeps it.
    own = _fake_venv(pathlib.Path(cwd) / "venv")
    assert "VIRTUAL_ENV" not in run() and "python venv" not in worker_task(p, p.db.task(tid), cwd, None)
    import shutil
    shutil.rmtree(own)
    # A venv whose interpreter is gone is skipped; a configured path wins; "" turns it off.
    (venv / "bin" / "python").unlink()
    assert worktree.project_venv(p, cwd) is None
    other = _fake_venv(p.root / "envs" / "py")
    p.set_config("worktree.venv", "envs/py")
    d.cfg = p.config()
    assert run()["VIRTUAL_ENV"] == str(other.resolve())
    p.set_config("worktree.venv", str(other))
    assert worktree.project_venv(p, cwd) == other.resolve()
    p.set_config("worktree.venv", "")
    assert "VIRTUAL_ENV" not in run()


def test_a_new_worktree_links_the_checkouts_ignored_venv_and_removing_it_keeps_the_target(env):
    p = make(env)
    from ttp import worktree
    ident = ("-c", "user.name=t", "-c", "user.email=t@t")
    (p.root / ".gitignore").write_text(".venv/\nscratch/\n")
    _git_out(p.root, "add", ".gitignore")
    _git_out(p.root, *ident, "commit", "-qm", "ignore the venv")

    def task(title):
        path, _ = worktree.ensure(p, p.db.task(p.db.add_task(title, "s", kind="code", tier="light", origin="user")))
        return path
    # No venv in the checkout: nothing is linked.
    bare = task("bare")
    assert not os.path.lexists(bare / ".venv")
    venv = _fake_venv(p.root / ".venv")
    # The checkout's ignored .venv is linked into a new worktree. `.venv/` matches no symlink, so the link
    # goes into info/exclude: the worktree stays clean and `git add -A` does not commit it.
    path = task("linked")
    assert (path / ".venv").is_symlink() and (path / ".venv").resolve() == venv.resolve()
    assert (path / ".venv" / "bin" / "python").exists()
    assert _git_out(path, "status", "--porcelain") == ""
    _git_out(path, "add", "-A")
    assert _git_out(path, "diff", "--cached", "--name-only") == ""
    assert worktree.keep_reason(path) is None
    # Existing paths are left alone; tracked or not-ignored entries and paths outside the root are never linked.
    (p.root / "scratch").mkdir()
    (p.root / "data").mkdir()
    (p.root / "tracked.txt").write_text("v1")
    _git_out(p.root, "add", "tracked.txt")
    _git_out(p.root, *ident, "commit", "-qm", "tracked")
    p.set_config("worktree.link_paths", [".venv", "scratch", "data", "tracked.txt", "../outside", "/tmp"])
    own = task("own")
    assert sorted(x.name for x in own.iterdir() if x.is_symlink()) == [".venv", "scratch"]
    (own / "scratch").unlink()
    (own / "scratch").mkdir()
    (own / "scratch" / "mine").write_text("keep")
    (own / ".venv").unlink()
    _fake_venv(own / ".venv")
    assert worktree.link_paths(p, own) == []
    assert not (own / ".venv").is_symlink() and (own / "scratch" / "mine").read_text() == "keep"
    assert (own / "tracked.txt").read_text() == "v1" and not (own / "tracked.txt").is_symlink()
    p.set_config("worktree.link_paths", [])
    assert not os.path.lexists(task("off") / ".venv")
    # Removing a worktree, or clearing its caches, deletes the link and never the venv it points to.
    tid = int(path.name[1:])
    worktree.remove(p, tid)
    assert not os.path.lexists(path) and (venv / "pyvenv.cfg").is_file() and (venv / "bin" / "python").is_file()
    p.set_config("worktree.link_paths", [".venv"])
    again = task("again")
    assert (again / ".venv").is_symlink()
    assert ".venv" in worktree.clear_caches(again)
    assert not os.path.lexists(again / ".venv") and (venv / "pyvenv.cfg").is_file()


def test_every_worktree_of_the_project_gets_the_venv_link_a_review_one_too(env, monkeypatch, tmp_path):
    """A worktree a reviewer works in, or made itself, gets the same .venv link as a code task's, so
    push checks like `.venv/bin/python -m pytest` run there; none without a project .venv, and the main
    checkout or another repository's worktree is left alone."""
    p = make(env)
    from ttp import cli, worktree
    (p.root / ".gitignore").write_text(".venv/\n")
    _git_out(p.root, "add", ".gitignore")
    _git_out(p.root, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "ignore the venv")

    def review_worktree(name):
        path = p.worktrees / name
        p.worktrees.mkdir(parents=True, exist_ok=True)
        _git_out(p.root, "worktree", "add", "-q", "--detach", str(path), "HEAD")
        return path
    # No venv in the project: nothing is linked.
    bare = review_worktree("r1")
    assert worktree.prepare(p, bare) == [] and not os.path.lexists(bare / ".venv")
    venv = _fake_venv(p.root / ".venv")
    rev = review_worktree("r2")
    assert worktree.prepare(p, rev) == [".venv"]
    assert (rev / ".venv").resolve() == venv.resolve() and _git_out(rev, "status", "--porcelain") == ""
    assert worktree.prepare(p, rev) == [], "a second call finds the link in place"
    assert worktree.prepare(p, p.root) == [] and not (p.root / ".venv").is_symlink()
    other = tmp_path / "other"
    subprocess.run(["git", "init", "-q", str(other)], check=True)
    _git_out(other, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "x")
    _git_out(other, "worktree", "add", "-q", "--detach", str(tmp_path / "other-wt"), "HEAD")
    assert worktree.prepare(p, tmp_path / "other-wt") == [] and not os.path.lexists(tmp_path / "other-wt" / ".venv")
    # `ttp checks` in a worktree a reviewer made itself: the venv check runs.
    p.set_config("delivery.push_checks", ["test -x .venv/bin/python"])
    (venv / "bin" / "python").chmod(0o755)
    made = review_worktree("r3")
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    monkeypatch.setenv("TTP_RUN_DIR", str(tmp_path))
    monkeypatch.chdir(made)
    cli.main(["checks", "--fresh"])
    assert (made / ".venv").is_symlink() and "test -x .venv/bin/python" in (tmp_path / "checks.log").read_text()


def test_ttp_in_a_run_ignores_a_broken_project_venv_python(env):
    """The venv's bin sits right after the harness bin on a run's PATH: `ttp` must still run under
    the daemon's interpreter, not whatever `python3` the venv has."""
    p = make(env)
    from ttp import __version__
    from ttp.daemon import Daemon
    venv = _fake_venv(p.root / ".venv")
    for name in ("python3", "python"):
        (venv / "bin" / name).write_text("#!/bin/sh\necho broken venv python >&2\nexit 1\n")
        (venv / "bin" / name).chmod(0o755)
    d = Daemon(p.base)
    tid = p.db.add_task("build it", "s", kind="code", tier="light", origin="user")
    cwd, _ = d._workdir_for(p.db.task(tid))
    rid = d.start_run("worker", "go", "claude", "light", cwd, task=p.db.task(tid))
    (p.runs / str(rid) / "STOP").touch()
    run_env = json.loads((p.runs / str(rid) / "run.json").read_text())["env"]
    assert run_env["VIRTUAL_ENV"] == str(venv.resolve())
    r = subprocess.run(["ttp", "--version"], env=run_env, cwd=cwd, capture_output=True, text=True, timeout=60)
    assert r.returncode == 0 and __version__ in r.stdout + r.stderr, r.stderr
    # Outside a run (no TTP_PYTHON, or a stale one) the launcher still falls back to python3.
    for extra in ({}, {"TTP_PYTHON": str(p.root / "gone" / "python3")}):
        plain = {k: v for k, v in run_env.items() if k not in ("TTP_PYTHON", "VIRTUAL_ENV")}
        plain["PATH"] = run_env["PATH"].replace(str(venv.resolve() / "bin") + ":", "")
        r = subprocess.run([str(p.harness / "bin" / "ttp"), "--version"], env={**plain, **extra}, cwd=cwd,
                           capture_output=True, text=True, timeout=60)
        assert r.returncode == 0 and __version__ in r.stdout + r.stderr, r.stderr


