def _review_due(p, last_run=None):
    p.db.x("UPDATE schedules SET last_run=?, next_run=? WHERE name='daily-review'", (last_run, time.time() - 1))


def _review_done(p, tid, ended):
    p.db.update_task(tid, status="done")
    p.db.x("INSERT INTO runs(task,role,provider,started,ended,status) VALUES(?,?,?,?,?,?)",
           (tid, "worker", "fake", ended - 300, ended, "ok"))


def _reviews(p):
    return [r["id"] for r in p.db.q("SELECT id FROM tasks WHERE origin='schedule' AND labels=? ORDER BY id",
                                    (json.dumps(["daily-review"]),))]


@pytest.mark.parametrize("clock_at", ["00:10", "04:01", "12:00", "23:50"])
def test_a_daily_review_done_on_unchanged_evidence_is_not_repeated_within_the_debounce(env, monkeypatch, host_tz,
                                                                                       clock_at):
    # The wall clock is pinned to a time of day in the schedule's zone (never the host's, set apart here):
    # the review's regular slot (04:30) may fall inside the debounce.
    from datetime import datetime
    from ttp import schedule as sched, timefmt
    host_tz("Pacific/Auckland")
    p = make(env)
    zone = sched.zone_of(p.db.one("SELECT * FROM schedules WHERE name='daily-review'"), timefmt.home(p))
    real = time.time
    hh, mm = (int(x) for x in clock_at.split(":"))
    offset = [datetime.now(timefmt.tzinfo(zone)).replace(hour=hh, minute=mm, second=0, microsecond=0).timestamp() - real()]
    monkeypatch.setattr(time, "time", lambda: real() + offset[0])
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.gates = {}
    work = p.db.add_task("real work", "x", kind="work", tier="light", origin="user")
    _review_due(p)
    d.run_schedules()
    [first] = _reviews(p)
    assert p.db.kv(sched.DEBOUNCE_KEY + "daily-review")["task"] == first
    _review_done(p, first, time.time() - 3600)
    # A second trigger (a late retry, then the regular slot) an hour after it ended, nothing changed.
    _review_due(p)
    d.run_schedules()
    s = p.db.one("SELECT * FROM schedules WHERE name='daily-review'")
    assert s["last_status"].startswith("skipped: last run done 1.0 h ago on unchanged evidence"), s["last_status"]
    # The skip counts as the period's run: the next trigger is the regular slot, not a quick retry.
    assert _reviews(p) == [first] and s["last_run"] > time.time() - 60
    assert s["next_run"] == sched.next_run(s["every_s"], s["at"], s["last_run"], zone) > time.time()
    assert s["next_run"] > s["last_run"]
    if s["next_run"] < time.time() + 3600:
        # That slot falls inside the debounce: it wakes, skips again, and moves on a full period.
        offset[0] += s["next_run"] - time.time() + 1
        d.run_schedules()
        s = p.db.one("SELECT * FROM schedules WHERE name='daily-review'")
        assert s["last_status"].startswith("skipped: last run done 1."), s["last_status"]
        assert _reviews(p) == [first] and s["next_run"] > time.time() + 86400 - 3600
    # The debounce counts from the run's end, not from skipped triggers: past it, the review runs.
    p.db.x("UPDATE runs SET ended=? WHERE task=?", (time.time() - 3 * 3600, first))
    _review_due(p)
    d.run_schedules()
    assert len(_reviews(p)) == 2
    # Changed evidence runs at once: a task moved, or the user wrote.
    for change in (lambda: p.db.update_task(work, status="done", result=json.dumps({"summary": "shipped"})),
                   lambda: p.db.x("INSERT INTO messages(direction, chat, text, ts, handled) VALUES('in', 'c', 'how is it going?', ?, 0)",
                                  (time.time(),))):
        last = _reviews(p)[-1]
        _review_done(p, last, time.time() - 60)
        change()
        _review_due(p, time.time() - 1800)
        d.run_schedules()
        assert p.db.one("SELECT last_status FROM schedules WHERE name='daily-review'")["last_status"] == "queued"
        assert _reviews(p)[-1] != last


def test_the_review_evidence_is_taken_at_enqueue_and_ignores_accounting(env):
    p = make(env)
    from ttp import schedule as sched
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.gates = {}
    work = p.db.add_task("real work", "x", kind="work", tier="light", origin="user")
    _review_due(p)
    d.run_schedules()
    [first] = _reviews(p)
    # Spend and timestamps alone are no change.
    before = sched.evidence(p.db)
    p.db.x("UPDATE tasks SET spent_usd=1.5, updated=?, attempts=2 WHERE id=?", (time.time(), work))
    p.db.x("INSERT INTO ledger(ts,source,usd) VALUES(?,?,?)", (time.time(), "worker", 0.4))
    assert sched.evidence(p.db) == before
    # A worker finishing while the review runs is new: the next trigger reviews it.
    p.db.update_task(work, status="done", result=json.dumps({"summary": "landed"}))
    _review_done(p, first, time.time() - 60)
    _review_due(p, time.time() - 600)
    d.run_schedules()
    assert len(_reviews(p)) == 2


def test_a_failed_review_never_earns_the_debounce_and_it_is_configurable(env):
    p = make(env)
    from ttp import schedule as sched
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.gates = {}
    p.db.add_task("real work", "x", kind="work", tier="light", origin="user")
    _review_due(p)
    d.run_schedules()
    [first] = _reviews(p)
    for status in ("failed", "cancelled"):
        # It ended a minute ago on the evidence it was queued on, and a worker ran since (not idle).
        _review_done(p, _reviews(p)[-1], time.time() - 60)
        p.db.update_task(_reviews(p)[-1], status=status)
        p.db.x("INSERT INTO runs(task,role,provider,started,status) VALUES(?,?,?,?,?)",
               (None, "worker", "fake", time.time(), "ok"))
        assert p.db.kv(sched.DEBOUNCE_KEY + "daily-review")["evidence"] == sched.evidence(p.db)
        n = len(_reviews(p))
        _review_due(p, time.time() - 30)
        d.run_schedules()
        assert len(_reviews(p)) == n + 1, status
    assert sched.debounce_s("daily-review", {}) == 7200
    assert sched.debounce_s("daily-review", {"debounce_h": None}) == 0
    assert sched.debounce_s("daily-review", {"debounce_h": 0}) == 0
    assert sched.debounce_s("audit", {}) == 0 and sched.debounce_s("audit", {"debounce_h": 5}) == 5 * 3600
    # A longer debounce holds a run done 3 h ago; none at all lets it run.
    last = _reviews(p)[-1]
    _review_done(p, last, time.time() - 3 * 3600)
    for debounce, runs in ((5, False), (None, True)):
        sched.upsert(p.db, "daily-review", "llm", "1d", "04:30",
                     payload={"prompt": "daily-review.md", "debounce_h": debounce, "skip_if_idle": False})
        _review_due(p, time.time() - 30)
        d.run_schedules()
        assert (_reviews(p)[-1] != last) is runs, debounce


def test_a_debounced_schedule_keeps_its_period_while_its_run_is_open_or_its_budget_used(env):
    p = make(env)
    from ttp import schedule as sched
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.gates = {}
    p.db.add_task("real work", "x", kind="work", tier="light", origin="user")
    _review_due(p)
    d.run_schedules()
    [first] = _reviews(p)
    last = time.time() - 86400
    _review_due(p, last)
    before = time.time()
    d.run_schedules()
    s = p.db.one("SELECT * FROM schedules WHERE name='daily-review'")
    assert s["last_status"] == "deferred: previous run still open"
    assert s["last_run"] == last and before + 1800 - 5 <= s["next_run"] <= time.time() + 1800
    _review_done(p, first, time.time() - 5 * 3600)
    p.db.x("INSERT INTO ledger(ts,source,usd) VALUES(?,?,?)", (time.time() - 600, "schedule:daily-review", 9.0))
    _review_due(p, last)
    d.run_schedules()
    s = p.db.one("SELECT * FROM schedules WHERE name='daily-review'")
    assert s["last_status"] == "deferred: daily budget used" and s["last_run"] == last
    assert sched.waiting_line(p.db) == "" and not sched.failing(s["last_status"])


def _idle_review(p, d):
    """A user task and a review that ended done 3 h ago (past the debounce), due again with no run and
    no user message since its last trigger: only the evidence or the review's own outcome can owe a run."""
    work = p.db.add_task("real work", "x", kind="work", tier="light", origin="user")
    _review_due(p)
    d.run_schedules()
    _review_done(p, _reviews(p)[-1], time.time() - 3 * 3600)
    p.db.x("UPDATE messages SET ts=?", (time.time() - 86400,))
    return work


def _review_status(p):
    return p.db.one("SELECT last_status FROM schedules WHERE name='daily-review'")["last_status"]


def test_the_idle_guard_never_skips_a_review_owed_by_changed_evidence_or_its_own_failed_run(env):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.gates = {}
    work = _idle_review(p, d)
    # Nothing changed and nothing ran: the idle guard still skips it.
    _review_due(p, time.time() - 1800)
    d.run_schedules()
    assert _review_status(p) == "skipped: nothing happened since the last run"
    n = len(_reviews(p))
    # An owner cancels a task: its outcome moved with no run since the last review.
    p.db.update_task(work, status="cancelled")
    _review_due(p, time.time() - 1800)
    d.run_schedules()
    assert _review_status(p) == "queued" and len(_reviews(p)) == n + 1
    # The review itself failed, or was cancelled, on unchanged evidence and with nothing run since: retried.
    for status in ("failed", "cancelled"):
        last = _reviews(p)[-1]
        _review_done(p, last, time.time() - 3 * 3600)
        p.db.update_task(last, status=status)
        _review_due(p, time.time() - 1800)
        d.run_schedules()
        assert _review_status(p) == "queued" and _reviews(p)[-1] != last, status


def test_the_waiting_probes_model_free_rewrites_never_owe_an_idle_review(env):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.gates = {}
    work = _idle_review(p, d)
    # The task goes waiting and a review covers that; then the project is idle again.
    p.db.update_task(work, status="waiting", not_before=time.time() + 600,
                     blocked_reason="waiting for ci; next try 16:40 PDT")
    _review_due(p, time.time() - 1800)
    d.run_schedules()
    assert _review_status(p) == "queued"
    _review_done(p, _reviews(p)[-1], time.time() - 3 * 3600)
    _review_due(p, time.time() - 1800)
    d.run_schedules()
    assert _review_status(p) == "skipped: nothing happened since the last run"
    n = len(_reviews(p))
    # The probe loop says "not yet" again: only not_before and blocked_reason move, with no run.
    p.db.update_task(work, not_before=time.time() + 1200,
                     blocked_reason="waiting for ci; its probe says pending; next try 16:50 PDT")
    _review_due(p, time.time() - 1800)
    d.run_schedules()
    assert _review_status(p) == "skipped: nothing happened since the last run" and len(_reviews(p)) == n
    # The same churn after a failed review still retries it.
    _review_done(p, _reviews(p)[-1], time.time() - 3 * 3600)
    p.db.update_task(_reviews(p)[-1], status="failed")
    p.db.update_task(work, not_before=time.time() + 1800, blocked_reason="waiting for ci; next try 17:00 PDT")
    _review_due(p, time.time() - 1800)
    d.run_schedules()
    assert _review_status(p) == "queued" and len(_reviews(p)) == n + 1


def test_a_debounce_record_from_before_the_outcome_digest_falls_back_to_the_evidence(env):
    p = make(env)
    from ttp import schedule as sched
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.gates = {}
    _idle_review(p, d)
    last = p.db.kv(sched.DEBOUNCE_KEY + "daily-review")
    assert last["outcome"] == sched.outcome(p.db) and last["evidence"] == sched.evidence(p.db)
    p.db.set_kv(sched.DEBOUNCE_KEY + "daily-review", {"task": last["task"], "evidence": last["evidence"]})
    assert sched.debounce_gate(p.db, "daily-review", {})[2] == ""
    p.db.set_kv(sched.DEBOUNCE_KEY + "daily-review", {"task": last["task"], "evidence": "older"})
    assert sched.debounce_gate(p.db, "daily-review", {})[2] == "changed"


def test_a_review_owed_by_changed_evidence_still_waits_for_its_budget_and_its_open_run(env):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.gates = {}
    work = _idle_review(p, d)
    # Changed evidence while the day's budget is used: deferred, then queued once the budget allows.
    p.db.update_task(work, status="done", result=json.dumps({"summary": "shipped"}))
    spend = p.db.x("INSERT INTO ledger(ts,source,usd) VALUES(?,?,?)",
                   (time.time() - 600, "schedule:daily-review", 1e6))
    _review_due(p, time.time() - 1800)
    d.run_schedules()
    assert _review_status(p) == "deferred: daily budget used"
    p.db.x("DELETE FROM ledger WHERE id=?", (spend,))
    _review_due(p, time.time() - 1800)
    d.run_schedules()
    assert _review_status(p) == "queued"
    # A change during the open review: deferred while it runs, queued once it ended (done).
    open_review = _reviews(p)[-1]
    p.db.add_task("more work", "x", kind="work", tier="light", origin="user")
    _review_due(p, time.time() - 1800)
    d.run_schedules()
    assert _review_status(p) == "deferred: previous run still open" and _reviews(p)[-1] == open_review
    _review_done(p, open_review, time.time() - 60)
    _review_due(p, time.time() - 30)
    d.run_schedules()
    assert _review_status(p) == "queued" and _reviews(p)[-1] != open_review


def test_a_worker_that_finishes_after_the_last_review_counts_as_activity(env):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    since = time.time() - 3600
    p.db.x("UPDATE messages SET ts=?", (since - 86400,))
