def test_a_daily_receipt_watcher_keeps_its_pending_item_quiet_until_it_changes(env, tmp_path):
    p = make(env)
    from ttp import coordinator as coord
    from ttp import screen as scr
    from ttp.daemon import Daemon
    out = tmp_path / "receipts.txt"
    tok_a, tok_b = "evidence_" + "a1" * 20, "evidence_" + "b2" * 20
    assert coord.apply(p, [{"type": "schedule_set", "name": "receipts", "kind": "command", "every": "1d",
                            "command": f"cat {out}; test -s {out}", "rewake_after_h": None}]) == []
    s = p.db.one("SELECT * FROM schedules WHERE name='receipts'")
    assert json.loads(s["payload"])["rewake_after_h"] is None
    d = Daemon(p.base)
    d.gates = {}

    def run(text, rc_cmd=None):
        out.write_text(text)
        row = p.db.one("SELECT * FROM schedules WHERE name='receipts'")
        payload = json.loads(row["payload"])
        if rc_cmd:
            payload = {**payload, "command": rc_cmd}
        n = p.db.one("SELECT COUNT(*) n FROM events WHERE source='watcher:receipts'")["n"]
        status = d._run_command_watcher(row, payload)
        return status, p.db.one("SELECT COUNT(*) n FROM events WHERE source='watcher:receipts'")["n"] - n

    def age(hours):   # as if the last sighting were this long ago
        p.db.x("UPDATE issues SET last_seen=last_seen-? WHERE source='watcher:receipts'", (hours * 3600,))

    line = json.dumps({"text": f"owner outcome: task done; {tok_a}; owner must reassess",
                       "severity": "normal"}) + "\n"
    assert run(line)[1] == 1, "a new receipt wakes"
    # The next day, and after a failed run and a producer retry the day after: open, and quiet.
    age(25)
    d.cfg = p.config()
    scr.close_quiet_watcher_issues(p.db, {"watcher:receipts": 86400})
    assert not p.db.q("SELECT id FROM issues WHERE source='watcher:receipts' AND status!='open'")
    assert run(line)[1] == 0
    age(25)
    assert run("", rc_cmd="exit 3")[0].startswith("ok")
    age(25)
    scr.close_quiet_watcher_issues(p.db, {"watcher:receipts": 86400})
    assert p.db.one("SELECT COUNT(*) n FROM issues WHERE source='watcher:receipts' AND status='open' "
                    "AND title LIKE '%evidence_a1%'")["n"] == 1
    assert run(line)[1] == 0 and run(line)[1] == 0
    # The same outcome with new evidence (a changed success) wakes, though bare hashes are masked.
    assert run(line.replace(tok_a, tok_b))[1] == 1
    assert scr.condition_fingerprint("watcher:x", "owner outcome", "a1" * 20) == \
        scr.condition_fingerprint("watcher:x", "owner outcome", "b2" * 20), "bare tokens would stay one issue"
    # A fast watcher's issues still close after 24 h quiet; a daily one's after three days.
    p.db.x("INSERT INTO issues(fingerprint,source,first_seen,last_seen,title,status) VALUES(?,?,?,?,?,?)",
           ("fast1", "watcher:fast", 0, time.time() - 25 * 3600, "x", "open"))
    age(73)
    assert scr.close_quiet_watcher_issues(p.db, {"watcher:receipts": 86400, "watcher:fast": 300}) >= 2
    assert p.db.one("SELECT status FROM issues WHERE fingerprint='fast1'")["status"] == "fixed"
    assert {r["cleared_why"] for r in p.db.q("SELECT cleared_why FROM issues WHERE source='watcher:receipts'")} \
        == {"not seen for 72 h"}


def _receipt_rig(env, tmp_path, name="receipts", lifecycle="explicit_clear"):
    """A project with a daily command schedule that prints the file `out`, and helpers that run it
    the way the daemon's tick does (the quiet sweep first, then the due schedules)."""
    p = make(env)
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    out = tmp_path / f"{name}.txt"
    out.write_text("")
    act = {"type": "schedule_set", "name": name, "kind": "command", "every": "1d",
           "command": f"cat {out}; test -s {out}", "rewake_after_h": None}
    if lifecycle:
        act["issue_lifecycle"] = lifecycle
    assert coord.apply(p, [act]) == []
    rig = {"d": Daemon(p.base), "src": f"watcher:{name}", "err": f"watcher-error:{name}"}
    rig["d"].gates = {}

    def db():
        return rig["d"].p.db

    def events():   # its reports' and its errors' wakes
        return db().one("SELECT COUNT(*) n FROM events WHERE source IN (?,?)", (rig["src"], rig["err"]))["n"]

    def tick(text=None, command=None):
        """One tick: sweep, then the schedule (due now). Returns (status, new events)."""
        if text is not None:
            out.write_text(text)
        if command:
            row = db().one("SELECT payload FROM schedules WHERE name=?", (name,))
            db().x("UPDATE schedules SET payload=? WHERE name=?",
                   (json.dumps({**json.loads(row["payload"]), "command": command}), name))
        n = events()
        db().x("UPDATE schedules SET next_run=? WHERE name=?", (time.time() - 1, name))
        rig["d"].sweep_watcher_issues()
        rig["d"].run_schedules()
        if command:   # back to the producer
            row = db().one("SELECT payload FROM schedules WHERE name=?", (name,))
            db().x("UPDATE schedules SET payload=? WHERE name=?",
                   (json.dumps({**json.loads(row["payload"]), "command": f"cat {out}; test -s {out}"}), name))
        return db().one("SELECT last_status FROM schedules WHERE name=?", (name,))["last_status"], events() - n

    def age(hours):   # as if every sighting of this watcher were this much older
        db().x("UPDATE issues SET last_seen=last_seen-? WHERE source IN (?,?)", (hours * 3600, rig["src"], rig["err"]))

    def restart():   # the daemon and its database go away and come back
        rig["d"].p.db.close()
        rig["d"] = Daemon(p.base)
        rig["d"].gates = {}

    def open_titles():
        return {r["title"] for r in db().q("SELECT title FROM issues WHERE source=? AND status='open'",
                                           (rig["src"],))}

    rig.update(p=p, db=db, tick=tick, age=age, restart=restart, open_titles=open_titles, out=out)
    return rig


def _line(text, **kw):
    return json.dumps({"text": text, "severity": "normal", **kw}) + "\n"


def test_explicit_clear_receipts_stay_pending_through_the_quiet_sweep_downtime_and_restarts(env, tmp_path):
    from ttp import daemon as dmod
    from ttp import screen as scr
    r = _receipt_rig(env, tmp_path)
    tick, age = r["tick"], r["age"]
    # The tick sweeps quiet issues before it runs the day's commands.
    import inspect
    body = inspect.getsource(dmod.Daemon.tick)
    assert body.index("self.sweep_watcher_issues()") < body.index("self.run_schedules")
    a, b = "job7: done; evidence_" + "a1" * 20, "job8: done; evidence_" + "c3" * 20
    assert tick(_line(a) + _line(b)) == ("ok (2 observations)", 2), "each new receipt line wakes once"
    pending = r["open_titles"]()
    assert len(pending) == 4 and all(row["lifecycle"] == "receipt" for row in r["db"]().q(
        "SELECT lifecycle FROM issues WHERE source=?", (r["src"],)))
    # A day, then four days of downtime and a restart: the sweep that runs first closes none of them,
    # and the same receipts reported again stay quiet.
    age(25)
    assert tick()[1] == 0 and r["open_titles"]() == pending
    age(4 * 24)
    r["restart"]()
    assert r["d"].sweep_watcher_issues() == 0 and r["open_titles"]() == pending
    assert tick()[1] == 0 and r["open_titles"]() == pending
    # A producer that fails and retries: its failure is an error (it wakes); the retry repairs it and
    # the receipts stay pending without a wake.
    age(25)
    status, woke = tick(command="echo boom >&2; exit 3")
    assert woke == 1 and r["open_titles"]() >= pending
    err = r["db"]().one("SELECT * FROM issues WHERE source=? AND lifecycle='error'", (r["err"],))
    assert err["status"] == "open" and "rc=3" in err["title"]
    assert tick()[1] == 0 and r["open_titles"]() == pending
    assert r["db"]().one("SELECT * FROM issues WHERE id=?", (err["id"],))["cleared_why"] == scr.REPAIRED_WHY
    # A changed outcome for one subject wakes and replaces that subject's old items only.
    failed = "job7: failed; evidence_" + "b2" * 20
    assert tick(_line(failed) + _line(b))[1] == 1
    assert {t for t in r["open_titles"]() if t.startswith("job7")} == {"job7: failed", "job7: evidence_" + "b2" * 20}
    assert {t for t in r["open_titles"]() if t.startswith("job8")} == {t for t in pending if t.startswith("job8")}
    assert {x["cleared_why"] for x in r["db"]().q("SELECT cleared_why FROM issues WHERE source=? AND status='fixed' "
                                                     "AND lifecycle='receipt'", (r["src"],))} == {scr.REPLACED_WHY}
    # Job 8 not reported by a run keeps pending; a later return of job7 to done wakes again.
    assert tick(_line(failed))[1] == 0 and any(t.startswith("job8") for t in r["open_titles"]())
    assert tick(_line(a))[1] == 1
    # Explicit acknowledgement: `cleared:` closes an item, a run printing nothing closes the rest.
    assert tick(_line("job8: cleared: done; cleared: evidence_" + "c3" * 20) + _line(a))[1] == 0
    assert not any(t.startswith("job8") for t in r["open_titles"]())
    assert tick("")[0] == "ok (0 observations)" and r["open_titles"]() == set()


def test_an_info_outcome_replaces_the_older_receipt_of_its_subject(env, tmp_path):
    from ttp import screen as scr
    r = _receipt_rig(env, tmp_path)
    tick, db = r["tick"], r["db"]
    old = ("job-1: failed", "job-1: evidence_" + "a1" * 20)
    assert tick(_line("job-1: failed; evidence_" + "a1" * 20))[1] == 1
    assert r["open_titles"]() == set(old)
    # The newer outcome, rated info, still replaces the pending receipts of its subject, without a wake.
    assert tick(_line("job-1: done; evidence_" + "b2" * 20, severity="info"))[1] == 0
    rows = db().q("SELECT status, cleared_why FROM issues WHERE source=? AND title IN (?,?)", (r["src"], *old))
    assert len(rows) == 2 and {(x["status"], x["cleared_why"]) for x in rows} == {("fixed", scr.REPLACED_WHY)}
    assert r["open_titles"]() == set()
    # A "whole": true line is one receipt of its subject, replaced the same way by the next outcome.
    first, then = "job-2: failed; evidence_" + "c3" * 20, "job-2: done; evidence_" + "d4" * 20
    assert tick(_line(first, whole=True))[1] == 1 and r["open_titles"]() == {first}
    assert tick(_line(then, whole=True))[1] == 1 and r["open_titles"]() == {then}
    assert db().one("SELECT cleared_why FROM issues WHERE title=?", (first,))["cleared_why"] == scr.REPLACED_WHY


def test_explicit_clear_errors_recover_and_a_later_recurrence_wakes(env, tmp_path):
    from ttp import screen as scr
    r = _receipt_rig(env, tmp_path)
    tick, age = r["tick"], r["age"]
    receipt = _line("job 1: done; evidence_" + "a1" * 20)
    own_error = _line("accountant: failed to read the ledger", error=True, severity="high")
    for restart in (False, True):
        # The producer's own failure line, then a successful non-empty run without it, then the same
        # failure more than a day later (across a restart in the second round): a fresh event.
        assert tick(receipt + own_error)[1] >= 1
        assert tick(receipt)[1] == 0
        row = r["db"]().one("SELECT * FROM issues WHERE source=? AND lifecycle='error'", (r["err"],))
        assert row["status"] == "fixed" and row["cleared_why"] == scr.REPAIRED_WHY
        assert any(t.startswith("job 1") for t in r["open_titles"]()), "the receipt stays pending"
        age(30)
        if restart:
            r["restart"]()
        assert tick(receipt + own_error)[1] == 1, "the same failure after recovery is news"
        # A run that still reports the failure repairs nothing: it stays open and quiet.
        assert tick(receipt + own_error)[1] == 0
        assert r["db"]().one("SELECT status FROM issues WHERE id=?", (row["id"],))["status"] == "open"
        assert tick(receipt)[1] == 0
    # The daemon's own failure report (exit code, no output) recovers the same way, across a restart.
    assert tick(command="exit 4")[1] == 1
    assert tick(receipt)[1] == 0
    age(30)
    r["restart"]()
    assert tick(command="exit 4")[1] == 1
    # An error nothing repairs is not exempt from expiry: the quiet sweep closes it (3 daily periods)
    # while the receipt stays.
    age(73)
    assert r["d"].sweep_watcher_issues() == 1
    assert {x["lifecycle"] for x in r["db"]().q("SELECT lifecycle FROM issues WHERE source=? AND status='open'",
                                                  (r["src"],))} == {"receipt"}


def test_command_errors_have_their_own_source_beside_explicit_clear_receipts(env, tmp_path):
    from ttp import coordinator as coord
    from ttp import screen as scr
    r = _receipt_rig(env, tmp_path)
    tick, db, src, err = r["tick"], r["db"], r["src"], r["err"]

    def open_errors():
        return db().q("SELECT * FROM issues WHERE source=? AND status='open'", (err,))

    receipt = _line("job 1: done; evidence_" + "a1" * 20)
    assert tick(receipt)[1] == 1
    pending = r["open_titles"]()
    # A failing command after a run with receipts surfaces under watcher-error:<name>, which no receipt
    # rule (expiry exemption, null rewake, a mute of the receipts) covers.
    assert coord.apply(r["p"], [{"type": "observation_mute", "source": src, "match": "watcher command",
                                 "hours": 24}]) == []
    assert tick(command="echo boom >&2; exit 3")[1] == 1
    assert [e["lifecycle"] for e in open_errors()] == ["error"] and "rc=3" in open_errors()[0]["title"]
    assert not db().one("SELECT id FROM issues WHERE source=? AND title LIKE '%rc=3%'", (src,))
    assert r["open_titles"]() == pending
    # It recurs quietly while open; a successful run (exit 0) clears it, receipts untouched.
    assert tick(command="echo boom >&2; exit 3")[1] == 0 and len(open_errors()) == 1
    assert tick(command=f"cat {r['out']}")[0] == "ok (1 observations)"
    assert open_errors() == [] and r["open_titles"]() == pending
    assert db().one("SELECT cleared_why FROM issues WHERE source=?", (err,))["cleared_why"] == scr.REPAIRED_WHY
    # The same failure again is news, and so is a timeout; a run exiting 0 with nothing to report clears
    # both and, being an acknowledgement, the receipts too.
    assert tick(command="echo boom >&2; exit 3")[1] == 1
    row = db().one("SELECT payload FROM schedules WHERE name='receipts'")
    db().x("UPDATE schedules SET payload=? WHERE name='receipts'",
           (json.dumps({**json.loads(row["payload"]), "timeout_s": 1}), ))
    assert tick(command="sleep 3") == ("timeout", 1)
    assert len(open_errors()) == 2 and r["open_titles"]() == pending
    db().x("UPDATE schedules SET payload=? WHERE name='receipts'", (row["payload"], ))   # 1s is too tight under load
    assert tick(command="true")[0] == "ok (0 observations)"
    assert open_errors() == [] and r["open_titles"]() == set()


def test_command_errors_clear_on_success_and_expire_while_receipts_wait_for_acknowledgement(env, tmp_path):
    from ttp import coordinator as coord
    r = _receipt_rig(env, tmp_path)
    tick, db, err = r["tick"], r["db"], r["err"]
    receipt = _line("job 1: done; evidence_" + "a1" * 20)
    assert tick(receipt)[1] == 1
    pending = r["open_titles"]()
    # An error nothing repairs expires after three daily periods; the receipts wait, across a restart.
    assert tick(command="exit 4")[1] == 1
    r["age"](73)
    r["restart"]()
    assert r["d"].sweep_watcher_issues() == 1
    assert not db().one("SELECT id FROM issues WHERE source=? AND status='open'", (err,))
    assert r["open_titles"]() == pending
    # Only the owner's acknowledgement closes a receipt.
    assert tick(receipt)[1] == 0 and r["open_titles"]() == pending
    assert tick(_line("job 1: cleared: done; cleared: evidence_" + "a1" * 20))[1] == 0
    assert r["open_titles"]() == set()
    # Removing the policy brings ordinary expiry back for its receipts.
    assert tick(receipt)[1] == 1 and r["open_titles"]() == pending
    assert coord.apply(r["p"], [{"type": "schedule_set", "name": "receipts", "issue_lifecycle": None}]) == []
    r["age"](73)
    assert r["d"].sweep_watcher_issues() == 2 and r["open_titles"]() == set()


def test_plain_command_watcher_errors_clear_on_the_next_successful_run(env, tmp_path):
    r = _receipt_rig(env, tmp_path, name="plain", lifecycle=None)
    tick, db, err = r["tick"], r["db"], r["err"]
    line = _line("disk 1: nearly full")
    assert tick(line)[1] == 1
    assert tick(command="echo boom >&2; exit 2")[1] == 1
    assert db().one("SELECT status FROM issues WHERE source=?", (err,))["status"] == "open"
    # A run that exits 0 and still reports its own items repairs the error and leaves the items open.
    assert tick(command=f"cat {r['out']}")[1] == 0
    assert db().one("SELECT status FROM issues WHERE source=?", (err,))["status"] == "fixed"
    assert r["open_titles"]() == {"disk 1: nearly full"}


def test_command_watcher_exit_1_is_a_normal_run_and_only_error_true_lines_are_errors(env, tmp_path):
    """The documented protocol: exit 0 or 1 is a normal run, so every line it prints is a report under
    watcher:<name>, however it is worded; only a JSON line with "error": true (the JSON boolean) is the
    watcher's own error, under watcher-error:<name>, cleared by the next successful run without it."""
    from ttp import screen as scr
    r = _receipt_rig(env, tmp_path, name="acct", lifecycle=None)
    tick, db, src, err, out = r["tick"], r["db"], r["src"], r["err"], r["out"]

    def issues(source):
        return db().q("SELECT title, status, lifecycle, cleared_why FROM issues WHERE source=?", (source,))

    def fix_tasks():
        return db().one("SELECT COUNT(*) n FROM tasks WHERE labels LIKE '%schedule_fix:acct%'")["n"]

    # Exit 1 without error:true, even when the text says error: reports, and the run is ok.
    plain = (_line("ledger: entry missing") + _line("ledger: error reading the books")
             + _line("ledger: a string is not the flag", error="true"))
    assert tick(plain, command=f"cat {out}; exit 1") == ("ok (3 observations)", 3)
    assert len(issues(src)) == 3 and issues(err) == []
    # Twice in a row is still a healthy schedule: no fix task.
    assert tick(command=f"cat {out}; exit 1")[0] == "ok (3 observations)" and fix_tasks() == 0
    # The same failure with "error": true is the watcher's own error, also at exit 1.
    assert tick(_line("ledger: cannot read the books", error=True), command=f"cat {out}; exit 1") \
        == ("ok (1 observations)", 1)
    assert [(x["title"], x["status"], x["lifecycle"]) for x in issues(err)] \
        == [("ledger: cannot read the books", "open", scr.ERROR)]
    assert len(issues(src)) == 3, "an error line opens no report"
    assert tick(command=f"cat {out}; exit 1")[1] == 0, "a known error does not wake again"
    # The next successful run that no longer prints it repairs it; its reports stay as they were.
    assert tick(_line("ledger: entry missing"), command=f"cat {out}; exit 1")[1] == 0
    assert [(x["status"], x["cleared_why"]) for x in issues(err)] == [("fixed", scr.REPAIRED_WHY)]
    # Any other exit code is a failed run: its lines still stand, and the failure is an error of its own.
    assert tick(command=f"cat {out}; echo broke >&2; exit 2")[1] == 1
    assert any(x["title"].startswith("watcher command exited rc=2") and x["status"] == "open"
               for x in issues(err))
    assert fix_tasks() == 0
    # The skill and the coordinator's schedule_set entry say so.
    skill = " ".join((RUNTIME.parent / "skills" / "tt-project-harness" / "SKILL.md").read_text().split())
    prompt = " ".join((RUNTIME.parent / "template" / "prompts" / "coordinator.md").read_text().split())
    assert "exit 0 or 1 is a normal run" in skill and '`"error": true` (the JSON boolean' in skill
    assert "any other exit code is a failed run" in skill.lower()
    assert "exit 0 or 1 is a normal run" in prompt and '`"error": true` (the JSON boolean)' in prompt


def test_watcher_sweep_before_its_schedule_exists_then_its_first_run(env, tmp_path):
    """The tick sweeps watcher issues before any command schedule exists (a new project, or a schedule
    still to come from schedules.json or schedule_set): nothing breaks, a leftover issue of an unknown
    watcher closes on the default 24 h rule, and the schedule's first run then works as usual."""
    from ttp import coordinator as coord
    from ttp import screen as scr
    from ttp.daemon import Daemon
    p = make(env)
    assert not p.db.q("SELECT name FROM schedules WHERE kind='command'")
    d = Daemon(p.base)
    d.gates = {}
    assert d.sweep_watcher_issues() == 0
    now = time.time()
    for fp, source, seen, life in (("old", "watcher:later", now - 25 * 3600, None),
                                   ("recent", "watcher:later", now - 3600, None),
                                   ("err", "watcher-error:later", now - 3600, scr.ERROR)):
        p.db.x("INSERT INTO issues(fingerprint,source,first_seen,last_seen,title,status,lifecycle) "
               "VALUES(?,?,?,?,?,?,?)", (fp, source, seen, seen, fp, "open", life))
    assert d.sweep_watcher_issues() == 1
    status = lambda fp: p.db.one("SELECT status FROM issues WHERE fingerprint=?", (fp,))["status"]
    assert (status("old"), status("recent"), status("err")) == ("fixed", "open", "open")
    out = tmp_path / "later.txt"
    out.write_text(_line("books: 2 entries late"))
    assert coord.apply(p, [{"type": "schedule_set", "name": "later", "kind": "command", "every": "1h",
                            "command": f"cat {out}; exit 1"}]) == []
    d.p.db.x("UPDATE schedules SET next_run=? WHERE name='later'", (time.time() - 1,))
    d.sweep_watcher_issues()
    d.run_schedules()
    assert d.p.db.one("SELECT last_status FROM schedules WHERE name='later'")["last_status"] == "ok (1 observations)"
    assert status("err") == "fixed", "its first successful run repairs the error it no longer reports"
    assert d.p.db.one("SELECT COUNT(*) n FROM issues WHERE source='watcher:later' AND status='open' "
                      "AND fingerprint NOT IN ('old','recent')")["n"] == 1


def test_an_old_database_with_open_watcher_issues_migrates_and_then_recovers(env, tmp_path):
    """A database from before issue lifecycles, with open watcher reports and errors in it, keeps them
    open through the migration; the watcher's next runs then recover it as on a new one."""
    from ttp import screen as scr
    r = _receipt_rig(env, tmp_path, name="acct", lifecycle=None)
    db, src, err, out = r["db"], r["src"], r["err"], r["out"]
    r["tick"](_line("ledger: entry missing") + _line("ledger: cannot read the books", error=True))
    before = {(x["source"], x["title"]) for x in db().q("SELECT source, title FROM issues WHERE status='open'")}
    assert before == {(src, "ledger: entry missing"), (err, "ledger: cannot read the books")}
    # Back to the old schema: no lifecycle, subject or opened columns.
    for col in ("lifecycle", "subject", "opened"):
        db().x(f"ALTER TABLE issues DROP COLUMN {col}")
    r["restart"]()
    cols = {x["name"] for x in db().q("PRAGMA table_info(issues)")}
    assert {"lifecycle", "subject", "opened"} <= cols
    assert {(x["source"], x["title"]) for x in db().q("SELECT source, title FROM issues WHERE status='open'")} \
        == before, "the migration closes nothing"
    assert all(x["opened"] == x["first_seen"] for x in db().q("SELECT opened, first_seen FROM issues"))
    # A recurrence of the error after the migration wakes nothing new and keeps one issue.
    assert r["tick"]()[1] == 0
    assert db().one("SELECT lifecycle FROM issues WHERE source=?", (err,))["lifecycle"] == scr.ERROR
    # Repaired: a successful run without the error line closes it; the report stays.
    assert r["tick"](_line("ledger: entry missing"))[1] == 0
    assert db().one("SELECT status FROM issues WHERE source=?", (err,))["status"] == "fixed"
    assert r["open_titles"]() == {"ledger: entry missing"}
    # A run that prints nothing closes the rest.
    out.write_text("")
    assert r["tick"]()[0] == "ok (0 observations)" and r["open_titles"]() == set()


def test_ordinary_expiry_stays_for_sources_that_did_not_opt_in(env, tmp_path):
    from ttp import coordinator as coord
    r = _receipt_rig(env, tmp_path, name="plain", lifecycle=None)
    p, db = r["p"], r["db"]
    line = _line("job 1: done; evidence_" + "a1" * 20)
    assert r["tick"](line)[1] == 1
    assert {x["lifecycle"] for x in db().q("SELECT lifecycle FROM issues WHERE source=?", (r["src"],))} == {None}
    r["age"](73)
    assert r["d"].sweep_watcher_issues() == 2 and r["open_titles"]() == set()
    assert r["tick"](line)[1] == 1, "reopened after expiry, as before"
    # A fast watcher's items still close after 24 h, beside an explicit_clear source.
    assert coord.apply(p, [{"type": "schedule_set", "name": "plain", "issue_lifecycle": "explicit_clear"}]) == []
    assert r["tick"](line)[1] == 0, "its next run marks the open items receipts"
    db().x("INSERT INTO issues(fingerprint,source,first_seen,last_seen,title,status) VALUES(?,?,?,?,?,?)",
           ("fast1", "watcher:fast", 0, time.time() - 25 * 3600, "x", "open"))
    r["age"](100)
    assert r["d"].sweep_watcher_issues() == 1
    assert db().one("SELECT status FROM issues WHERE fingerprint='fast1'")["status"] == "fixed"
    assert len(r["open_titles"]()) == 2 and r["tick"](line)[1] == 0
    # Turning the option off brings ordinary expiry back; a bad value is rejected.
    assert coord.apply(p, [{"type": "schedule_set", "name": "plain", "issue_lifecycle": None}]) == []
    assert "issue_lifecycle" not in json.loads(db().one("SELECT payload FROM schedules WHERE name='plain'")["payload"])
    r["age"](73)
    assert r["d"].sweep_watcher_issues() == 2
    errs = coord.apply(p, [{"type": "schedule_set", "name": "plain", "issue_lifecycle": "forever"}])
    assert errs and "issue_lifecycle" in str(errs[0])


def test_issue_lifecycle_columns_are_added_to_an_old_database(env, tmp_path):
    from ttp.db import DB
    path = tmp_path / "old.db"
    c = sqlite3.connect(path)
    c.execute("CREATE TABLE issues (id INTEGER PRIMARY KEY AUTOINCREMENT, fingerprint TEXT UNIQUE, source TEXT, "
              "first_seen REAL, last_seen REAL, count INTEGER DEFAULT 1, title TEXT, severity TEXT DEFAULT 'normal', "
              "status TEXT DEFAULT 'open', task INTEGER, screen TEXT, closed REAL, cleared_why TEXT)")
    c.execute("INSERT INTO issues(fingerprint,source,title) VALUES('f','watcher:x','t')")
    c.commit()
    c.close()
    db = DB(path)
    cols = {r["name"] for r in db.q("PRAGMA table_info(issues)")}
    assert {"lifecycle", "subject"} <= cols
    assert db.one("SELECT lifecycle FROM issues WHERE fingerprint='f'")["lifecycle"] is None
    db.close()


def test_schedule_set_takes_rewake_and_debounce_hours_or_null(env):
    p = make(env)
    from ttp import coordinator as coord
    assert coord.apply(p, [{"type": "schedule_set", "name": "probe", "kind": "command", "command": "true",
                            "every": "1d", "rewake_after_h": 48},
                           {"type": "schedule_set", "name": "audit", "kind": "llm", "spec": "x", "every": "1d",
                            "debounce_h": None}]) == []
