def test_a_task_continuing_a_failed_review_starts_from_the_reviewed_branch(env, monkeypatch):
    # A re-plan labelled continues:<review> builds on what the review reviewed, not on the base,
    # so its head contains the reviewed branch (the push queue refuses one that does not).
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    from ttp.prompts import worker_task
    work, path, branch = _code_task(p, "change", status="done")
    _commit_file(path, "change")
    head = _git_out(path, "rev-parse", "HEAD")
    review = p.db.add_task("review change", f"Review branch {branch}.", kind="review", tier="light",
                           origin="user")
    p.db.update_task(review, status="failed")
    replan = p.db.add_task("redo change", "s", kind="code", tier="light", origin="user",
                           labels=[f"continues:{review}"])
    new_path, new_branch = worktree.ensure(p, p.db.task(replan))
    assert new_branch != branch and _git_out(new_path, "rev-parse", "HEAD") == head
    assert (new_path / "change.txt").exists()
    assert "starts from the head of what it reviewed" in worker_task(p, p.db.task(replan), str(new_path), new_branch)
    # A fix branch built on the reviewed branch is what a later re-plan of its re-review starts from.
    _commit_file(new_path, "fix")
    fix_head = _git_out(new_path, "rev-parse", "HEAD")
    p.db.update_task(replan, branch=new_branch, status="done")
    again = p.db.add_task("review change again", f"Review branch {branch}.", kind="review", tier="light",
                          origin="user")
    p.db.update_task(again, status="failed")
    third = p.db.add_task("redo change again", "s", kind="code", tier="light", origin="user",
                          labels=[f"continues:{again}"])
    assert worktree.continued_head(p, p.db.task(third)) == fix_head
    # A review naming nothing that resolves: the base, as before.
    lost = p.db.add_task("review gone", "Review branch ttp/t999-gone.", kind="review", tier="light", origin="user")
    stray = p.db.add_task("redo gone", "s", kind="code", tier="light", origin="user", labels=[f"continues:{lost}"])
    assert worktree.continued_head(p, p.db.task(stray)) is None


def test_a_task_rebasing_a_branch_and_continuing_a_review_starts_from_the_rebased_branch(env, monkeypatch):
    # rebases:<branch> wins over continues:<review>: the rebase works on that branch's head, not on
    # what the earlier review reviewed.
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import worktree
    _, path, branch = _code_task(p, "change", status="done")
    _commit_file(path, "change")
    review = p.db.add_task("review change", f"Review branch {branch}.", kind="review", tier="light",
                           origin="user")
    p.db.update_task(review, status="failed")
    _, other_path, other = _code_task(p, "other", status="done")
    _commit_file(other_path, "other")
    other_head = _git_out(other_path, "rev-parse", "HEAD")
    task = p.db.add_task("rebase other", "s", kind="code", tier="light", origin="user",
                         labels=[f"rebases:{other}", f"continues:{review}"])
    assert worktree.continued_head(p, p.db.task(task)) != other_head
    new_path, new_branch = worktree.ensure(p, p.db.task(task))
    assert new_branch != other and _git_out(new_path, "rev-parse", "HEAD") == other_head
    assert (new_path / "other.txt").exists() and not (new_path / "change.txt").exists()


def test_worktree_retention_delays_removal(env, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp.daemon import Daemon
    p.set_config("disk.worktree_retention_days", 7)
    tid, recent, _ = _code_task(p, "recent")
    _, old, _ = _code_task(p, "old")
    p.db.x("UPDATE tasks SET updated=? WHERE id!=?", (time.time() - 8 * 86400, tid))
    Daemon(p.base).prune_worktrees()
    assert recent.exists() and not old.exists()


def test_ttp_prune_sweeps_finished_worktrees_once(env, capsys, monkeypatch):
    p = make(env)
    _no_grace(monkeypatch)
    from ttp import cli
    _, clean, branch = _code_task(p, "clean")
    t_dirty, dirty, _ = _code_task(p, "dirty")
    (dirty / "new.txt").write_text("unsaved")
    cli.main(["prune", "demo"])
    out = capsys.readouterr().out
    assert not clean.exists() and not dirty.exists()
    assert f"removed, branch {branch} kept" in out and f"#{t_dirty} (done): archived 1 file(s)" in out, out
    assert "removed 2 worktree(s), kept 0; freed" in out, out
    cli.main(["prune", "demo"])
    assert "no finished task's worktree to tidy" in capsys.readouterr().out
    cli.main(["prune", "demo", "--archived", str(t_dirty)])
    out = capsys.readouterr().out
    assert "new.txt" in out and "files.tar.gz:new.txt" in out, out


def _run_worktree(p, task, status="done", ended_ago=7 * 3600):
    """A run of `task` whose worker made its own git worktree at state/runs/<run id>/wt, as workers do."""
    import time as _t
    now = _t.time()
    rid = p.db.x("INSERT INTO runs(task, role, started, ended, status) VALUES(?,?,?,?,?)",
                 (task, "worker", now - ended_ago - 60, None if status == "running" else now - ended_ago, status))
    wt = p.runs / str(rid) / "wt"
    wt.parent.mkdir(parents=True, exist_ok=True)
    _git_out(p.root, "worktree", "add", "-q", "--detach", str(wt))
    return rid, wt


def test_run_directory_worktrees_go_when_finished_and_clean_and_stay_with_a_reason(env, monkeypatch):
    """Worktrees a worker made in its run directory are found from git's records and swept like task
    worktrees: a clean one of a finished run goes (artifacts archived first); a live run's, an open
    task's, a dirty one and one that ended under the grace stay, each with its reason."""
    import json
    from pathlib import Path
    p = make(env)
    from ttp import archive, worktree
    (p.root / ".git" / "info").mkdir(exist_ok=True)
    (p.root / ".git" / "info" / "exclude").write_text("*.out\n")
    done = p.db.add_task("finished", "s", kind="experiment", tier="light", origin="user")
    p.db.update_task(done, status="done")
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (1.0, done))
    waiting = p.db.add_task("waits", "s", kind="experiment", tier="light", origin="user")
    p.db.update_task(waiting, status="waiting")
    clean_run, clean = _run_worktree(p, done)
    art_run, art = _run_worktree(p, done)
    (art / "result.out").write_text("the figure")
    (p.runs / str(art_run) / "result.json").write_text(json.dumps({"status": "done", "artifacts": [str(art / "result.out")]}))
    _, live = _run_worktree(p, done, status="running")
    _, open_ = _run_worktree(p, waiting)
    _, dirty = _run_worktree(p, done)
    (dirty / "README.md").write_text("edited, never committed")
    _, recent = _run_worktree(p, done, ended_ago=600)
    found = {w["path"] for w in worktree.run_worktrees(p)}
    assert found == {w.resolve() for w in (clean, art, live, open_, dirty, recent)}, found
    dry = {Path(r["path"]): r for r in worktree.sweep(p, dry_run=True)}
    assert dry[clean.resolve()]["why"] is None and clean.exists(), "a dry run removed it"
    res = {Path(r["path"]): r for r in worktree.sweep(p)}
    assert res[clean.resolve()]["why"] is None and not clean.exists()
    assert res[clean.resolve()]["run"] == clean_run and res[clean.resolve()]["task"] == done
    assert res[art.resolve()]["why"] is None and not art.exists()
    assert res[art.resolve()]["archived"]["files"] == 1 and archive.manifest(p, done)["files"][0]["path"] == "result.out"
    assert "is still going" in res[live.resolve()]["why"] and res[live.resolve()]["held"]
    assert f"task #{waiting} (waiting) is still open" in res[open_.resolve()]["why"]
    assert "uncommitted changes" in res[dirty.resolve()]["why"]
    assert "ended under 1 h ago" in res[recent.resolve()]["why"]
    assert all(w.exists() for w in (live, open_, dirty, recent))
    listed = _git_out(p.root, "worktree", "list")
    assert str(clean) not in listed and str(art) not in listed and str(dirty) in listed
    assert (p.runs / str(clean_run)).is_dir(), "the run directory itself stays"


def test_stray_worktrees_of_finished_tasks_go_and_open_tasks_keep_theirs(env, tmp_path):
    """Note 7a885770f745d36e: worktrees workers made outside worktrees/t<id> and run directories
    (state/worktrees/t<id>, state/wt-<id>, worktrees/t<id>-review, <repo>/.wt/r<id>) were never swept.
    Found from git's records and mapped to a task by their folder name, a done or cancelled task's
    one whose HEAD is on a remote branch goes, its small dirty files archived first; an open task's,
    a failed task's, one with commits on no remote branch and one with too many dirty files stay."""
    import json
    import subprocess as sp
    from pathlib import Path
    p = make(env)
    from ttp import worktree
    from ttp.daemon import Daemon
    root = p.root
    remote = tmp_path / "remote.git"
    sp.run(["git", "init", "-q", "--bare", str(remote)], check=True)
    _git_out(root, "remote", "add", "origin", str(remote))
    _git_out(root, "push", "-q", "origin", "HEAD:refs/heads/main")
    _git_out(root, "fetch", "-q", "origin")

    def task(status):
        t = p.db.add_task(f"a {status} task", "s", kind="code", tier="light", origin="user")
        p.db.update_task(t, status=status)
        p.db.x("UPDATE tasks SET updated=? WHERE id=?", (1.0, t))
        return t

    def add(path):
        path.parent.mkdir(parents=True, exist_ok=True)
        _git_out(root, "worktree", "add", "-q", "--detach", str(path))
        return path
    clean, dirty, local, big = task("done"), task("done"), task("done"), task("done")
    cancelled, open_, failed, own = task("cancelled"), task("waiting"), task("failed"), task("done")
    w_clean = add(p.state / "worktrees" / f"t{clean}")
    w_dirty = add(p.state / f"wt-{dirty}")
    readme = next(f for f in w_dirty.iterdir() if f.is_file() and f.name != ".git")
    readme.write_text("edited, never committed\n")
    (w_dirty / "notes.txt").write_text("a small untracked file")
    w_review = add(p.worktrees / f"t{cancelled}-review")
    w_open = add(root / ".wt" / f"r{open_}")
    (w_open / "wip.txt").write_text("work in progress")
    w_local = add(p.state / "worktrees" / f"t{local}")
    (w_local / "new.txt").write_text("x")
    _git_out(w_local, "add", "new.txt")
    _git_out(w_local, "-c", "user.name=t", "-c", "user.email=t@example.invalid", "commit", "-qm", "local only")
    w_big = add(p.state / "worktrees" / f"t{big}")
    (w_big / "big.bin").write_bytes(b"0" * (worktree.STRAY_ARCHIVE_MAX_MB * 10 ** 6 + 1))
    w_failed = add(p.state / "worktrees" / f"t{failed}")
    w_own = add(p.worktrees / f"t{own}")             # the task sweep's own: not a stray
    w_name = add(p.state / "scratch" / "notes")      # no task id in its name
    (root / "sub" / p.base.name).mkdir(parents=True)  # another project's folder below this root
    w_other = add(root / "sub" / "wt" / f"t{clean}")
    found = {w["path"]: w["task"] for w in worktree.stray_worktrees(p)}
    want = {w_clean: clean, w_dirty: dirty, w_review: cancelled, w_open: open_, w_local: local, w_big: big,
            w_failed: failed}
    assert found == {k.resolve(): v for k, v in want.items()}, found
    assert w_own.resolve() not in found and w_name.resolve() not in found and w_other.resolve() not in found

    dry = {Path(r["path"]): r for r in worktree.sweep(p, dry_run=True) if r.get("stray")}
    assert dry[w_clean.resolve()]["why"] is None and dry[w_dirty.resolve()]["why"] is None
    assert all(w.exists() for w in want), "a dry run removed one"
    assert not (p.state / worktree.STRAY_ARCHIVE_DIR).exists(), "a dry run archived"

    d = Daemon(p.base)
    res = {Path(r["path"]): r for r in d.prune_worktrees(every_s=0, force=True) if r.get("stray")}
    assert set(res) == {k.resolve() for k in want}, res
    for gone in (w_clean, w_dirty, w_review):
        assert res[gone.resolve()]["why"] is None and not gone.exists(), res[gone.resolve()]
    ar = p.state / worktree.STRAY_ARCHIVE_DIR / w_dirty.name
    assert res[w_dirty.resolve()]["archived"]["dir"] == str(ar)
    assert (ar / "files" / "notes.txt").read_text() == "a small untracked file"
    assert (ar / "files" / readme.name).read_text() == "edited, never committed\n"
    assert readme.name in (ar / "tracked.patch").read_text()
    man = json.loads((ar / "manifest.json").read_text())
    assert man["task"] == dirty and set(man["files"]) == {"notes.txt", readme.name} and man["tracked"] == [readme.name]
    assert res[w_open.resolve()]["held"] and f"task #{open_} (waiting) is still open" in res[w_open.resolve()]["why"]
    assert "no remote branch" in res[w_local.resolve()]["why"]
    assert f"over the {worktree.STRAY_ARCHIVE_MAX_MB} MB" in res[w_big.resolve()]["why"]
    assert f"#{failed} failed" in res[w_failed.resolve()]["why"]
    assert all(w.exists() for w in (w_open, w_local, w_big, w_failed, w_name, w_other))
    assert (w_open / "wip.txt").read_text() == "work in progress"
    listed = _git_out(root, "worktree", "list")
    assert str(w_clean) not in listed and str(w_dirty) not in listed and str(w_open) in listed
    log = (p.logs / "daemon.log").read_text()
    assert f"stray worktree {w_clean.resolve()} (task {clean}) removed" in log, log
    assert f"stray worktree {w_dirty.resolve()} (task {dirty}): archived 2 file(s)" in log, log


def test_stray_worktrees_of_a_repository_in_the_project_root_are_found(env):
    """A repository directly in the project root (<repo>/.wt/t<id>) is asked for its worktrees too."""
    p = make(env)
    from ttp import worktree
    lib = p.root / "lib"
    lib.mkdir()
    _git_out(lib, "init", "-q")
    (lib / "a.txt").write_text("a")
    _git_out(lib, "add", "a.txt")
    _git_out(lib, "-c", "user.name=t", "-c", "user.email=t@example.invalid", "commit", "-qm", "first")
    t = p.db.add_task("done", "s", kind="code", tier="light", origin="user")
    _git_out(lib, "worktree", "add", "-q", "--detach", str(lib / ".wt" / f"t{t}"))
    got = worktree.stray_worktrees(p)
