def test_local_only_posts_no_burst_on_upgrade_and_flags_age_out(env):
    p = make(env)
    from ttp import daemon as dm
    _with_origin(env)
    old = []
    for i in range(4):
        tid, path, _ = _code_task(p, f"old {i}")
        _commit_file(path, f"o{i}")
        old.append(tid)
    d = dm.Daemon(p.base)   # first start with the check: earlier work is not flagged
    _check_local_only(d)
    assert not _local_only_events(p) and p.db.kv(dm.KV_LOCAL_ONLY) is None
    since = p.db.kv(dm.KV_LOCAL_ONLY_FROM)
    dm.Daemon(p.base)
    assert p.db.kv(dm.KV_LOCAL_ONLY_FROM) == since   # kept across restarts
    time.sleep(0.01)
    tid, path, _ = _code_task(p, "new")
    _commit_file(path, "n")
    d._local_only_due = 0
    _check_local_only(d)
    assert [e["task"] for e in _local_only_events(p)] == [tid]
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (time.time() - (dm.LOCAL_ONLY_DAYS + 1) * 86400, tid))
    p.db.set_kv(dm.KV_LOCAL_ONLY_FROM, 0)
    d._local_only_due = 0
    _check_local_only(d)
    assert p.db.kv(dm.KV_LOCAL_ONLY) == {str(t): p.db.kv(dm.KV_LOCAL_ONLY)[str(t)] for t in old}
    assert len(_local_only_events(p)) == 1 + len(old)

def _delivered_repo(env):
    """A repository with a base commit on main, for worktree.delivered."""
    r = env["tmp"] / "delivered"
    r.mkdir()
    _git_out(r, "init", "-q", "-b", "main")
    return r, _commit_files(r, {"a": "1\n2\n3\n4\n5\n6\n7\n8\n", "b": "x\n"}, "base")


def _commit_files(repo, files, msg):
    for name, text in files.items():
        (repo / name).write_text(text)
    _git_out(repo, "add", "-A")
    _git_out(repo, *_IDENT, "commit", "-qm", msg)
    return _git_out(repo, "rev-parse", "HEAD")


def _count_binary_diffs(monkeypatch, raise_on=None):
    """Count the binary diffs git is asked for; a command holding `raise_on` times out instead."""
    seen, real = [], subprocess.run

    def run(cmd, *a, **kw):
        if raise_on and raise_on in cmd:
            raise subprocess.TimeoutExpired(cmd, 120)
        if "--binary" in cmd:
            seen.append(cmd)
        return real(cmd, *a, **kw)
    monkeypatch.setattr(subprocess, "run", run)
    return seen


def test_delivered_builds_no_binary_diff_when_the_ref_left_a_changed_file_alone(env, monkeypatch):
    from ttp import worktree
    repo, _ = _delivered_repo(env)
    _git_out(repo, "checkout", "-qb", "feat")
    head = _commit_files(repo, {"a": "1\n2\nNEW\n4\n5\n6\n7\n8\n"}, "feature work on a")
    _git_out(repo, "checkout", "-q", "main")
    _commit_files(repo, {"b": "y\n"}, "other work on b only")
    diffs = _count_binary_diffs(monkeypatch)
    assert worktree.delivered(repo, head, "main") is False
    assert diffs == []


def test_delivered_finds_batched_work_and_remembers_it_per_ref_commit(env, monkeypatch):
    from ttp import worktree
    repo, _ = _delivered_repo(env)
    _git_out(repo, "checkout", "-qb", "feat")
    head = _commit_files(repo, {"a": "1\n2\nNEW\n4\n5\n6\n7\n8\n"}, "feature work on a")
    _git_out(repo, "checkout", "-q", "main")
    _commit_files(repo, {"a": "1\n2\nNEW\n4\n5\n6\n7\nLATER\n"}, "batch: lots of work squashed together")
    diffs = _count_binary_diffs(monkeypatch)
    assert worktree.delivered(repo, head, "main") is True
    assert len(diffs) == 1
    assert worktree.delivered(repo, head, "main") is True
    assert len(diffs) == 1                       # remembered for this (repo, head, ref commit)
    _commit_files(repo, {"b": "z\n"}, "the ref moved on")
    assert worktree.delivered(repo, head, "main") is True
    assert len(diffs) == 2                       # a new ref commit is looked at again
    assert worktree.delivered(repo, head, "no-such-ref") is False


def test_delivered_cache_is_bounded(env, monkeypatch):
    from ttp import worktree
    repo, _ = _delivered_repo(env)
    _git_out(repo, "checkout", "-qb", "feat")
    head = _commit_files(repo, {"a": "changed\n"}, "feature work on a")
    _git_out(repo, "checkout", "-q", "main")
    monkeypatch.setattr(worktree, "_DELIVERED_MAX", 2)
    worktree._DELIVERED.update({("r", "h1", "c"): True, ("r", "h2", "c"): True})
    assert worktree.delivered(repo, head, "main") is False
    assert list(worktree._DELIVERED) == [(str(repo), head, _git_out(repo, "rev-parse", "main"))]


@pytest.mark.parametrize("slow", ["--binary", "cherry"])
def test_delivered_counts_a_git_call_that_times_out_as_not_delivered(env, monkeypatch, slow):
    from ttp import worktree
    repo, _ = _delivered_repo(env)
    _git_out(repo, "checkout", "-qb", "feat")
    head = _commit_files(repo, {"a": "1\n2\nNEW\n4\n5\n6\n7\n8\n"}, "feature work on a")
    _git_out(repo, "checkout", "-q", "main")
    _commit_files(repo, {"a": "0\n1\n2\n3\n4\n5\n6\n7\n8\n"}, "unrelated change to a")
    _count_binary_diffs(monkeypatch, raise_on=slow)
    assert worktree.delivered(repo, head, "main") is False


def _dated_commit(repo, files, msg, date):
    """A commit with a fixed author date (a rebase or an amend keeps the original one)."""
    for name, text in files.items():
        (repo / name).write_text(text)
    _git_out(repo, "add", "-A")
    subprocess.run(["git", "-C", str(repo), *_IDENT, "commit", "-qm", msg], check=True, capture_output=True,
                   env={**os.environ, "GIT_AUTHOR_DATE": date})
    return _git_out(repo, "rev-parse", "HEAD")


def test_delivered_needs_more_than_a_subject_and_finds_a_squashed_reland(env):
    """A commit on the ref with the same subject but another author date and patch is other work;
    the same author, date and subject is a rebase that settled a conflict; one commit whose patch-id
    is the branch's whole change is a squashed re-land."""
    from ttp import worktree
    repo, _ = _delivered_repo(env)
    _git_out(repo, "checkout", "-qb", "feat")
    _dated_commit(repo, {"a": "1\n2\nFIRST\n4\n5\n6\n7\n8\n"}, "first part of the feature work", "1700000000 +0000")
    head = _dated_commit(repo, {"a": "1\n2\nFIRST\n4\n5\nSECOND\n7\n8\n"}, "second part of the feature work",
                         "1700000100 +0000")
    _git_out(repo, "checkout", "-q", "main")
    _dated_commit(repo, {"a": "1\n2\nOTHER\n4\n5\n6\n7\n8\n"}, "first part of the feature work", "1700000500 +0000")
    _dated_commit(repo, {"a": "1\n2\nOTHER\n4\n5\nMORE\n7\n8\n"}, "second part of the feature work",
                  "1700000600 +0000")
    assert worktree.delivered(repo, head, "main") is False, "the same subjects alone are not the same work"
    _git_out(repo, "checkout", "-q", "-B", "settled", f"{head}~2")
    _dated_commit(repo, {"a": "1\n2\nFIRST!\n4\n5\n6\n7\n8\n"}, "first part of the feature work", "1700000000 +0000")
    _dated_commit(repo, {"a": "1\n2\nFIRST!\n4\n5\nSECOND!\n7\n8\n"}, "second part of the feature work",
                  "1700000100 +0000")
    assert worktree.delivered(repo, head, "settled") is True, "same author, date and subject: rebased"
    _git_out(repo, "checkout", "-q", "-B", "squashed", f"{head}~2")
    _dated_commit(repo, {"b": "y\n"}, "other work", "1700000700 +0000")
    _dated_commit(repo, {"a": "1\n2\nFIRST\n4\n5\nSECOND\n7\n8\n"}, "re-land: the feature as one commit",
                  "1700000800 +0000")
    _dated_commit(repo, {"a": "1\n2\nFIRST later\n4\n5\nSECOND later\n7\n8\n"}, "later work", "1700000900 +0000")
    assert worktree.delivered(repo, head, "squashed") is True, "the whole change's patch-id is one commit there"
    _git_out(repo, "checkout", "-q", "-B", "settled-squash", f"{head}~2")
    _dated_commit(repo, {"a": "1\n2\nFIRST\n4\n5\nSECOND, settled\n7\n8\n"}, "re-land: the feature as one commit",
                  "1700000800 +0000")
    _dated_commit(repo, {"a": "1\n2\nFIRST later\n4\n5\nSECOND later\n7\n8\n"}, "later work", "1700000900 +0000")
    assert worktree.delivered(repo, head, "settled-squash") is False, "a settled squash needs a record"


def test_local_only_clears_a_branch_recorded_as_superseded_by_a_commit_on_the_push_branch(env, monkeypatch, capsys):
    """A re-land after a push conflict puts a task's work on the push branch as one new commit with
    another patch and subject: the check flags it until a task records the commit that carries it.
    The record needs that commit on the push branch, covers the branch head it was made at, and also
    answers `landed:#<id>`."""
    from ttp import cli, landed
    from ttp import daemon as dm
    p, repo, other, tid, path, branch, head = _landed_setup(env, monkeypatch)
    _commit(path, "more.txt", "a\nb\n")
    _commit(path, "more.txt", "a\nb\nc\n")
    mine = _git_out(path, "rev-parse", "HEAD")
    (other / "more.txt").write_text("a\nb, settled\nc\n")
    _git_out(other, "add", "more.txt")
    _git_out(other, "commit", "-qm", "re-land of the more work after a push conflict")
    relanded = _git_out(other, "rev-parse", "HEAD")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    d = _local_only_daemon(p)
    _check_local_only(d)
    assert [e["task"] for e in _local_only_events(p)] == [tid]
    assert f"ttp task {p.name} superseded {tid} <sha>" in _local_only_events(p)[0]["text"]
    assert landed.check(p, repo, tid=tid)[0] == 1

    def ttp_task(*args):
        try:
            cli.main(["task", p.name, *args])
        except SystemExit as e:
            return e.code
        return 0
    assert ttp_task("superseded", str(tid), mine) not in (0, None), "the branch's own head is not on the push branch"
    assert ttp_task("superseded", str(tid)) not in (0, None)
    assert p.db.q("SELECT * FROM task_superseded") == []
    assert ttp_task("superseded", str(tid), relanded[:12]) == 0
    assert f"recorded as superseded by {relanded[:10]}" in capsys.readouterr().out
    assert landed.superseded(p.db, [tid]) == {tid: [(mine, relanded)]}
    assert landed.check(p, repo, tid=tid)[0] == 0
    d._local_only_due = 0
    _check_local_only(d)
    assert p.db.kv(dm.KV_LOCAL_ONLY) is None
    _commit(path, "after.txt", "new work after the record\n")
    d._local_only_due = 0
    _check_local_only(d)
    assert set(p.db.kv(dm.KV_LOCAL_ONLY) or {}) == {str(tid)}, "work past the recorded head is flagged again"


def test_superseded_refuses_a_commit_that_cannot_carry_the_branchs_work(env, monkeypatch, capsys):
    """A record hides the branch for good at its head, so it must name a commit that can hold the
    work: not the branch's base or another commit the branch already has, not a later push-branch
    commit that changes none of the branch's files, and only for a done task."""
    from ttp import cli, landed
    from ttp import daemon as dm
    p, repo, other, tid, path, branch, head = _landed_setup(env, monkeypatch)
    _commit(path, "more.txt", "a\nb\n")
    _commit(path, "more.txt", "a\nb\nc\n")
    _commit(other, "unrelated.txt", "other work\n")
    unrelated = _git_out(other, "rev-parse", "HEAD")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    _git_out(repo, "fetch", "-q", "origin")
    base = _git_out(repo, "merge-base", branch, "origin/proj")
    d = _local_only_daemon(p)
    _check_local_only(d)
    assert set(p.db.kv(dm.KV_LOCAL_ONLY) or {}) == {str(tid)}

    def ttp_task(*args):
        try:
            cli.main(["task", p.name, *args])
        except SystemExit as e:
            return e.code
        return 0
    assert ttp_task("superseded", str(tid), base) not in (0, None)
    assert "predates the work" in capsys.readouterr().err
    assert ttp_task("superseded", str(tid), unrelated) not in (0, None)
    assert "changes none of the files" in capsys.readouterr().err
    with pytest.raises(ValueError, match="not done"):
        p.db.update_task(tid, status="running")
        landed.record_superseded(p, tid, unrelated)
    p.db.update_task(tid, status="done")
    assert p.db.q("SELECT * FROM task_superseded") == []
    d._local_only_due = 0
    _check_local_only(d)
    assert set(p.db.kv(dm.KV_LOCAL_ONLY) or {}) == {str(tid)}, "the undelivered work stays flagged"


def test_a_task_whose_change_landed_under_another_commit_gets_no_review_or_fix(env, monkeypatch):
    """Replay of a duplicate: a code task's one commit (its change plus a version bump and changeset)
    sits in review while a fix chain of another task rebased the change and the push queue landed it
    as a new commit, without the bump and with other context around it, so git's patch-id differs. The
    sweep, the daemon's review and the fix of a failed review all find it landed: the task is recorded
    as superseded and closed, the coordinator is told once, and no review or fix is queued."""
    from ttp import landed
    from ttp.daemon import Daemon
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    BUMP = {"files": ["VERSION"], "changeset_dir": ".changeset"}
    p.set_config("delivery.version_bump", BUMP)
    lines = [f"line {i}" for i in range(1, 11)]
    (repo / "VERSION").write_text("0.1.0\n")
    (repo / "app.txt").write_text("\n".join(lines) + "\n")
    _git_out(repo, "add", "VERSION", "app.txt")
    _git_out(repo, "commit", "-qm", "base")
    _git_out(repo, "push", "-q", "origin", "HEAD:proj")
    _git_out(other, "pull", "-q", "origin", "proj")
    tid, path, branch = _code_task(p, "duplicate change", status="review")
    p.db.update_task(tid, result=json.dumps({"status": "done", "summary": "made the change"}))
    change = lines[:5] + ["line 6 changed"] + lines[6:]
    (path / "app.txt").write_text("\n".join(change) + "\n")
    (path / "VERSION").write_text("0.1.1\n")
    (path / ".changeset").mkdir()
    (path / ".changeset" / "change.md").write_text("the change\n")
    _git_out(path, "add", "-A")
    _git_out(path, "commit", "-qm", "the change, with its version bump")
    head = _git_out(path, "rev-parse", "HEAD")
    assert landed.equivalent(p, branch, BUMP) is None, "not landed yet"
    # Another task's chain: a neighbouring change first, then the same change re-landed, then a fix.
    (other / "app.txt").write_text("\n".join(lines[:3] + ["line 4 by someone else"] + lines[4:]) + "\n")
    _git_out(other, "commit", "-qam", "a neighbouring change")
    (other / "app.txt").write_text("\n".join(lines[:3] + ["line 4 by someone else"] + change[4:]) + "\n")
    _git_out(other, "commit", "-qam", "re-land of the change under another task")
    relanded = _git_out(other, "rev-parse", "HEAD")
    _commit(other, "fix.txt", "a later fix of the change\n")
    _git_out(other, "push", "-q", "origin", "HEAD:proj")
    _git_out(repo, "fetch", "-q", "origin")
    tip = _git_out(repo, "rev-parse", "origin/proj")
    assert not landed.on_branch(repo, head, tip), "git's patch-id and the commit keys miss it"
    assert landed.equivalent(p, branch, None) is None, "the version files count unless excluded"
    assert landed.equivalent(p, branch, BUMP) == (relanded, head)

    def reset():
        p.db.x("DELETE FROM task_superseded")
        p.db.x("DELETE FROM events WHERE kind='task_superseded'")
        p.db.update_task(tid, status="review")

    def told():
        return p.db.q("SELECT status, text FROM events WHERE kind='task_superseded' AND task=?", (tid,))

    def closed():
        t = p.db.task(tid)
        assert t["status"] == "done" and json.loads(t["result"])["superseded_by"] == relanded
        assert landed.superseded(p.db, [tid]) == {tid: [(head, relanded)]}
        (e,) = told()
        assert e["status"] == "queued" and relanded[:10] in e["text"] and "no review or fix" in e["text"]
        assert not p.db.q("SELECT id FROM tasks WHERE id!=? AND status NOT IN ('done','failed','cancelled')",
                          (tid,)), "no review or fix queued"

    _ran(p, tid, time.time() - 1900)
    d = Daemon(p.base)
    _sweep(d)
    closed()
    _sweep(d)
    assert len(told()) == 1, "told once"
    reset()
    assert d._auto_review(p.db.task(tid), "made the change") is None
    closed()
    reset()
    review = p.db.add_task(f"Review #{tid}: duplicate change", "Review it.", kind="review", origin="coordinator",
                           depends_on=[tid])
    p.db.update_task(review, status="failed")
    assert d._fix_failed_review(p.db.task(review), [{"title": "fix it", "spec": "fix the finding"}], "bad") is None
    closed()


def _done_code_task_on(p, branch):
    tid = p.db.add_task("example work", "s", kind="code", tier="light", origin="user")
    p.db.update_task(tid, status="done", branch=branch)
    return tid


def test_local_only_check_runs_off_the_tick_and_a_later_tick_applies_it(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm
    tid = _done_code_task_on(p, "ttp/t1-example")
    d = _local_only_daemon(p)
    go, calls, on_tick = threading.Event(), [], []

    def slow(repo, branches, targets=(), known=frozenset(), timeout_s=0, pushed=frozenset(), superseded=None):
        calls.append(branches)
        on_tick.append(threading.current_thread() is threading.main_thread())
        go.wait(10)
        return {"ttp/t1-example": ("abc1234", 2)}, True, {}
    monkeypatch.setattr(dm.worktree, "local_only", slow)
    monkeypatch.setattr(dm.worktree, "base_ref", lambda p: "main")
    d.check_local_only()
    d.check_local_only()                         # still running: neither applied nor started again
    assert p.db.kv(dm.KV_LOCAL_ONLY) is None and d._local_only_job is not None
    go.set()
    _finish_local_only(d)
    assert p.db.kv(dm.KV_LOCAL_ONLY)[str(tid)]["head"] == "abc1234"
    assert [e["task"] for e in _local_only_events(p)] == [tid]
    d.check_local_only()                         # not due again for an hour
    assert len(calls) == 1 and d._local_only_job is None
    assert on_tick == [False], "the tick waited for git"


def _backup_remote(env, name="backup"):
    remote = env["tmp"] / f"{name}.git"
    subprocess.run(["git", "init", "-q", "--bare", str(remote)], check=True)
    subprocess.run(["git", "-C", str(env["repo"]), "remote", "add", name, str(remote)], check=True)
    return remote


def _finish_backup(d):
    """One backup_branches pass as the daemon runs it: started on one tick, applied on a later one."""
    d.backup_branches()
    job = d._backup_job
    if job is not None:
        assert job["done"].wait(60), "the backup pushes did not finish"
        d.backup_branches()
        assert d._backup_job is None


def _remote_head(remote, branch):
    out = subprocess.run(["git", "-C", str(remote), "rev-parse", "--verify", "--quiet", f"refs/heads/{branch}"],
                         capture_output=True, text=True)
    return out.stdout.strip()


def test_backup_remote_is_off_by_default_and_pushes_nothing(env):
    p = make(env)
    from ttp import daemon as dm
    assert "backup_remote" not in p.config()["delivery"]
    remote = _backup_remote(env, "origin")
    p.set_config("review.auto", False)
    tid, path, branch = _code_task(p, "hand-off", status="queued")
    _commit_file(path, "a")
    d = _local_only_daemon(p)
    d._local_only_due = time.time() + 3600
    assert _run_until(d, p, lambda: p.db.task(tid)["status"] == "done")
    _finish_backup(d)
    _finish_local_only(d)
    assert p.db.kv(dm.KV_BACKUP) is None and not _remote_head(remote, branch)
    assert [e["task"] for e in _local_only_events(p)] == [tid]   # the local-only event stays as is


def test_backup_remote_gets_a_finished_task_branch_and_skips_a_non_fast_forward(env):
    p = make(env)
    from ttp import daemon as dm
    remote = _backup_remote(env)
    p.set_config("delivery.backup_remote", "backup")
    p.set_config("review.auto", False)
    tid, path, branch = _code_task(p, "hand-off", status="queued")
    _commit_file(path, "a")
    d = _local_only_daemon(p)
    d._local_only_due = time.time() + 3600
    assert _run_until(d, p, lambda: p.db.task(tid)["status"] == "done")
    _finish_local_only(d)   # a branch still to be backed up is not flagged meanwhile
    assert not _local_only_events(p)
    _finish_backup(d)
    head = _git_out(path, "rev-parse", "HEAD")
    assert _remote_head(remote, branch) == head and p.db.kv(dm.KV_BACKUP) is None
    _finish_local_only(d)
    assert not _local_only_events(p)   # the backup remote has it
    # Another copy moved on there: the rewritten local branch is not a fast-forward and is not forced.
    other = env["tmp"] / "other"
    subprocess.run(["git", "clone", "-q", "-b", branch, str(remote), str(other)], check=True)
    _commit_file(other, "theirs")
    _git_out(other, "push", "-q", "origin", branch)
    theirs = _remote_head(remote, branch)
    _git_out(path, *_IDENT, "commit", "-q", "--amend", "-m", "rewritten")
    d._queue_backup(p.db.task(tid))
    _finish_backup(d)
    assert _remote_head(remote, branch) == theirs and p.db.kv(dm.KV_BACKUP) is None
    obs = p.db.q("SELECT text, task FROM events WHERE kind='observation'")
    assert len(obs) == 1 and obs[0]["task"] == tid and "not a fast-forward" in obs[0]["text"], obs
    assert "nothing was forced" in obs[0]["text"]


def test_backup_remote_refuses_to_name_a_branch(env):
    p = make(env)
    from ttp import coordinator as coord, push
    from ttp import daemon as dm
    from ttp.project import config_problems
    d = {"push_branch": "origin/team/work", "base_ref": "origin/dev"}
    for bad in ("main", "master", "origin/team/work", "team/work", "origin/dev", "dev"):
        assert "names a branch" in push.backup_problem({**d, "backup_remote": bad}) \
            or "not a git remote" in push.backup_problem({**d, "backup_remote": bad}), bad
        assert config_problems({"delivery": {**d, "backup_remote": bad}}), bad
    assert push.backup_problem({**d, "backup_remote": "backup"}) == ""
    assert push.backup_problem({**d, "backup_remote": ""}) == ""
    assert push.backup(env["repo"], "backup", "main")[0] == "refused"   # only ttp/t<id>-... branches
    p.set_config("delivery.base_ref", "dev")
    bad = {"type": "config_set", "key": "delivery.backup_remote", "value": "dev"}
    notes = coord.apply(p, [bad], user_turn=True)
    assert notes and "names a branch" in notes[0], notes
    assert "ask_user (blocking access)" in coord.apply(p, [{**bad, "value": "backup"}])[0]
    assert coord.apply(p, [{**bad, "value": "backup"}], user_turn=True) == []
    assert coord.apply(p, [{**bad, "value": ""}]) == []   # off needs no one's word
    # A key that names a branch anyway (edited by hand) pushes nothing and drops the queue.
    p.set_config("delivery.base_ref", "")
    remote = _backup_remote(env, "main")
    p.set_config("delivery.backup_remote", "main")
    tid, path, branch = _code_task(p, "work")
    _commit_file(path, "a")
    dm_ = dm.Daemon(p.base)
    dm_._queue_backup(p.db.task(tid))
    _finish_backup(dm_)
    assert p.db.kv(dm.KV_BACKUP) is None and not _remote_head(remote, branch)


def test_dirty_main_checkout_at_hand_off_is_observed_once_per_path_set(env):
    p = make(env)
    from ttp import daemon as dm
    d = dm.Daemon(p.base)
    task = p.db.task(p.db.add_task("t", "s", kind="code", tier="light", origin="user"))
    obs = lambda: p.db.q("SELECT text FROM events WHERE kind='observation'")
    d._note_dirty_main(task)
    assert not obs()
    (env["repo"] / "README.md").write_text("edited\n")
    (env["repo"] / "untracked.txt").write_text("not tracked\n")
    d._note_dirty_main(task)
    d._note_dirty_main(task)
    assert len(obs()) == 1 and "README.md" in obs()[0]["text"] and "untracked" not in obs()[0]["text"]
    assert "Nothing was committed or changed" in obs()[0]["text"]
    assert (env["repo"] / "README.md").read_text() == "edited\n"
    assert _git_out(env["repo"], "status", "--porcelain", "--untracked-files=no") == "M README.md"
    _git_out(env["repo"], "checkout", "README.md")
    d._note_dirty_main(task)
    (env["repo"] / "README.md").write_text("edited again\n")
    d._note_dirty_main(task)
    assert len(obs()) == 2   # clean in between: the same paths count again


def test_local_only_check_that_raises_in_its_thread_is_logged_and_not_left_running(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dm
    _done_code_task_on(p, "ttp/t1-example")
    d = _local_only_daemon(p)
    calls = []

    def broken(repo, branches, **kw):
        calls.append(branches)
        raise RuntimeError("git exploded")
    monkeypatch.setattr(dm.worktree, "local_only", broken)
    monkeypatch.setattr(dm.worktree, "base_ref", lambda p: "main")
    _check_local_only(d)
    assert d._local_only_job is None and len(calls) == 1
    assert "local-only branch check: Traceback" in (p.logs / "daemon.log").read_text()
    assert "git exploded" in (p.logs / "daemon.log").read_text()
    assert not _local_only_events(p) and p.db.kv(dm.KV_LOCAL_ONLY) is None
    d._local_only_due = 0                        # the next check starts again when due
    _check_local_only(d)
    assert len(calls) == 2 and d._local_only_job is None


