def test_the_disk_guard_alert_says_what_fills_the_disk_and_the_projects_share(env, monkeypatch):
    import collections
    p = make(env)
    from ttp import coordinator as coord
    from ttp import daemon as dm
    other = env["tmp"] / "someone-elses-cache"
    other.mkdir()
    with open(other / "blob", "wb") as fh:  # far bigger than the repo and runtime copy can grow
        for _ in range(32):
            fh.write(os.urandom(1 << 20))
    (p.root / "build.bin").write_bytes(os.urandom(1 << 20))   # the code repo is not the project's own data
    wt = p.runs / "7" / "wt"     # a worktree a worker left in its run directory
    wt.mkdir(parents=True)
    (wt / ".git").write_text("gitdir: /nowhere\n")
    (wt / "big.bin").write_bytes(os.urandom(3 << 20))
    (p.runs / "7" / "log.txt").write_bytes(os.urandom(1 << 20))
    usage = collections.namedtuple("usage", "total used free")
    monkeypatch.setattr(dm.shutil, "disk_usage", lambda path: usage(1000e9, 960e9, 40e9))
    b = dm.disk_breakdown(p, p.base)
    assert b["complete"] and b["own_complete"] and b["mount"] == str(env["tmp"])
    top = dict(b["top"])
    assert top[str(other)] >= 32 << 20 and top[str(env["repo"])] >= 1 << 20, top
    assert next(iter(top)) == str(other), "the biggest directory comes first"
    assert (4 << 20) <= b["own_bytes"] < top[str(other)]
    assert b["own_folders"] == [str(p.state.resolve())] + ([str(p.worktrees.resolve())] if p.worktrees.is_dir() else [])
    cons = {label: (n, count) for label, n, count in b["own_consumers"]}
    assert cons["run worktrees"][1] == 1 and (3 << 20) <= cons["run worktrees"][0] < (4 << 20), cons
    assert (1 << 20) <= cons["state/runs (other run files)"][0] < (2 << 20), cons
    assert b["own_consumers"][0][0] == "run worktrees", "the biggest consumer comes first"
    dm.Daemon(p.base).check_disk()
    text = p.db.one("SELECT text FROM messages WHERE kind='alert' AND ref='disk'")["text"]
    mb = b["own_bytes"] / 1e6
    assert (f"This project's own data (state/ and worktrees/) is {mb:.1f} MB of the 960.0 GB used on "
            f"{env['tmp']} (run worktrees: 1, ") in text, text
    assert "0.0 GB of" not in text and "or more" not in text, text
    assert f"biggest top-level directories: {other} 0.0 GB" in text, text
    assert "--min-free-gb" in text
    assert "This project's own data" in coord.digest(p, {}, [], [])


def test_the_disk_breakdown_keeps_what_du_measured_before_its_time_ran_out(env, monkeypatch):
    import subprocess as sp
    p = make(env)
    from ttp import daemon as dm

    def slow(cmd, timeout):
        assert timeout <= dm.DISK_DU_TIMEOUT_S
        if cmd[-1] == str(p.state.resolve()):   # cut short: only the archive was finished
            return f"{5 * 10 ** 6}\t{p.state.resolve() / 'archive'}\n".encode(), False
        if cmd[-1] != str(dm._mount_of(p.base)):
            return b"", True
        return f"{700 * 10 ** 6}\t/data/scratch\n".encode(), False
    monkeypatch.setattr(dm, "_run_bounded", slow)
    b = dm.disk_breakdown(p, p.base)
    assert b["top"] == [("/data/scratch", 700 * 10 ** 6 * 1024)] and not b["complete"] and not b["own_complete"]
    assert b["own_bytes"] == 5 * 10 ** 6 * 1024
    line = dm.disk_usage_line(b, 900e9)
    assert line == (f"This project's own data (state/ and worktrees/) is at least 5.1 GB (partial: what du measured "
                    f"within {dm.DISK_DU_TIMEOUT_S // 2} s) of the 900.0 GB used on {env['tmp']} (state/archive 5.1 GB); "
                    f"biggest top-level directories (du stopped after {dm.DISK_DU_TIMEOUT_S} s; partial): "
                    "/data/scratch 716.8 GB."), line
    assert "or more" not in line
    monkeypatch.setattr(dm, "_run_bounded", lambda cmd, timeout: (b"", False))   # du printed nothing at all
    line = dm.disk_usage_line(dm.disk_breakdown(p, p.base), 900e9)
    assert "this project's own data (state/ and worktrees/) was not measured" in line and " 0.0 GB" not in line, line


def _measured_by_pairs(sizes, root):
    """The disk breakdown's former _measured (every path pair compared): the reference its fast one must equal."""
    from pathlib import Path
    if str(root) in sizes:
        return sizes[str(root)]
    done = []
    for k in sorted(sizes, key=lambda k: len(Path(k).parts)):
        q = Path(k)
        if root in q.parents and not any(d in q.parents for d in done):
            done.append(q)
    return sum(sizes[str(d)] for d in done)


def test_the_disk_breakdown_sums_a_partial_du_output_in_linear_time(env, monkeypatch):
    """Note 7ef8a2c60a779672: du cut off at its time limit prints no line for the folders it had not
    finished, and _measured then compared every path pair, stalling the dispatch tick for minutes on a
    big state/. It must give the same bytes as before, and replaying a large partial du output (root
    lines dropped) through own_usage must take well under a second or two."""
    import random
    import time as _t
    from pathlib import Path
    p = make(env)
    from ttp import daemon as dm
    root = Path("/x/state")
    cases = [
        {},
        {"/x/state": 9, "/x/state/a": 4},                                    # root finished: its own line
        {"/x/state/a": 4, "/x/state/a/b": 3, "/x/state/c/d": 2},             # outermost finished entries
        {"/x/state/a/b": 3, "/x/state/a/b/c": 1, "/x/state/ab": 5},          # a sibling sharing a prefix
        {"/x/stateful/a": 7, "/x/state/q": 1, "/y/state/q": 6, "/x": 99},    # outside the root: not counted
        {"/x/state/a/b/c": 1, "/x/state/a/b/d": 2, "/x/state/a/e": 3},
    ]
    rng = random.Random(7)
    for _ in range(200):
        sizes = {}
        for _ in range(rng.randint(1, 30)):
            parts = [rng.choice("abc") for _ in range(rng.randint(1, 4))]
            sizes["/x/state/" + "/".join(parts)] = rng.randint(1, 100)
        cases.append(sizes)
    for sizes in cases:
        for r in (root, root / "a", root / "a" / "b", Path("/x"), Path("/x/stat")):
            assert dm._measured(sizes, r) == _measured_by_pairs(sizes, r), (sizes, r)
            assert dm._measured(sizes, r, dm._ancestry(sizes)) == _measured_by_pairs(sizes, r), (sizes, r)
    # A big state/ whose du was stopped: run directories finished, runs/ and state/ themselves not.
    state, runs = p.state.resolve(), p.runs.resolve()
    lines = [f"4\t{runs / str(r) / sub}" for r in range(4000) for sub in ("wt", "logs", "tmp")]
    lines += [f"12\t{runs / str(r)}" for r in range(4000)] + [f"8\t{state / 'archive'}"]
    big = "\n".join(lines).encode()
    for r in range(30):   # own_usage asks _measured for each run worktree it finds
        (runs / str(r) / "wt").mkdir(parents=True)
        (runs / str(r) / "wt" / ".git").write_text("gitdir: /nowhere\n")
    monkeypatch.setattr(dm, "_run_bounded", lambda cmd, timeout: (big if cmd[-1] == str(state) else b"", False))
    start = _t.monotonic()
    own = dm.own_usage(p, dm.os.stat(state).st_dev, [], 30)
    took = _t.monotonic() - start
    assert own["bytes"] == (4000 * 12 + 8) * 1024 and not own["complete"], own
    assert ("run worktrees", 30 * 4 * 1024, 30) in own["consumers"], own["consumers"]
    assert took < 5, f"own_usage took {took:.1f} s on a partial du output of {len(lines)} lines"


def test_disk_scans_never_walk_root_home_or_network_mounts(env, monkeypatch, tmp_path):
    from pathlib import Path
    p = make(env)
    from ttp import daemon as dm
    from ttp import worktree as wt
    mounts = tmp_path / "mounts"
    net = env["tmp"] / "shared-net"
    mounts.write_text(f"/dev/sda1 / ext4 rw 0 0\nhost:/vol {net} nfs4 rw 0 0\nfs {tmp_path}/f fuse.sshfs rw 0 0\n")
    real = Path.read_text
    monkeypatch.setattr(Path, "read_text", lambda self, *a, **k: real(mounts if str(self) == "/proc/self/mounts" else self, *a, **k))
    nets = dm.network_mounts()
    assert net in nets and tmp_path / "f" in nets and Path("/") not in nets
    assert not dm._scan_ok(Path("/"), nets) and not dm._scan_ok(Path.home(), nets)
    assert not dm._scan_ok(env["tmp"], nets), "a dir holding a network mount is not scanned"
    assert dm._scan_ok(p.root.resolve(), nets)
    ran = []
    monkeypatch.setattr(dm, "_run_bounded", lambda cmd, timeout: (ran.append(cmd), (b"", True))[1])
    b = dm.disk_breakdown(p, p.base)
    assert b["top_skipped"] and not b["top"] and all(c[-1] != str(env["tmp"]) for c in ran), ran
    assert "top-level directories unknown" in dm.disk_usage_line(b, 1e9)
    monkeypatch.setenv("TTP_TEST_DISK_MOUNT", "/")
    ran.clear()
    dm.disk_breakdown(p, p.base)
    assert all(c[-1] != "/" for c in ran), "never du from /"
    (net / "x").mkdir(parents=True)
    (net / "x" / "f").write_bytes(b"1" * 100)
    assert wt._size(env["tmp"], ["shared-net"]) == 0, "a network mount is never walked"


