    for also in (None, [], ""):
        if also is not None:
            p.set_config("delivery.fast_forward_also", also)
        _commit(repo, "mine.txt", f"{also!r}\n")
        assert push.run(p, repo) == 0
        assert _git_out(origin, "rev-parse", "main") == main and push.last_ff == []


