def test_a_login_ends_the_logged_out_pause_without_a_model_call(env, monkeypatch, tmp_path):
    creds = tmp_path / "creds.json"
    creds.write_text("{}")
    monkeypatch.setenv("TTP_FAKE_CREDENTIALS", str(creds))
    p = make(env)
    from ttp.daemon import Daemon
    from ttp.providers import get_provider
    d = Daemon(p.base)
    p.db.set_kv("limited:fake", {"until": time.time() + 900, "note": "logged out",
                                 "creds": get_provider("fake").credentials_stamp()})
    d.update_gates()
    assert d.gates["fake"].level == "red" and d._provider_pause("fake")
    runs = p.db.one("SELECT COUNT(*) n FROM runs")["n"]
    creds.write_text('{"token": "new login"}')
    d.update_gates()
    assert d.gates["fake"].level != "red"
    assert (p.db.kv("limited:fake") or {}).get("until", 0) <= time.time()
    assert p.db.one("SELECT COUNT(*) n FROM runs")["n"] == runs   # detected by a stat, not a model turn


def test_a_login_that_creates_the_missing_credentials_file_ends_the_pause(env, monkeypatch, tmp_path):
    creds = tmp_path / "creds.json"   # logged out with no credentials file yet
    monkeypatch.setenv("TTP_FAKE_CREDENTIALS", str(creds))
    p = make(env)
    from ttp.daemon import Daemon
    from ttp.providers import get_provider
    d = Daemon(p.base)
    p.db.set_kv("limited:fake", {"until": time.time() + 900, "note": "logged out",
                                 "creds": get_provider("fake").credentials_stamp()})
    assert d._provider_pause("fake")
    creds.write_text("{}")
    assert d._provider_pause("fake") is None
    monkeypatch.delenv("TTP_FAKE_CREDENTIALS")   # a provider without credential files waits the pause out
    p.db.set_kv("limited:fake", {"until": time.time() + 900, "note": "logged out",
                                 "creds": get_provider("fake").credentials_stamp()})
    assert d._provider_pause("fake")


def test_cursor_credential_file_follows_xdg_config_home(env, monkeypatch, tmp_path):
    from ttp.providers import get_provider
    monkeypatch.setenv("XDG_CONFIG_HOME", str(tmp_path))
    cursor = get_provider("cursor")
    assert cursor.credential_files() == [str(tmp_path / "cursor" / "auth.json")]
    before = cursor.credentials_stamp()
    (tmp_path / "cursor").mkdir()
    (tmp_path / "cursor" / "auth.json").write_text("{}")
    assert cursor.credentials_stamp() != before
    monkeypatch.delenv("XDG_CONFIG_HOME")
    monkeypatch.setenv("HOME", str(tmp_path))
    assert cursor.credential_files() == [str(tmp_path / ".config" / "cursor" / "auth.json")]


def _due_waiting_task(p, probe, since_ago=600.0, **extra):
    now = time.time()
    tid = p.db.add_task("measure", "s", kind="work", tier="light", origin="user", not_before=now - 1)
    p.db.update_task(tid, result=json.dumps({"status": "waiting", "summary": "board busy", "waiting_for": "a board",
                                             "retry_after_s": 900, "retry_when": probe,
                                             "waiting_since": now - since_ago, **extra}))
    return tid


def _settle_probe(d, tid):
    d.probe_waiting()
    if tid in d._probes:
        d._probes[tid][0].wait(_load_scaled(60))
        d.probe_waiting()


def _ready(p, tid):
    return tid in [t["id"] for t in p.db.ready_tasks()]


def _ssh_255(p, up=False):
    """A stand-in `ssh` first on the probes' PATH (the harness bin): a host that does not answer
    (exit 255, ssh's own error), or with `up` one that answers: `true` passes, any other remote
    command fails (exit 1). No real host is contacted. Returns a probe that reaches box-a over it."""
    b = p.harness / "bin"
    b.mkdir(parents=True, exist_ok=True)
    act = ('[ "$*" = true ] && exit 0; exit 1' if up
           else 'echo "ssh: connect to host $host port 22: Connection timed out" >&2; exit 255')
    (b / "ssh").write_text("#!/bin/sh\n"
                           "while [ $# -gt 0 ]; do case $1 in -o) shift 2;; -*) shift;; *) break;; esac; done\n"
                           f"host=$1; shift\n{act}\n")
    (b / "ssh").chmod(0o755)
    return "ssh -o BatchMode=yes box-a test -e /tmp/marker"


def test_a_due_waiting_task_sleeps_on_while_its_probe_says_not_yet(env):
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    tid = _due_waiting_task(p, "exit 1")
    d.probe_waiting()
    assert not _ready(p, tid) and tid in d._probes, "with no verdict yet it must ask the probe before waking"
    d._probes[tid][0].wait(10)
    d.probe_waiting()          # reaps the probe: exit 1
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()          # due with a fresh "not yet": extended, not run
    task = p.db.task(tid)
    assert not _ready(p, tid) and task["not_before"] > time.time() + 800, task["not_before"] - time.time()
    assert "probe says not yet" in task["blocked_reason"]
    assert "woke" not in json.loads(task["result"])
    assert f"task {tid} retry_when probe still failing" in (p.logs / "daemon.log").read_text()


def test_a_waiting_task_wakes_when_its_probe_passes_and_says_so(env, monkeypatch):
    p = make(env)
    from ttp import daemon as dmod
    from ttp.prompts import worker_task
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid = _due_waiting_task(p, "true")
    p.db.update_task(tid, not_before=time.time() + 3600)
    _settle_probe(d, tid)
    assert _ready(p, tid)
    assert "Woken because: probe passed." in worker_task(p, p.db.task(tid), str(p.root), None)


def _checks_wait_task(p, tmp_path, on_pass=None, rc="0", tier="standard"):
    """A code task that handed off `waiting` on its own detached `ttp checks`, which ended with `rc`."""
    from ttp import push, worktree
    now = time.time()
    tid = p.db.add_task("fix the parser", "s", kind="code", tier=tier, origin="user")
    path, branch = worktree.ensure(p, p.db.task(tid))
    p.db.update_task(tid, branch=branch)
    (path / "fix.txt").write_text("fixed\n")
    git = ["git", "-C", str(path)]
    subprocess.run([*git, "add", "fix.txt"], check=True, capture_output=True)
    subprocess.run([*git, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "fix"], check=True,
                   capture_output=True)
    head = subprocess.run([*git, "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    run_dir = tmp_path / f"run-{tid}"
    run_dir.mkdir()
    p.db.x("INSERT INTO runs(task,role,provider,started,ended,status,dir) VALUES(?,?,?,?,?,?,?)",
           (tid, "worker", "fake", now - 120, now - 60, "ok", str(run_dir)))
    hand = {"status": "waiting", "summary": "checks running", "waiting_for": "my checks", "retry_after_s": 900,
            "retry_when": f"{push._own_ttp(p)} checks --result {shlex.quote(str(run_dir))}"}
    if on_pass is not None:
        hand["on_pass"] = on_pass
    (run_dir / "result.json").write_text(json.dumps(hand))
    if rc is not None:
        (run_dir / "checks.rc").write_text(f"{rc}\n")
    (run_dir / "checks.out").write_text("collected 9 items\nFAILED tests/test_x.py::test_parses_empty\n"
                                        "ttp checks: 'pytest -q' failed\n")
    (run_dir / "checks.json").write_text(json.dumps({"head": head, "worktree": str(path), "passed": rc == "0",
                                                     "commands": ["pytest -q"], "skipped": [], "ts": now}))
    p.db.update_task(tid, status="queued", not_before=now + 3600,
                     result=json.dumps({**hand, "waiting_since": now - 60}))
    return tid, path


DONE_ON_PASS = {"status": "done", "summary": "parser fixed; checks pass", "artifacts": ["fix.txt"],
                "metrics": {"tests": "9 passed"}}


def test_passed_checks_record_the_on_pass_hand_off_without_a_model_run(env, monkeypatch, tmp_path):
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid, _ = _checks_wait_task(p, tmp_path, DONE_ON_PASS)
    _settle_probe(d, tid)
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert task["status"] == "done", (task["status"], task["blocked_reason"], res)
    assert res["summary"] == "parser fixed; checks pass" and res["run_status"] == "model-free"
    assert res["metrics"] == {"tests": "9 passed"} and res["artifacts"] == ["fix.txt"]
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1, "a model run was started"
    # The normal finish: its review is queued, and the event says no model ran.
    assert p.db.q("SELECT id FROM tasks WHERE kind='review'"), "the review did not start as usual"
    ev = p.db.one("SELECT text FROM events WHERE kind='task_done' AND task=?", (tid,))
    assert "run model-free" in ev["text"] and "$0.00" in ev["text"]
    assert "recorded its on_pass (done) model-free" in (p.logs / "daemon.log").read_text()
    for _ in range(3):
        d.tick()
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


@pytest.mark.parametrize("rc", ["1", "killed"])
def test_failed_checks_wake_the_task_at_its_own_tier_with_their_output(env, monkeypatch, tmp_path, rc):
    p = make(env)
    from ttp import budget as bud, daemon as dmod
    from ttp.prompts import worker_task
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid, _ = _checks_wait_task(p, tmp_path, DONE_ON_PASS, rc=rc)
    _settle_probe(d, tid)
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert _ready(p, tid) and task["status"] == "queued" and task["attempts"] == 0
    assert bud.wake_tier(task["tier"], res) == "standard", res
    prompt = worker_task(p, task, str(p.root), None, wake={"tier": "standard", "escalated": True})
    assert "FAILED tests/test_x.py::test_parses_empty" in prompt
    assert ("killed" if rc == "killed" else "exit 1") in res["woke"]
    assert "mechanical step" not in prompt and "check whether the wait is over" not in prompt


