@pytest.mark.parametrize("change, why", [
    ("moved", "no longer the head"), ("dirty", "no longer the head"), ("no_rc", None), ("no_on_pass", None),
    ("waiting", "must be done or needs_review"), ("retry", "cannot carry retry_when"),
    ("not_handoff", "not the hand-off the task waits on")])
def test_an_unclear_checks_wait_falls_back_to_a_light_wake(env, monkeypatch, tmp_path, change, why):
    p = make(env)
    from ttp import budget as bud, daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    on_pass = {"waiting": {"status": "waiting", "summary": "x"},
               "retry": {**DONE_ON_PASS, "retry_when": "true"},
               "no_on_pass": None}.get(change, DONE_ON_PASS)
    tid, path = _checks_wait_task(p, tmp_path, on_pass, rc=None if change == "no_rc" else "0")
    run_dir = tmp_path / f"run-{tid}"
    if change == "moved":
        subprocess.run(["git", "-C", str(path), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q",
                        "--allow-empty", "-m", "more"], check=True, capture_output=True)
    elif change == "dirty":
        (path / "fix.txt").write_text("changed after the checks\n")
    elif change == "not_handoff":
        (run_dir / "result.json").write_text(json.dumps({"status": "done", "summary": "x", "on_pass": DONE_ON_PASS}))
    _settle_probe(d, tid)
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert _ready(p, tid) and task["status"] == "queued", (task["status"], res)
    assert bud.wake_tier(task["tier"], res) == "light", res
    assert res["woke"].startswith("probe passed") and (why is None or why in res["woke"]), res["woke"]
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


def _on_pass_cmd_task(p, tmp_path, cmd, probe="true"):
    """A task that handed off `waiting` on `probe` and named `cmd` to run once it passes."""
    now = time.time()
    tid = p.db.add_task("run the long job", "s", kind="work", tier="standard", origin="user")
    run_dir = tmp_path / f"run-{tid}"
    run_dir.mkdir()
    p.db.x("INSERT INTO runs(task,role,provider,started,ended,status,dir) VALUES(?,?,?,?,?,?,?)",
           (tid, "worker", "fake", now - 120, now - 60, "ok", str(run_dir)))
    hand = {"status": "waiting", "summary": "job running", "waiting_for": "the job", "retry_after_s": 900,
            "retry_when": probe, "on_pass_cmd": cmd}
    (run_dir / "result.json").write_text(json.dumps(hand))
    p.db.update_task(tid, status="queued", not_before=now + 3600,
                     result=json.dumps({**hand, "waiting_since": now - 60}))
    return tid, run_dir


def _settle_on_pass(d, tid):
    _settle_probe(d, tid)
    if tid in d._on_pass:
        d._on_pass[tid][0].wait(120)
        d.probe_waiting()


def test_an_on_pass_cmd_that_records_done_is_the_hand_off_without_a_model_run(env, monkeypatch, tmp_path):
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    seen = tmp_path / "seen"
    tid, run_dir = _on_pass_cmd_task(p, tmp_path, f"echo \"$PWD $TTP_TASK\" > {seen}; echo verifying; "
                                     "printf '{\"status\":\"done\",\"summary\":\"job verified\","
                                     "\"metrics\":{\"rows\":\"9\"}}' > \"$TTP_RESULT\"")
    _settle_on_pass(d, tid)
    task = p.db.task(tid)
    res = json.loads(task["result"])
    assert task["status"] == "done", (task["status"], task["blocked_reason"], res)
    assert res["summary"] == "job verified" and res["run_status"] == "model-free" and res["metrics"] == {"rows": "9"}
    assert seen.read_text().split() == [str(p.root), str(tid)]
    assert "verifying" in (run_dir / "on_pass" / "on_pass.log").read_text()
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1, "a model run was started"
    ev = p.db.one("SELECT text FROM events WHERE kind='task_done' AND task=?", (tid,))
    assert "run model-free" in ev["text"]
    assert "on_pass_cmd recorded done model-free" in (p.logs / "daemon.log").read_text()
    for _ in range(3):
        d.tick()
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


def test_an_on_pass_cmd_keeps_the_task_asleep_while_it_runs_and_runs_once(env, monkeypatch, tmp_path):
    p = make(env)
    from ttp import daemon as dmod
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    tid, _ = _on_pass_cmd_task(p, tmp_path, "sleep 30")
    _settle_probe(d, tid)
    try:
        proc = d._on_pass[tid][0]
        assert not _ready(p, tid) and "on_pass_cmd" in p.db.task(tid)["blocked_reason"]
        p.db.update_task(tid, not_before=time.time() - 1)   # its own timer runs out meanwhile
        _settle_probe(d, tid)
        assert d._on_pass[tid][0] is proc and p.db.task(tid)["status"] == "queued"
        assert "woke" not in json.loads(p.db.task(tid)["result"])
    finally:
        dmod._kill_group(d._on_pass[tid][0])


@pytest.mark.parametrize("stale_context", [False, True])
def test_an_on_pass_cmd_can_send_notes_with_only_note_context(env, monkeypatch, tmp_path, stale_context):
    from ttp import daemon as dmod
    from ttp.project import register
    p = make(env)
    (env["tmp"] / "second").mkdir()
    register("second", {"host": "testhost", "dir": str(env["tmp"] / "second")})
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    cmd = ("set -e; ttp note 'job checked'; "
           "ttp note --to second 'job finished'; ttp note --to second 'job finished'; "
           "test -z \"$TTP_RUN_DIR$TTP_RUN_ID\"; "
           "if ttp notify 'should refuse'; then exit 10; fi; "
           "if ttp checks; then exit 11; fi; "
           "printf '{\"status\":\"done\",\"summary\":\"checked and reported\"}' > \"$TTP_RESULT\"")
    tid, run_dir = _on_pass_cmd_task(p, tmp_path, cmd)
    # Even a daemon launched with stale worker variables must not grant a full run context.
    if stale_context:
        monkeypatch.setenv("TTP_RUN_DIR", str(tmp_path / "stale-run"))
        monkeypatch.setenv("TTP_RUN_ID", "999")
    _settle_on_pass(d, tid)
    task = p.db.task(tid)
    output = (run_dir / "on_pass" / "on_pass.log").read_text()
    assert task["status"] == "done", (task["result"], output)
    (note,) = _upstream_inbox(env)
    assert (note["project"], note["task"], note["to"], note["from"], note["spec"]) == (
        p.name, tid, "second", "worker", "job finished")
    assert "stored 12 characters" in output and "sha256" in output
    assert "job checked" in (run_dir / "progress.md").read_text()
    assert "ttp notify only works inside a tt-project run" in output
    assert "ttp checks only works inside a tt-project run" in output
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


def test_an_on_pass_cmd_records_obligation_progress_and_receipts_with_note_context(env, monkeypatch, tmp_path):
    """`ttp obligation progress|receipt` in an on_pass_cmd go to the waiting run's file, filed for its task
    when it settles, however old that run; user-only obligation actions stay refused."""
    from ttp import daemon as dmod, obligations as ob
    p = make(env)
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0)
    d = dmod.Daemon(p.base)
    cmd = ("set -e; ttp obligation progress \"$OID\" 'job checked'; "
           "ttp obligation receipt \"$OID\" 'docs/report.md'; "
           "if ttp obligation add 'should refuse'; then exit 10; fi; "
           "printf '{\"status\":\"done\",\"summary\":\"delivered\"}' > \"$TTP_RESULT\"")
    tid, run_dir = _on_pass_cmd_task(p, tmp_path, cmd)
    p.db.x("UPDATE runs SET started=?, ended=? WHERE task=?",
           (time.time() - 30 * 86400, time.time() - 30 * 86400 + 60, tid))
    oid = ob.add(p, "the urgent report", [tid])
    monkeypatch.setenv("OID", oid)
    _settle_on_pass(d, tid)
    output = (run_dir / "on_pass" / "on_pass.log").read_text()
    assert p.db.task(tid)["status"] == "done", (p.db.task(tid)["result"], output)
    assert "not inside a run" in output and f"recorded for task #{tid}" in output
    o = ob.get(p.db, oid)
    assert o["receipt"] and o["receipt"]["evidence"] == "docs/report.md", o
    assert [e["text"] for e in o["owners"][str(tid)]["evidence"]][:1] == ["job checked"]


def _ack_wait(cli, *args):
    with pytest.raises(SystemExit) as e:
        cli.main(["ack-wait", *args])
    return e.value.code


def test_ack_wait_probe_passes_only_on_the_named_projects_reply_naming_the_hash(env, monkeypatch, capsys):
    from ttp import cli, upstream
    from ttp.project import register
    p = make(env)
    for name in ("second", "third"):
        (env["tmp"] / name).mkdir()
        register(name, {"host": "testhost", "dir": str(env["tmp"] / name)})
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    request = "please confirm the new probe works"
    assert upstream.send(p.name, 4, "second", request) == "sent"
    fp, sha = upstream.note_id("second", request), upstream.receipt(request).split()[-1]
    probe = ["probe", "--from", "second", "--hash", fp]
    assert _ack_wait(cli, *probe) == 1, "the request itself is no reply"
    upstream.send("third", 1, p.name, f"re {fp}: not ours")
    upstream.send("second", 1, "third", f"re {fp}: to another project")
    upstream.send("second", 1, p.name, "an unrelated note")
    assert _ack_wait(cli, *probe) == 1
    upstream.send("second", 9, p.name, f"Re {fp.upper()} and {sha}: works here")
    assert _ack_wait(cli, *probe) == 0 and _ack_wait(cli, "probe", "--from", "second", "--hash", sha) == 0
    assert _ack_wait(cli, "probe", "--from", "nowhere", "--hash", fp) == 2, "an unknown project never replies"
    assert _ack_wait(cli, "probe", "--from", p.name, "--hash", fp) == 2
    assert _ack_wait(cli, "probe", "--from", "second", "--hash", "xyz") == 2
    assert _ack_wait(cli, "probe", "--from", "second", "--hash", "abc1234") == 2, "too short to name one note"
    assert _ack_wait(cli, "settle", "--from", "second", "--hash", fp) == 2, "settle writes $TTP_RESULT only"
    assert "not set" in capsys.readouterr().err


