def test_worker_prompt_says_how_to_wait_on_a_job_on_another_machine():
    prompt = (RUNTIME.parent / "template" / "prompts" / "worker.md").read_text()
    flat = " ".join(prompt.split())
    assert "or 255, ssh not reaching the host" in flat
    assert "For a job on another machine" in flat
    assert "start its driver there with `ttp detach --remote <ssh alias> <name> -- <command...>`" in flat
    assert "`ttp detach --check --host <alias> <dir>/<name>`" in flat and "255 while ssh fails" in flat
    assert "Prefer it to a bare `ssh <host> test -e <marker>`" in flat
    assert 'set `"survives_reboot": true`' in flat
    # Device runners stay first: a device job goes through one, not a remote driver.
    assert "a device job goes through a device runner instead" in flat


def _lost_to_reboot(p, d, tmp_path, tid, name="lost", notes=()):
    """A run of task tid that the host went down under, as the reaper finds it after the reboot."""
    p.db.update_task(tid, status="running")
    run_dir = tmp_path / name
    run_dir.mkdir()
    (run_dir / "output.jsonl").write_text("")
    if notes:
        (run_dir / "progress.md").write_text("".join(f"10:0{i} {n}\n" for i, n in enumerate(notes)))
    (run_dir / "lease").touch()
    os.utime(run_dir / "lease", (time.time() - 999, time.time() - 999))
    p.db.x("INSERT INTO runs(task,role,provider,started,status,dir,boot_id) VALUES(?,?,?,?,?,?,?)",
           (tid, "worker", "fake", time.time() - 1800, "running", str(run_dir), "an-earlier-boot"))
    d.reap_runs()
    return run_dir


def test_a_run_lost_to_a_reboot_spends_no_attempt_and_retries_at_once(env, tmp_path):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = p.db.add_task("build", "s", kind="work", tier="light", origin="user")
    p.db.update_task(tid, attempts=2)
    _lost_to_reboot(p, d, tmp_path, tid)
    t = p.db.task(tid)
    assert t["status"] == "queued" and t["attempts"] == 2, dict(t)
    assert not t["not_before"] or t["not_before"] <= time.time(), "a reboot loss was delayed like a failure"
    assert tid in [x["id"] for x in p.db.ready_tasks()]


def test_the_third_reboot_loss_blocks_the_task(env, tmp_path):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = p.db.add_task("flash the board", "s", kind="work", tier="light", origin="user")
    for i in range(3):
        _lost_to_reboot(p, d, tmp_path, tid, name=f"lost{i}")
        assert p.db.task(tid)["status"] == ("blocked" if i == 2 else "queued")
    t = p.db.task(tid)
    assert t["attempts"] == 0
    assert t["blocked_reason"] == "lost to a host reboot 3 times; it may be causing them"
    ev = p.db.q("SELECT severity, status FROM events WHERE kind='task_blocked' AND task=?", (tid,))
    assert ev and ev[-1]["severity"] == "high" and ev[-1]["status"] == "queued", ev



def test_a_requeued_task_is_not_blocked_again_by_one_later_reboot_loss(env, tmp_path):
    p = make(env)
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = p.db.add_task("flash the board", "s", kind="work", tier="light", origin="user")
    for i in range(3):
        _lost_to_reboot(p, d, tmp_path, tid, name=f"lost{i}")
    assert p.db.task(tid)["status"] == "blocked"
    assert coord.apply(p, [{"type": "task_update", "id": tid, "status": "queued"}]) == []
    _lost_to_reboot(p, d, tmp_path, tid, name="after")
    assert p.db.task(tid)["status"] == "queued", "a requeue did not start the reboot count over"


def _waiting_from_before_the_boot(p, tid, job=True, boot="an-earlier-boot"):
    """Task tid waits from before this boot; with job, on a detached job of its own that the reboot
    cut short (no .rc)."""
    if job:
        run_dir = p.runs / f"pre-boot-{tid}-{len(p.db.q('SELECT id FROM runs WHERE task=?', (tid,)))}"
        run_dir.mkdir(parents=True)
        (run_dir / "detached.json").write_text(json.dumps([{"name": "soak", "rc": str(run_dir / "soak.rc"),
                                                            "log": str(run_dir / "soak.log")}]))
        p.db.x("INSERT INTO runs(task,role,provider,started,ended,status,dir,boot_id) VALUES(?,?,?,?,?,?,?,?)",
               (tid, "worker", "fake", time.time() - 1800, time.time() - 900, "ok", str(run_dir), boot))
    p.db.update_task(tid, status="queued", not_before=time.time() + 3600, result=json.dumps(
        {**json.loads(p.db.task(tid)["result"] or "{}"), "status": "waiting", "summary": "job running",
         "retry_after_s": 3600, "retry_when": "exit 1", "waiting_since": time.time() - 900}))


def test_three_boot_time_wakes_of_a_waiting_task_block_it(env):
    p = make(env)
    from ttp.daemon import Daemon
    tid = p.db.add_task("soak test", "s", kind="work", tier="light", origin="user")
    for i in range(3):
        _waiting_from_before_the_boot(p, tid)
        d = Daemon(p.base)
        d.boot_at = time.time() - 300
        d.wake_after_reboot()
        t = p.db.task(tid)
        assert t["status"] == ("blocked" if i == 2 else "queued"), (i, dict(t))
    assert t["blocked_reason"] == "lost to a host reboot 3 times; it may be causing them"
    assert "reboot_wakes" not in json.loads(t["result"]), "a block kept the old count"
    ev = p.db.q("SELECT severity, status FROM events WHERE kind='task_blocked' AND task=?", (tid,))
    assert ev and ev[-1]["severity"] == "high" and ev[-1]["status"] == "queued", ev


def _checks_killed_by_reboot(p, tmp_path, tid, boot="an-earlier-boot"):
    """Task tid waits on its own `ttp checks --detach` in a clean git worktree; the reboot behind
    `boot` killed them (checks.pid of that boot, a dead pid, no checks.rc)."""
    from ttp import cli
    wt = tmp_path / f"wt-{tid}"
    if not wt.exists():
        wt.mkdir()
        _git_out(wt, "init", "-q")
        (wt / "app.py").write_text("x = 1\n")
        _git_out(wt, "add", ".")
        _git_out(wt, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "c")
    head = _git_out(wt, "rev-parse", "HEAD").strip()
    run_dir = p.runs / f"checks-{tid}"
    run_dir.mkdir(parents=True, exist_ok=True)
    (run_dir / cli.CHECKS_RC).unlink(missing_ok=True)
    (run_dir / cli.CHECKS_PID).write_text(json.dumps(
        {"pid": 999999, "started": "gone", "ts": time.time() - 900, "boot": boot, "worktree": str(wt),
         "head": head, "cmd": ["--", "test -f app.py"], "fresh": True}))
    if not p.db.one("SELECT id FROM runs WHERE task=? AND dir=?", (tid, str(run_dir))):
        p.db.x("INSERT INTO runs(task,role,provider,started,ended,status,dir,boot_id) VALUES(?,?,?,?,?,?,?,?)",
               (tid, "worker", "fake", time.time() - 1800, time.time() - 900, "ok", str(run_dir), boot))
    p.db.update_task(tid, status="queued", not_before=time.time() + 3600, result=json.dumps(
        {"status": "waiting", "summary": "checks running", "retry_after_s": 3600,
         "retry_when": f"ttp checks --result {run_dir}", "waiting_since": time.time() - 900,
         "on_pass": {"status": "done", "summary": "checks passed"}}))
    return wt, run_dir


def _relaunches(p, tid):
    return p.db.q("SELECT * FROM events WHERE kind='checks_relaunched' AND task=?", (tid,))


def test_checks_a_reboot_killed_start_again_without_a_model_run(env, tmp_path):
    from ttp import cli
    from ttp.daemon import Daemon
    p = make(env)
    tid = p.db.add_task("feature", "s", kind="code", tier="light", origin="user")
    wt, run_dir = _checks_killed_by_reboot(p, tmp_path, tid)
    d = Daemon(p.base)
    d.boot_at = time.time() - 300
    d.wake_after_reboot()
    t = p.db.task(tid)
    assert t["not_before"] and "woke" not in json.loads(t["result"]), "the task was woken for a model run"
    (ev,) = _relaunches(p, tid)
    assert ev["status"] == "handled" and ev["severity"] == "low", dict(ev)
    assert _wait_precheck(run_dir) == "0", (run_dir / cli.CHECKS_OUT).read_text()
    info = cli._read_checks_pid(run_dir)
    assert info["boot"] == d.boot and info["worktree"] == str(wt) and info["fresh"] is True, info
    scratch = pathlib.Path(info['check_run_dir'])
    assert scratch.parent == p.state / 'check-runs' and re.fullmatch(r'[0-9a-f]{32}', scratch.name)
    assert not scratch.is_relative_to(wt)
    assert "$ test -f app.py" in (run_dir / "checks.log").read_text(), "not the same checks"
    # A daemon restart on the same boot starts nothing more and wakes nothing, even with them dead again.
    _checks_killed_by_reboot(p, tmp_path, tid)
    d2 = Daemon(p.base)
    d2.boot, d2.boot_at = d.boot, d.boot_at
    d2.wake_after_reboot()
    assert len(_relaunches(p, tid)) == 1 and not (run_dir / cli.CHECKS_RC).exists()
    assert p.db.task(tid)["not_before"], "a daemon restart woke the task"
    # The next boot may start them once more.
    d3 = Daemon(p.base)
    d3.boot, d3.boot_at = "a-later-boot", time.time() - 60
    d3.wake_after_reboot()
    assert len(_relaunches(p, tid)) == 2
    assert _wait_precheck(run_dir) == "0"


def test_checks_a_reboot_killed_are_not_restarted_on_a_moved_or_dirty_worktree(env, tmp_path):
    from ttp import cli
    from ttp.daemon import Daemon

    def boot(tid):
        d = Daemon(p.base)
        d.boot_at = time.time() - 300
        d.wake_after_reboot()
        t = p.db.task(tid)
        return t["not_before"] is None and json.loads(t["result"]).get("woke") == "the host rebooted"

    p = make(env)
    moved = p.db.add_task("moved", "s", kind="code", tier="light", origin="user")
    wt, run_dir = _checks_killed_by_reboot(p, tmp_path, moved)
    (wt / "b.py").write_text("y = 2\n")
    _git_out(wt, "add", ".")
    _git_out(wt, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "later")
    assert boot(moved), "checks of a moved head were started, not the task woken"
    dirty = p.db.add_task("dirty", "s", kind="code", tier="light", origin="user")
    wt, run_dir2 = _checks_killed_by_reboot(p, tmp_path, dirty)
    (wt / "app.py").write_text("x = 3\n")
    (run_dir2 / "untracked.txt").write_text("")
    assert boot(dirty), "checks on a dirty tree were started"
    gone = p.db.add_task("gone", "s", kind="code", tier="light", origin="user")
    wt, _ = _checks_killed_by_reboot(p, tmp_path, gone)
    shutil.rmtree(wt)
    assert boot(gone), "checks in a removed worktree were started"
    # Untracked files alone do not count, as for `ttp checks` itself.
    fine = p.db.add_task("untracked", "s", kind="code", tier="light", origin="user")
    wt, run_dir3 = _checks_killed_by_reboot(p, tmp_path, fine)
    (wt / "notes.txt").write_text("")
    assert not boot(fine) and len(_relaunches(p, fine)) == 1
    assert _wait_precheck(run_dir3) == "0"
    # An old checks.pid that names no worktree, head or boot: woken as before.
    old = p.db.add_task("old", "s", kind="code", tier="light", origin="user")
    _, run_dir4 = _checks_killed_by_reboot(p, tmp_path, old)
    (run_dir4 / cli.CHECKS_PID).write_text(json.dumps({"pid": 999999, "started": "gone", "ts": 1}))
    assert boot(old)
    assert not any(_relaunches(p, x) for x in (moved, dirty, gone, old))


def test_checks_a_reboot_killed_start_again_at_most_max_reboot_losses_times_per_head(env, tmp_path):
    from ttp.daemon import Daemon
    p = make(env)
    tid = p.db.add_task("crashy", "s", kind="code", tier="light", origin="user")
    for i in range(4):
        _, run_dir = _checks_killed_by_reboot(p, tmp_path, tid, boot=f"boot-{i}")
        d = Daemon(p.base)
        d.boot, d.boot_at = f"boot-{i + 1}", time.time() - 300
        d.wake_after_reboot()
        if i < 3:
            assert _wait_precheck(run_dir) == "0"
    assert len(_relaunches(p, tid)) == 3
    t = p.db.task(tid)
    assert t["status"] == "blocked", "checks that keep dying with the host were started forever"
    assert t["blocked_reason"] == "lost to a host reboot 4 times; it may be causing them"


def test_relaunched_checks_count_toward_reboot_losses(env, tmp_path):
    """Reboots the relaunched checks went through count as reboot losses once the relaunch cap is
    reached: the task is blocked then, not woken for max_reboot_losses more model runs."""
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    p = make(env)

    def reboot(tid, boot, orderly=False):
        _, run_dir = _checks_killed_by_reboot(p, tmp_path, tid, boot=boot)
        d = Daemon(p.base)
        d.cfg["budget"]["max_reboot_losses"] = 2
        d.boot, d.boot_at = f"{boot}+1", time.time() - 300
        if orderly:
            p.db.set_kv("boot_prev", {"boot": d.boot, "prev_boot": boot, "shutdown": "orderly"})
        n = len(_relaunches(p, tid))
        d.wake_after_reboot()
        if len(_relaunches(p, tid)) > n:
            assert _wait_precheck(run_dir) == "0"   # done before the next reboot rewrites checks.pid

    tid = p.db.add_task("crashy", "s", kind="code", tier="light", origin="user")
    reboots = 0
    while p.db.task(tid)["status"] != "blocked" and reboots < 10:
        reboot(tid, f"boot-{reboots}")
        reboots += 1
    assert len(_relaunches(p, tid)) == 2
    assert reboots == 3, f"blocked only after {reboots} reboots"
    assert p.db.task(tid)["blocked_reason"] == "lost to a host reboot 3 times; it may be causing them"
    # An orderly shutdown is not one the checks caused: past the cap they wake the task, uncounted.
    other = p.db.add_task("calm", "s", kind="code", tier="light", origin="user")
    for i in range(3):
        reboot(other, f"calm-{i}", orderly=i == 2)
    t = p.db.task(other)
    assert t["status"] == "queued" and t["not_before"] is None, dict(t)
    # A requeue starts the count over: the checks may be started again.
    assert coord.apply(p, [{"type": "task_update", "id": tid, "status": "queued"}]) == []
    reboot(tid, "boot-after")
    assert len(_relaunches(p, tid)) == 3 and p.db.task(tid)["status"] == "queued"


def test_a_malformed_checks_pid_does_not_stop_other_tasks_waking(env, tmp_path):
    from ttp import cli
    from ttp.daemon import Daemon
    p = make(env)
    bad = {}
    for field, value in (("head", 123), ("boot", ["x"]), ("worktree", 7)):
        tid = p.db.add_task(f"bad {field}", "s", kind="code", tier="light", origin="user")
        _, run_dir = _checks_killed_by_reboot(p, tmp_path, tid)
        info = json.loads((run_dir / cli.CHECKS_PID).read_text())
        (run_dir / cli.CHECKS_PID).write_text(json.dumps({**info, field: value}))
        bad[tid] = field
    later = p.db.add_task("later", "s", kind="work", tier="light", origin="user")
    _waiting_from_before_the_boot(p, later, job=False)
    d = Daemon(p.base)
    d.boot_at = time.time() - 300
    d.wake_after_reboot()
    for tid in [*bad, later]:
        t = p.db.task(tid)
        assert t["not_before"] is None and json.loads(t["result"]).get("woke") == "the host rebooted", \
            (bad.get(tid), dict(t))
    assert not any(_relaunches(p, x) for x in bad)


def _resumable_job_cut_by_reboot(p, tmp_path, tid, name="job", resumable=True):
    """Task tid waits on `ttp detach [--resumable] <name>` of its own run; a reboot cut it short: no
    .rc, its resume record and registry entry name an earlier boot. Returns (rc, counter file)."""
    from ttp import detach
    run_dir = p.runs / f"jobs-{tid}"
    run_dir.mkdir(parents=True, exist_ok=True)
    counter = tmp_path / f"runs-{tid}-{name}"
    rc = run_dir / f"{name}.rc"
    if not detach.resume_file(rc).exists() and not rc.exists():
        r = _ttp_run(p, "detach", *(["--resumable"] if resumable else []), name, "--", "sh", "-c",
                     f'echo run >>{counter}; echo "token=${{MY_API_TOKEN:-}}"',
                     env={"TTP_RUN_DIR": str(run_dir), "MY_API_TOKEN": "s3cret"})
        assert r.returncode == 0, r.stderr
        assert _wait_for_path(rc)
    rc = rc.resolve()
    rc.unlink()
    if resumable:
        m = json.loads(detach.resume_file(rc).read_text())
        detach.resume_file(rc).write_text(json.dumps({**m, "boot": "an-earlier-boot"}))
    reg = run_dir / "detached.json"
    reg.write_text(json.dumps([{**j, "boot": "an-earlier-boot"} for j in json.loads(reg.read_text())]))
    if not p.db.one("SELECT id FROM runs WHERE task=? AND dir=?", (tid, str(rc.parent))):
        p.db.x("INSERT INTO runs(task,role,provider,started,ended,status,dir,boot_id) VALUES(?,?,?,?,?,?,?,?)",
               (tid, "worker", "fake", time.time() - 1800, time.time() - 900, "ok", str(rc.parent), "an-earlier-boot"))
    p.db.update_task(tid, status="queued", not_before=time.time() + 3600, result=json.dumps(
        {"status": "waiting", "summary": "job running", "retry_after_s": 3600,
         "retry_when": f"ttp detach --check {rc}", "waiting_since": time.time() - 900}))
    return rc, counter


def _job_relaunches(p, tid):
    return p.db.q("SELECT * FROM events WHERE kind='job_relaunched' AND task=?", (tid,))


def _boot_daemon(p, boot="a-later-boot", max_losses=None, orderly_after=None):
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.boot, d.boot_at = boot, time.time() - 300
    if max_losses is not None:
        d.cfg["budget"]["max_reboot_losses"] = max_losses
    if orderly_after:
        p.db.set_kv("boot_prev", {"boot": boot, "prev_boot": orderly_after, "shutdown": "orderly"})
    d.wake_after_reboot()
    return d


def _woken(p, tid):
    t = p.db.task(tid)
    return t["not_before"] is None and json.loads(t["result"]).get("woke") == "the host rebooted"


def test_a_resumable_job_a_reboot_cut_short_is_relaunched_without_a_model_run(env, tmp_path):
    from ttp import detach
    p = make(env)
    tid = p.db.add_task("soak", "s", kind="work", tier="light", origin="user")
    rc, counter = _resumable_job_cut_by_reboot(p, tmp_path, tid)
    m = json.loads(detach.resume_file(rc).read_text())
    assert m["command"][:2] == ["sh", "-c"] and m["cwd"] and m["relaunches"] == 0
    assert "MY_API_TOKEN" not in m["env"], "a secret went to disk"
    assert oct(detach.resume_file(rc).stat().st_mode & 0o777) == "0o600"
    assert json.loads((rc.parent / "detached.json").read_text())[0]["resumable"] is True
    _boot_daemon(p)
    assert not _woken(p, tid) and p.db.task(tid)["not_before"], "the task was woken for a model run"
    assert _wait_for_path(rc) and rc.read_text().strip() == "0"
    assert counter.read_text().split() == ["run", "run"], "not the same command"
    assert (rc.parent / "job.log.1").exists(), "the cut-short run's log was lost"
    (ev,) = _job_relaunches(p, tid)
    assert ev["status"] == "handled" and ev["severity"] == "low", dict(ev)
    assert "relaunched it (1 of 3), no model run" in (rc.parent / "progress.md").read_text()
    m = json.loads(detach.resume_file(rc).read_text())
    assert m["relaunches"] == 1 and m["boot"] == "a-later-boot"
    # A daemon restart on the same boot starts nothing more and wakes nothing.
    rc.unlink()
    _boot_daemon(p)
    assert len(_job_relaunches(p, tid)) == 1 and not _woken(p, tid)
    assert counter.read_text().split() == ["run", "run"]


def test_no_relaunch_of_a_job_that_ended_did_not_opt_in_or_whose_task_no_longer_waits(env, tmp_path):
    p = make(env)
    ended = p.db.add_task("ended", "s", kind="work", tier="light", origin="user")
    rc, counter = _resumable_job_cut_by_reboot(p, tmp_path, ended)
    rc.write_text("0\n")
    plain = p.db.add_task("plain", "s", kind="work", tier="light", origin="user")
    _, counter2 = _resumable_job_cut_by_reboot(p, tmp_path, plain, resumable=False)
    done = p.db.add_task("done", "s", kind="work", tier="light", origin="user")
    _, counter3 = _resumable_job_cut_by_reboot(p, tmp_path, done)
    p.db.update_task(done, status="done", not_before=None, result=json.dumps({"status": "done", "summary": "ok"}))
    _boot_daemon(p)
    assert _woken(p, ended) and _woken(p, plain), "woken as before"
    assert p.db.task(done)["status"] == "done"
    assert not any(_job_relaunches(p, t) for t in (ended, plain, done))
    time.sleep(0.5)
    assert [len(c.read_text().split()) for c in (counter, counter2, counter3)] == [1, 1, 1]


def test_a_resumable_job_past_its_relaunch_cap_wakes_the_task_with_a_note(env, tmp_path):
    from ttp import detach
    p = make(env)
    tid = p.db.add_task("crashy", "s", kind="work", tier="light", origin="user")
    rc, counter = _resumable_job_cut_by_reboot(p, tmp_path, tid)
    for i in range(3):   # max_reboot_losses above the job cap: the job cap is what stops it here
        _boot_daemon(p, f"boot-{i}", max_losses=10)
        assert not _woken(p, tid), i
        assert _wait_for_path(rc)
        _resumable_job_cut_by_reboot(p, tmp_path, tid)
    assert json.loads(detach.resume_file(rc).read_text())["relaunches"] == 3
    _boot_daemon(p, "boot-3", max_losses=10)
    assert _woken(p, tid), "a job that keeps dying with the host was relaunched forever"
    assert len(_job_relaunches(p, tid)) == 3 and len(counter.read_text().split()) == 4
    assert "relaunched 3 times already (cap 3), so the task wakes instead" in (rc.parent / "progress.md").read_text()


def test_resumable_job_relaunches_count_toward_max_reboot_losses(env, tmp_path, monkeypatch):
    """Abrupt reboots answered by a relaunch are reboot losses: the task is blocked as a reboot loop
    once they reach max_reboot_losses, as it would be without --resumable. A new job name per run
    starts no fresh count; orderly reboots and planned host cycles are not counted."""
    from ttp import coordinator as coord, daemon as dm
    p = make(env)
    tid = p.db.add_task("crashy", "s", kind="work", tier="light", origin="user")
    rc, counter = _resumable_job_cut_by_reboot(p, tmp_path, tid)
    _boot_daemon(p, "boot-0")
    assert not _woken(p, tid) and _wait_for_path(rc)
    # The next run's job has another name: the count carries over.
    rc2, _ = _resumable_job_cut_by_reboot(p, tmp_path, tid, name="job2")
    _boot_daemon(p, "boot-1")
    assert not _woken(p, tid) and _wait_for_path(rc2)
    _resumable_job_cut_by_reboot(p, tmp_path, tid, name="job2")
    _boot_daemon(p, "boot-2")
    t = p.db.task(tid)
    assert t["status"] == "blocked", "a reboot loop through relaunches was not counted"
    assert t["blocked_reason"] == "lost to a host reboot 3 times; it may be causing them"
    assert len(_job_relaunches(p, tid)) == 2
    assert "reaches budget.max_reboot_losses (3)" in (rc2.parent / "progress.md").read_text()
    # A requeue starts the count over.
    assert coord.apply(p, [{"type": "task_update", "id": tid, "status": "queued"}]) == []
    assert dm.Daemon(p.base)._job_relaunch_boots(tid) == 0
    # Orderly reboots and planned host cycles relaunch without counting.
    calm = p.db.add_task("calm", "s", kind="work", tier="light", origin="user")
    rc3, _ = _resumable_job_cut_by_reboot(p, tmp_path, calm, name="calm")
    for i in range(3):
        with monkeypatch.context() as m:
            if i == 1:
                m.setattr(dm.Daemon, "_planned_cycle", lambda self, boot: {"path": "x", "reason": "planned"})
            _boot_daemon(p, f"calm-{i}", orderly_after=None if i == 1 else "an-earlier-boot")
        assert not _woken(p, calm) and _wait_for_path(rc3), i
        _resumable_job_cut_by_reboot(p, tmp_path, calm, name="calm")
    assert p.db.task(calm)["status"] == "queued" and len(_job_relaunches(p, calm)) == 3
    assert dm.Daemon(p.base)._job_relaunch_boots(calm) == 0
    _boot_daemon(p, "calm-3", orderly_after="an-earlier-boot")
    assert _woken(p, calm), "the job cap still wakes it"
    assert p.db.task(calm)["status"] == "queued"


def test_a_partial_relaunch_stops_the_jobs_it_started_and_counts_the_boot_once(env, tmp_path):
    """Two resumable jobs; the second cannot start. The task wakes with no job left running, and the
    boot counts once (as the wake), never also as a relaunch boot."""
    from ttp import detach, locks
    from ttp.daemon import Daemon
    p = make(env)
    tid = p.db.add_task("pair", "s", kind="work", tier="light", origin="user")
    rc1, counter = _resumable_job_cut_by_reboot(p, tmp_path, tid, name="a")
    m = json.loads(detach.resume_file(rc1).read_text())
    detach.resume_file(rc1).write_text(json.dumps({**m, "command": ["sh", "-c", f"echo run >>{counter}; sleep 60"]}))
    rc2, _ = _resumable_job_cut_by_reboot(p, tmp_path, tid, name="b")
    m = json.loads(detach.resume_file(rc2).read_text())
    detach.resume_file(rc2).write_text(json.dumps({**m, "cwd": str(tmp_path / "gone")}))
    t = p.db.task(tid)
    p.db.update_task(tid, result=json.dumps({**json.loads(t["result"]),
                                             "retry_when": f"ttp detach --check {rc1} {rc2}"}))
    d = _boot_daemon(p)
    assert _woken(p, tid), "a job that could not start did not wake the task"
    assert not _job_relaunches(p, tid), "a boot that woke the task was also counted as a relaunch boot"
    assert d._job_relaunch_boots(tid) == 0 and json.loads(p.db.task(tid)["result"]).get("reboot_wakes") == 1
    deadline = time.time() + _load_scaled(10)
    while not locks.any_free([locks.job_lock(rc1)]) and time.time() < deadline:
        time.sleep(0.05)
    assert locks.any_free([locks.job_lock(rc1)]), "the first job was left running"
    assert not rc1.exists() and detach.state(rc1)[0] == "lost"
    assert "could not start" in detach.state(rc1)[1]
    notes = (rc1.parent / "progress.md").read_text()
    assert "detached job b; not relaunched: it could not start" in notes and "stopped the jobs relaunched before it (a)" in notes
    assert "relaunched it" not in notes
    # A daemon restart on the same boot leaves the woken task alone.
    _boot_daemon(p)
    assert not _job_relaunches(p, tid) and json.loads(p.db.task(tid)["result"]).get("reboot_wakes") == 1


def _two_resumable_jobs(p, tmp_path, tid, b_cwd=None):
    """Task tid waits on resumable jobs a (sleeps) and b, both cut short by a reboot."""
    from ttp import detach
    rc1, counter = _resumable_job_cut_by_reboot(p, tmp_path, tid, name="a")
    m = json.loads(detach.resume_file(rc1).read_text())
    detach.resume_file(rc1).write_text(json.dumps({**m, "command": ["sh", "-c", f"echo run >>{counter}; sleep 60"]}))
    rc2, _ = _resumable_job_cut_by_reboot(p, tmp_path, tid, name="b")
    if b_cwd:
        m = json.loads(detach.resume_file(rc2).read_text())
        detach.resume_file(rc2).write_text(json.dumps({**m, "cwd": b_cwd}))
    t = p.db.task(tid)
    p.db.update_task(tid, result=json.dumps({**json.loads(t["result"]),
                                             "retry_when": f"ttp detach --check {rc1} {rc2}"}))
    return rc1, rc2, counter


def _job_stopped(rc):
    from ttp import detach, locks
    deadline = time.time() + _load_scaled(10)
    while not locks.any_free([locks.job_lock(rc)]) and time.time() < deadline:
        time.sleep(0.05)
    return locks.any_free([locks.job_lock(rc)]) and not rc.exists() and detach.state(rc)[0] == "lost"


def test_a_daemon_restart_mid_relaunch_stops_the_jobs_its_earlier_life_relaunched(env, tmp_path):
    """The daemon died after relaunching job a, before job b; on restart b cannot start. a, started by
    the earlier life on this boot, is stopped too: the woken task has no job left running."""
    from ttp import detach
    p = make(env)
    tid = p.db.add_task("pair", "s", kind="work", tier="light", origin="user")
    rc1, rc2, counter = _two_resumable_jobs(p, tmp_path, tid, b_cwd=str(tmp_path / "gone"))
    why, pid = detach.relaunch(rc1, "a-later-boot")   # the earlier daemon life, then it died
    assert not why and pid
    assert json.loads(detach.resume_file(rc1).read_text())["cut_boot"] == "an-earlier-boot"
    d = _boot_daemon(p)
    assert _woken(p, tid), "a job that could not start did not wake the task"
    assert _job_stopped(rc1), "the job the earlier daemon life relaunched was left running"
    assert "could not start" in detach.state(rc1)[1]
    assert "stopped the jobs relaunched before it (a)" in (rc1.parent / "progress.md").read_text()
    assert not _job_relaunches(p, tid) and d._job_relaunch_boots(tid) == 0
    assert json.loads(p.db.task(tid)["result"]).get("reboot_wakes") == 1


def test_a_daemon_restart_after_the_relaunches_records_the_boot_once(env, tmp_path):
    """The daemon died after relaunching both jobs, before recording them: the restart starts
    nothing more, keeps the task asleep and writes the missing job_relaunched events (once), so
    the boot counts toward max_reboot_losses."""
    from ttp import detach
    p = make(env)
    tid = p.db.add_task("pair", "s", kind="work", tier="light", origin="user")
    rc1, rc2, counter = _two_resumable_jobs(p, tmp_path, tid)
    for rc in (rc1, rc2):
        assert detach.relaunch(rc, "a-later-boot")[0] == ""
    for _ in range(2):
        d = _boot_daemon(p)
        assert not _woken(p, tid) and p.db.task(tid)["not_before"]
        assert len(_job_relaunches(p, tid)) == 2 and d._job_relaunch_boots(tid) == 1
    assert _wait_for_path(rc2)
    assert len((tmp_path / f"runs-{tid}-b").read_text().split()) == 2, "a job was started again"
    assert len(counter.read_text().split()) <= 2, "a job was started again"
    notes = (rc1.parent / "progress.md").read_text()
    assert notes.count("cut short detached job a; relaunched it (1 of 3)") == 1
    # The same restart when the reboot that cut them short was orderly: recorded, not a loss.
    calm = p.db.add_task("calm", "s", kind="work", tier="light", origin="user")
    rc3, counter3 = _resumable_job_cut_by_reboot(p, tmp_path, calm, name="calm")
    assert detach.relaunch(rc3, "calm-boot")[0] == ""
    d = _boot_daemon(p, "calm-boot", orderly_after="an-earlier-boot")
    assert not _woken(p, calm) and len(_job_relaunches(p, calm)) == 1 and d._job_relaunch_boots(calm) == 0
    detach.stop(rc1, detach.running_pid(rc1, lambda b: b == "a-later-boot"), "test over")
    assert _job_stopped(rc1)


def test_a_daemon_death_between_start_and_registry_still_stops_the_job(env, tmp_path, monkeypatch):
    """The daemon died right after starting job a, before its registry entry named the new pid and
    boot; on restart b cannot start. a is found by the pid its wrapper wrote and stopped."""
    from ttp import detach
    p = make(env)
    tid = p.db.add_task("pair", "s", kind="work", tier="light", origin="user")
    rc1, rc2, counter = _two_resumable_jobs(p, tmp_path, tid, b_cwd=str(tmp_path / "gone"))
    with monkeypatch.context() as mp:
        mp.setattr(detach, "_restamp", lambda *a: None)   # the crash: the registry is never restamped
        why, pid = detach.relaunch(rc1, "a-later-boot")
    assert not why and pid and _wait_for_path(detach.started(rc1))
    assert json.loads((rc1.parent / "detached.json").read_text())[0]["boot"] == "an-earlier-boot"
    assert detach.running_pid(rc1, lambda b: b == "a-later-boot") == pid
    _boot_daemon(p)
    assert _woken(p, tid), "a job that could not start did not wake the task"
    assert _job_stopped(rc1), "the job relaunched before the registry named it was left running"
    assert not _job_relaunches(p, tid)


def test_a_daemon_death_between_counting_and_starting_a_job_starts_it_once(env, tmp_path, monkeypatch):
    """The daemon died after counting the relaunch in the resume record, before starting the job. The
    restart starts it, counted once, and writes job_relaunched only once it runs."""
    from ttp import detach

    class Crash(BaseException):
        pass

    def die(*a, **k):
        raise Crash
    p = make(env)
    tid = p.db.add_task("soak", "s", kind="work", tier="light", origin="user")
    rc, counter = _resumable_job_cut_by_reboot(p, tmp_path, tid)
    with monkeypatch.context() as mp:
        mp.setattr(detach, "start", die)
        with pytest.raises(Crash):
            detach.relaunch(rc, "a-later-boot")
    m = json.loads(detach.resume_file(rc).read_text())
    assert m["relaunches"] == 1 and m["boot"] == "a-later-boot" and not detach.relaunch_started(rc)
    d = _boot_daemon(p)
    assert not _woken(p, tid) and p.db.task(tid)["not_before"]
    assert _wait_for_path(rc) and rc.read_text().strip() == "0", "the counted job was never started"
    assert counter.read_text().split() == ["run", "run"]
    assert json.loads(detach.resume_file(rc).read_text())["relaunches"] == 1, "counted twice"
    assert len(_job_relaunches(p, tid)) == 1 and d._job_relaunch_boots(tid) == 1
    assert (rc.parent / "progress.md").read_text().count("relaunched it (1 of 3)") == 1
    # A further restart on the same boot starts nothing more.
    _boot_daemon(p)
    assert counter.read_text().split() == ["run", "run"] and len(_job_relaunches(p, tid)) == 1


def test_a_resumable_job_queued_before_a_reboot_is_relaunched_not_lost(env, tmp_path):
    """A --resumable job queued for the daemon but not started before a reboot longer than the queue
    timeout: wake_after_reboot relaunches it, and its stale queue entry is settled without .lost."""
    from ttp import detach
    p = make(env)
    tid = p.db.add_task("queued", "s", kind="work", tier="light", origin="user")
    rc, counter = _resumable_job_cut_by_reboot(p, tmp_path, tid)
    m = json.loads(detach.resume_file(rc).read_text())
    detach.resume_file(rc).write_text(json.dumps({**m, "command": ["sh", "-c", f"echo run >>{counter}; sleep 60"]}))
    q = detach.enqueue(p.state, rc, rc.with_suffix(".log"), ["sh", "-c", f"echo queued >>{counter}"],
                       str(tmp_path), {})
    old = json.loads(q.read_text())
    q.write_text(json.dumps({**old, "queued": time.time() - detach.QUEUED_S - 1200}))
    _boot_daemon(p)
    assert not _woken(p, tid)
    detach.tend(p)
    assert not q.exists() and not detach.queued(rc).exists(), "the stale queue entry stayed"
    assert not detach.lost(rc).exists(), "a relaunched job was marked lost"
    assert detach.state(rc) == ("running", "")
    # An expired entry of a job that runs (its lock held), relaunched or not, is no lost job either.
    q = detach.enqueue(p.state, rc, rc.with_suffix(".log"), ["true"], str(tmp_path), {})
    q.write_text(json.dumps({**json.loads(q.read_text()), "queued": time.time() - detach.QUEUED_S - 60}))
    detach.tend(p)
    assert not q.exists() and not detach.lost(rc).exists() and detach.state(rc) == ("running", "")
    d = _boot_daemon(p)
    detach.stop(rc, detach.running_pid(rc, d._this_boot), "test over")
    assert _job_stopped(rc)
    # Without a relaunch or a running job, an expired entry is still recorded as lost.
    other = p.runs / f"jobs-{tid}" / "other.rc"
    q = detach.enqueue(p.state, other, other.with_suffix(".log"), ["true"], str(tmp_path), {})
    q.write_text(json.dumps({**json.loads(q.read_text()), "queued": time.time() - detach.QUEUED_S - 60}))
    detach.tend(p)
    assert detach.lost(other).exists() and "did not start it within" in detach.lost(other).read_text()


