def test_detached_ttp_checks_keep_their_output_and_marker_out_of_the_worktree():
    """A detached `ttp checks` writes its output and exit-code marker in the run's directory: a log
    or marker in the worktree (tmp/checks.log) got committed once, and the retry_when probe runs in
    the project root, where a relative marker path never appears."""
    prompts = RUNTIME.parent / "template" / "prompts"
    for name in ("kind-code.md", "kind-review.md"):
        text = " ".join((prompts / name).read_text().split())
        assert "`ttp checks --detach -- <cmds>`" in text and "the `retry_when` it prints" in text, name
        assert "never the worktree" in text and "also wakes the task if the checks were killed" in text, name
        assert "setsid nohup sh -c 'ttp checks" not in text and "<log>" not in text and "> <marker>" not in text, name
    worker = " ".join((prompts / "worker.md").read_text().split())
    assert "Never kill by name or pattern (`pkill -f`, `killall`)" in worker


def _detached_checks(run, capsys, *check):
    from ttp import cli
    cli.main(["checks", "--detach", "--", *check])
    out = capsys.readouterr().out
    probe = next(x for x in out.splitlines() if x.startswith("retry_when: "))[len("retry_when: "):]
    assert probe.endswith(f" checks --result {shlex.quote(str(run))}"), out
    return json.loads((run / "checks.pid").read_text())["pid"]


def _gone_pid(pid):
    from ttp.daemon import _alive
    try:   # the detached checks are this test's child: reap them, or their zombie answers kill(pid, 0)
        os.waitpid(pid, os.WNOHANG)
    except ChildProcessError:
        pass
    return not _alive(pid)


@pytest.mark.parametrize("proc", [True, False], ids=["proc", "ps"])
def test_a_zombie_child_counts_as_gone(monkeypatch, proc):
    """A killed child stays a zombie until it is reaped and kill(pid, 0) still finds it. On macOS,
    which has no /proc, the probe of detached checks it had killed kept saying they ran."""
    from ttp import cli, daemon, locks, project
    from ttp.runner import proc_start
    if proc and not project._PROC:
        pytest.skip("no /proc here")
    monkeypatch.setattr(project, "_PROC", proc)      # False: the `ps` path macOS takes
    child = subprocess.Popen(["sleep", "60"])
    try:
        assert daemon._alive(child.pid) and not project.zombie(child.pid)
        info = {"pid": child.pid, "started": proc_start(child.pid)}
        assert cli._checks_alive(info)
        os.kill(child.pid, signal.SIGKILL)
        assert _wait_for(lambda: project.zombie(child.pid), 10), "the killed child is not a zombie"
        os.kill(child.pid, 0)                         # not reaped: kill(pid, 0) still finds it
        assert not daemon._alive(child.pid)
        assert not locks._alive(child.pid)
        assert not cli._checks_alive(info)
        assert not cli._listener_alive(child.pid, "chat")
    finally:
        child.kill()
        child.wait()
    assert child.returncode == -signal.SIGKILL, "the check reaped the child and took its exit code"


def test_detached_ttp_checks_write_their_exit_code_when_another_worker_pkills_them(env, tmp_path, monkeypatch, capsys):
    """A worker's `pkill -f "ttp checks"` sent TERM to another run's `sh -c 'ttp checks; echo $? >
    checks.rc'` and its ttp checks: the wrapper died too, no checks.rc was written, and the waiting
    task slept until its retry_after_s. A detached `ttp checks` writes checks.rc on TERM, ends the
    check it ran (no orphan writing on), and its probe answers at once."""
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    started, child = tmp_path / "started", tmp_path / "child.pid"
    pid = _detached_checks(run, capsys, "sh", "-c", f"echo $$ > {child}; touch {started}; sleep 60")
    try:
        assert _wait_for(started.exists), (run / "checks.out").read_text()
        assert _ttp("checks", "--result", str(run)) == 1
        assert "running" in capsys.readouterr().out
        os.kill(pid, signal.SIGTERM)                       # what `pkill -f "ttp checks"` does
        assert _wait_for(lambda: (run / "checks.rc").exists(), 15), "no exit code after a TERM"
        assert (run / "checks.rc").read_text().strip() == str(128 + signal.SIGTERM)
        assert _wait_for(lambda: _gone_pid(int(child.read_text())), 10), "the check outlived ttp checks"
        assert _ttp("checks", "--result", str(run)) == 0
        assert "finished with exit code 143" in capsys.readouterr().out
        assert "stopped by signal 15" in (run / "checks.log").read_text()
    finally:
        for k in (pid, int(child.read_text()) if child.exists() else 0):
            try:
                if k:
                    os.killpg(k, signal.SIGKILL)
            except OSError:
                pass


def test_the_detached_checks_probe_wakes_the_task_when_they_were_killed_outright(env, tmp_path, monkeypatch, capsys):
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    started = tmp_path / "started"
    pid = _detached_checks(run, capsys, "sh", "-c", f"touch {started}; sleep 60")
    try:
        assert _wait_for(started.exists)
        os.killpg(pid, signal.SIGKILL)                     # nothing can trap this: no checks.rc
        assert _wait_for(lambda: _gone_pid(pid), 10)
        assert not (run / "checks.rc").exists()
        assert _ttp("checks", "--result", str(run)) == 0, "a dead check run left its task asleep"
        assert "ended without an exit code" in capsys.readouterr().out
        assert (run / "checks.rc").read_text().strip() == "killed"
    finally:
        try:
            os.killpg(pid, signal.SIGKILL)
        except OSError:
            pass


def test_detached_ttp_checks_finish_record_the_pass_and_a_rerun_stops_the_earlier_one(env, tmp_path, monkeypatch, capsys):
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    started = tmp_path / "started"
    first = _detached_checks(run, capsys, "sh", "-c", f"touch {started}; sleep 60")
    try:
        assert _wait_for(started.exists)
        second = _detached_checks(run, capsys, "true")     # stops the first itself: no pkill needed
        assert _gone_pid(first), "a rerun left the run's earlier checks running"
        assert second != first
        assert _wait_for(lambda: (run / "checks.rc").exists(), 30)
        assert (run / "checks.rc").read_text().strip() == "0"
        assert json.loads((run / "checks.json").read_text())["passed"] is True
        assert _ttp("checks", "--result", str(run)) == 0
        out = capsys.readouterr().out
        assert "finished with exit code 0" in out
        assert f"full output ('$ cmd' lines, test results) in {run / 'checks.log'}" in out
    finally:
        try:
            os.killpg(first, signal.SIGKILL)
        except OSError:
            pass
    assert _ttp("checks", "--result", str(tmp_path / "nothing")) == 0, "no record must not keep a task asleep"

@pytest.mark.parametrize("box", ["pidns", "cgroup"])
def test_sandboxed_checks_are_queued_and_finish_model_free(env, tmp_path, monkeypatch, capsys, box):
    from ttp import cli, detach, push
    from ttp.daemon import Daemon
    from ttp.runner import proc_start
    if not (push.pid_ns() if box == "pidns" else push.cgroup()):
        pytest.skip("no /proc")
    p = make(env)
    tid, repo = _checks_wait_task(p, tmp_path, {"status": "done", "summary": "checks passed"}, rc=None)
    run = pathlib.Path(p.db.one("SELECT dir FROM runs WHERE task=?", (tid,))["dir"])
    monkeypatch.chdir(repo)
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    monkeypatch.setenv("TTP_RUN_DIR", str(run))
    marker = "TTP_PIDNS" if box == "pidns" else "TTP_CGROUP"
    monkeypatch.setenv(marker, "another sandbox")
    monkeypatch.setenv("SOME_API_TOKEN", "keep-off-disk")
    monkeypatch.setenv("CHECK_VALUE", "preserved")
    cli.main(["checks", "--detach", "--fresh", "--", 'test "$CHECK_VALUE" = preserved'])
    assert "queued" in capsys.readouterr().out
    assert not (run / cli.CHECKS_PID).exists(), "the sandbox must launch no child"
    q = next((p.state / detach.QUEUE).glob("*.json"))
    assert "keep-off-disk" not in q.read_text() and marker not in json.loads(q.read_text())["env"]
    assert cli._checks_result(run) == 1 and not (run / cli.CHECKS_RC).exists()
    monkeypatch.delenv(marker)
    d = Daemon(p.base)
    d.boot_at = time.time() - 30   # queued work survives a daemon restart or host reboot
    d.wake_after_reboot()
    assert p.db.task(tid)["not_before"] and "woke" not in json.loads(p.db.task(tid)["result"])
    d.tend_pushes()
    info = cli._read_checks_pid(run)
    assert info["pid"] and info["started"] == proc_start(info["pid"])
    assert info["worktree"] == str(repo) and info["fresh"] is True
    assert _wait_precheck(run) == "0"
    assert not q.exists() and not detach.queued(run / cli.CHECKS_RC).exists()
    assert cli._checks_result(run) == 0
    _settle_probe(d, tid)
    assert p.db.task(tid)["status"] == "done"
    assert json.loads(p.db.task(tid)["result"])["run_status"] == "model-free"
    assert len(p.db.q("SELECT id FROM runs WHERE task=?", (tid,))) == 1


def test_queued_checks_survive_the_launching_process_exit(env, tmp_path, monkeypatch):
    from ttp import cli, detach
    from ttp.runner import proc_start
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    launcher = subprocess.run(
        [sys.executable, "-c", "from ttp import cli, push; push._boxed = lambda: True; "
         "cli.main(['checks', '--detach', '--', 'true'])"],
        cwd=repo, env={**os.environ, "PYTHONPATH": str(RUNTIME)}, capture_output=True, text=True, timeout=30)
    assert launcher.returncode == 0 and "queued" in launcher.stdout, launcher.stderr
    assert not (run / cli.CHECKS_PID).exists(), "the disposable launcher must start no checks"
    detach.tend(p)   # the launcher has exited before the durable executor starts the checks
    info = cli._read_checks_pid(run)
    assert info["started"] == proc_start(info["pid"])
    assert _wait_precheck(run) == "0"
    assert json.loads((run / "checks.json").read_text())["passed"] is True
    assert cli._checks_result(run) == 0


def _record_checks_argv(monkeypatch):
    """Record the argv of every `ttp checks` process started in this test, then start it as usual."""
    real, seen = subprocess.Popen, []

    def popen(args, *a, **kw):
        if isinstance(args, list) and "checks" in args:
            seen.append([str(x) for x in args])
        return real(args, *a, **kw)
    monkeypatch.setattr(subprocess, "Popen", popen)
    return seen


def test_queued_checks_keep_full(env, tmp_path, monkeypatch, capsys):
    from ttp import cli, detach, push
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    monkeypatch.setattr(push, "_boxed", lambda: True)
    cli.main(["checks", "--detach", "--full", "--", "true"])
