def test_pr_watch_drops_flags_for_cancelled_tasks_and_prs_it_cannot_read(env, monkeypatch):
    """A flagged PR whose task was cancelled, or that gh has not been able to read for a day, no longer
    holds its high alert."""
    from ttp import alerts, prguard, watchers
    from ttp.daemon import Daemon
    p = make(env)
    a, b = "https://github.com/acme/widgets/pull/7", "https://github.com/acme/widgets/pull/8"
    ids = [p.db.x("INSERT INTO tasks(title,kind,status,pr_url,created) VALUES(?,?,?,?,?)",
                  ("t", "code", "done", url, time.time())) for url in (a, b)]
    readable = {a: True, b: True}
    monkeypatch.setattr(watchers, "_gh", lambda args, cwd: None if args[0] == "api" or not readable[args[2]] else
                        {"url": args[2], "state": "OPEN", "title": "t", "isDraft": False})
    p.db.set_kv("pr_signatures", {})
    _run_tried(p, "acme/widgets#7")
    _run_tried(p, "acme/widgets#8")
    d = Daemon(p.base)

    def alerting():
        return sorted(m["ref"] for m in p.db.q("SELECT * FROM messages WHERE kind='alert' AND ref LIKE 'pr-ready:%'")
                      if alerts.active(p.db, m["ref"], m["ts"], time.time()))

    watchers.watch_prs(d)
    assert alerting() == ["pr-ready:acme/widgets#7", "pr-ready:acme/widgets#8"]
    # #7's task is cancelled: its flag goes on the next pass.
    p.db.x("UPDATE tasks SET status='cancelled' WHERE id=?", (ids[0],))
    # gh cannot read #8: the flag stays for a day, then goes.
    readable[b] = False
    watchers.watch_prs(d)
    assert set(p.db.kv(prguard.UNAPPROVED_KEY)) == {"acme/widgets#8"}
    assert alerting() == ["pr-ready:acme/widgets#8"]
    flags = p.db.kv(prguard.UNAPPROVED_KEY)
    flags["acme/widgets#8"]["seen"] -= watchers.DAY + 1
    p.db.set_kv(prguard.UNAPPROVED_KEY, flags)
    watchers.watch_prs(d)
    assert p.db.kv(prguard.UNAPPROVED_KEY) == {} and alerting() == []

def test_pr_watch_skips_comments_its_own_runs_marked(env, monkeypatch):
    """A comment or review this project's runs post on their PR ends with the hidden <!-- ttp --> marker
    and is not reported back as new review activity, whatever the author (the shared account may not
    be the PR's opener). An unmarked comment from the same account still counts."""
    from ttp import watchers
    from ttp.daemon import Daemon
    p = make(env)
    url = "https://github.com/acme/widgets/pull/7"
    p.db.x("INSERT INTO tasks(title,kind,status,pr_url,created) VALUES(?,?,?,?,?)",
           ("t", "code", "done", url, time.time()))
    own, other = {"login": "runs"}, {"login": "reviewer"}
    pr = {"url": url, "state": "OPEN", "title": "t", "isDraft": True, "author": own,
          "comments": [{"author": other, "body": "Please rename this."}], "reviews": []}
    monkeypatch.setattr(watchers, "_gh", lambda args, cwd: json.loads(json.dumps(pr)))
    p.db.set_kv("pr_signatures", {})
    d = Daemon(p.base)

    def events():
        return [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind='pr_changed' ORDER BY id")]

    watchers.watch_prs(d)   # baseline
    assert watchers.pr_signature(pr)["n_human"] == 1
    pr["comments"].append({"author": own, "body": "Renamed in abc123.\n<!-- ttp -->"})
    pr["reviews"].append({"author": own, "body": "Looks fine.\n\n<!-- ttp -->", "state": "COMMENTED"})
    watchers.watch_prs(d)
    assert events() == []
    # A marked reply through an account that did not open the PR is the harness's own too.
    pr["comments"].append({"author": other, "body": "Fixed. <!-- ttp -->"})
    watchers.watch_prs(d)
    assert events() == [] and watchers.pr_signature(pr)["n_human"] == 1
    # An unmarked comment from the same account counts.
    pr["comments"].append({"author": other, "body": "Typed by hand."})
    watchers.watch_prs(d)
    assert len(events()) == 1 and watchers.pr_signature(pr)["n_human"] == 2


def test_pr_watch_skips_mergeable_unknown_flaps_and_honours_pr_mutes(env, monkeypatch):
    """GitHub reports mergeable UNKNOWN while it recomputes. A change that only moves mergeable to or
    from UNKNOWN queues nothing, and a real move through UNKNOWN still reports the known values. A
    pr_changed event an active 'pr' mute covers is recorded and counted on the mute but does not wake."""
    from ttp import screen, watchers
    from ttp.daemon import Daemon
    p = make(env)
    url = "https://github.com/acme/widgets/pull/7"
    p.db.x("INSERT INTO tasks(title,kind,status,pr_url,created) VALUES(?,?,?,?,?)",
           ("t", "code", "done", url, time.time()))
    pr = {"url": url, "state": "OPEN", "title": "t", "isDraft": True, "author": {"login": "runs"},
          "mergeable": "MERGEABLE", "comments": [], "reviews": []}
    monkeypatch.setattr(watchers, "_gh", lambda args, cwd: json.loads(json.dumps(pr)))
    p.db.set_kv("pr_signatures", {})
    d = Daemon(p.base)

    def events():
        return [(e["status"], e["text"]) for e in
                p.db.q("SELECT status, text FROM events WHERE kind='pr_changed' ORDER BY id")]

    watchers.watch_prs(d)   # baseline
    for m in ("UNKNOWN", "MERGEABLE", "UNKNOWN", "UNKNOWN", "MERGEABLE"):
        pr["mergeable"] = m
        watchers.watch_prs(d)
    assert events() == []
    pr["mergeable"] = "UNKNOWN"
    watchers.watch_prs(d)
    pr["mergeable"] = "CONFLICTING"
    watchers.watch_prs(d)
    assert [(s, "MERGEABLE → CONFLICTING" in t) for s, t in events()] == [("queued", True)]
    # A 'pr' mute covering the text: recorded and counted, not queued.
    screen.mute(p.db, "pr", "acme/widgets/pull/7", 4, why="known")
    pr["isDraft"] = False
    watchers.watch_prs(d)
    assert [s for s, _ in events()] == ["queued", "muted"]
    assert screen.mutes(p.db)[0]["count"] == 1


def test_pr_watch_ci_only_flips_on_an_open_pr_raise_no_pr_changed(env, monkeypatch):
    """CI moving on an open PR (passing -> pending -> passing) raises no pr_changed: the findings
    check reports each outcome once (a failure as pr_findings, green again as pr_clean). A change of
    mergeable or state still raises pr_changed."""
    from ttp import watchers
    from ttp.daemon import Daemon
    p = make(env)
    url = "https://github.com/acme/widgets/pull/7"
    p.db.x("INSERT INTO tasks(title,kind,status,pr_url,created) VALUES('t','code','done',?,?)", (url, time.time()))
    pr = {"url": url, "state": "OPEN", "isDraft": True, "title": "t", "mergeable": "MERGEABLE",
          "statusCheckRollup": [{"name": "tests", "conclusion": "SUCCESS"}]}
    graph = {"data": {"repository": {"pullRequest": {"comments": {"nodes": []}, "reviews": {"nodes": []},
                                                     "reviewThreads": {"nodes": []}}}}}
    monkeypatch.setattr(watchers, "_gh", lambda args, cwd: graph if args[0] == "api" else json.loads(json.dumps(pr)))
    d = Daemon(p.base)

    def events(kind):
        return [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind=? ORDER BY id", (kind,))]

    def ci(**c):
        pr["statusCheckRollup"] = [{"name": "tests", **c}]
        watchers.watch_prs(d)

    watchers.watch_prs(d)   # baseline
    ci(status="IN_PROGRESS")
    ci(conclusion="SUCCESS")
    assert events("pr_changed") == [] and events("pr_findings") == [] and events("pr_clean") == []
    ci(status="QUEUED")
    ci(conclusion="FAILURE")
    assert events("pr_changed") == [] and len(events("pr_findings")) == 1 and "CI failing: tests" in events("pr_findings")[0]
    ci(conclusion="FAILURE")   # unchanged: nothing more
    ci(status="IN_PROGRESS")
    ci(conclusion="SUCCESS")
    assert events("pr_changed") == [] and len(events("pr_findings")) == 1 and len(events("pr_clean")) == 1
    pr["mergeable"] = "CONFLICTING"
    ci(status="IN_PROGRESS")   # CI moving alongside a real change still reports the change
    (changed,) = events("pr_changed")
    assert "MERGEABLE → CONFLICTING" in changed and "checks: passing → pending" in changed
    pr["state"] = "MERGED"
    ci(conclusion="SUCCESS")
    assert len(events("pr_changed")) == 2 and "OPEN → MERGED" in events("pr_changed")[1]


PR_WATCH_GH = '''#!{python}
import json, os, sys
a, path = sys.argv[1:], os.environ["FAKE_PRS"]
prs = json.load(open(path))
with open(os.environ["FAKE_GH_LOG"], "a") as f:
    f.write(" ".join(a) + "\\n")
if a[:2] == ["pr", "view"]:
    print(json.dumps({{"url": a[2], "state": "OPEN", "title": "t", "isDraft": prs[a[2]]}}))
elif a[:2] == ["pr", "ready"] and "--undo" in a and not os.environ.get("FAKE_GH_FAIL"):
    prs[a[2]] = True
    json.dump(prs, open(path, "w"))
else:
    sys.exit(1)
'''


def test_pr_watch_never_changes_a_prs_draft_state_or_reviewers(env, tmp_path, monkeypatch):
    """pr-watch only reads PRs. Whoever took a PR out of draft (the user on GitHub, or a run around the
    harness's gh), it never runs `gh pr ready --undo`, never edits reviewers and never writes to the
    GitHub API; the PR stays as it is."""
    from ttp import prguard, watchers
    from ttp.daemon import Daemon
    assert not hasattr(watchers, "_undo_ready") and not hasattr(prguard, "UNDONE_KEY")
    p = make(env)
    by_user, by_run, ok = (f"https://github.com/acme/widgets/pull/{n}" for n in (3, 7, 9))
    for url in (by_user, by_run, ok):
        p.db.x("INSERT INTO tasks(title,kind,status,pr_url,created) VALUES(?,?,?,?,?)",
               ("t", "code", "done", url, time.time()))
    fake = tmp_path / "bin"
    fake.mkdir()
    (fake / "gh").write_text(PR_WATCH_GH.format(python=sys.executable))
    (fake / "gh").chmod(0o755)
    prs, log = tmp_path / "prs.json", tmp_path / "gh.log"
    prs.write_text(json.dumps({by_user: True, by_run: True, ok: False}))
    log.write_text("")
    monkeypatch.setenv("PATH", f"{fake}:{os.environ['PATH']}")
    monkeypatch.setenv("FAKE_PRS", str(prs))
    monkeypatch.setenv("FAKE_GH_LOG", str(log))
    p.db.set_kv(prguard.APPROVALS_KEY, {"acme/widgets#9": {"source": 1, "answer": 1, "ts": time.time()}})
    d = Daemon(p.base)
    watchers.watch_prs(d)
    _run_tried(p, "acme/widgets#7")
    prs.write_text(json.dumps({by_user: False, by_run: False, ok: False}))
    for _ in range(3):
        watchers.watch_prs(d)
    calls = log.read_text().splitlines()
    assert calls and all(c.startswith("pr view ") or c.startswith("api graphql ") for c in calls), calls
    assert not [c for c in calls if "--undo" in c or "reviewer" in c or "PATCH" in c or "DELETE" in c]
    assert json.loads(prs.read_text()) == {by_user: False, by_run: False, ok: False}
    assert set(p.db.kv(prguard.UNAPPROVED_KEY)) == {"acme/widgets#7"}
    assert p.db.kv(prguard.APPROVALS_KEY)["acme/widgets#3"]["channel"] == prguard.GITHUB


def test_workers_gh_logs_its_ready_and_reviewer_calls_for_pr_watch(env, tmp_path, monkeypatch):
    """Inside a run, the harness's gh still refuses `gh pr ready` and human reviewers without the
    user's approval, and logs each such call with its run, so pr-watch can tell a run's doing from
    the user's. Calls outside a run, and other calls, are not logged."""
    from ttp import prguard, watchers
    from ttp.daemon import Daemon
    p = make(env)
    url = "https://github.com/acme/widgets/pull/7"
    p.db.x("INSERT INTO tasks(title,kind,status,pr_url,created) VALUES(?,?,?,?,?)",
           ("t", "code", "done", url, time.time()))
    _heads_seen(p, "acme/widgets#7")
    monkeypatch.setenv("TTP_RUN_ID", "41")
    monkeypatch.setenv("TTP_TASK", "5")
    gh = _gh_runner(p, tmp_path)
    logged = lambda: [json.loads(x) for x in prguard.gh_log_path(p.state).read_text().splitlines()] \
        if prguard.gh_log_path(p.state).exists() else []
    rc, err, ran = gh("pr", "ready", "7")
    assert rc == 1 and "refused" in err and ran == []
    rc, err, ran = gh("pr", "edit", url, "--add-reviewer", "someone")
    assert rc == 1 and "never request human reviewers" in err and ran == []
    for args in (("pr", "ready", "7", "--undo"), ("pr", "list"), ("pr", "create", "-d"),
                 ("pr", "edit", url, "--add-reviewer", "copilot")):
        gh(*args)
    recs = logged()
    assert [(r["action"], r["prs"], r["refused"], r["run"], r["task"]) for r in recs] == \
        [("ready", ["acme/widgets#7"], True, "41", "5"), ("reviewers", ["acme/widgets#7"], True, "41", "5")]
    assert recs[0]["cmd"] == "pr ready 7"
    # Marked ready on the user's recorded approval: it runs, and is logged as run.
    p.db.set_kv(prguard.APPROVALS_KEY, {"acme/widgets#7": {"answer": 1, "head": HEAD, "spent": None}})
    rc, err, ran = gh("pr", "ready", "7")
    assert rc == 0 and ran == ["pr ready 7"] and not prguard.may_ready(p.db, "acme/widgets#7")
    assert (logged()[-1]["refused"], logged()[-1]["rc"]) == (False, 0)
    # Outside a run nothing is logged.
    monkeypatch.delenv("TTP_RUN_ID")
    n = len(logged())
    assert _gh_runner(p, tmp_path)("pr", "ready", "8")[0] == 1 and len(logged()) == n
    # pr-watch finds run 41's refused call: the PR leaving draft is flagged high, never undone.
    p.db.set_kv(prguard.APPROVALS_KEY, {})
    monkeypatch.setattr(watchers, "_gh", lambda args, cwd: None if args[0] == "api" else
                        {"url": url, "state": "OPEN", "title": "t", "headRefOid": HEAD, "isDraft": False})
    p.db.set_kv("pr_signatures", {})
    watchers.watch_prs(Daemon(p.base))
    assert p.db.kv(prguard.UNAPPROVED_KEY)["acme/widgets#7"]["run"] == "41"


def test_setup_warns_when_installed_copy_is_older_than_checkout(env, tmp_path, monkeypatch, capsys):
    from ttp import cli, project
    home = tmp_path / "home"
    installed = home / "lib" / "0.0.1" / "runtime"
    installed.mkdir(parents=True)
    monkeypatch.setattr(project, "HOME_DIR", home)
    monkeypatch.setattr(cli, "RUNTIME", installed)
    monkeypatch.setattr(cli, "__version__", "0.0.1")
    plugin = tmp_path / "repo" / "plugins" / "tt-project"
    (plugin / "runtime" / "ttp").mkdir(parents=True)
    (plugin / "bin").mkdir()
    (plugin / "bin" / "ttp").write_text("")
    (plugin / "runtime" / "ttp" / "__init__.py").write_text('__version__ = "9.9.9"\n')
    sub = tmp_path / "repo" / "docs"
    sub.mkdir()
    msg = cli.stale_install_warning(sub)
    assert "9.9.9" in msg and f"{plugin / 'bin' / 'ttp'} setup" in msg
    assert "9.9.9" in capsys.readouterr().err
    # Same or older checkout, or running from the checkout itself: no warning.
    (plugin / "runtime" / "ttp" / "__init__.py").write_text('__version__ = "0.0.1"\n')
    assert cli.stale_install_warning(sub) == ""
    (plugin / "runtime" / "ttp" / "__init__.py").write_text('__version__ = "9.9.9"\n')
    monkeypatch.setattr(cli, "RUNTIME", plugin / "runtime")
    assert cli.stale_install_warning(sub) == ""


@needs_sockets
def test_web_api_paths_use_their_own_connection_after_a_coordinator_turn(env):
    """Every API path runs in a request thread, and the helpers it calls must read through that
    thread's connection: the daemon's p.db belongs to the main thread, and SQLite refuses it
    anywhere else. The release line used p.db to find the open upgrade task, so the page's data
    failed whenever an upgrade waited on that task."""
    p = make(env)
    from ttp import release, web
    p.db.set_kv("last_coordinator_turn", time.time() - 600)    # opens p.db in this thread
    p.db.set_kv(release.KV_RELEASE, {"installed": "9.9.9 (abc1234)", "current": "0.0.1 (def5678)",
                                     "key": "9.9.9 abc1234", "newer": True})
    upgrade = p.db.add_task(release.UPGRADE_TASK_TITLE, "merge it", kind="harness", origin="user")
    other = p.db.add_task("docs", "write them")
    port = _start_web(p)
    base, tok = f"http://127.0.0.1:{port}", web.token(p)
    for _ in range(50):
        try:
            urllib.request.urlopen(base + "/", timeout=1)
            break
        except OSError:
            time.sleep(0.1)

    def call(path, body=None):
        req = urllib.request.Request(base + path, headers={"X-TTP-Token": tok, "Content-Type": "application/json"},
                                     method="POST" if body is not None else "GET",
                                     data=json.dumps(body).encode() if body is not None else None)
        try:
            with urllib.request.urlopen(req, timeout=10) as r:
                return r.status, json.loads(r.read())
        except urllib.error.HTTPError as e:
            return e.code, e.read().decode(errors="replace")

    code, data = call("/api/state")
    assert code == 200, data
    assert f"the merge needs harness task #{upgrade}" in data["health"]["release"]
    assert call("/api/messages")[0] == 200
    assert call("/api/pause", {"resource": "board", "paused": True, "reason": "check"})[0] == 400   # no end
    until = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() + 3600))
    assert call("/api/pause", {"resource": "board", "paused": True, "reason": "check", "until": until})[0] == 200
    assert call("/api/pause", {"resource": "board", "paused": False})[0] == 200
    assert call("/api/schedule/pr-watch", {"enabled": False})[0] == 200
    assert call(f"/api/task/{other}", {"status": "cancelled"})[0] == 200
    assert call("/api/config", {"key": "budget.daily_usd", "value": 7})[0] == 200
    assert p.db.task(other)["status"] == "cancelled" and p.config()["budget"]["daily_usd"] == 7


def test_pr_approve_counts_only_a_clear_yes_in_the_users_own_words(env):
    """An answer that is not a yes, words the user never wrote, a reply the harness posted and an
    answer already used once never let a PR out of draft."""
    p = make(env)
    from ttp import coordinator as coord, prguard
    url = "https://github.com/acme/widgets/pull/7"

    def approve(msg, quote):
        return " ".join(coord.apply(p, [{"type": "pr_approve", "id": msg, "text": url, "quote": quote}]))

    _heads_seen(p, "acme/widgets#7")

    coord.apply(p, [{"type": "ask_user", "text": f"Take {url} out of draft?", "blocking": "review",
                     "recommendation": "yes"}])
    ask = p.db.one("SELECT id FROM messages WHERE kind='ask'")["id"]
    p.db.post("out", "yes", chat="web", kind="reply")   # the harness's own words are not the user's
    assert "not answered" in approve(ask, "yes")
    for said in ("no, not yet", "acme/widgets#7 is broken", "yes once CI is green", "ok?",
                 "please look at acme/widgets#7 again", "rename x to y in acme/widgets#7"):
        p.db.post("in", said, chat="web", provenance="web-session")
        assert "not a clear yes" in approve(ask, said), said
    assert "never wrote" in approve(ask, "yes, go ahead")
    assert "needs `quote`" in approve(ask, "")
    assert not prguard.approved(p.db, "acme/widgets#7")
    assert prguard.clear_yes("y") and prguard.clear_yes("Please mark it ready")
    p.db.post("in", "Yes, go ahead", chat="web", provenance="web-session")
    assert "no Slack ts" in approve(ask, "yes, go ahead")   # this ask never reached Slack
    yes = p.db.post("in", f"Yes, go ahead with {url}", chat="web", provenance="web-session")
    assert approve(yes, "yes, go ahead") == ""
    rec = p.db.kv(prguard.APPROVALS_KEY)["acme/widgets#7"]
    assert rec["answer"] == yes and rec["said"] == f"Yes, go ahead with {url}" and rec["spent"] is None
    # Used once, the same answer cannot approve it again.
    prguard.spend(p.db, {"acme/widgets#7"})
    assert not prguard.may_ready(p.db, "acme/widgets#7") and prguard.approved(p.db, "acme/widgets#7")
    assert "fresh yes" in approve(yes, "yes, go ahead")


def test_an_approval_is_spent_and_a_pr_back_in_draft_needs_a_fresh_yes(env, tmp_path, monkeypatch):
    from ttp import coordinator as coord, prguard, watchers
    from ttp.daemon import Daemon
    p = make(env)
    gh = _gh_runner(p, tmp_path)
    url = "https://github.com/acme/widgets/pull/7"
    p.db.x("INSERT INTO tasks(title,kind,status,pr_url,created) VALUES('t','code','done',?,?)", (url, time.time()))
    _heads_seen(p, "acme/widgets#7")
    said = p.db.post("in", f"yes, mark {url} ready", chat="web", provenance="web-session")
    assert coord.apply(p, [{"type": "pr_approve", "id": said, "text": url, "quote": "yes"}]) == []
    assert gh("pr", "ready", "7")[0] == 0
    state = {"isDraft": False}
    monkeypatch.setattr(watchers, "_gh", lambda args, cwd: None if args[0] == "api" else
                        {"url": url, "state": "OPEN", "title": "t", "headRefOid": HEAD, **state})
    d = Daemon(p.base)
    watchers.watch_prs(d)
    assert p.db.kv(prguard.UNAPPROVED_KEY) == {}, "a PR the user approved was flagged"
    state["isDraft"] = True    # the user put it back in draft
    watchers.watch_prs(d)
    assert not prguard.approved(p.db, "acme/widgets#7")
    rc, err, _ = gh("pr", "ready", "7")
    assert rc == 1 and "hand off `blocked`" in err and "PR's URL" in err
    assert "fresh yes" in " ".join(coord.apply(p, [{"type": "pr_approve", "id": said, "text": url,
                                                    "quote": "yes"}]))


def test_task_specs_that_take_a_pr_out_of_draft_need_the_users_approval(env):
    p = make(env)
    from ttp import coordinator as coord
    url = "https://github.com/acme/widgets/pull/7"
    for spec in (f"Mark {url} ready for review.", "Run gh pr ready 7 in acme/widgets#7.",
                 "Set draft=false on acme/widgets#7 via the API", "Update the description and mark it ready."):
        out = " ".join(coord.apply(p, [{"type": "task_add", "title": "ready it", "kind": "code", "spec": spec}]))
        assert "rejected" in out and "approval is not on record" in out, spec
    assert not p.db.q("SELECT id FROM tasks")
    for n, spec in enumerate((f"Put {url} back with gh pr ready --undo", "NEVER mark a PR ready for review",
                              "Make the guard refuse gh pr ready without approval", f"Fix CI on {url}")):
        assert coord.apply(p, [{"type": "task_add", "title": f"ok {n}", "kind": "code", "spec": spec}]) == [], spec
    tid = p.db.one("SELECT id FROM tasks WHERE title='ok 3'")["id"]
    out = " ".join(coord.apply(p, [{"type": "task_update", "id": tid, "spec": f"Then gh pr ready {url}"}]))
    assert "rejected" in out and "Then gh pr ready" not in p.db.task(tid)["spec"]
    _heads_seen(p, "acme/widgets#7")
    said = p.db.post("in", f"yes, {url} can leave draft", chat="web", provenance="web-session")
    assert coord.apply(p, [{"type": "pr_approve", "id": said, "text": url, "quote": "yes"}]) == []
    assert coord.apply(p, [{"type": "task_update", "id": tid, "spec": f"Then gh pr ready {url}"}]) == []


def test_a_task_asked_to_deliver_a_pr_runs_as_code(env):
    """A `work` task whose spec asked for a draft PR was refused by its worker (only code tasks open
    PRs) and produced nothing. task_add and a spec update now make such a task `code`, and say why."""
    p = make(env)
    from ttp import coordinator as coord, prguard
    asks = ("Deliver the reviewed harness as one draft PR using supported guarded publication.",
            "Publish the reviewed repair as a draft PR after the review passes.",
            "Fix the parser, then open a draft PR against main, never mark it ready.",
            "Update the PR description with the new numbers.", "Run gh pr create --draft.",
            "Publish the branch with ttp push --own --detach.")
    for n, spec in enumerate(asks):
        kind = "question" if n % 2 else "work"
        out = coord.apply(p, [{"type": "task_add", "title": f"deliver {n}", "kind": kind, "spec": spec}])
        assert out == [], out
        task = p.db.one("SELECT * FROM tasks WHERE title=?", (f"deliver {n}",))
        assert task["kind"] == "code", spec
        note = " ".join(p.db.kv(coord.NOTES_KEY))
        assert f"#{task['id']} added as `code`, not `{kind}`" in note and "only code tasks" in note, note
    # A condition or a time before the comma does not make it a rule.
    for spec in ("If CI passes, open a draft PR.", "When done, open a draft PR."):
        assert prguard.delivery_instruction(spec), spec
    # The title alone asks for it too.
    coord.apply(p, [{"type": "task_add", "title": "Deliver the fix as a draft PR", "spec": "see task 3"}])
    assert p.db.one("SELECT kind FROM tasks WHERE title='Deliver the fix as a draft PR'")["kind"] == "code"
    # Rules about PRs, questions about them and someone else's PR are not a request to deliver one.
    for n, spec in enumerate(("Never open pull requests (the user opens the PR).", "Do not open a PR.",
                 "Only code tasks may open PRs.", "The user will open the PR later; write the report.",
                 "Find out how to open a PR on a fork.", "Leave PR123 untouched; no force-push.",
                 "Summarize the review comments on https://github.com/acme/widgets/pull/7 in a report.",
                 "Check whether the opened PR passes CI.",
                 # "open" as an adjective, and a bare plural, describe PRs; they do not ask for one.
                 "Use GitHub sources to identify relevant open PRs and record their authors.",
                 "Look at commits and PRs from the last 3 weeks (main and open PRs) for speedups.",
                 "List the open pull requests.",
                 # A negation carries through a comma list.
                 "Do not force-push, open PRs or merge.", "Never push to main, open PRs or force-push.",
                 "Do not force-push, open a PR or merge.", "Never push to main, open a draft PR or force-push.",
                 # A PR as a modifier or a thing to read.
                 "Send a PR status digest to the chat.", "Update the PR list in the weekly report.",
                 "Open PR 12 in the browser and summarise it.", "Publish the summary in the PR thread.")):
        assert prguard.delivery_instruction(spec) is None, spec
        title = f"no pr {n}"
        coord.apply(p, [{"type": "task_add", "title": title, "kind": "work", "spec": spec}])
        assert p.db.one("SELECT kind FROM tasks WHERE title=?", (title,))["kind"] == "work", spec
    # Reviews, plans and harness tasks keep their kind.
    for kind in ("review", "plan", "harness"):
        coord.apply(p, [{"type": "task_add", "title": f"k {kind}", "kind": kind, "spec": asks[0]}])
        assert p.db.one("SELECT kind FROM tasks WHERE title=?", (f"k {kind}",))["kind"] == kind
    # A spec update asking for it switches a queued task; a running one keeps its kind mid-run.
    tid = p.db.add_task("report", "write the report", kind="work", tier="light", origin="user")
    assert coord.apply(p, [{"type": "task_update", "id": tid, "spec": "Then open a draft PR with it."}]) == []
    assert p.db.task(tid)["kind"] == "code"
    assert f"#{tid} is now `code`, not `work`" in " ".join(p.db.kv(coord.NOTES_KEY))
    busy = p.db.add_task("busy", "write the report", kind="work", tier="light", origin="user")
    p.db.update_task(busy, status="running")
    coord.apply(p, [{"type": "task_update", "id": busy, "spec": "Then open a draft PR with it."}])
    assert p.db.task(busy)["kind"] == "work"
    note = " ".join(p.db.kv(coord.NOTES_KEY))
    assert f"#{busy} asks for PR delivery but is running as `work`" in note and "continues" in note, note


def test_an_approval_covers_only_the_commit_the_user_said_yes_to(env, tmp_path, monkeypatch):
    """A yes was recorded, then more commits were pushed and the PR was marked ready with them. The
    approval is bound to the PR's head as pr-watch last read it: a moved head is refused (and the
    worker told to hand off blocked), and a head first seen after the yes cannot be approved with it."""
    from ttp import coordinator as coord, prguard, watchers
    from ttp.daemon import Daemon
    p = make(env)
    gh = _gh_runner(p, tmp_path)
    url, moved = "https://github.com/acme/widgets/pull/7", "b" * 40
    p.db.x("INSERT INTO tasks(title,kind,status,pr_url,created) VALUES('t','code','done',?,?)", (url, time.time()))
    pr = {"url": url, "state": "OPEN", "title": "t", "isDraft": True, "headRefOid": HEAD}
    monkeypatch.setattr(watchers, "_gh", lambda args, cwd: None if args[0] == "api" else dict(pr))

    def approve(msg):
        return " ".join(coord.apply(p, [{"type": "pr_approve", "id": msg, "text": url, "quote": "yes"}]))

    early = p.db.post("in", f"yes, mark {url} ready", chat="web", provenance="web-session")
    assert "has not read" in approve(early), "approved with no head commit on record"
    d = Daemon(p.base)
    watchers.watch_prs(d)          # pr-watch reads the head only after that yes
    assert p.db.kv(prguard.HEADS_KEY)["acme/widgets#7"]["sha"] == HEAD
    assert "new commits since the user's yes" in approve(early)
    said = p.db.post("in", f"yes, mark {url} ready", chat="web", provenance="web-session")
    assert approve(said) == ""
    assert p.db.kv(prguard.APPROVALS_KEY)["acme/widgets#7"]["head"] == HEAD
    # Commits pushed after the yes: every way of marking it ready is refused, and the approval stays unspent.
    for args in [("pr", "ready", "7"), ("api", "graphql", "-f", READY_7),
                 ("api", "-X", "PATCH", "repos/acme/widgets/pulls/7", "-F", "draft=false")]:
        rc, err, ran = gh(*args, head=moved)
        assert rc == 1 and ran == [], f"gh {' '.join(args)} let new commits out of draft"
        assert "new commits since the user approved it" in err and "hand off `blocked`" in err and "PR's URL" in err
    assert prguard.may_ready(p.db, "acme/widgets#7")
    # pr-watch sees the new head after the yes: re-recording the same yes does not cover it.
    pr["headRefOid"] = moved
    watchers.watch_prs(d)
    assert "new commits since the user's yes" in approve(said)
    # The head the user said yes to is still the head: it may leave draft (once).
    pr["headRefOid"] = HEAD
    watchers.watch_prs(d)
    yes = p.db.post("in", f"yes, mark {url} ready", chat="web", provenance="web-session")
    assert approve(yes) == ""
    rc, err, ran = gh("pr", "ready", "7")
    assert rc == 0 and ran, err
    # An approval recorded before heads were bound has no head and lets nothing out of draft.
    p.db.set_kv(prguard.APPROVALS_KEY, {"acme/widgets#7": {"answer": 1, "spent": None}})
    rc, err, ran = gh("pr", "ready", "7")
    assert rc == 1 and ran == [] and "could not check that its head commit" in err


def test_gh_opens_a_draft_pr_only_after_the_runs_checks_passed_on_head(env, tmp_path, monkeypatch):
    from ttp import cli
    p = make(env)
    repo, run = tmp_path / "work", tmp_path / "run"
    run.mkdir()
    repo.mkdir()
    git = ["git", "-C", str(repo), "-c", "user.email=t@example.com", "-c", "user.name=t"]
    subprocess.run(["git", "init", "-q", str(repo)], check=True)
    (repo / "a.txt").write_text("a\n")
    subprocess.run([*git, "add", "a.txt"], check=True)
    subprocess.run([*git, "commit", "-qm", "a"], check=True)
    gh = _gh_runner(p, tmp_path, run_dir=run, cwd=repo)
    rc, err, ran = gh("pr", "create", "--draft", "--title", "t")
    assert rc == 1 and ran == [] and "ttp checks" in err, "a draft PR opened with no checks on record"
    monkeypatch.setenv("TTP_RUN_DIR", str(run))
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    monkeypatch.chdir(repo)
    with pytest.raises(SystemExit) as e:
        cli.main(["checks", "--", "false"])
    assert e.value.code == 1
    assert gh("pr", "create", "--draft", "--title", "t")[0] == 1, "failed checks let a draft PR open"
    cli.main(["checks", "--", "test", "-f", "a.txt"])
    assert json.loads((run / "checks.json").read_text())["passed"] is True
    rc, err, ran = gh("pr", "create", "--draft", "--title", "t")
    assert rc == 0 and ran, err
    assert gh("api", "repos/acme/widgets/pulls", "-F", "draft=true", "-f", "title=t")[0] == 0
    (repo / "a.txt").write_text("b\n")
    with pytest.raises(SystemExit):
        cli.main(["checks", "--", "true"])   # an uncommitted change is not what the PR shows
    subprocess.run([*git, "commit", "-qam", "b"], check=True)
    rc, err, ran = gh("pr", "create", "--draft", "--title", "t")
    assert rc == 1 and "not on this worktree's HEAD" in err, "checks on an older commit let a PR open"


def test_gh_accepts_a_checks_pass_from_another_run_of_the_task_only_on_the_same_clean_head(env, tmp_path,
                                                                                           monkeypatch):
    """A detached `ttp checks` passes in one run; the task's wake run opens the PR on that pass. Only the
    same task, the same worktree, the same HEAD, no uncommitted changes and a pass that is the latest
    record on that HEAD count."""
    p = make(env)
    repo, other = tmp_path / "work", tmp_path / "other"
    git = ["git", "-C", str(repo), "-c", "user.email=t@example.com", "-c", "user.name=t"]
    subprocess.run(["git", "init", "-q", str(repo)], check=True)
    (repo / "a.txt").write_text("a\n")
    subprocess.run([*git, "add", "a.txt"], check=True)
    subprocess.run([*git, "commit", "-qm", "a"], check=True)
    head = subprocess.run([*git, "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    task = p.db.x("INSERT INTO tasks(title,kind,status,created) VALUES('t','code','running',?)", (time.time(),))
    stranger = p.db.x("INSERT INTO tasks(title,kind,status,created) VALUES('u','code','running',?)", (time.time(),))

    def run_of(t, rec=None):
        rid = p.db.x("INSERT INTO runs(task,role,status) VALUES(?,'worker','ok')", (t,))
        (p.runs / str(rid)).mkdir(parents=True, exist_ok=True)
        if rec is not None:
            (p.runs / str(rid) / "checks.json").write_text(json.dumps(rec))
        return p.runs / str(rid)

    def rec(passed=True, sha=head, top=repo):
        return {"head": sha, "worktree": str(top), "passed": passed, "commands": ["true"], "ts": time.time()}

    def opens(wake):
        monkeypatch.setenv("TTP_TASK", str(task))
        r = _gh_runner(p, tmp_path, run_dir=wake, cwd=repo)("pr", "create", "--draft", "--title", "t")
        return r[0] == 0 and bool(r[2]), r[1]

    run_of(stranger, rec())                       # another task's pass on this very head
    wake = run_of(task)
    assert not opens(wake)[0], "another task's pass let a PR open"
    run_of(task, rec(top=other))                  # this task's pass in another worktree
    assert not opens(run_of(task))[0], "a pass in another worktree let a PR open"
    run_of(task, rec())                           # the detached checks of an earlier run passed on HEAD
    wake = run_of(task)
    ok, err = opens(wake)
    assert ok, err
    (repo / "a.txt").write_text("dirty\n")
    ok, err = opens(wake)
    assert not ok and "ttp checks" in err, "a pass let a PR open from a worktree with uncommitted changes"
    subprocess.run([*git, "checkout", "-q", "a.txt"], check=True)
    assert opens(wake)[0]
    run_of(task, rec(passed=False))               # a later run's checks failed on the same head
    assert not opens(run_of(task))[0], "an earlier pass outweighed a later failure on the same head"
    run_of(task, rec())
    subprocess.run([*git, "commit", "-q", "--allow-empty", "-m", "b"], check=True)
    ok, err = opens(run_of(task))
    assert not ok and "ttp checks" in err, "a pass on an older HEAD let a PR open"
    # This run's own failed record on HEAD is not outweighed by an earlier run's pass on it.
    new = subprocess.run([*git, "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    run_of(task, rec(sha=new))
    wake = run_of(task, rec(passed=False, sha=new))
    ok, err = opens(wake)
    assert not ok and "failed" in err


def test_ttp_checks_reuses_a_pass_of_the_same_commands_given_in_another_form(env, tmp_path, monkeypatch, capsys):
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    cli.main(["checks", "--", "test", "-f", "a.txt"])
    assert "(recorded)" not in capsys.readouterr().out
    for form in (["test  -f 'a.txt'"], ["--", 'test -f "a.txt"'], ["test", "-f", "a.txt"]):
        cli.main(["checks", *form])
        assert "(recorded)" in capsys.readouterr().out, f"{form} ran the same check again"
    # Shell syntax can change what runs: a quoted glob or `$` is not the bare one.
    assert cli._command_key("ls '*.py'") != cli._command_key("ls *.py")
    assert cli._command_key("echo '$HOME'") != cli._command_key("echo $HOME")
    assert cli._command_key("a 'b;c'") != cli._command_key("a b;c")
    assert cli._command_key("pytest -k 'a and b'") == cli._command_key('pytest  -k "a and b"')


def test_pr_watch_turns_ci_failures_and_bot_comments_into_work_before_the_review_ask(env, monkeypatch):
    from ttp import coordinator as coord, prguard, watchers
    from ttp.daemon import Daemon
    p = make(env)
    url = "https://github.com/acme/widgets/pull/7"
    p.db.x("INSERT INTO tasks(title,kind,status,pr_url,created) VALUES('t','code','done',?,?)", (url, time.time()))
    bot, human = {"__typename": "Bot", "login": "review-bot"}, {"__typename": "User", "login": "dev"}
    pr = {"url": url, "state": "OPEN", "isDraft": True, "title": "t",
          "statusCheckRollup": [{"name": "tests", "conclusion": "FAILURE"}]}
    thread = {"isResolved": False, "isOutdated": False, "comments": {"nodes": [{"author": bot, "url": "u1"}]}}
    graph = {"data": {"repository": {"pullRequest": {"comments": {"nodes": []}, "reviews": {"nodes": []},
                                                     "reviewThreads": {"nodes": [thread]}}}}}
    monkeypatch.setattr(watchers, "_gh", lambda args, cwd: graph if args[0] == "api" else pr)
    d = Daemon(p.base)

    def events(kind):
        return [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind=? ORDER BY id", (kind,))]

    def ask():
        return coord.apply(p, [{"type": "ask_user", "text": f"Review draft {url}?", "blocking": "review",
                                "recommendation": "yes"}])

    watchers.watch_prs(d)
    watchers.watch_prs(d)
    found = events("pr_findings")
    assert len(found) == 1 and "tests" in found[0] and "1 bot review comment" in found[0] and "code task" in found[0]
    out = " ".join(ask())
    assert "rejected" in out and "open findings" in out
    pr["statusCheckRollup"] = [{"name": "tests", "conclusion": "SUCCESS"}]   # CI fixed; the bot comment is not
    watchers.watch_prs(d)
    assert len(events("pr_findings")) == 2 and "rejected" in " ".join(ask())
    thread["comments"]["nodes"].append({"author": human, "url": "u2"})      # answered on the PR
    pr["statusCheckRollup"] = [{"name": "tests", "status": "IN_PROGRESS"}]
    watchers.watch_prs(d)
    assert "still running" in " ".join(ask()) and not events("pr_clean")
    pr["statusCheckRollup"] = [{"name": "tests", "conclusion": "SUCCESS"}]
    watchers.watch_prs(d)
    clean = events("pr_clean")
    assert len(clean) == 1 and "ask the user for a draft review" in clean[0]
    assert ask() == []
    assert prguard.findings_problem(p.db, "Other PR acme/widgets#8") is None
    # A bot's top-level comment counts until a person comments after it.
    graph["data"]["repository"]["pullRequest"]["comments"]["nodes"] = [
        {"author": bot, "createdAt": "2026-01-02T00:00:00Z", "url": "c1"},
        {"author": human, "createdAt": "2026-01-01T00:00:00Z", "url": "c0"}]
    assert watchers.bot_open(graph) == ["c1"]
    graph["data"]["repository"]["pullRequest"]["comments"]["nodes"].append(
        {"author": human, "createdAt": "2026-01-03T00:00:00Z", "url": "c2"})
    assert watchers.bot_open(graph) == []


def test_pr_findings_keep_one_owner_when_the_task_that_delivered_the_pr_finishes(env, monkeypatch):
    """Open findings on a PR whose delivering task is done get exactly one owner: while a task on the
    PR is open it owns them and no second one is queued; once none is, the daemon queues one code task
    on the PR's branch (even when pr-watch already reported the same findings), a bounded number of
    times. pr-watch only reports; the coordinator is told who owns them."""
    from ttp import daemon as dm, watchers
    from ttp.daemon import Daemon
    p = make(env)
    url = "https://github.com/acme/widgets/pull/7"
    src = p.db.add_task("Speed up the loader", "s", kind="code", tier="deep", priority=2)
    p.db.update_task(src, status="running", pr_url=url, branch=f"ttp/t{src}-speed-up-the-loader")
    bot = {"__typename": "Bot", "login": "review-bot"}
    pr = {"url": url, "state": "OPEN", "isDraft": True, "title": "t", "headRefName": f"ttp/t{src}-speed-up-the-loader",
          "statusCheckRollup": [{"name": "tests", "conclusion": "FAILURE"}]}
    thread = {"isResolved": False, "isOutdated": False, "comments": {"nodes": [{"author": bot, "url": "u1"}]}}
    graph = {"data": {"repository": {"pullRequest": {"comments": {"nodes": []}, "reviews": {"nodes": []},
                                                     "reviewThreads": {"nodes": [thread]}}}}}
    monkeypatch.setattr(watchers, "_gh", lambda args, cwd: graph if args[0] == "api" else pr)
    d = Daemon(p.base)

    def events():
        return [(e["status"], e["text"]) for e in p.db.q("SELECT status, text FROM events WHERE kind='pr_findings' ORDER BY id")]

    def fixes():
        return p.db.q("SELECT * FROM tasks WHERE labels LIKE '%pr_fix:%' ORDER BY id")

    watchers.watch_prs(d)
    ((st, text),) = events()
    assert f"Open task #{src} (running) owns them" in text and st == "handled" and not fixes()
    # The delivering task finishes with the same findings open: nothing new to report, but they need an owner.
    p.db.update_task(src, status="done")
    watchers.watch_prs(d)
    (fix,) = fixes()
    assert (fix["kind"], fix["tier"], fix["priority"], fix["origin"], fix["branch"]) == (
        "code", "deep", 2, "daemon", f"ttp/t{src}-speed-up-the-loader")
    assert f'"continues:{src}"' in fix["labels"] and url in fix["spec"] and "u1" in fix["spec"]
    assert "open no new PR" in fix["spec"] and "ttp push --own" in fix["spec"]
    st, text = events()[-1]
    assert st == "handled" and f"queued code task #{fix['id']}" in text and "Queue no other task" in text
    watchers.watch_prs(d)
    watchers.watch_prs(d)
    assert len(fixes()) == 1 and len(events()) == 2, "a second owner was queued"
    # A task the coordinator queued for the PR (its spec names it) is an owner too.
    p.db.update_task(fix["id"], status="cancelled")
    other = p.db.add_task("Answer the bot on acme/widgets#7", "Fix acme/widgets#7.", kind="code")
    watchers.watch_prs(d)
    assert len(fixes()) == 1 and p.db.task(other)["status"] == "queued"
    # Bounded: after PR_FIX_ROUNDS daemon fixes the findings go back to the coordinator, once.
    p.db.update_task(other, status="done")
    for _ in range(dm.PR_FIX_ROUNDS + 2):
        watchers.watch_prs(d)
        for f in fixes():
            if f["status"] == "queued":
                p.db.update_task(f["id"], status="done")
    assert len(fixes()) == dm.PR_FIX_ROUNDS
    st, text = events()[-1]
    assert st == "queued" and "no open task owns them now" in text and "queue a code task" in text
    n = len(events())
    watchers.watch_prs(d)
    assert len(events()) == n
    # A branch another worktree still holds is not checked out again: the fix builds on its head.
    p.db.x("UPDATE tasks SET labels='[]' WHERE labels LIKE '%pr_fix:%'")
    subprocess.run(["git", "-C", str(p.root), "branch", pr["headRefName"]], check=True)
    subprocess.run(["git", "-C", str(p.root), "worktree", "add", "-q", str(env["tmp"] / "held"), pr["headRefName"]],
                   check=True)
    watchers.watch_prs(d)
    (fix,) = fixes()
    assert fix["branch"] is None and f'"continues:{src}"' in fix["labels"] and pr["headRefName"] in fix["spec"]
    # A delivering task that failed is the coordinator's call: no fix is queued for it.
    p.db.x("DELETE FROM tasks WHERE id=?", (fix["id"],))
    p.db.update_task(src, status="failed")
    watchers.watch_prs(d)
    assert not fixes()


def test_a_pr_fix_task_publishes_onto_the_prs_branch_whether_it_is_free_or_held(env, monkeypatch, capsys):
    """The daemon's PR-fix task delivers with `ttp push --own` onto the PR's branch, the finished task's
    ttp/t<id>-... branch: from a worktree on that branch when it is free, and from its own branch onto
    the PR's when another worktree holds it. Fast-forward only, never a new remote branch."""
    from ttp import push, worktree
    from ttp.daemon import Daemon
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    url = "https://github.com/acme/widgets/pull/7"
    src = p.db.add_task("Speed up the loader", "s", kind="code")
    pr_branch = f"ttp/t{src}-speed-up-the-loader"
    p.db.update_task(src, status="done", pr_url=url, branch=pr_branch)
    _git_out(repo, "branch", pr_branch)
    other_wt = env["tmp"] / "pr"
    _git_out(repo, "worktree", "add", "-q", str(other_wt), pr_branch)
    _commit(other_wt, "pr.txt", "pr\n")
    _git_out(other_wt, "push", "-q", "origin", f"HEAD:refs/heads/{pr_branch}")
    _git_out(repo, "worktree", "remove", str(other_wt))
    d = Daemon(p.base)
    rec = {"task": src, "branch": pr_branch, "url": url}

    def publish(fix):
        path, branch = worktree.ensure(p, fix)
        _commit(path, f"fix{fix['id']}.txt", "fix\n")
        monkeypatch.chdir(path)
        monkeypatch.setenv("TTP_TASK", str(fix["id"]))
        assert push.resolve(p, path, own=True) == ("origin", pr_branch, True), branch
        assert _ttp("push", "--own") == 0, capsys.readouterr().err
        assert _git_out(origin, "rev-parse", pr_branch) == _git_out(path, "rev-parse", "HEAD")
        return path, branch

    # Free: the fix works on the PR's branch itself.
    fix, made = d.pr_findings_owner("acme/widgets#7", rec, "CI failing: tests")
    assert made and fix["branch"] == pr_branch
    path, branch = publish(fix)
    assert branch == pr_branch
    p.db.update_task(fix["id"], status="done")
    monkeypatch.chdir(repo)
    # Held: another worktree keeps the PR's branch; the fix's own branch is published onto the PR's.
    fix, made = d.pr_findings_owner("acme/widgets#7", rec, "CI failing: tests")
    assert made and fix["branch"] is None and f'"pr_branch:{pr_branch}"' in fix["labels"]
    assert "checked out elsewhere" in fix["spec"]
    path2, branch2 = publish(fix)
    assert branch2 == f"ttp/t{fix['id']}-fix-pr-findings-speed-up-the-loader"
    remote = _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads").split()
    assert branch2 not in remote and pr_branch in remote
    # Never a rewrite: a head that does not fast-forward the PR's branch is refused before the checks.
    _git_out(path2, "reset", "-q", "--hard", "HEAD~2")
    _commit(path2, "other.txt", "x\n")
    tip = _git_out(origin, "rev-parse", pr_branch)
    assert _ttp("push", "--own") == 2 and "not an ancestor" in capsys.readouterr().err
    assert _git_out(origin, "rev-parse", pr_branch) == tip
    # Another task, neither carrying nor continuing the PR's branch, still may not publish it.
    monkeypatch.chdir(path)
    monkeypatch.setenv("TTP_TASK", str(p.db.add_task("unrelated", kind="code")))
    with pytest.raises(ValueError):
        push.own_target(p, path)


def test_task_add_naming_a_finished_tasks_branch_carries_it_only_with_a_pr_branch_line(env):
    """A task_add whose spec names a done task's work branch (ttp/t<id>-...) carries it only with a
    `pr_branch:` line naming it: a mere mention (a plan or follow-up citing earlier work) carries
    nothing and the coordinator is told so. Failed or cancelled work is continued instead, so `ttp push
    --own` accepts the branch. One that already carries a branch is left alone, and a name that matches
    no task's branch, or a live task's, is not labelled."""
    p = make(env)
    from ttp import coordinator as coord

    def labels(title):
        return json.loads(p.db.one("SELECT labels FROM tasks WHERE title=?", (title,))["labels"])

    src = p.db.add_task("Speed up the loader", "s", kind="code")
    b = f"ttp/t{src}-speed-up-the-loader"
    p.db.update_task(src, status="done", branch=b)
    # (a) Done work merely named (a plan task citing earlier work): no label, and the coordinator is told why.
    for kind, title, spec in (("code", "Profile the decoder", f"Profile the decoder the way `{b}` did."),
                              ("plan", "Plan the cache work", f"Plan the cache work; {b} has the loader part."),
                              ("question", "Why is it slow", f"Explain why reads stay slow after {b}?")):
        assert coord.apply(p, [{"type": "task_add", "title": title, "kind": kind, "spec": spec}]) == [], kind
        new = p.db.one("SELECT id FROM tasks WHERE title=?", (title,))["id"]
        assert not [x for x in labels(title) if x.startswith(("pr_branch:", "continues:"))], kind
        assert any(f"#{new} names #{src}'s branch {b} but carries no branch" in n
                   for n in p.db.kv(coord.NOTES_KEY)), kind
    # Only a `pr_branch:` line naming it carries it.
    assert coord.apply(p, [{"type": "task_add", "title": "Fix the PR's CI", "kind": "code",
                            "spec": f"pr_branch: {b}\nCI fails on the PR from branch `{b}`. Fix it there."}]) == []
    assert labels("Fix the PR's CI") == [f"pr_branch:{b}"]
    # A never-started task's branch is the name worktree.ensure would give it.
    idle = p.db.add_task("Tidy the docs", "s", kind="code")
    p.db.update_task(idle, status="cancelled")
    # Failed or cancelled work is continued instead (it takes over its dependents).
    dep = p.db.add_task("after the docs", "s", depends_on=[idle])
    assert coord.apply(p, [{"type": "task_add", "title": "Docs again", "kind": "code",
                            "spec": f"Pick up ttp/t{idle}-tidy-the-docs and finish it."}]) == []
    again = p.db.one("SELECT id FROM tasks WHERE title='Docs again'")["id"]
    assert labels("Docs again") == [f"continues:{idle}"]
    assert json.loads(p.db.task(dep)["depends_on"]) == [again]
    # (b) Already carrying a branch: left alone.
    gone = p.db.add_task("Port the parser", "s", kind="code")
    p.db.update_task(gone, status="failed", branch=f"ttp/t{gone}-port-the-parser")
    assert coord.apply(p, [{"type": "task_add", "title": "Parser, smaller", "kind": "code", "continues": gone,
                            "spec": f"Finish ttp/t{gone}-port-the-parser in a smaller scope."}]) == []
    assert labels("Parser, smaller") == [f"continues:{gone}"]
    assert coord.apply(p, [{"type": "task_add", "title": "Fix the feature PR", "kind": "code",
                            "spec": f"pr_branch: `feature/fast-io`\nLike {b}, but on the feature branch."}]) == []
    assert labels("Fix the feature PR") == ["pr_branch:feature/fast-io"]
    # (c) No such task, a branch that is not the task's, a live task's branch, or a review: no label.
    live = p.db.add_task("Rewrite the cache", "s", kind="code")
    p.db.update_task(live, status="running", branch=f"ttp/t{live}-rewrite-the-cache")
    for title, kind, spec in (("Nothing named", "code", "Work from ttp/t99999-no-such-task please."),
                              ("Wrong slug", "code", f"Work from ttp/t{src}-another-name please."),
                              ("Live branch", "code", f"Help ttp/t{live}-rewrite-the-cache along."),
                              ("Review the loader", "review", f"Review {b}.")):
        assert coord.apply(p, [{"type": "task_add", "title": title, "kind": kind, "spec": spec}]) == [], title
        assert not [x for x in labels(title) if x.startswith(("pr_branch:", "continues:"))], title


def test_follow_ups_and_redos_carry_a_branch_only_when_they_should(env):
    """A follow-up (`continues` on a done task) that names a finished task's branch but has no
    `pr_branch:` line carries no branch, so it lands on the push branch with `ttp push`; one with its
    own line carries that branch. A continuation of a failed task keeps the branch that task carried,
    unless its spec names only the push branch or the coordinator sets `pr_branch` to "" (task_add, or
    task_update before it starts): then it carries none (push.pr_branch_of)."""
    p = make(env)
    from ttp import coordinator as coord
    from ttp import push

    def task(title):
        return p.db.one("SELECT * FROM tasks WHERE title=?", (title,))

    def labels(title):
        return json.loads(task(title)["labels"])

    p.set_config("delivery.push_branch", "origin/proj")
    src = p.db.add_task("Speed up the loader", "s", kind="code")
    b = f"ttp/t{src}-speed-up-the-loader"
    p.db.update_task(src, status="done", branch=b)
    rev = p.db.add_task("Review the loader", "s", kind="review")
    p.db.update_task(rev, status="done")
    # A follow-up naming the done task's branch as where its commit comes from: no label.
    assert coord.apply(p, [{"type": "task_add", "title": "Land the last commit", "kind": "code", "continues": rev,
                            "spec": f"Cherry-pick the last commit of {b} and land it on proj with `ttp push`."}]) == []
    assert labels("Land the last commit") == []
    assert push.pr_branch_of(p, task("Land the last commit")) == ""
    # A follow-up with its own line carries that branch.
    assert coord.apply(p, [{"type": "task_add", "title": "Fix the loader PR", "kind": "code", "continues": rev,
                            "spec": f"pr_branch: `{b}`\nFix the PR's CI."}]) == []
    assert labels("Fix the loader PR") == [f"pr_branch:{b}"]
    # A continuation of a failed task keeps the branch that task carried (it exists).
    subprocess.run(["git", "-C", str(p.root), "branch", "feature/x"], check=True, capture_output=True)
    gone = p.db.add_task("Fix the feature PR", "s", kind="code", labels=["pr_branch:feature/x"])
    p.db.update_task(gone, status="failed", branch=f"ttp/t{gone}-fix-the-feature-pr")
    assert coord.apply(p, [{"type": "task_add", "title": "Feature PR again", "kind": "code", "continues": gone,
                            "spec": "Finish the CI fix."}]) == []
    assert labels("Feature PR again") == [f"continues:{gone}"]
    assert push.pr_branch_of(p, task("Feature PR again")) == "feature/x"
    # A redo of a cancelled, mislabelled task whose spec names only the push branch carries none.
    bad = p.db.add_task("Land the entry", "s", kind="code", labels=[f"pr_branch:{b}"])
    p.db.update_task(bad, status="cancelled")
    assert coord.apply(p, [{"type": "task_add", "title": "Land the entry, redo", "kind": "code", "continues": bad,
                            "spec": "Land the entry on proj with `ttp push`; this task has no PR-branch label."}]) == []
    redo = task("Land the entry, redo")
    assert labels("Land the entry, redo") == [f"continues:{bad}", "no_pr_branch"]
    assert push.pr_branch_of(p, redo) == "" and push.pr_elsewhere(p, redo, p.config()["delivery"]) == ""
    assert any(f"#{redo['id']} continues #{bad} but not its branch {b}" in n for n in p.db.kv(coord.NOTES_KEY))
    # A branch never published (neither here nor on a remote) cannot be delivered onto: a redo that
    # does not name it carries none; one that names it keeps it.
    lost = p.db.add_task("Land the table", "s", kind="code", labels=["pr_branch:feature/never-made"])
    p.db.update_task(lost, status="cancelled")
    assert coord.apply(p, [{"type": "task_add", "title": "Land the table, redo", "kind": "code", "continues": lost,
                            "spec": "Land the table."},
                           {"type": "task_add", "title": "Make the table PR", "kind": "code", "continues": lost,
                            "spec": "Create feature/never-made with the table."}]) == []
    assert labels("Land the table, redo") == [f"continues:{lost}", "no_pr_branch"]
    assert any(f"#{task('Land the table, redo')['id']} continues #{lost} but not its branch feature/never-made "
               f"(never published)" in n for n in p.db.kv(coord.NOTES_KEY))
    assert labels("Make the table PR") == [f"continues:{lost}"]
    # Or the coordinator says so: pr_branch "" on task_add ...
    bad2 = p.db.add_task("Land the docs", "s", kind="code", labels=["pr_branch:feature/x"])
    p.db.update_task(bad2, status="cancelled")
    assert coord.apply(p, [{"type": "task_add", "title": "Land the docs, redo", "kind": "code", "continues": bad2,
                            "pr_branch": "", "spec": "Land the docs."}]) == []
    assert push.pr_branch_of(p, task("Land the docs, redo")) == ""
    # ... or on task_update before it starts, which also drops its own label; never once it runs.
    assert coord.apply(p, [{"type": "task_update", "id": task("Feature PR again")["id"], "pr_branch": ""},
                           {"type": "task_update", "id": task("Fix the loader PR")["id"], "pr_branch": ""}]) == []
    assert labels("Feature PR again") == [f"continues:{gone}", "no_pr_branch"]
    assert labels("Fix the loader PR") == ["no_pr_branch"]
    assert push.pr_branch_of(p, task("Feature PR again")) == ""
    p.db.update_task(task("Land the docs, redo")["id"], status="running")
    problems = coord.apply(p, [{"type": "task_update", "id": task("Land the docs, redo")["id"], "pr_branch": ""}])
    assert problems and "running" in problems[0]


def test_a_pr_branch_line_labels_its_first_token_with_text_after_it(env):
    """A spec's `pr_branch:` line (the marker starts the line, a list bullet aside) labels the task with
    the branch right after it, backticks or quotes aside, even with more text on the same line, and
    writes no note about it; a mention in running prose labels nothing. A label that is not a
    valid branch name is ignored when the task runs (worktree.carried_branch)."""
    p = make(env)
    from ttp import coordinator as coord, worktree

    def labels(title):
        return json.loads(p.db.one("SELECT labels FROM tasks WHERE title=?", (title,))["labels"])

    for i, (spec, want) in enumerate((("pr_branch: feature/fast-io Goal: fix CI.", "feature/fast-io"),
                                      ("pr_branch: `ttp/t5-x` Context: the old parser read it.", "ttp/t5-x"),
                                      ("Goal: fix CI.\npr_branch: `user/fix-ci`.", "user/fix-ci"),
                                      ("pr_branch: 'release-2.1' then more", "release-2.1"),
                                      ('pr_branch: "feature/q"', "feature/q"),
                                      ("Goal: fix CI.\n  - pr_branch: `feature/bullet`", "feature/bullet"),
                                      ("Steps:\n1. pr_branch: feature/numbered\n2. Fix CI.", "feature/numbered"))):
        title = f"carry {i}"
        assert coord.apply(p, [{"type": "task_add", "title": title, "kind": "code", "spec": spec}]) == []
        assert labels(title) == [f"pr_branch:{want}"], spec
    assert not [n for n in p.db.kv(coord.NOTES_KEY) or [] if "pr_branch" in n]
    # A mention in running prose is no `pr_branch:` line: it labels nothing.
    for i, spec in enumerate(("SPEC_PR_BRANCH misread the spec's pr_branch: line in running prose.",
                              "Fix how the spec's `pr_branch:` line is parsed.",
                              "`pr_branch:` line parsing: fix it.",
                              "pr_branch:\nfeature/next-line",
                              "pr_branch: line's parsing",
                              'pr_branch: ""')):
        title = f"prose {i}"
        assert coord.apply(p, [{"type": "task_add", "title": title, "kind": "code", "spec": spec}]) == []
        assert not [x for x in labels(title) if x.startswith("pr_branch:")], spec
    assert worktree.carried_branch({"labels": json.dumps(["pr_branch:use that branch"])}) == ""
    assert worktree.carried_branch({"labels": json.dumps(["pr_branch:feat..ure"])}) == ""
    assert worktree.carried_branch({"labels": json.dumps(["pr_branch:feature/x"])}) == "feature/x"


def test_own_push_refuses_a_pr_branch_that_exists_nowhere(env, monkeypatch):
    """`ttp push --own` from a task's own branch publishes onto its pr_branch only when that branch
    exists here or on the remote; a missing one (e.g. a word parsed out of prose) or an invalid one is
    refused, and main/master never go."""
    from ttp import push
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])

    def target(label):
        t = p.db.add_task("Carry it", "s", kind="code", labels=[f"pr_branch:{label}"])
        own = f"ttp/t{t}-carry-it"
        _git_out(repo, "checkout", "-q", "-B", own)
        monkeypatch.setenv("TTP_TASK", str(t))
        return push.own_target(p, repo)

    with pytest.raises(ValueError, match="exists neither here nor on origin"):
        target("use")
    assert "use" not in _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads").split()
    for bad in ("use that branch", "feat..ure"):
        with pytest.raises(ValueError, match="not one valid branch name"):
            target(bad)
    for shared in ("main", "master"):
        with pytest.raises(ValueError):
            target(shared)
    _git_out(other, "push", "-q", "origin", "HEAD:refs/heads/feature/remote")
    assert target("feature/remote") == ("origin", "feature/remote")
    _git_out(repo, "branch", "feature/local", "HEAD")
    assert target("feature/local") == ("origin", "feature/local")


def test_push_own_prints_its_target_before_it_pushes(env, monkeypatch, capsys):
    """`ttp push --own` prints the remote branch it publishes to before it pushes anything, in the
    foreground and detached (the line is also the detached push's log's first word on it)."""
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    t = p.db.add_task("Speed it up", "s", kind="code")
    own = f"ttp/t{t}-speed-it-up"
    p.db.update_task(t, status="running", branch=own)
    _git_out(repo, "checkout", "-q", "-b", own)
    _commit(repo, "mine.txt", "mine\n")
    monkeypatch.setenv("TTP_TASK", str(t))
    capsys.readouterr()
    assert _ttp("push", "--own") == 0
    out = capsys.readouterr()
    said = f"ttp push: --own target: origin/{own}"
    assert said in out.out, out
    assert _git_out(origin, "rev-parse", own) == _git_out(repo, "rev-parse", "HEAD")
    _commit(repo, "more.txt", "more\n")
    assert _ttp("push", "--own", "--detach") == 0
    out = capsys.readouterr().out
    assert out.index(said) < out.index("marker: "), out
    marker = pathlib.Path(next(ln.split(": ", 1)[1] for ln in out.splitlines() if ln.startswith("marker: ")))
    probe = next(ln.split(": ", 1)[1] for ln in out.splitlines() if ln.startswith("retry_when: "))
    assert _probe_until_done(p, probe).returncode == 0
    log = marker.with_suffix(".log").read_text()
    assert said in log and _git_out(origin, "rev-parse", own) == _git_out(repo, "rev-parse", "HEAD"), log


def test_own_push_refuses_another_tasks_branch_it_only_inherited(env, monkeypatch, capsys):
    """A reported case, replayed: a plan task whose worktree started from a finished task's branch
    carried `pr_branch:<that branch>` without its spec asking for it, so `ttp push --own` targeted the
    other task's branch. Such an inherited branch of another task is refused, saying how to deliver
    instead (`ttp push --own-branch`, which publishes the own branch under its own name); a spec line
    `pr_branch: <branch>`, a continuation of the branch's owner and a review of an authorized task
    still publish onto it."""
    from ttp import push
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    src = p.db.add_task("Profile the loader", "s", kind="code")
    theirs = f"ttp/t{src}-profile-the-loader"
    p.db.update_task(src, status="done", branch=theirs)
    _git_out(repo, "checkout", "-q", "-b", theirs)
    _commit(repo, "theirs.txt", "theirs\n")
    _git_out(repo, "push", "-q", "origin", theirs)
    shipped = _git_out(origin, "rev-parse", theirs)

    def task(title, spec="s", kind="plan", labels=(), on=None):
        t = p.db.add_task(title, spec, kind=kind, labels=list(labels))
        own = f"ttp/t{t}-{title.lower().replace(' ', '-')}"
        p.db.update_task(t, status="running", branch=on or own)
        _git_out(repo, "checkout", "-q", "-B", on or own, theirs)
        _commit(repo, f"t{t}.txt", "work\n")
        monkeypatch.setenv("TTP_TASK", str(t))
        return t, on or own

    # The plan task on its own branch, labelled with the other task's branch: refused, nothing pushed.
    plan, own = task("Plan the cache", labels=[f"pr_branch:{theirs}"])
    with pytest.raises(ValueError, match="only inherited") as e:
        push.own_target(p, repo)
    assert f"task #{src}'s branch" in str(e.value) and "ttp push --own-branch --detach" in str(e.value)
    capsys.readouterr()
    assert _ttp("push", "--own") == 2
    assert "only inherited" in capsys.readouterr().err
    assert _git_out(origin, "rev-parse", theirs) == shipped
    # --own-branch publishes the task's own branch under its own name. cmd_push sets OWN_BRANCH_ENV in
    # this process: registered unset first, so teardown unsets it rather than restoring its value.
    monkeypatch.delenv(push.OWN_BRANCH_ENV, raising=False)
    assert _ttp("push", "--own-branch") == 0, capsys.readouterr().err
    assert _git_out(origin, "rev-parse", own) == _git_out(repo, "rev-parse", "HEAD")
    assert _git_out(origin, "rev-parse", theirs) == shipped
    monkeypatch.delenv(push.OWN_BRANCH_ENV)
    # A worktree on the other task's branch itself (it started there): refused too.
    task("Plan again", labels=[f"pr_branch:{theirs}"], on=theirs)
    with pytest.raises(ValueError, match="only inherited"):
        push.own_target(p, repo)
    # Inherited through a continued task that only inherited it: refused.
    mid = p.db.add_task("Middle step", "s", kind="code", labels=[f"pr_branch:{theirs}"])
    p.db.update_task(mid, status="failed")
    task("Pick up the middle", kind="code", labels=[f"continues:{mid}", f"pr_branch:{theirs}"])
    with pytest.raises(ValueError, match="only inherited"):
        push.own_target(p, repo)
    # Allowed: a spec line naming it, a continuation of its owner, a review of an authorized task.
    named, _ = task("Fix its CI", spec=f"pr_branch: {theirs}\nFix CI there.", kind="code",
                    labels=[f"pr_branch:{theirs}"])
    assert push.own_target(p, repo) == ("origin", theirs)
    task("Finish the loader", kind="code", labels=[f"continues:{src}", f"pr_branch:{theirs}"])
    assert push.own_target(p, repo) == ("origin", theirs)
    rev = p.db.add_task(f"Review #{named}: Fix its CI", "s", kind="review", depends_on=[named],
                        labels=[f"pr_branch:{theirs}"])
    monkeypatch.setenv("TTP_TASK", str(rev))
    _git_out(repo, "checkout", "-q", f"ttp/t{named}-fix-its-ci")
    assert push.own_target(p, repo) == ("origin", theirs)


def test_a_continuation_does_not_inherit_a_third_tasks_branch_its_spec_does_not_name(env, monkeypatch):
    """A task_add continuing a task that only inherited another task's ttp/t<id>-... branch carries
    no branch (no_pr_branch) unless its own spec has a `pr_branch:` line naming it. The branch counts
    as published, so only its owner being another task keeps it off."""
    p = make(env)
    from ttp import coordinator as coord, push, worktree
    monkeypatch.setattr(push, "never_published", lambda *a, **k: False)
    src = p.db.add_task("Speed up the loader", "s", kind="code")
    b = f"ttp/t{src}-speed-up-the-loader"
    p.db.update_task(src, status="done", branch=b)
    mid = p.db.add_task("Plan the cache", "s", kind="plan", labels=[f"pr_branch:{b}"])
    p.db.update_task(mid, status="failed")

    def labels(title):
        return json.loads(p.db.one("SELECT labels FROM tasks WHERE title=?", (title,))["labels"])

    assert coord.apply(p, [{"type": "task_add", "title": "Plan it again", "kind": "plan", "continues": mid,
                            "spec": "Redo the cache plan."}]) == []
    assert worktree.NO_PR_BRANCH in labels("Plan it again")
    again = p.db.one("SELECT id FROM tasks WHERE title='Plan it again'")["id"]
    assert any(f"#{again} continues #{mid} but not its branch {b} (#{src}'s branch" in n
               for n in p.db.kv(coord.NOTES_KEY))
    assert coord.apply(p, [{"type": "task_add", "title": "Fix the loader PR", "kind": "code", "continues": mid,
                            "spec": f"pr_branch: {b}\nFix the PR."}]) == []
    assert f"pr_branch:{b}" in labels("Fix the loader PR") and worktree.NO_PR_BRANCH not in labels("Fix the loader PR")


def test_the_daemon_clears_push_markers_of_dead_runs_and_logs_it(env):
    """A push marker left `running` by a run that died (its run lock free: killed, crashed, rebooted)
    is recorded as failed by the daemon's sweep (push.tend), which returns a line for its log; a
    finished marker past KEEP_S is removed, and a live push (its lock held) is left alone."""
    from ttp import push, locks
    p = make(env)
    folder = p.state / push.DETACHED
    folder.mkdir(parents=True, exist_ok=True)
    dead = folder / "t603-20261013-022410-57783.json"
    dead.write_text(json.dumps({"id": dead.stem, "status": "running", "task": "603", "pid": 57783,
                                "target": "origin/ttp/t598-plan", "started": time.time() - 3600}))
    live = folder / "t604-20261013-022410-57784.json"
    live.write_text(json.dumps({"id": live.stem, "status": "running", "task": "604", "pid": os.getpid(),
                                "target": "origin/ttp/t604-x", "started": time.time()}))
    old = folder / "t1-20260101-000000-1.json"
    old.write_text(json.dumps({"id": old.stem, "status": "pushed", "ended": 0}))
    os.utime(old, (time.time() - push.KEEP_S - 60,) * 2)
    held = locks.try_take([push._run_lock(live)], "test", "test")
    try:
        lines = push.tend(p)
        assert push.tend(p) == [], "a marker is reported once"
    finally:
        held.close()
    assert json.loads(dead.read_text())["status"] == "failed"
    assert json.loads(live.read_text())["status"] == "running"
    assert not old.exists()
    assert any(f"cleared stale push marker {dead.name} of task 603 (origin/ttp/t598-plan)" in ln for ln in lines), lines
    assert any("removed 1 finished push marker" in ln for ln in lines), lines
    assert not [ln for ln in lines if live.name in ln]


def test_own_push_refuses_a_task_branch_other_than_the_one_its_run_was_given(env, monkeypatch, capsys):
    """A worktree that left the branch its task's run was given (the row's branch) for another of the
    task's own ttp/t<id>-... branches is refused by `ttp push --own`, naming both branches: it would
    otherwise publish the new branch's head onto the carried branch, which another task owns. On the
    given branch it publishes as before: onto the carried branch, or under its own name."""
    from ttp import push
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    owner = p.db.add_task("First fix", "s", kind="code")
    carried = f"ttp/t{owner}-first-fix"
    _git_out(other, "push", "-q", "origin", f"HEAD:refs/heads/{carried}")
    theirs = _git_out(origin, "rev-parse", carried)
    tid = p.db.add_task("Follow up", f"pr_branch: {carried}", kind="code", labels=[f"pr_branch:{carried}"])
    p.db.update_task(tid, status="running", branch=carried)
    monkeypatch.setenv("TTP_TASK", str(tid))
    _git_out(repo, "checkout", "-q", "-B", carried, theirs)
    assert push.own_target(p, repo) == ("origin", carried)   # the normal case: on the given branch
    new = f"ttp/t{tid}-new"
    _git_out(repo, "checkout", "-q", "-B", new)
    _commit(repo, "new.py", "x\n")
    with pytest.raises(ValueError, match=rf"{re.escape(new)} checked out.*delivers from {re.escape(carried)}"):
        push.own_target(p, repo)
    capsys.readouterr()
    assert _ttp("push", "--own") != 0
    err = capsys.readouterr().err
    assert new in err and carried in err, err
    assert _git_out(origin, "rev-parse", carried) == theirs
    assert new not in _git_out(origin, "for-each-ref", "--format=%(refname:short)", "refs/heads").split()
    # Given its own branch (the carried one was held elsewhere): that branch publishes onto the
    # carried one; a second own branch is refused, naming the given branch and where it goes.
    given = f"ttp/t{tid}-follow-up"
    p.db.update_task(tid, branch=given)
    with pytest.raises(ValueError, match=rf"delivers from {re.escape(given)}, which it publishes onto {re.escape(carried)}"):
        push.own_target(p, repo)
    _git_out(repo, "checkout", "-q", "-B", given)
    assert push.own_target(p, repo) == ("origin", carried)
    # A task with no pr_branch: its given branch goes under its own name, another of its own does not.
    plain = p.db.add_task("Plain", "s", kind="code")
    p.db.update_task(plain, status="running", branch=f"ttp/t{plain}-plain")
    monkeypatch.setenv("TTP_TASK", str(plain))
    _git_out(repo, "checkout", "-q", "-B", f"ttp/t{plain}-plain")
    assert push.own_target(p, repo) == ("origin", f"ttp/t{plain}-plain")
    _git_out(repo, "checkout", "-q", "-B", f"ttp/t{plain}-other")
    with pytest.raises(ValueError, match=f"task #{plain} delivers from ttp/t{plain}-plain"):
        push.own_target(p, repo)
    # Its notes branch still publishes itself.
    _git_out(repo, "checkout", "-q", "-B", f"ttp/t{plain}-notes")
    assert push.own_target(p, repo) == ("origin", f"ttp/t{plain}-notes")


def test_own_push_publishes_a_fresh_own_branch_made_off_an_inherited_one(env, monkeypatch):
    """A task given another task's branch it only inherited (through `continues`, no `pr_branch:` line
    in its spec) whose spec asks for a fresh branch publishes its own ttp/t<id>-... branch under its
    own name with `ttp push --own`, never onto the inherited one. Another task's branch stays refused,
    and so does a second own branch when the given one is the task's own."""
    from ttp import push
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    owner = p.db.add_task("Earlier", "s", kind="code")
    inherited = f"ttp/t{owner}-earlier"
    _git_out(other, "push", "-q", "origin", f"HEAD:refs/heads/{inherited}")
    theirs = _git_out(origin, "rev-parse", inherited)
    p.db.update_task(owner, status="done", branch=inherited)
    tid = p.db.add_task("Fresh", "start a new ttp/* branch from the named base", kind="code",
                        labels=[f"continues:{owner}", f"pr_branch:{inherited}"])
    p.db.update_task(tid, status="running", branch=inherited)
    monkeypatch.setenv("TTP_TASK", str(tid))
    fresh = f"ttp/t{tid}-from-base"
    _git_out(repo, "checkout", "-q", "-B", fresh)
    _commit(repo, "fresh.py", "x\n")
    assert push.own_target(p, repo) == ("origin", fresh)
    assert _git_out(origin, "rev-parse", inherited) == theirs
    # Another task's branch checked out is still not this task's to publish.
    _git_out(repo, "checkout", "-q", "-B", f"ttp/t{owner + 1000}-elsewhere")
    with pytest.raises(ValueError, match="only this task's own branch"):
        push.own_target(p, repo)
    # Its spec naming the inherited branch makes it the one to deliver on: the fresh branch is refused.
    p.db.update_task(tid, spec=f"pr_branch: {inherited}")
    _git_out(repo, "checkout", "-q", fresh)
    with pytest.raises(ValueError, match=rf"{re.escape(fresh)} checked out.*delivers from {re.escape(inherited)}"):
        push.own_target(p, repo)


def test_a_review_publishes_the_pr_branch_its_subject_carries_and_nothing_else(env, monkeypatch, capsys):
    """A review whose subject task (named by the `Review #<id>` title or its depends_on) carries a
    pr_branch that is another task's ttp/t<id>-... branch publishes that branch with `ttp push --own`
    from a worktree on it, fast-forward only. Any other task's branch is still refused, and a head
    the remote already has is reported as pushed without running the checks or pushing again."""
    from ttp import push
    log = env["tmp"] / "checked"
    p, repo, origin, other = _push_setup(env, monkeypatch, [f"git rev-parse HEAD >> {log}"])
    src = p.db.add_task("Fix the mask", "s", kind="code")
    b = f"ttp/t{src}-fix-the-mask"
    p.db.update_task(src, status="done", branch=b)
    pub = p.db.add_task("Publish the mask fix", f"pr_branch: {b}\nPublish it.", kind="code",
                        labels=[f"pr_branch:{b}"])
    p.db.update_task(pub, status="done", branch=b)
    by_title = p.db.add_task(f"Review #{pub}: Publish the mask fix", "s", kind="review", labels=["review_only"])
    by_dep = p.db.add_task("Check the publish", "s", kind="review", depends_on=[pub])
    _git_out(repo, "checkout", "-q", "-B", b)
    _commit(repo, "mask.py", "fixed\n")   # local only, as the finished task left it
    head = _git_out(repo, "rev-parse", "HEAD")
    for rev in (by_title, by_dep):
        monkeypatch.setenv("TTP_TASK", str(rev))
        assert push.own_target(p, repo) == ("origin", b), rev
    assert _ttp("push", "--own") == 0, capsys.readouterr().err
    assert _git_out(origin, "rev-parse", b) == head
    assert log.read_text().split() == [head]
    # Already there: success, with no checks and no push.
    capsys.readouterr()
    assert _ttp("push", "--own") == 0
    assert "nothing to push" in capsys.readouterr().err
    assert log.read_text().split() == [head]
    # An unrelated task's branch is refused, for a review of any subject and for a non-review.
    stray = p.db.add_task("Something else", "s", kind="code", labels=["pr_branch:feature/x"])
    _git_out(repo, "checkout", "-q", "-B", f"ttp/t{stray}-something-else")
    _commit(repo, "stray.py", "x\n")
    plain = p.db.add_task("Not a review", "s", kind="code", depends_on=[pub])
    for task in (by_title, by_dep, plain):
        monkeypatch.setenv("TTP_TASK", str(task))
        with pytest.raises(ValueError, match="publishes only this task's own branch"):
            push.own_target(p, repo)
    # A review's subject carrying the branch is what lets it through: a non-review never publishes it.
    _git_out(repo, "checkout", "-q", b)
    monkeypatch.setenv("TTP_TASK", str(plain))
    with pytest.raises(ValueError, match="publishes only this task's own branch"):
        push.own_target(p, repo)
    assert _git_out(origin, "rev-parse", b) == head


def test_a_task_carrying_a_branch_works_on_it_in_a_worktree_and_publishes_onto_it(env, monkeypatch, capsys):
    """A task labelled pr_branch:<branch>, of any kind but review or harness, runs in a worktree on that
    branch (made from the remote's when there is no local one) and `ttp push --own` fast-forwards it.
    When it cannot check the branch out (another worktree holds it, or it is a shared branch), the task
    works on its own branch from that branch's head."""
    from pathlib import Path
    from ttp import prompts, push, worktree
    from ttp.daemon import Daemon
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    src = p.db.add_task("Speed up the loader", "s", kind="code")
    b = f"ttp/t{src}-speed-up-the-loader"
    p.db.update_task(src, status="done", branch=b)
    _git_out(repo, "branch", b)
    wt = env["tmp"] / "pr"
    _git_out(repo, "worktree", "add", "-q", str(wt), b)
    _commit(wt, "pr.txt", "pr\n")
    _git_out(wt, "push", "-q", "origin", f"HEAD:refs/heads/{b}")
    _git_out(repo, "worktree", "remove", str(wt))
    _git_out(repo, "branch", "-D", b)   # only the remote has it now
    d = Daemon(p.base)
    task = p.db.task(p.db.add_task("Answer the PR comments", "s", kind="work",
                                   labels=[f"continues:{src}", f"pr_branch:{b}"]))
    cwd, branch = d._workdir_for(task)
    assert Path(cwd) == p.worktrees / f"t{task['id']}" and branch == b
    assert _git_out(cwd, "rev-parse", "HEAD") == _git_out(origin, "rev-parse", b)
    assert f"delivers onto branch {b}" in prompts.worker_task(p, task, cwd, branch)
    _commit(Path(cwd), "fix.txt", "fix\n")
    monkeypatch.chdir(cwd)
    monkeypatch.setenv("TTP_TASK", str(task["id"]))
    assert push.resolve(p, Path(cwd), own=True) == ("origin", b, True)
    assert _ttp("push", "--own") == 0, capsys.readouterr().err
    assert _git_out(origin, "rev-parse", b) == _git_out(cwd, "rev-parse", "HEAD")
    # Held by that worktree: the next one works on its own branch from the carried branch's head.
    monkeypatch.chdir(repo)
    held = p.db.task(p.db.add_task("More PR comments", f"pr_branch: `{b}`", kind="work",
                                   labels=[f"pr_branch:{b}"]))
    cwd2, branch2 = d._workdir_for(held)
    assert branch2 == f"ttp/t{held['id']}-more-pr-comments"
    assert _git_out(cwd2, "rev-parse", "HEAD") == _git_out(origin, "rev-parse", b)
    monkeypatch.setenv("TTP_TASK", str(held["id"]))
    assert push.resolve(p, Path(cwd2), own=True) == ("origin", b, True)
    # A shared branch is never checked out as the task's branch.
    shared = p.db.task(p.db.add_task("On the push branch", "s", kind="code", labels=["pr_branch:proj"]))
    assert worktree.on_carried(p, shared) == ""
    assert d._workdir_for(shared)[1] == f"ttp/t{shared['id']}-on-the-push-branch"
    # A review still works in the change's worktree.
    review = p.db.task(p.db.add_task("Review it", "s", kind="review", labels=[f"pr_branch:{b}"]))
    assert d._workdir_for(review) == (str(p.root), None)


def test_pr_findings_wait_for_the_delivering_tasks_review_chain_and_a_pr_has_one_fixer(env, monkeypatch):
    """While the done task's review, or the daemon's fix and re-review of it, is open, PR findings
    queue no PR fix: that stack owns them. A review that fails while a PR fix is open hands its
    findings to that fix (and a re-review waits on it) instead of queuing a second fixer."""
    from ttp.daemon import Daemon
    p = make(env)
    url = "https://github.com/acme/widgets/pull/7"
    src = p.db.add_task("Speed up the loader", "s", kind="code")
    pr_branch = f"ttp/t{src}-speed-up-the-loader"
    subprocess.run(["git", "-C", str(p.root), "branch", pr_branch], check=True)
    p.db.update_task(src, status="done", pr_url=url, branch=pr_branch)
    review = p.db.add_task(f"Review #{src}", "r", kind="review", depends_on=[src], labels=[f"auto_review:{src}"])
    d = Daemon(p.base)
    rec, key = {"task": src, "branch": pr_branch, "url": url}, "acme/widgets#7"

    def fixers():
        return [t for t in p.db.q("SELECT * FROM tasks WHERE kind='code' AND status NOT IN ('done','failed','cancelled')")]

    # (a) The auto-review is open: it owns the findings, no PR fix.
    owner, made = d.pr_findings_owner(key, rec, "CI failing: tests")
    assert owner["id"] == review and not made and not fixers()
    # Its fix and re-review (the daemon's chain) own them too, until the chain ends.
    p.db.update_task(review, status="failed")
    rf = p.db.add_task(f"Fix review #{review}", "f", kind="code", labels=[f"continues:{src}", f"review_fix:{review}"])
    rr = p.db.add_task(f"Re-review #{review}", "r", kind="review", depends_on=[rf],
                       labels=[f"auto_review:{rf}", f"continues:{review}"])
    p.db.update_task(rf, status="done")
    owner, made = d.pr_findings_owner(key, rec, "CI failing: tests")
    assert owner["id"] == rr and not made
    p.db.update_task(rr, status="done")
    owner, made = d.pr_findings_owner(key, rec, "CI failing: tests")
    assert made and [t["id"] for t in fixers()] == [owner["id"]]
    prfix = owner["id"]
    # (b) A review of the change fails while the PR fix is open: the fix takes its findings.
    late = p.db.add_task(f"Review #{src} again", "r", kind="review", depends_on=[src],
                         labels=[f"auto_review:{src}"])
    after = p.db.add_task("after", "a", kind="work", depends_on=[late])
    p.db.update_task(late, status="failed")
    out = d._fix_failed_review(p.db.task(late), [{"title": "Loader leaks", "spec": "close the file"}], "leaks")
    assert out is not None
    fid, rid, moved = out
    assert fid == prfix and [t["id"] for t in fixers()] == [prfix], "a second fixer was queued for the PR"
    fix = p.db.task(prfix)
    assert "Loader leaks" in fix["spec"] and "CI failing" in fix["spec"] and f'"review_fix:{late}"' in fix["labels"]
    assert p.db.task(rid)["depends_on"] == f"[{prfix}]" and moved == [after]
    # And it is not repeated for the same review.
    assert d._fix_failed_review(p.db.task(late), [{"title": "Loader leaks", "spec": "x"}], "leaks") is None


def _batch_setup(env, monkeypatch, busy):
    p = make(env)
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    p.db.x("UPDATE events SET status='handled'")
    p.db.x("UPDATE tasks SET status='done'")
    p.set_config("budget.max_parallel_workers", 2)
    d.cfg = p.config()
    d.update_gates()
    clock = [time.time()]
    starts = _count_turns(d, monkeypatch, clock)
    for _ in range(busy):
        p.db.x("INSERT INTO runs(role, started, status) VALUES('worker', ?, 'running')", (clock[0],))
    return p, d, clock, starts


def _event(p, clock, kind, severity="normal"):
    p.db.x("INSERT INTO events(ts,source,kind,severity,text,status) VALUES(?,?,?,?,?,?)",
           (clock[0], "task:1", kind, severity, f"{kind} happened", "queued"))


def _turn_within(d, clock, starts, seconds, step=5):
    n, end = len(starts), clock[0] + seconds
    while clock[0] < end and len(starts) == n:
        d.maybe_coordinate()
        clock[0] += step
    return len(starts) > n


def test_routine_events_wait_for_company_while_every_slot_is_busy(env, monkeypatch):
    p, d, clock, starts = _batch_setup(env, monkeypatch, busy=2)
    batch = float(p.config()["coordinator"]["batch_s"])
    assert batch == 300
    _event(p, clock, "task_done")
    _event(p, clock, "followup_proposed")
    assert not _turn_within(d, clock, starts, 120), "a routine hand-off woke a turn while every slot was busy"
    _event(p, clock, "task_done")
    _event(p, clock, "observation", "low")
    assert _turn_within(d, clock, starts, batch), "the batch was held past coordinator.batch_s"
    assert len(starts) == 1


def test_routine_events_wait_while_runnable_work_fills_the_free_slot(env, monkeypatch):
    p, d, clock, starts = _batch_setup(env, monkeypatch, busy=0)
    p.db.add_task("next up", "s", origin="coordinator")
    _event(p, clock, "task_done")
    _event(p, clock, "task_notes")
    # One runnable task for two free slots: the other slot would sit idle, so the turn starts.
    assert _turn_within(d, clock, starts, 30), "held although a free slot has nothing to run"
    p.db.x("UPDATE events SET status='handled'")
    p.db.x("INSERT INTO runs(role, started, status) VALUES('worker', ?, 'running')", (clock[0],))
    p.db.set_kv("last_coordinator_turn", clock[0])
    _event(p, clock, "task_done")
    _event(p, clock, "task_notes")
    assert not _turn_within(d, clock, starts, 120), "woke although queued work fills the free slot"
    # Queued work held by a paused resource cannot fill the slot: the slot would sit idle.
    p.db.x("UPDATE tasks SET blocked_reason='waits for a paused resource: x' WHERE status='queued'")
    assert _turn_within(d, clock, starts, 30)


def test_a_free_slot_with_nothing_runnable_wakes_at_once(env, monkeypatch):
    p, d, clock, starts = _batch_setup(env, monkeypatch, busy=1)
    _event(p, clock, "task_done")
    debounce = float(p.config()["coordinator"]["debounce_s"])
    assert _turn_within(d, clock, starts, debounce + 10)


def test_urgent_events_and_messages_wake_at_once_even_with_every_slot_busy(env, monkeypatch):
    debounce = None
    for kind, severity in (("task_failed", "normal"), ("task_review", "normal"), ("task_blocked", "high"),
                           ("observation", "high"), ("observation", "critical"), ("task_done", "high")):
        p, d, clock, starts = _batch_setup(env, monkeypatch, busy=2)
        debounce = float(p.config()["coordinator"]["debounce_s"])
        _event(p, clock, "task_done")
        _event(p, clock, kind, severity)
        assert _turn_within(d, clock, starts, debounce + 10), f"{kind}/{severity} waited for the batch"
        p.db.x("UPDATE events SET status='handled'")
        monkeypatch.undo()
    p, d, clock, starts = _batch_setup(env, monkeypatch, busy=2)
    _event(p, clock, "task_done")
    p.db.post("in", "status?", chat="c1", kind="user")
    assert _turn_within(d, clock, starts, debounce + 10), "a user message waited for the batch"


def test_batch_s_0_turns_batching_off(env, monkeypatch):
    p, d, clock, starts = _batch_setup(env, monkeypatch, busy=2)
    p.set_config("coordinator.batch_s", 0)
    d.cfg = p.config()
    _event(p, clock, "task_done")
    assert _turn_within(d, clock, starts, float(d.cfg["coordinator"]["debounce_s"]) + 10)


def test_replay_reports_the_turns_batching_saves_without_idle_slots(env):
    from ttp import replay
    p = make(env)
    db = p.db
    db.x("DELETE FROM runs")
    t0 = time.time() - 7200

    def history(workers):
        db.x("DELETE FROM runs")
        db.x("DELETE FROM events")
        for _ in range(workers):
            db.x("INSERT INTO runs(role, started, ended, status) VALUES('worker', ?, ?, 'ok')", (t0, t0 + 3000))
        for at, kinds in ((100, ("task_done", "followup_proposed")), (200, ("task_done",)), (300, ("task_done",))):
            ids = [db.x("INSERT INTO events(ts,source,kind,severity,text,status) VALUES(?,?,?,?,?,?)",
                        (t0 + at, "task:1", k, "normal", k, "handled")) for k in kinds]
            db.x("INSERT INTO runs(role, started, ended, status, cost_usd, note) VALUES('coordinator',?,?,'ok',0.1,?)",
                 (t0 + at + 15, t0 + at + 25, json.dumps({"events": ids, "messages": []})))
        return replay.load(pathlib.Path(db.path), 1, now=t0 + 3600)

    out = replay.report(history(workers=2), 300, 2)
    assert (out["replayed_turns"], out["batched_turns"]) == (3, 1), out
    assert out["saved_pct"] > 60 and out["idle_slot_s"] == 0 and out["extra_idle_slot_s"] == 0
    # A free slot with nothing to run: every hand-off gets its turn at once.
    out = replay.report(history(workers=1), 300, 2)
    assert out["turns_saved"] == 0 and out["held_s"] == 0, out
    assert replay.main([str(db.path), "--days", "1", "--slots", "2"]) == 0


def test_idle_slot_wake_backs_off_to_long_waits_while_every_queued_task_is_gated(env, monkeypatch):
    from ttp import budget as bud
    from ttp import coordinator as coord
    from ttp.daemon import starve_state
    plan = [{"window": "seven_day", "utilization": 50.0, "resets_at": time.time() + 36000, "hours_left": 10.0,
             "headroom": 40.0, "per_worker_per_h": 1.0}]
    gate = bud.Gate(provider="fake", regime="windows", max_parallel=6, numbers={"plan": plan})
    p, d, clock, starts = _wake_setup(env, monkeypatch, gate)
    c = p.config()["coordinator"]
    assert coord.apply(p, [{"type": "task_add", "title": "on a probe", "spec": "s", "start_when": "exit 1"},
                           {"type": "task_add", "title": "in 3 days", "spec": "s", "start_after": "3d"}]) == []
    _no_events(p)
    t0 = clock[0]
    while clock[0] < t0 + 86400:
        d.maybe_coordinate()
        if starts and p.db.kv("last_coordinator_turn") == clock[0]:
            # Other turns (messages, events) in between start each wake's fingerprint afresh.
            p.db.set_kv("idle_wake", {})
        clock[0] += 60
    assert starts and starts[0] - t0 >= float(c["idle_wake_s"]), \
        "probe and time gates wake the coordinator themselves: no short idle-slot wakes meanwhile"
    assert len(starts) <= 5, f"{len(starts)} idle-slot turns in a day for work that only waits on its gates"
    # The gate opens and the queue empties: the idle-slot wake is capped at the idle wake again.
    p.db.x("UPDATE tasks SET status='done'")
    st = starve_state(p.db, p.config(), gate.as_dict(), clock[0])
    assert st and st["wait"] <= float(c["idle_wake_s"]), st
    # A new task starts the short wait afresh.
    p.db.x("UPDATE tasks SET status='queued'")
    assert coord.apply(p, [{"type": "task_add", "title": "later", "spec": "s", "start_when": "exit 1"}]) == []
    st = starve_state(p.db, p.config(), gate.as_dict(), clock[0])
    assert st and st["wait"] == float(c["idle_wake_s"]), st


def _finish_code(env, p, title, files, result=None, labels=None, before=None, edit=None):
    """A code task that committed `files` (name -> lines), and what `edit(worktree)` changed, on its
    branch, then handed off. `before` is called with the task id and its branch's head just before
    the hand-off."""
    from ttp import worktree
    from ttp.daemon import Daemon
    from ttp.providers.base import RunUsage as Usage
    tid = p.db.add_task(title, f"spec of {title}", kind="code", tier="standard", origin="coordinator",
                        labels=labels)
    path, branch = worktree.ensure(p, p.db.task(tid))
    for name, lines in files.items():
        (path / name).parent.mkdir(parents=True, exist_ok=True)
        (path / name).write_text("".join(f"{title} {i}\n" for i in range(lines)))
    if edit:
        edit(path)
    if files or edit:
        _git_out(path, "add", ".")
        _git_out(path, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", title)
    p.db.update_task(tid, status="running", branch=branch)
    run_dir = env["tmp"] / f"run-{tid}"
    run_dir.mkdir()
    (run_dir / "result.json").write_text(json.dumps(result or {"status": "done", "summary": f"{title} works"}))
    if before:
        before(tid, _git_out(path, "rev-parse", "HEAD").strip())
    Daemon(p.base)._finish_worker({"task": tid}, Usage(cost_usd=1.0), "ok", run_dir)
    done = p.db.one("SELECT * FROM events WHERE task=? AND kind='task_done'", (tid,))
    reviews = p.db.q("SELECT * FROM tasks WHERE kind='review' AND depends_on=?", (json.dumps([tid]),))
    return tid, branch, done, reviews


def test_the_daemon_queues_the_review_of_a_finished_code_task(env):
    p = make(env)
    _with_origin(env, clone=False)   # a repo with no remote never pushes: review only
    tid, branch, done, reviews = _finish_code(env, p, "small fix", {"app.py": 20, "NOTES.md": 300})
    assert len(reviews) == 1, "no review queued"
    rev = reviews[0]
    assert rev["title"] == f"Review #{tid}: small fix" and rev["origin"] == "daemon" and rev["tier"] == "light"
    assert rev["priority"] == 2 and rev["budget_usd"] == p.config()["budget"]["task_default_usd"]["light"]
    head = _git_out(p.root, "rev-parse", "--short=12", branch)
    assert branch in rev["spec"] and head in rev["spec"] and "spec of small fix" in rev["spec"]
    assert "small fix works" in rev["spec"] and "Review only" in rev["spec"] and "ttp push" not in rev["spec"]
    assert done["status"] == "handled", "a routine hand-off still starts a coordinator turn"
    assert f"Review #{rev['id']} queued by the daemon" in done["text"]
    # Big or risky diffs get a standard review; push delivery and the project's notes go in its spec.
    p.set_config("delivery.push_branch", "work")
    p.set_config("review.auto_notes", "After the push, upgrade the staging copy.")
    _, _, _, (big,) = _finish_code(env, p, "big change", {"app.py": 200})
    assert big["tier"] == "standard" and "ttp push" in big["spec"] and "work" in big["spec"]
    assert big["spec"].rstrip().endswith("the pushed commit.") and "upgrade the staging copy" in big["spec"]
    p.set_config("review.risky_paths", ["state/*"])
    _, _, _, (risky,) = _finish_code(env, p, "risky", {"state/db.py": 3})
    assert risky["tier"] == "standard"


def test_with_the_push_queue_on_the_daemon_starts_the_checks_as_it_queues_the_review(env):
    # Reviewers ended waiting on `ttp checks` they started themselves. With the push queue on, the
    # daemon starts them on the head as it queues the review, holds the review while they run, and
    # their recorded pass lets the reviewer's own `ttp checks` there reuse it.
    from ttp import cli
    from ttp.daemon import PRECHECK_HOLD_S, PRECHECK_LABEL, PRECHECKS_DIR, Daemon
    from ttp.runner import proc_start
    p = make(env)
    _with_origin(env, clone=False)   # a repo with no remote never pushes: review only
    p.set_config("delivery.push_branch", "work")
    p.set_config("delivery.push_checks", ["test -f app.py"])
    # Queue off: nothing starts, the review is not held.
    _, _, _, (off,) = _finish_code(env, p, "queue off", {"app.py": 3})
    assert "ttp checks --result" not in off["spec"] and PRECHECK_LABEL not in off["labels"]
    assert not (p.state / PRECHECKS_DIR).exists()
    p.set_config("delivery.push_queue", True)
    tid, branch, _, (rev,) = _finish_code(env, p, "queue on", {"app.py": 3})
    head = _git_out(p.root, "rev-parse", branch).strip()
    out = p.state / PRECHECKS_DIR / f"t{tid}-{head[:12]}"
    assert f"{PRECHECK_LABEL}{out.name}" in json.loads(rev["labels"])
    assert f"ttp checks --result {out}" in rev["spec"] and "run only focused tests" in rev["spec"]
    assert _wait_precheck(out) == "0", (out / cli.CHECKS_OUT).read_text()
    tree = _git_out(p.root, "rev-parse", f"{head}^{{tree}}").strip()
    assert cli._recorded_pass(p, tree, ["test -f app.py"]), "the reviewer's `ttp checks` could not reuse the pass"
    d, now = Daemon(p.base), time.time()
    task = p.db.task(rev["id"])
    assert not d._precheck_holds(task, now), "finished checks hold the review"
    # While they run the review waits, at most PRECHECK_HOLD_S; checks that died hold nothing.
    (out / cli.CHECKS_RC).unlink()
    alive = {"pid": os.getpid(), "started": proc_start(os.getpid()), "ts": now}
    (out / cli.CHECKS_PID).write_text(json.dumps(alive))
    assert d._precheck_holds(task, now)
    assert not d._precheck_holds(task, now + PRECHECK_HOLD_S + 1)
    assert not d._precheck_holds(dict(task, kind="code"), now)
    (out / cli.CHECKS_PID).write_text(json.dumps(dict(alive, started="other")))
    assert not d._precheck_holds(task, now)
    # A worktree that moved past the reviewed head, or no project checks: nothing starts.
    assert d._precheck(p.db.task(tid), "0" * 40) is None
    p.set_config("delivery.push_checks", [])
    _, _, _, (none,) = _finish_code(env, p, "no checks", {"app.py": 3})
    assert PRECHECK_LABEL not in none["labels"] and "ttp checks --result" not in none["spec"]


def _wait_precheck(out: Path, timeout: float = 180.0) -> str:
    """The exit code the detached checks in `out` wrote. They start as their own processes, which a
    busy host can take well over 30 s to get through: this waits while they run, up to `timeout`, and
    fails at once, with their log, when they ended without writing it."""
    from ttp import cli
    rc = out / cli.CHECKS_RC

    def ended():
        info = cli._read_checks_pid(out)
        return rc.exists() or (bool(info) and not cli._checks_alive(info))
    _wait_for(ended, timeout)
    if not rc.exists():
        log = next((f.read_text() for f in (out / "checks.log", out / cli.CHECKS_OUT) if f.exists()), "")
        pytest.fail(f"the checks in {out} wrote no {cli.CHECKS_RC} ({cli._read_checks_pid(out)}): {log[-2000:]}")
    return rc.read_text().strip()


def test_a_pass_of_more_commands_answers_for_the_commands_they_start_with(env):
    # The daemon's pre-started checks run delivery.push_checks alone; the code task recorded its pass
    # of them with its own commands after `--`. That pass answers for push_checks: nothing reruns.
    from ttp import cli
    from ttp.daemon import PRECHECKS_DIR
    p = make(env)
    cli._record_pass(p, "t" * 40, ["a", "b"])
    assert cli._recorded_pass(p, "t" * 40, ["a"]) and cli._recorded_pass(p, "t" * 40, ["a", "b"])
    assert not cli._recorded_pass(p, "t" * 40, ["b"]), "a pass of a later command alone was reused"
    assert not cli._recorded_pass(p, "t" * 40, ["a", "b", "c"])
    assert not cli._recorded_pass(p, "u" * 40, ["a"])
    # Through the daemon: a project check that would fail if it ran is answered by the recorded pass.
    _with_origin(env, clone=False)   # a repo with no remote never pushes: review only
    p.set_config("delivery.push_branch", "work")
    p.set_config("delivery.push_queue", True)
    p.set_config("delivery.push_checks", ["false"])

    def worker_checks(tid, head):
        cli._record_pass(p, _git_out(p.root, "rev-parse", f"{head}^{{tree}}").strip(), ["false", "pytest -q"])
    tid, branch, _, (rev,) = _finish_code(env, p, "reuse", {"app.py": 3}, before=worker_checks)
    head = _git_out(p.root, "rev-parse", branch).strip()
    out = p.state / PRECHECKS_DIR / f"t{tid}-{head[:12]}"
    assert _wait_precheck(out) == "0", (out / "checks.log").read_text()
    assert "(recorded)" in (out / "checks.log").read_text()


def test_a_re_review_gets_its_checks_started_when_the_fix_finishes(env):
    # _fix_failed_review queues the re-review before the fix has a head; the fix's hand-off finds it
    # open and starts the checks on the fix's head for it, as for a review queued then.
    from ttp import worktree
    from ttp.daemon import PRECHECK_LABEL, PRECHECKS_DIR, Daemon
    from ttp.providers.base import RunUsage as Usage
    p = make(env)
    _with_origin(env, clone=False)   # a repo with no remote never pushes: review only
    p.set_config("delivery.push_branch", "work")
    p.set_config("delivery.push_queue", True)
    p.set_config("delivery.push_checks", ["test -f app.py"])
    _, _, _, (rev,) = _finish_code(env, p, "feature", {"app.py": 40})
    _fail_review(env, p, rev["id"], [{"title": "add the missing test", "spec": "test_x"}])
    (fix,) = p.db.q("SELECT * FROM tasks WHERE kind='code' AND origin='daemon'")
    (re_rev,) = p.db.q("SELECT * FROM tasks WHERE kind='review' AND id!=?", (rev["id"],))
    assert not any(x.startswith(PRECHECK_LABEL) for x in json.loads(re_rev["labels"]))
    path, _ = worktree.ensure(p, p.db.task(fix["id"]))
    (path / "test_x.py").write_text("def test_x(): pass\n")
    _git_out(path, "add", ".")
    _git_out(path, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "fix")
    head = _git_out(path, "rev-parse", "HEAD").strip()
    p.db.update_task(fix["id"], status="running")
    run_dir = env["tmp"] / f"run-{fix['id']}"
    run_dir.mkdir()
    (run_dir / "result.json").write_text(json.dumps({"status": "done", "summary": "fixed"}))
    Daemon(p.base)._finish_worker({"task": fix["id"]}, Usage(cost_usd=1.0), "ok", run_dir)
    re_rev = p.db.task(re_rev["id"])
    out = p.state / PRECHECKS_DIR / f"t{fix['id']}-{head[:12]}"
    assert json.loads(re_rev["labels"]).count(f"{PRECHECK_LABEL}{out.name}") == 1, re_rev["labels"]
    assert f"ttp checks --result {out}" in re_rev["spec"] and "Re-review after review" in re_rev["spec"]
    assert _wait_precheck(out) == "0"
    # Once per head: finding the review again starts nothing more.
    spec = re_rev["spec"]
    Daemon(p.base)._precheck_open(p.db.task(fix["id"]), re_rev)
    assert p.db.task(re_rev["id"])["spec"] == spec


def test_a_review_held_for_its_checks_does_not_fill_a_slot_for_the_turn_batch(env):
    from ttp import cli
    from ttp.daemon import PRECHECK_LABEL, PRECHECKS_DIR, Daemon
    from ttp.runner import proc_start
    p = make(env)
    p.db.x("UPDATE events SET status='handled'")
    p.db.x("UPDATE tasks SET status='done'")
    p.set_config("budget.max_parallel_workers", 1)
    out = p.state / PRECHECKS_DIR / "t1-abc"
    out.mkdir(parents=True)
    (out / cli.CHECKS_PID).write_text(json.dumps({"pid": os.getpid(), "started": proc_start(os.getpid()),
                                                  "ts": time.time()}))
    rid = p.db.add_task("Review #1: x", "s", kind="review", tier="standard", origin="daemon",
                        labels=[PRECHECK_LABEL + out.name])
    d = Daemon(p.base)
    d.gates = {}
    evs = [{"ts": time.time() - 10, "kind": "task_done", "severity": "normal"}]
    assert d._precheck_holds(p.db.task(rid), time.time())
    assert not d._batch_hold(evs, time.time()), "a review held for its checks filled the free slot"
    (out / cli.CHECKS_RC).write_text("0\n")
    assert d._batch_hold(evs, time.time()), "the same review, its checks done, fills the slot"


def test_the_review_of_a_head_already_delivered_as_a_pr_publishes_nothing_more(env):
    # A code task delivered its head as a draft PR; a push branch is configured too. A passing review
    # of that head is review only: no `ttp push` toward a branch that may be unrelated or absent.
    from ttp import prguard
    p = make(env)
    _with_origin(env, clone=False)   # a repo with no remote never pushes: review only
    p.set_config("delivery.push_branch", "work")
    url = "https://github.com/acme/app/pull/7"
    pr = {"status": "done", "summary": "draft PR opened", "pr": url}

    def watched(sha):
        return lambda tid, head: p.db.set_kv(prguard.HEADS_KEY, {"acme/app#7": {"sha": sha(head), "seen": 1.0}})

    def pushed_own(task=None, status="pushed"):
        def write(tid, head):
            p.db.set_kv(prguard.HEADS_KEY, {})   # pr-watch has not read the PR yet
            folder = p.state / "pushes"
            folder.mkdir(parents=True, exist_ok=True)
            (folder / f"t{tid}-own.json").write_text(json.dumps(
                {"own": True, "status": status, "sha": head, "task": str(task or tid), "exit": 0}))
        return write

    def spec(title, before):
        _, _, _, (rev,) = _finish_code(env, p, title, {f"{title}.py": 5}, result=pr, before=before)
        return rev["spec"]

    # pr-watch read the PR at this head: delivered.
    s = spec("seen", watched(lambda h: h))
    assert f"already delivered as PR {url}" in s and "ttp push` from" not in s
    assert s.rstrip().endswith("findings.") and "Leave the branch and the PR as they are" in s
    # Not read yet, but this task's `ttp push --own` pushed exactly this head: delivered.
    s = spec("own", pushed_own())
    assert "already delivered" in s and "ttp push` from" not in s
    # The PR carries another head, the own push failed or was another task's: the review pushes as before.
    for title, before in (("moved", watched(lambda h: "0" * 40)), ("failed", pushed_own(status="failed")),
                          ("other", pushed_own(task=999))):
        s = spec(title, before)
        assert "already delivered" not in s and "ttp push` from" in s and s.rstrip().endswith("the pushed commit."), title
    # A PR pr-watch read as closed delivers nothing, whatever head it had.
    p.db.set_kv("pr_signatures", {url: {"state": "CLOSED"}})
    s = spec("closed", watched(lambda h: h))
    assert "already delivered" not in s and "ttp push` from" in s
    # No push branch: review only either way, and no pushed commit asked for.
    p.db.set_kv("pr_signatures", {url: {"state": "OPEN"}})
    p.set_config("delivery.push_branch", "")
    s = spec("nobranch", watched(lambda h: h))
    assert "already delivered" in s and "ttp push` from" not in s and s.rstrip().endswith("findings.")


def test_the_review_prompt_and_coordinator_treat_a_head_in_a_pr_as_delivered(env):
    from ttp.prompts import worker_task
    p = make(env)
    p.set_config("delivery.push_branch", "work")
    review = p.db.add_task("review it", "s", kind="review", tier="light", origin="user")
    for on in (False, True):   # kept whichever delivery section the review's prompt carries
        p.set_config("delivery.push_queue", on)
        text = " ".join(worker_task(p, p.db.task(review), str(p.root), None).split())
        assert "already delivered as a PR, or a change it says must not reach the push branch, is review only: " \
               "a pass is `done`, with no push and no approval for the push queue" in text, on
    coord_md = " ".join((RUNTIME.parent / "template" / "prompts" / "coordinator.md").read_text().split())
    assert "A head already delivered as a PR (draft or open, same head) is delivered" in coord_md
    assert "a change whose whole diff `delivery.push_exclude_paths` keeps off the push branch (notes only), " \
           "or whose spec or hand-off marks it: review only, no push or push-queue step" in coord_md
    assert "put a line `no_push: <why>` in its spec" in coord_md


def test_the_review_of_a_change_that_must_not_reach_the_push_branch_has_no_push_step(env, monkeypatch):
    # A notes-only change (every file push-excluded), or one its spec or hand-off keeps off the push
    # branch, gets a review-only spec: no `ttp push` and no push-queue approval, with the reason.
    from ttp import push, pushq
    p = make(env)
    _with_origin(env, clone=False)   # a repo with no remote never pushes: review only
    p.set_config("delivery.push_branch", "work")
    p.set_config("delivery.push_exclude_paths", ["notes", "*.log"])
    monkeypatch.setattr(pushq, "enabled", lambda *a, **k: False)   # no prechecks: the spec text is the subject

    def review(title, files, spec=None, result=None):
        before = (lambda tid, head: p.db.update_task(tid, spec=spec)) if spec else None
        _, _, _, (rev,) = _finish_code(env, p, title, files, result=result, before=before)
        return rev

    def review_only(rev):
        return "ttp push` from" not in rev["spec"] and "Review only" in rev["spec"] \
            and push.REVIEW_ONLY_LABEL in json.loads(rev["labels"]) and rev["spec"].rstrip().endswith("findings.")

    def pushes(rev):
        return "ttp push` from" in rev["spec"] and push.REVIEW_ONLY_LABEL not in json.loads(rev["labels"])

    for on in (False, True):
        p.set_config("delivery.push_queue", on)
        rev = review(f"notes {on}", {"notes/a.md": 5, "run.log": 2})
        assert review_only(rev) and "delivery.push_exclude_paths keeps off" in rev["spec"], (on, rev["spec"])
        assert pushes(review(f"mixed {on}", {"notes/b.md": 5, "app.py": 3})), on
        rev = review(f"forbidden {on}", {"c.py": 3}, spec="Write the notes.\nno_push: notes stay local\n")
        assert review_only(rev) and "notes stay local" in rev["spec"], on
        for i, ban in enumerate(("no_push:", "  no_push: `a local tool`", "Fix it.\n\nno_push: true\nThen stop.")):
            assert review_only(review(f"ban {on} {i}", {f"d{i}.py": 3}, spec=ban)), (on, ban)
        rev = review(f"flag {on}", {"e.py": 3}, result={"status": "done", "summary": "ok", "no_push": "a local tool"})
        assert review_only(rev) and "a local tool" in rev["spec"], on
        # The usual rule that the review pushes, not the worker, is not a prohibition.
        for i, usual in enumerate(("Do not push.", "Never push to the push branch yourself.",
                                   "Do not push to work directly; the review pushes it.", "Never push to main.",
                                   "Never push to the push branches of other projects.",
                                   "Only a change whose whole diff is kept off the push branch by "
                                   "delivery.push_exclude_paths is review only.",
                                   "With the push queue on, workers never push to the push branch; the daemon does.",
                                   "Do not push to the push branch: the review pushes it.",
                                   "Workers must not push to the push branch themselves.",
                                   "Fix: a notes commit cannot reach the push branch, so drop it.",
                                   "Never push it to the push branch yourself.",
                                   # Prose is never a ban, not even one naming the change: only the marker line.
                                   "Write the notes. They must not be pushed to the push branch.",
                                   "Never push this to work.", "This change must not reach the push branch.",
                                   "These notes must not be pushed to work.", "Keep this change off origin/work.",
                                   "or (b) the code task's spec or hand-off says the change must not be pushed "
                                   "to the push branch",
                                   "A review of a change whose spec says it must not reach the push branch is "
                                   "review only.",
                                   "Detect when the hand-off says this change must not be pushed to the push branch.",
                                   "If it must not reach the push branch, the review is review only.",
                                   'Such a spec names the change as what is banned ("this change must not be '
                                   'pushed to the push branch")',
                                   "Rely on one explicit spec marker on its own line, e.g. a line starting "
                                   "`no_push:` (the reason follows).",
                                   "no_push: false", "Set no_push: true in the hand-off.")):
            assert pushes(review(f"usual {on} {i}", {f"g{i}.py": 3}, spec=usual)), (on, usual)
        rev = review(f"summary {on}", {"f.py": 3},
                     result={"status": "done", "summary": "Done; keep it off the push branch."})
        assert pushes(rev), on
    # No push branch: review only as before, without the reason.
    p.set_config("delivery.push_branch", "")
    rev = review("no branch", {"notes/c.md": 5})
    assert "Review only" in rev["spec"] and push.REVIEW_ONLY_LABEL not in json.loads(rev["labels"])


def test_kept_off_explicit_no_push_false_in_a_continuation_ends_the_walk(env, monkeypatch):
    # `no_push: false` in a continuation's spec, or no_push false in its hand-off, lifts the
    # ancestor's ban for it and for its own continuations; silence still inherits.
    from ttp import push, pushq
    p = make(env)
    _with_origin(env, clone=False)
    p.set_config("delivery.push_branch", "work")
    monkeypatch.setattr(pushq, "enabled", lambda *a, **k: False)
    d = p.config()["delivery"]

    def code(title, spec="", labels=None, result=None):
        tid = p.db.add_task(title, spec, kind="code", origin="coordinator", labels=labels)
        if result:
            p.db.update_task(tid, result=json.dumps(result))
        return p.db.task(tid)

    root = code("notes", "no_push: notes stay local\n")
    lifted = code("continue: notes", "Go on.\nno_push: false\n", labels=[f"continues:{root['id']}"])
    assert push.kept_off(lifted, None, d, p) == ""
    assert push.kept_off(code("fix", "", labels=[f"continues:{lifted['id']}"]), None, d, p) == ""
    for flag in (False, "false", 0):
        h = code("handed", "", labels=[f"continues:{root['id']}"],
                 result={"status": "done", "summary": "ok", "no_push": flag})
        assert push.kept_off(h, None, d, p) == "", flag
    assert "notes stay local" in push.kept_off(code("quiet", "", labels=[f"continues:{root['id']}"]), None, d, p)


def test_kept_off_inherits_no_push_from_the_tasks_it_continues(env, monkeypatch):
    # A continuation (a `continue:` task, or a fix of a review's findings) keeps the nearest ancestor's
    # no_push: its review is review only too. A chain without the marker stays pushable; a cycle ends.
    from ttp import push, pushq
    p = make(env)
    _with_origin(env, clone=False)
    p.set_config("delivery.push_branch", "work")
    monkeypatch.setattr(pushq, "enabled", lambda *a, **k: False)
    d = p.config()["delivery"]

    def code(title, spec="", labels=None, result=None):
        tid = p.db.add_task(title, spec, kind="code", origin="coordinator", labels=labels)
        if result:
            p.db.update_task(tid, result=json.dumps(result))
        return p.db.task(tid)

    root = code("notes", "Write the notes.\nno_push: notes stay local\n")
    cont = code("continue: notes", "Go on.", labels=[f"continues:{root['id']}"])
    fix = code("Fix review #9: notes", "", labels=[f"continues:{cont['id']}", "review_fix:9"])
    why = push.kept_off(fix, {"a.py": 1}, d, p)
    assert "notes stay local" in why and f"#{root['id']} (which it continues)" in why, why
    assert "notes stay local" in push.kept_off(cont, None, d, p)
    assert push.kept_off(fix, None, d) == ""   # without the project only its own marker counts
    flagged = code("tool", "", result={"status": "done", "summary": "ok", "no_push": "a local tool"})
    assert "a local tool" in push.kept_off(code("more", "", labels=[f"continues:{flagged['id']}"]), None, d, p)
    # The nearest ancestor's reason wins; the task's own marker before any.
    mid = code("mid", "no_push: nearer", labels=[f"continues:{root['id']}"])
    assert "nearer" in push.kept_off(code("leaf", "", labels=[f"continues:{mid['id']}"]), None, d, p)
    assert "its spec" in push.kept_off(code("own", "no_push: mine", labels=[f"continues:{root['id']}"]), None, d, p)
    # No marker anywhere in the chain: pushable. A cycle of continues labels ends.
    plain = code("plain", "Just code.")
    assert push.kept_off(code("next", "", labels=[f"continues:{plain['id']}"]), None, d, p) == ""
    a = code("loop a", "")
    b = code("loop b", "", labels=[f"continues:{a['id']}"])
    p.db.update_task(a["id"], labels=json.dumps([f"continues:{b['id']}"]))
    assert push.kept_off(p.db.task(a["id"]), None, d, p) == ""
    # End to end: the review of a fix of a no_push task is review only; that of a plain chain pushes.
    _, _, _, (rev,) = _finish_code(env, p, "fix of notes", {"b.py": 3},
                                   labels=[f"continues:{root['id']}", "review_fix:9"])
    assert "Review only" in rev["spec"] and "notes stay local" in rev["spec"], rev["spec"]
    assert push.REVIEW_ONLY_LABEL in json.loads(rev["labels"]) and "ttp push` from" not in rev["spec"]
    _, _, _, (rev,) = _finish_code(env, p, "fix of plain", {"c.py": 3}, labels=[f"continues:{plain['id']}"])
    assert "ttp push` from" in rev["spec"] and push.REVIEW_ONLY_LABEL not in json.loads(rev["labels"])


def test_allow_protected_push_branch_lets_reviews_push_to_main_and_without_it_they_never_git_push(env, monkeypatch, capsys):
    from ttp import cli, push, pushq
    from ttp.project import config_problems
    p = make(env)
    monkeypatch.setattr(pushq, "enabled", lambda *a, **k: False)   # no prechecks: the spec text is the subject
    for ref in ("main", "origin/master", "refs/heads/main"):
        assert push.push_branch_problem(ref, allow=True) == "", ref
        assert "allow_protected_push_branch" in push.push_branch_problem(ref)
    assert "always refuses" in push.push_branch_problem("HEAD", allow=True)
    _with_origin(env, clone=False)
    p.set_config("delivery.push_branch", "main")

    def review(title):
        _, _, _, (rev,) = _finish_code(env, p, title, {f"{title}.py": 3})
        return rev

    rev = review("off")
    assert "Review only" in rev["spec"] and "never fall back to a raw `git push` to main" in rev["spec"]
    assert push.REVIEW_ONLY_LABEL in json.loads(rev["labels"]) and "ttp push` from" not in rev["spec"]
    cli.main(["doctor", p.name])
    out = capsys.readouterr().out
    assert "delivery.allow_protected_push_branch" in out and "raw `git push`" in out
    p.set_config("delivery.allow_protected_push_branch", True)
    assert not any("push_branch" in x for x in config_problems(p.raw_config(), p.root))
    rev = review("on")
    assert "ttp push` from" in rev["spec"] and push.REVIEW_ONLY_LABEL not in json.loads(rev["labels"])
    # The prompts say the same: the reviewer never falls back to git push; only the user's word sets the key.
    text = (RUNTIME.parent / "template" / "prompts" / "kind-review.md").read_text()
    assert "NEVER fall back to a raw `git push` to that branch" in text
    coordinator = (RUNTIME.parent / "template" / "prompts" / "coordinator.md").read_text()
    rule = next(line for line in coordinator.splitlines() if line.startswith("| `config_set`"))
    assert "`delivery.allow_protected_push_branch`" in rule and rule.index("allow_protected") < rule.index("only on the user's word")
    assert "never a raw `git push` to it" in coordinator


def test_a_push_branch_no_push_can_reach_is_flagged_and_its_reviews_are_review_only(env, monkeypatch, capsys):
    # delivery.push_branch names main/master (ttp push always refuses it), or the code repo has no
    # remote: every review push would exit 2. The config check and doctor say so, and the review
    # spec has no push step.
    from ttp import cli, push, pushq
    from ttp.project import config_problems
    p = make(env)
    monkeypatch.setattr(pushq, "enabled", lambda *a, **k: False)   # no prechecks: the spec text is the subject
    # No repo to ask: only the name, its first part read either way.
    for ref in ("main", "master", "origin/main", "upstream/master", "refs/heads/main", "origin/refs/heads/master"):
        assert "always refuses" in push.push_branch_problem(ref), ref
    for ref in ("", None, "work", "origin/work", "maintenance", "main-next"):
        assert push.push_branch_problem(ref) == "", ref
    # A repo with no remote: any push branch.
    assert "no git remote" in push.push_branch_problem("work", p.root)
    assert any("no git remote" in x for x in config_problems({"delivery": {"push_branch": "work"}}, p.root))
    assert config_problems({"delivery": {"push_branch": "work"}}) == []
    # Not a git repo: only the name.
    assert push.push_branch_problem("work", env["tmp"] / "nowhere") == ""

    def review(title):
        _, _, _, (rev,) = _finish_code(env, p, title, {f"{title}.py": 3})
        return rev

    def review_only(rev, why):
        return "ttp push` from" not in rev["spec"] and "Review only" in rev["spec"] and why in rev["spec"] \
            and push.REVIEW_ONLY_LABEL in json.loads(rev["labels"]) and rev["spec"].rstrip().endswith("findings.")

    p.set_config("delivery.push_branch", "work")
    for on in (False, True):
        p.set_config("delivery.push_queue", on)
        assert review_only(review(f"noremote{on}"), "no git remote"), on
    cli.main(["doctor", p.name])
    assert "project.json: delivery.push_branch: the code repo has no git remote" in capsys.readouterr().out
    # With a remote: a protected branch, bare or behind the remote's name, never pushes either.
    _with_origin(env, clone=False)
    _git_out(p.root, "remote", "add", "upstream", str(env["tmp"] / "remote.git"))
    for i, ref in enumerate(("main", "origin/master", "upstream/main")):
        p.set_config("delivery.push_branch", ref)
        assert review_only(review(f"protected{i}"), "a branch ttp push always refuses"), ref
        assert any("always refuses" in x for x in config_problems(p.raw_config(), p.root)), ref
    cli.main(["doctor", p.name])
    assert "project.json: delivery.push_branch: upstream/main is main, a branch ttp push always refuses" \
        in capsys.readouterr().out
    # A remote the name does not use: origin is the fallback, and missing it never pushes.
    p.set_config("delivery.push_branch", "work")
    _git_out(p.root, "remote", "remove", "origin")
    assert review_only(review("noorigin"), "which is not a git remote")
    # A branch of its own on a remote the repo has: the review pushes as before; "team/main" is a
    # branch of origin, not main.
    _git_out(p.root, "remote", "add", "origin", str(env["tmp"] / "remote.git"))
    for i, ref in enumerate(("work", "upstream/work", "team/main")):
        p.set_config("delivery.push_branch", ref)
        rev = review(f"ok{i}")
        assert "ttp push` from" in rev["spec"] and push.REVIEW_ONLY_LABEL not in json.loads(rev["labels"]), ref
        assert not any("push_branch" in x for x in config_problems(p.raw_config(), p.root)), ref


def _pq_stacked(s, name, on=None, picks=(), review=None):
    """A code task whose branch starts at `on` (default: the target's tip), cherry-picks `picks` (a
    rebased copy of each) and adds one commit of its own, and a review of it with status `review`
    (None: none). Returns (task, branch, head, review id)."""
    tid, path, branch = _code_task(s.p, name)
    _git_out(path, "reset", "-q", "--hard", on or "origin/proj")
    for c in picks:
        _git_out(path, "cherry-pick", "-x", c)
    _commit(path, f"{name}.txt", f"{name}\n")
    rid = None
    if review:
        rid = s.p.db.add_task(f"review {name}", "r", kind="review", origin="coordinator", depends_on=[tid])
        s.p.db.update_task(rid, status=review)
    return tid, branch, _git_out(path, "rev-parse", "HEAD"), rid


def test_the_push_queue_refuses_a_head_carrying_commits_of_a_failed_review_unless_its_review_accepts_them(
        env, monkeypatch):
    from ttp import pushq
    s = _pq(env, monkeypatch)
    x, xbranch, xhead, _ = _pq_stacked(s, "rejected", review="failed")
    # Stacked on the rejected branch: refused, naming the task and its commit.
    c, cbranch, chead, crev = _pq_stacked(s, "stacked", on=xbranch, review="running")
    check = pushq.check_approval(s.p, s.p.db.task(crev), [{"branch": cbranch, "head": chead}])
    assert f"carries unreviewed commits from #{x}," in check.get("invalid", ""), check
    assert "edit rejected.txt" in check["invalid"] and '"inherited": [%d]' % x in check["invalid"]
    # The review judged them and lists the task: approved, and the feed line says so.
    check = pushq.check_approval(s.p, s.p.db.task(crev), [{"branch": cbranch, "head": chead, "inherited": [x]}])
    assert check.get("entries") and check["inherited"] == {chead: [x]}, check
    assert f"carries commits of #{x}" in pushq.queued_text(s.p.db.task(crev), check)
    # A rebased copy of the rejected commit (another sha, the same patch) is caught too.
    d, dbranch, dhead, drev = _pq_stacked(s, "copied", picks=[xhead], review="running")
    assert _git_out(s.path, "rev-parse", f"{dbranch}~1") != xhead
    check = pushq.check_approval(s.p, s.p.db.task(drev), [{"branch": dbranch, "head": dhead}])
    assert f"from #{x}," in check.get("invalid", ""), check
    # The rejected task's own re-review (or a fix that continues it) covers it: not refused.
    rr = s.p.db.add_task("re-review", "r", kind="review", origin="coordinator", depends_on=[x])
    assert pushq.check_approval(s.p, s.p.db.task(rr), [{"branch": xbranch, "head": xhead}]).get("entries")
    # A later passing review of the rejected task clears it.
    s.p.db.update_task(rr, status="done")
    assert pushq.check_approval(s.p, s.p.db.task(crev), [{"branch": cbranch, "head": chead}]).get("entries")
    # An unrelated head is approved as before.
    assert pushq.check_approval(s.p, s.p.db.task(s.review), [{"branch": s.branch, "head": s.head}]).get("entries")


def test_the_push_queue_accepts_a_head_stacked_on_a_passed_branch_landed_or_not(env, monkeypatch):
    from ttp import pushq
    s = _pq(env, monkeypatch)
    p_, pbranch, phead, prev = _pq_stacked(s, "passed", review="done")
    # A rejected sibling stacked on the passed branch holds its commits too: they stay the passed task's.
    _pq_stacked(s, "sibling", on=pbranch, review="failed")
    c, cbranch, chead, crev = _pq_stacked(s, "stacked", on=pbranch, review="running")
    entries = [{"branch": cbranch, "head": chead}]
    check = pushq.check_approval(s.p, s.p.db.task(crev), entries)
    assert check.get("entries") and "inherited" not in check, check
    # Landed as a rebased copy (as a batch lands it) and its review gone: its patch is on the tip.
    s.p.db.update_task(prev, status="cancelled")
    _git_out(s.other, "fetch", "-q", str(s.repo), pbranch)
    _git_out(s.other, "cherry-pick", "-x", "FETCH_HEAD")
    _git_out(s.other, "push", "-q", "origin", "HEAD:proj")
    _git_out(s.repo, "fetch", "-q", "origin")
    assert _git_out(s.repo, "rev-parse", "origin/proj") != phead
    check = pushq.check_approval(s.p, s.p.db.task(crev), entries)
    assert check.get("entries"), check


def test_a_review_approving_a_head_with_rejected_commits_runs_again_and_is_told_why(env, monkeypatch):
    s = _pq(env, monkeypatch)
    x, xbranch, _, _ = _pq_stacked(s, "rejected", review="failed")
    c, cbranch, chead, crev = _pq_stacked(s, "stacked", on=xbranch, review="running")
    t = _pq_hand_off(env, s, push=[{"branch": cbranch, "head": chead}], task=crev)
    assert t["status"] == "queued", t
    assert f"carries unreviewed commits from #{x}" in json.loads(t["result"])["woke"]
    assert not s.p.db.q("SELECT id FROM push_queue WHERE task=?", (crev,))


def test_a_daemon_queued_review_names_the_rejected_commits_its_head_carries(env, monkeypatch):
    from ttp import pushq
    from ttp.daemon import Daemon
    s = _pq(env, monkeypatch)
    monkeypatch.setattr(Daemon, "_precheck", lambda self, task, head: None)
    x, xbranch, _, _ = _pq_stacked(s, "rejected", review="failed")
    c, cbranch, chead, _ = _pq_stacked(s, "stacked", on=xbranch)
    d = Daemon(s.p.base)
    rid, added = d._auto_review(s.p.db.task(c), "made the change")
    spec = s.p.db.task(rid)["spec"]
    assert added and f"carries unreviewed commits from tasks whose latest review failed (#{x}: " in spec, spec
    assert "edit rejected.txt" in spec and '"inherited": [%d]' % x in spec
    # What the spec names is what the queue would refuse the review's approval for, and accept once listed.
    entry = {"branch": cbranch, "head": chead}
    assert f"from #{x}," in pushq.check_approval(s.p, s.p.db.task(rid), [entry]).get("invalid", "")
    assert pushq.check_approval(s.p, s.p.db.task(rid), [{**entry, "inherited": [x]}]).get("entries")
    # A head with no rejected commits under it: no such line.
    f, _, _, _ = _pq_stacked(s, "fresh")
    rid, added = d._auto_review(s.p.db.task(f), "made the change")
    assert added and "unreviewed commits" not in s.p.db.task(rid)["spec"]


def _pq_add_reviewed_tasks(db, start, stop):
    """Code tasks start..stop-1 on branches of their own, each with a finished review naming its branch
    in the spec (passed and failed in turn)."""
    with db.conn:
        for i in range(start, stop):
            db.conn.execute("INSERT INTO tasks (created, updated, title, spec, kind, status, branch) "
                            "VALUES (?, ?, ?, '', 'code', 'done', ?)",
                            (time.time(), time.time(), f"t{i}", f"ttp/t{9000 + i}-change-{i}"))
            db.conn.execute("INSERT INTO tasks (created, updated, title, spec, kind, status) "
                            "VALUES (?, ?, ?, ?, 'review', ?)",
                            (time.time(), time.time(), f"check {i}",
                             f"Check ttp/t{9000 + i}-change-{i} against the spec.", ("done", "failed")[i % 2]))


def test_the_inherited_commit_check_stays_fast_with_many_tasks_and_reviews(env, monkeypatch):
    # check_approval runs in the daemon's result path: its work must not grow with tasks x reviews.
    # Counted, not timed against the clock (a loaded machine makes any wall-clock bound flaky): git
    # calls stay the same however many tasks there are, rows read from the database grow linearly,
    # and its own CPU time grows sub-quadratically from n to 8n tasks and reviews.
    from ttp import pushq
    from ttp.db import DB
    s = _pq(env, monkeypatch)
    x, xbranch, _, _ = _pq_stacked(s, "rejected", review="failed")
    c, cbranch, chead, crev = _pq_stacked(s, "stacked", on=xbranch, review="running")
    entries = [{"branch": cbranch, "head": chead}]
    n = {"git": 0, "rows": 0}
    run, q, one = subprocess.run, DB.q, DB.one

    def counted_run(*a, **kw):
        n["git"] += 1
        return run(*a, **kw)

    def counted_q(self, *a, **kw):
        rows = q(self, *a, **kw)
        n["rows"] += len(rows)
        return rows

    def counted_one(self, *a, **kw):
        n["rows"] += 1
        return one(self, *a, **kw)

    def measure():
        task = s.p.db.task(crev)
        took = []
        for _ in range(3):
            n.update(git=0, rows=0)
            with monkeypatch.context() as m:
                m.setattr(pushq.subprocess, "run", counted_run)
                m.setattr(DB, "q", counted_q)
                m.setattr(DB, "one", counted_one)
                t0 = time.process_time()
                check = pushq.check_approval(s.p, task, entries)
                took.append(time.process_time() - t0)
            assert f"carries unreviewed commits from #{x}," in check.get("invalid", ""), check
        return dict(n, cpu=min(took))

    _pq_add_reviewed_tasks(s.p.db, 0, 100)
    small = measure()
    _pq_add_reviewed_tasks(s.p.db, 100, 800)
    big = measure()
    assert big["git"] == small["git"], f"git calls grew with the tasks: {small} -> {big}"
    assert big["rows"] - small["rows"] <= 10 * 700, f"rows read grew faster than the tasks: {small} -> {big}"
    # 8x the tasks: linear work grows at most 8x (much less, as git dominates), quadratic 64x.
    assert big["cpu"] < 16 * small["cpu"], f"CPU time grew quadratically: {small} -> {big}"


def test_names_branch_matches_the_whole_word_pattern_it_replaces():
    import random
    from ttp.db import names_branch
    rng = random.Random(7)
    parts = ["ttp/t12-fix", "ttp/t1-fix", "fix", "a", "_", "/", ".", "-", " ", "\n", "é", "٣", "x", "`", ":", ","]
    for _ in range(20000):
        spec = "".join(rng.choice(parts) for _ in range(rng.randint(0, 8)))
        branch = rng.choice(["ttp/t12-fix", "ttp/t1-fix", "fix", "t1", "a.b", "-x"])
        want = bool(re.search(rf"(?<![\w/.-]){re.escape(branch)}(?![\w/-])", spec))
        assert names_branch(spec, branch) == want, (spec, branch)
    assert not names_branch("anything", "") and not names_branch("anything", None)


def test_branch_index_finds_the_same_tasks_as_names_branch_one_by_one():
    import random
    from ttp.db import BranchIndex, names_branch, reviewed_ids
    rng = random.Random(11)
    parts = ["ttp/t12-fix", "ttp/t1-fix", "fix", "a", "_", "/", ".", "-", " ", "\n", "\x1c", "é", "٣", "x", "`",
             ":", ",", "(", ")", "a b", "a.b"]
    branches = ["ttp/t12-fix", "ttp/t1-fix", "fix", "t1", "a.b", "-x", "x.", ".x", "/", "a b", "fix,", "`fix`"]
    tasks = [{"id": i, "branch": b} for i, b in enumerate(branches)] + [{"id": 99, "branch": "fix"},
                                                                         {"id": 98, "branch": None}]
    index = BranchIndex(tasks)
    for _ in range(20000):
        spec = "".join(rng.choice(parts) for _ in range(rng.randint(0, 10)))
        want = {t["id"] for t in tasks if names_branch(spec, t["branch"])}
        assert index.named(spec) == want, spec
        assert reviewed_ids({"spec": spec}, tasks) == want, spec
    assert reviewed_ids({"title": "Review #3", "spec": "fix"}, index) == {3}
    assert reviewed_ids({"title": "Review #77", "spec": "fix"}, index) == set()


def test_branch_index_scans_a_long_punctuation_run_in_linear_time(env):
    from ttp.db import BranchIndex
    index = BranchIndex([{"id": i, "branch": f"ttp/t{i}-fix-{'x' * (i % 40)}"} for i in range(600)])
    spec = "=" * 10000 + " see ===ttp/t7-fix-xxxxxxx=== too"
    t0 = time.perf_counter()
    assert index.named(spec) == {7}
    took = time.perf_counter() - t0
    assert took < 0.1, f"BranchIndex.named took {took:.2f} s"
    # Every start a branch could begin at: only the bound on a branch's length keeps this linear.
    t0 = time.perf_counter()
    assert index.named("t=" * 10000) == set()
    took = time.perf_counter() - t0
    assert took < 0.5, f"BranchIndex.named took {took:.2f} s"


def test_a_review_only_stack_stays_review_only_through_its_fix_and_the_push_queue_ignores_its_approval(
        env, monkeypatch):
    from ttp import push, pushq
    from ttp.daemon import Daemon
    s = _pq(env, monkeypatch)
    entries = [{"branch": s.branch, "head": s.head}]
    assert pushq.check_approval(s.p, s.p.db.task(s.review), entries).get("entries"), "approved"
    s.p.db.update_task(s.review, labels=[push.REVIEW_ONLY_LABEL])
    check = pushq.check_approval(s.p, s.p.db.task(s.review), entries)
    assert "review only" in check.get("ignored", ""), check
    # A failed review-only review: its fix is told not to push, its re-review stays review only.
    s.p.db.update_task(s.review, status="failed")
    d = Daemon(s.p.base)
    out = d._fix_failed_review(s.p.db.task(s.review), [{"title": "bug", "spec": "fix it"}], "one bug")
    assert out, "no fix queued"
    fid, rid, _ = out
    assert "do not push it" in s.p.db.task(fid)["spec"] and "Leave the push" not in s.p.db.task(fid)["spec"]
    assert push.REVIEW_ONLY_LABEL in json.loads(s.p.db.task(rid)["labels"])
    # Its checks are not started for the push queue either.
    started = []
    monkeypatch.setattr(Daemon, "_precheck", lambda self, task, full: started.append(task["id"]))
    s.p.db.update_task(fid, branch=s.branch)
    d._precheck_open(s.p.db.task(fid), s.p.db.task(rid))
    assert started == []


def test_the_re_review_of_a_pr_branch_stack_carries_its_pr_branch_or_no_push_step(env, monkeypatch):
    """A code task labelled pr_branch:<branch> whose review fails: the daemon's fix and re-review keep
    delivering onto that branch. The re-review carries the label and says to publish the fix's head
    from the fix's branch, so `ttp push --own` from there (or from its own branch) publishes onto
    the pr_branch. A re-review that cannot carry it (the stack carries no pr_branch now, or own
    pushes are off) has no push step and never mentions --own."""
    from ttp import push, pushq, worktree
    from ttp.daemon import Daemon
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    monkeypatch.setattr(pushq, "enabled", lambda *a, **k: False)
    _git_out(repo, "push", "-q", "origin", "HEAD:refs/heads/feature/x")

    def failed_stack(title):
        for t in p.db.q("SELECT id FROM tasks WHERE status NOT IN ('done','failed','cancelled')"):
            p.db.update_task(t["id"], status="cancelled")   # one stack at a time
        cid, _, _, (rev,) = _finish_code(env, p, title, {f"{title}.py": 3}, labels=["pr_branch:feature/x"])
        assert "`ttp push --own --detach`" in rev["spec"], rev["spec"]
        assert "pr_branch:feature/x" in json.loads(rev["labels"])
        p.db.update_task(rev["id"], status="failed")
        return cid, rev

    def fix_and_re_review(rev):
        out = Daemon(p.base)._fix_failed_review(p.db.task(rev["id"]), [{"title": "bug", "spec": "fix it"}], "bug")
        assert out, "no fix queued"
        return p.db.task(out[0]), p.db.task(out[1])

    cid, rev = failed_stack("one")
    fix, rr = fix_and_re_review(rev)
    labels = json.loads(rr["labels"])
    assert "pr_branch:feature/x" in labels and push.REVIEW_ONLY_LABEL in labels, labels
    assert (f"publish #{fix['id']}'s head onto its pr_branch feature/x with `ttp push --own --detach` from "
            f"#{fix['id']}'s worktree (branch {fix['branch']})") in rr["spec"], rr["spec"]
    # The fix leaves the push to the re-review.
    assert "do not push it" in fix["spec"] and "--own" not in fix["spec"]
    path, branch = worktree.ensure(p, fix)
    _commit(path, "fixed.py", "fixed\n")
    monkeypatch.setenv("TTP_TASK", str(rr["id"]))
    assert push.own_target(p, path) == ("origin", "feature/x")
    # From a branch of its own, too: the label is what it publishes onto.
    _git_out(path, "checkout", "-q", "-b", f"ttp/t{rr['id']}-re-review")
    assert push.own_target(p, path) == ("origin", "feature/x")

    # The stack no longer carries a pr_branch: no label, and the first review's --own step is left out.
    _, rev = failed_stack("two")
    for t in p.db.q("SELECT * FROM tasks WHERE kind='code' AND title='two'"):
        p.db.update_task(t["id"], labels=[worktree.NO_PR_BRANCH])
    _, rr = fix_and_re_review(rev)
    assert not any(lb.startswith("pr_branch:") for lb in json.loads(rr["labels"])), rr["labels"]
    assert "--own" not in rr["spec"] and "Review only" in rr["spec"], rr["spec"]
    assert "carries no pr_branch" in rr["spec"]

    # A first review older than its pr_branch label: its own step sentence still counts.
    _, rev = failed_stack("legacy")
    p.db.update_task(rev["id"], labels=[lb for lb in json.loads(rev["labels"]) if not lb.startswith("pr_branch:")])
    fix, rr = fix_and_re_review(rev)
    assert "pr_branch:feature/x" in json.loads(rr["labels"]), rr["labels"]
    assert f"publish #{fix['id']}'s head onto its pr_branch feature/x" in rr["spec"], rr["spec"]

    # Own pushes turned off since the first review: as the first review then would, the stack lands on
    # the push branch like any other change (no review-only label), and the re-review never mentions --own.
    _, rev = failed_stack("three")
    p.set_config("delivery.own_push", "off")
    fix, rr = fix_and_re_review(rev)
    labels = json.loads(rr["labels"])
    assert not any(lb.startswith("pr_branch:") for lb in labels) and push.REVIEW_ONLY_LABEL not in labels, labels
    assert "--own" not in rr["spec"] and "Review only" not in rr["spec"], rr["spec"]
    assert "Its branch label feature/x was ignored: own pushes are off" in rr["spec"], rr["spec"]
    assert f"push #{fix['id']}'s head with `ttp push` from #{fix['id']}'s worktree" in rr["spec"], rr["spec"]
    assert "do not push it" not in fix["spec"] and f"Leave the push to re-review #{rr['id']}" in fix["spec"]
    # ...unless nothing may reach the push branch: then review only, saying why.
    p.set_config("delivery.own_push", "on")
    _, rev = failed_stack("four")
    for t in p.db.q("SELECT * FROM tasks WHERE kind='code' AND title='four'"):
        p.db.update_task(t["id"], spec="no_push: an experiment")
    p.set_config("delivery.own_push", "off")
    _, rr = fix_and_re_review(rev)
    assert push.REVIEW_ONLY_LABEL in json.loads(rr["labels"]), rr["labels"]
    assert "--own" not in rr["spec"] and "Review only: own pushes are off" in rr["spec"], rr["spec"]
    assert "must not reach the push branch" in rr["spec"], rr["spec"]


def test_a_push_queue_stack_whose_spec_or_hand_off_mentions_own_keeps_its_push_step_on_re_review(env, monkeypatch):
    """A plain stack (no pr_branch) whose code spec and hand-off mention `ttp push --own`: the first
    review pushes with `ttp push`, and so does the re-review after it fails. The mention is the code
    task's text, not the review's push step: the re-review is not review only and keeps that text."""
    from ttp import push, pushq
    from ttp.daemon import Daemon
    p, repo, origin, other = _push_setup(env, monkeypatch, ["true"])
    monkeypatch.setattr(pushq, "enabled", lambda *a, **k: False)
    spec = ("Publish with `ttp push --own --detach` when asked.\n"
            "It delivers onto its pr_branch nowhere, not here. If it passes, publish it there with "
            "`ttp push --own --detach`.")
    cid, _, _, (rev,) = _finish_code(env, p, "plain", {"plain.py": 3},
                                     result={"status": "done", "summary": "fixed the `ttp push --own` refusal"},
                                     before=lambda tid, head: p.db.update_task(tid, spec=spec))
    assert "push it with `ttp push`" in rev["spec"] and push.REVIEW_ONLY_LABEL not in json.loads(rev["labels"])
    p.db.update_task(rev["id"], status="failed")
    fid, rid, _ = Daemon(p.base)._fix_failed_review(p.db.task(rev["id"]), [{"title": "bug", "spec": "fix it"}], "bug")
    rr, fix = p.db.task(rid), p.db.task(fid)
    labels = json.loads(rr["labels"])
    assert push.REVIEW_ONLY_LABEL not in labels and not any(lb.startswith("pr_branch:") for lb in labels), labels
    assert "Review only" not in rr["spec"] and "push it with `ttp push`" in rr["spec"], rr["spec"]
    assert "fixed the `ttp push --own` refusal" in rr["spec"] and "If it passes, publish it there with `ttp push --own --detach`." in rr["spec"], rr["spec"]
    assert f"Leave the push to re-review #{rid}" in fix["spec"]


def test_the_review_of_a_task_with_another_pr_branch_publishes_with_own_and_never_approves_for_the_queue(
        env, monkeypatch):
    """A code task whose pr_branch is the push branch gets the usual push step; one whose pr_branch is
    another branch gets a review that publishes with `ttp push --own` and is review only for the push
    branch: no plain `ttp push`, no push-queue approval."""
    from ttp import push, pushq
    p = make(env)
    _with_origin(env, clone=False)
    p.set_config("delivery.push_branch", "origin/work")
    monkeypatch.setattr(pushq, "enabled", lambda *a, **k: False)   # no prechecks: the spec text is the subject
    for on in (False, True):
        p.set_config("delivery.push_queue", on)
        _, _, _, (same,) = _finish_code(env, p, f"same {on}", {f"s{on}.py": 3}, labels=["pr_branch:work"])
        assert "ttp push` from" in same["spec"] and "--own" not in same["spec"], same["spec"]
        assert push.REVIEW_ONLY_LABEL not in json.loads(same["labels"])
        _, _, _, (other,) = _finish_code(env, p, f"other {on}", {f"o{on}.py": 3}, labels=["pr_branch:feature/x"])
        assert "ttp push` from" not in other["spec"], other["spec"]
        assert "pr_branch feature/x" in other["spec"] and "`ttp push --own --detach`" in other["spec"]
        assert "do not approve it for the push queue" in other["spec"]
        assert other["spec"].rstrip().endswith("the pushed commit.")
        assert push.REVIEW_ONLY_LABEL in json.loads(other["labels"])
    # A project that does not push: review only, no publish step.
    p.set_config("delivery.push_allowed", False)
    _, _, _, (rev,) = _finish_code(env, p, "no push", {"n.py": 3}, labels=["pr_branch:feature/x"])
    assert "Review only" in rev["spec"] and "--own --detach" not in rev["spec"], rev["spec"]
    coordinator = (RUNTIME.parent / "template" / "prompts" / "coordinator.md").read_text()
    assert "publish it with `ttp push --own --detach`\", never\n  plain `ttp push` or a push-queue approval" \
        in coordinator


def test_the_review_prompt_keeps_the_own_publish_step_when_the_push_queue_is_on(env, monkeypatch):
    """With the push queue on, a review whose spec says to publish with `ttp push --own` still gets
    the --own section with its --detach, retry_when and exit-code steps, and the queue section's
    'NEVER run `ttp push`' names it as the exception, so the two never contradict."""
    from ttp import pushq
    from ttp.prompts import worker_task
    p = make(env)
    _with_origin(env, clone=False)
    p.set_config("delivery.push_branch", "origin/work")
    p.set_config("delivery.push_queue", True)
    monkeypatch.setattr(pushq, "enabled", lambda *a, **k: False)
    _, _, _, (rev,) = _finish_code(env, p, "other", {"o.py": 3}, labels=["pr_branch:feature/x"])
    text = worker_task(p, rev, str(p.root), None)
    assert "push queue=True" in text and "`ttp push --own --detach`" in rev["spec"]
    own = text[text.index("## Publishing onto its own PR branch (when the spec says `ttp push --own`)"):]
    own = own[:own.index("\n## ")]
    assert "whatever the sections below say, with or without the push queue" in own
    assert "run `ttp push --own --detach` in the\n  change's worktree" in own
    assert "never approve it for the push queue" in own and "`waiting` with that\n  `retry_when`" in own
    for code in ("0 pushed", "3: rebase conflict", "4: a check failed", "5: the\n  branch kept moving",
                 "75: another push", "2 or 6: refused"):
        assert code in own, code
    queue = text[text.index("## Approving into the push queue"):]
    assert "NEVER run `ttp push` or `git push`" in queue
    assert "The one\n  exception: a spec that says to publish with `ttp push --own`" in queue
    # Without the queue the section is there too, next to the plain push section.
    p.set_config("delivery.push_queue", False)
    off = worker_task(p, rev, str(p.root), None)
    assert "## Publishing onto its own PR branch" in off and "## Approving into the push queue" not in off


def test_the_review_of_a_task_whose_pr_branch_is_absent_from_the_remote_delivers_to_the_push_branch(
        env, monkeypatch):
    """With the push queue on, a pr_branch the push remote has no branch of is ignored, as the queue's
    check_approval ignores it: the review gets the usual push step and the label is named as ignored.
    A task whose spec asks for `ttp push --own` (it creates that branch) keeps the --own step, and so
    does a pr_branch the remote has."""
    from ttp import push, pushq, settinghold
    from ttp.daemon import Daemon
    p = make(env)
    _with_origin(env, clone=False)
    p.set_config("delivery.push_branch", "origin/work")
    p.set_config("delivery.push_queue", True)
    monkeypatch.setattr(pushq, "enabled", lambda *a, **k: True)
    monkeypatch.setattr(Daemon, "_precheck", lambda *a: None)   # no checks: the spec text is the subject
    _, _, _, (gone,) = _finish_code(env, p, "gone", {"g.py": 3}, labels=["pr_branch:feature/x"])
    assert "ttp push` from" in gone["spec"] and "--own" not in gone["spec"], gone["spec"]
    assert "pr_branch label feature/x was ignored: origin has no such branch" in gone["spec"]
    assert push.REVIEW_ONLY_LABEL not in json.loads(gone["labels"])

    def own(tid, head):
        p.db.update_task(tid, spec="Create feature/x: publish it with `ttp push --own --detach`.")
    _, _, _, (mine,) = _finish_code(env, p, "own", {"m.py": 3}, labels=["pr_branch:feature/x"], before=own)
    assert "`ttp push --own --detach`" in mine["spec"] and "was ignored" not in mine["spec"], mine["spec"]
    assert push.REVIEW_ONLY_LABEL in json.loads(mine["labels"])
    # A pr_branch the remote has: its PR's branch, --own as before.
    monkeypatch.setattr(pushq, "_absent", lambda *a: False)
    _, _, _, (there,) = _finish_code(env, p, "there", {"t.py": 3}, labels=["pr_branch:feature/x"])
    assert "`ttp push --own --detach`" in there["spec"] and "was ignored" not in there["spec"]
    # asks_own reads an --own instruction, never a negated one or a plain push.
    assert settinghold.asks_own({"spec": "- ttp push --own --detach"})
    assert settinghold.asks_own({"title": "publish it with `ttp push --own`"})
    for spec in ("Do not use `ttp push --own` here.", "push it with `ttp push --detach`", "mentions --own"):
        assert not settinghold.asks_own({"spec": spec}), spec


def test_pr_elsewhere_compares_the_push_branchs_branch_part(env):
    """push_branch `team/x` is branch team/x of origin (team is no remote): pr_branch x is another
    branch; `origin/x` and `refs/heads/x` are x."""
