def test_ttp_stats_reports_reread_tokens_per_run_and_per_dollar_by_kind_and_tier(env, capsys):
    p = make(env)
    from ttp import budget as bud
    now = time.time()
    code = p.db.add_task("big code change", "s", kind="code", tier="deep", origin="user")
    review = p.db.add_task("review it", "s", kind="review", tier="standard", origin="user")
    for task, role, effort, usd, cr, out, age in ((code, "worker", "max", 6.0, 9_000_000, 100_000, 3600),
                                                  (code, "worker", "max", 2.0, 3_000_000, 20_000, 7200),
                                                  (review, "reviewer", "high", 1.0, 500_000, 10_000, 600),
                                                  (None, "coordinator", "low", 0.1, 20_000, 1_000, 60),
                                                  (code, "worker", "max", 9.0, 50_000_000, 1, 9 * 86400)):
        p.db.x("INSERT INTO runs(task,role,provider,effort,started,ended,status,cost_usd,cache_read_tokens,"
               "output_tokens) VALUES(?,?,?,?,?,?,?,?,?,?)",
               (task, role, "claude", effort, now - age, now - age + 600, "done", usd, cr, out))
    s = bud.reread_stats(p.db, 7, now=now)
    assert s["runs"] == 4 and s["cache_read"] == 12_520_000 and s["usd"] == 9.1, "an old run counted"
    assert s["per_run"] == 3_130_000 and s["per_usd"] == round(12_520_000 / 9.1)
    # 1.252 M weighted re-read units of 1.252 M + 5 * 131 k output units
    assert s["share"] == round(1_252_000 / (1_252_000 + 5 * 131_000), 3)
    top = s["groups"][0]
    assert (top["role"], top["kind"], top["tier"], top["effort"], top["runs"]) == ("worker", "code", "deep", "max", 2)
    assert top["per_run"] == 6_000_000 and top["max"] == 9_000_000
    assert [t["cache_read"] for t in s["top"]] == [9_000_000, 3_000_000, 500_000, 20_000]
    assert s["top"][0]["title"] == "big code change" and s["top"][0]["minutes"] == 10
    monkey = pytest.MonkeyPatch()
    monkey.chdir(p.root)
    try:
        cli_rc = _ttp_main("stats", "--days", "7")
    finally:
        monkey.undo()
    out = capsys.readouterr().out
    assert cli_rc is None and "Context re-reads, last 7 days: 4 runs, $9.10, 12.52 M cache-read tokens" in out
    assert "worker/code/deep/max: 2 runs, $8.00, 12.00 M (6.00 M per run, median 6.00 M, max 9.00 M)" in out
    assert "big code change" in out
    assert "Split steer: no run steered" in out
    for cr, at, how in ((9_000_000, 4_000_000, "done"), (3_000_000, 2_800_000, "waiting")):
        p.db.x("INSERT INTO runs(task,role,provider,effort,started,ended,status,cost_usd,cache_read_tokens,note) "
               "VALUES(?,?,?,?,?,?,?,?,?,?)", (code, "worker", "claude", "high", now - 60, now, "ok", 1.0, cr,
                                              json.dumps({"split": {"ts": now - 30, "cache_read": at, "handoff": how}})))
    p.db.x("INSERT INTO runs(task,role,provider,effort,started,status,cache_read_tokens,note) VALUES(?,?,?,?,?,?,?,?)",
           (code, "worker", "claude", "high", now - 60, "running", 4_000_000,
            json.dumps({"split": {"ts": now - 30, "cache_read": 3_100_000}})))
    s = bud.reread_stats(p.db, 7, now=now)
    assert s["steered"] == {"runs": 3, "after_avg": 2_033_333, "after_max": 5_000_000,
                            "handoffs": {"done": 1, "waiting": 1, "running": 1}}, s["steered"]
    assert ("Split steer: 3 runs steered, re-read after it 2.03 M avg (max 5.00 M); handed off: done 1, "
            "waiting 1, running 1") in bud.reread_text(s)


def test_ttp_stats_leaves_runs_with_no_model_call_out_of_per_run_averages(env, capsys):
    """Failed sign-ins (status auth, or no prompt tokens at all) cost a wake, not context: a burst of
    them must not move per-run or median re-reads, and is reported apart."""
    p = make(env)
    from ttp import budget as bud
    now = time.time()
    code = p.db.add_task("code change", "s", kind="code", tier="standard", origin="user")

    def run(age, cr, status="done", inp=100, usd=1.0, calls=None):
        note = json.dumps({"cache_telemetry": {"complete": True, "requests": None, "source": "result",
                                               "calls": calls, "first_context": 40_000}}) if calls else None
        p.db.x("INSERT INTO runs(task,role,provider,effort,started,ended,status,cost_usd,input_tokens,"
               "cache_read_tokens,note) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
               (code, "worker", "claude", "high", now - age, now - age + 60, status, usd, inp, cr, note))

    run(3600, 2_000_000, calls=20)
    run(3000, 4_000_000, calls=40)
    run(2400, 9_000_000, calls=90)
    clean = bud.reread_stats(p.db, 7, now=now)
    for age in range(10, 174):   # 164 runs that never reached the model
        run(age, 0, status="auth", inp=0, usd=0.0)
    run(5, 50, status="auth", inp=3, usd=0.0)   # an auth status counts as no call whatever it shows
    s = bud.reread_stats(p.db, 7, now=now)
    assert s["runs"] == clean["runs"] == 3 and s["per_run"] == clean["per_run"] == 5_000_000
    assert s["median"] == 4_000_000 and s["no_work"] == 165 and clean["no_work"] == 0
    assert s["calls_per_run"] == 50.0 and s["first_context"] == 40_000
    g = s["groups"][0]
    assert (g["runs"], g["per_run"], g["median"], g["no_work"]) == (3, 5_000_000, 4_000_000, 165)
    assert all(t["cache_read"] for t in s["top"]), "a no-call run listed among the top runs"
    assert "165 runs with no model call left out" in bud.reread_text(s)


def test_ttp_stats_split_at_compares_before_and_after_a_change(env, capsys):
    p = make(env)
    from ttp import budget as bud
    now = time.time()
    at = now - 2 * 86400
    code = p.db.add_task("code change", "s", kind="code", tier="standard", origin="user")
    for age, cr, status in ((4 * 86400, 6_000_000, "done"), (3 * 86400, 6_000_000, "done"),
                            (86400, 5_000_000, "done"), (3600, 5_000_000, "done"),
                            *((600 + i, 0, "auth") for i in range(10)), (20 * 86400, 90_000_000, "done")):
        p.db.x("INSERT INTO runs(task,role,provider,effort,started,ended,status,cost_usd,input_tokens,"
               "cache_read_tokens) VALUES(?,?,?,?,?,?,?,?,?,?)",
               (code, "worker", "claude", "high", now - age, now - age + 60, status, 1.0 if cr else 0.0,
                100 if cr else 0, cr))
    s = bud.reread_split(p.db, at, since=at - 7 * 86400, until=now, now=now)
    b, a = s["before"], s["after"]
    assert (b["runs"], b["per_run"], b["no_work"]) == (2, 6_000_000, 0), "the 20-day-old run counted"
    assert (a["runs"], a["per_run"], a["no_work"]) == (2, 5_000_000, 10)
    assert s["per_run_pct"] == -17 and s["groups"][0]["per_run_pct"] == -17
    assert s["groups"][0]["runs"] == (2, 2)
    monkey = pytest.MonkeyPatch()
    monkey.chdir(p.root)
    try:
        assert _ttp_main("stats", "--split-at", str(at), "--days", "7") is None
        out = capsys.readouterr().out
        assert "per run 6.00 M -> 5.00 M (-17%)" in out and "no model call 0 -> 10 (left out)" in out
        assert "worker/code/standard/high: 2 -> 2 runs" in out and "Before:" in out and "After:" in out
        iso = time.strftime("%Y-%m-%dT%H:%M:%S+00:00", time.gmtime(at))
        assert _ttp_main("stats", "--since", iso, "--json") is None
        after = json.loads(capsys.readouterr().out)
        assert after["runs"] == 2 and after["no_work"] == 10 and after["per_run"] == 5_000_000
        with pytest.raises(SystemExit):
            _ttp_main("stats", "--until", "last tuesday")
    finally:
        monkey.undo()


def _ttp_main(*args):
    from ttp import cli
    return cli.main(list(args))


def test_ttp_checks_runs_one_quoted_extra_command_through_the_shell(env, tmp_path, monkeypatch):
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    rec = lambda: json.loads((run / "checks.json").read_text())
    cli.main(["checks", "--fresh", "--", 'FOO=1 sh -c \'test "$FOO" = 1\' && test -f a.txt'])
    assert rec()["passed"] is True
    with pytest.raises(SystemExit) as e:
        cli.main(["checks", "--fresh", "--", "FOO=1 test -f missing.txt"])
    assert e.value.code != 0 and rec()["passed"] is False, "a failing quoted command is a failure"
    # Several words still run as argv: the spaces inside one word stay quoted.
    cli.main(["checks", "--fresh", "--", "test", "-n", "a b"])
    assert rec()["passed"] is True and rec()["commands"] == ["test -n 'a b'"]
    with pytest.raises(SystemExit) as e:
        cli.main(["checks", "--fresh", "--", "no-such-program-ttp"])
    assert e.value.code != 0 and rec()["passed"] is False
    assert "not found" in (run / "checks.log").read_text()



def test_ttp_checks_runs_several_quoted_extra_commands_as_one_check_each(env, tmp_path, monkeypatch, capsys):
    from ttp import cli
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    rec = lambda: json.loads((run / "checks.json").read_text())
    log = tmp_path / "ran"
    cli.main(["checks", "--fresh", "--", f"echo a >> {log}", f"test -f a.txt && echo b >> {log}"])
    assert rec()["passed"] is True and rec()["commands"] == [f"echo a >> {log}", f"test -f a.txt && echo b >> {log}"]
    assert log.read_text().split() == ["a", "b"], "each quoted command ran as its own check"
    with pytest.raises(SystemExit) as e:
        cli.main(["checks", "--fresh", "--", "test -f a.txt", "test -f missing.txt"])
    assert e.value.code != 0 and rec()["passed"] is False
    assert "'test -f missing.txt' failed" in capsys.readouterr().err
    # A plain argv, and argv with one quoted word among plain ones, stays one command.
    assert cli._extra_checks(["pytest", "-q", "tests/x.py"], []) == (["pytest -q tests/x.py"], [])
    assert cli._extra_checks(["pytest", "-k", "a and b"], []) == (["pytest -k 'a and b'"], [])
    assert cli._extra_checks(["FOO=1 pytest -q"], []) == (["FOO=1 pytest -q"], [])
    assert cli._extra_checks([], []) == ([], [])


def test_ttp_checks_drops_an_extra_command_the_project_checks_already_run(env, tmp_path, monkeypatch, capsys):
    from ttp import cli, push
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    count = tmp_path / "count"
    check = f"echo x >> {count}"
    p.set_config("delivery.push_checks", [check])
    cli.main(["checks", "--fresh", "--", check, "test -f a.txt"])
    out = capsys.readouterr().out
    assert len(count.read_text().splitlines()) == 1, "the push check ran once"
    assert json.loads((run / "checks.json").read_text())["commands"] == [check, "test -f a.txt"]
    assert out.count("delivery.push_checks already runs it") == 1 and repr(check) in out
    # The same command in another form, or given twice, is still one command.
    own = push.check_list(["pytest -q tests/a.py"])
    assert cli._extra_checks(["pytest", "-q", "tests/a.py"], own) == ([], ["pytest -q tests/a.py"])
    assert cli._extra_checks(["pytest  -q 'tests/a.py'"], own) == ([], ["pytest  -q 'tests/a.py'"])
    assert cli._extra_checks(["ruff check .", "ruff  check ."], own) == (["ruff check ."], ["ruff  check ."])
    # A scoped project check may be skipped on this head: the extra that matches it stays.
    scoped = push.check_list([{"run": "pytest -q", "if_changed": "src/**"}])
    assert cli._extra_checks(["pytest", "-q"], scoped) == (["pytest -q"], [])


def _recording_venv(path, ran):
    """A venv stand-in whose python records how it was called, with a pytest on its PATH."""
    venv = _fake_venv(path)
    (venv / "bin" / "python").write_text(f'#!/bin/sh\necho "$@" >> {ran}\n')
    (venv / "bin" / "pytest").write_text(f"#!/bin/sh\necho venv-pytest >> {ran}\n")
    for name in ("python", "pytest"):
        (venv / "bin" / name).chmod(0o755)
    return venv


def test_ttp_checks_runs_an_extra_pytest_once_and_in_the_projects_venv(env, tmp_path, monkeypatch, capsys):
    """Replays `ttp checks -- 'pytest -q --no-device-tests'` beside a project check that already runs
    it: it ran twice, the second time with the pytest on PATH, whose python lacked the project's
    packages, so it failed at import after the first run passed."""
    from ttp import cli, push
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    monkeypatch.delenv("VIRTUAL_ENV", raising=False)
    ran = tmp_path / "ran"
    venv = _recording_venv(p.root / ".venv", ran)
    stub = tmp_path / "stub"   # the pytest PATH finds outside the venv: no project packages
    stub.mkdir()
    (stub / "pytest").write_text(f"#!/bin/sh\necho path-pytest >> {ran}\nexit 1\n")
    (stub / "pytest").chmod(0o755)
    monkeypatch.setenv("PATH", f"{stub}{os.pathsep}{os.environ['PATH']}")
    cmd = "pytest -q --no-device-tests"
    # A scoped project check that applies on this head runs it: the extra is dropped, not run again.
    p.set_config("delivery.push_checks", [{"run": cmd, "if_exists": "a.txt"}])
    cli.main(["checks", "--fresh", "--", cmd])
    out = capsys.readouterr().out
    runs = lambda: [ln for ln in ran.read_text().splitlines() if ln != "-c pass"]   # not the venv probe
    assert runs() == ["-m pytest -q --no-device-tests"], "once, with the project venv's python"
    assert "a scoped delivery.push_checks entry runs it on this head" in out
    # Another spelling of the same pytest run is the same command.
    ran.unlink()
    p.set_config("delivery.push_checks", [f"{venv}/bin/python -m pytest -q --no-device-tests"])
    cli.main(["checks", "--fresh", "--", cmd])
    assert len(runs()) == 1
    assert "delivery.push_checks already runs it" in capsys.readouterr().out
    # An extra pytest no project check runs still uses the project's venv, not the pytest on PATH.
    ran.unlink()
    p.set_config("delivery.push_checks", ["true"])
    cli.main(["checks", "--fresh", "--", "pytest -q tests/x.py"])
    assert runs() == ["-m pytest -q tests/x.py"]
    # The same with the venv already active (a run's environment): VIRTUAL_ENV picks it.
    monkeypatch.setenv("VIRTUAL_ENV", str(venv))
    assert push.venv_cmd("pytest -q", repo) == f"{shlex.quote(str(venv / 'bin' / 'python'))} -m pytest -q"
    assert push.venv_cmd("pytest -q", repo, {}) == "pytest -q"
    # Spellings of one pytest run; shell syntax stays as written.
    keys = {cli._same_run_key(c, "/x/.venv/bin/python") for c in (
        "pytest -q", "py.test -q", "python -m pytest -q", "python3 -m pytest -q", "/x/.venv/bin/python -m pytest -q")}
    assert keys == {"pytest -q"}
    # Only those: another explicit interpreter runs as written, so it is not the same run.
    for c in ("/usr/bin/python3 -m pytest -q", "python3.11 -m pytest -q", ".venv/bin/pytest -q",
              "/x/.venv/bin/python -m pytest -q"):
        assert cli._same_run_key(c) == c
    assert cli._extra_checks(["/usr/bin/python3 -m pytest -q"], push.check_list(["pytest -q"])) == (
        ["/usr/bin/python3 -m pytest -q"], [])
    assert cli._extra_checks(["/x/.venv/bin/python -m pytest -q"], push.check_list(["pytest -q"]),
                             "/x/.venv/bin/python") == ([], ["/x/.venv/bin/python -m pytest -q"])
    assert cli._same_run_key("pytest -q; true") == "pytest -q; true"
    assert cli._same_run_key("python3 tools/pytest.py") == "python3 tools/pytest.py"


def test_ttp_checks_warns_of_a_broken_venv_with_the_command_that_makes_it_again(env, tmp_path, monkeypatch, capsys):
    """A project-root .venv link to a venv made on another OS (its python points at an interpreter
    missing here) leaves the checks without its packages: ttp checks says so and how to rebuild it."""
    from ttp import cli, push
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    monkeypatch.delenv("VIRTUAL_ENV", raising=False)
    (repo / ".gitignore").write_text(".venv\nvenv/\n")
    (repo / "pyproject.toml").write_text('[project]\nname = "x"\n[project.optional-dependencies]\ntest = ["pytest"]\n')
    subprocess.run([*git, "add", "."], check=True)
    subprocess.run([*git, "commit", "-qm", "b"], check=True)
    real = _fake_venv(repo / "venv", python=False)
    (real / "bin" / "python").symlink_to(tmp_path / "elsewhere" / "python3")
    (repo / ".venv").symlink_to("venv")
    p.set_config("delivery.push_checks", ["true"])
    cli.main(["checks", "--fresh"])
    out = capsys.readouterr().out
    assert out.count("warning: the venv") == 1, out   # .venv and venv are one venv
    assert f"python3 -m venv --clear {real} && {real}/bin/python -m pip install -e '{repo}[test]'" in out
    assert "warning: the venv" in (run / "checks.log").read_text()
    assert push.venv_cmd("pytest -q", repo) == "pytest -q"   # never the broken venv's python
    # A link that dangles, and a python that does not run; a working venv is not named.
    (repo / ".venv").unlink()
    (repo / ".venv").symlink_to(tmp_path / "gone")
    (real / "bin" / "python").unlink()
    (real / "bin" / "python").write_text("#!/bin/sh\necho bad interpreter >&2\nexit 1\n")
    (real / "bin" / "python").chmod(0o755)
    found = dict(push.broken_venvs(repo))
    assert "which is missing" in found[repo / ".venv"] and "bad interpreter" in found[repo / "venv"]
    (real / "bin" / "python").unlink()
    (real / "bin" / "python").symlink_to(sys.executable)
    assert list(push.broken_venvs(repo)) == [(repo / ".venv", found[repo / ".venv"])]
    assert push.venv_rebuild_cmd(tmp_path / "plain" / ".venv").endswith("-m pip install pytest")


def test_ttp_checks_still_reads_a_checks_record_from_before_extras_were_split(env, tmp_path, monkeypatch):
    from ttp import cli, push
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    head = subprocess.run([*git, "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
    (run / "checks.json").write_text(json.dumps({"head": head, "worktree": str(repo), "passed": True,
                                                 "commands": ["pytest -q", "test -n 'a b'"], "skipped": [],
                                                 "ts": time.time()}))
    assert push.recorded_extras(push.recorded_checks(run), head, push.check_list(["pytest -q"])) == ["test -n 'a b'"]
    cli.main(["checks", "--", "test", "-n", "a b"])
    assert json.loads((run / "checks.json").read_text())["commands"] == ["test -n 'a b'"]

# global daily cap and the fixed budget day ---------------------------------------------------------
def _other_project(tmp_path, name, host="testhost"):
    """Another project's database on this machine, registered as `ttp list` would show it."""
    from ttp.db import DB
    from ttp.project import FOLDER, register
    root = tmp_path / name
    db = DB(root / FOLDER / "state" / "project.db")
    register(name, {"host": host, "dir": str(root)})
    return db


def test_the_budget_day_starts_at_a_fixed_hour_in_its_zone_across_dst(env, monkeypatch):
    from datetime import datetime, timezone
    from ttp import budget as bud
    from ttp import globalcap as gcap
    monkeypatch.setenv("TZ", "UTC")   # the host's zone plays no part
    time.tzset()
    try:
        b = {"day_start": "08:00", "timezone": "America/New_York"}
        utc = lambda *a: datetime(*a, tzinfo=timezone.utc).timestamp()  # noqa: E731
        # Clocks go back on 2026-11-01: 07:00 EST is before the day's start, so today began at
        # 08:00 EDT the day before and is 25 h long.
        start, end = gcap.day_bounds(b, utc(2026, 11, 1, 12, 0))
        assert (start, end) == (utc(2026, 10, 31, 12, 0), utc(2026, 11, 1, 13, 0))
        # Clocks go forward on 2026-03-08: that day is 23 h long.
        start, end = gcap.day_bounds(b, utc(2026, 3, 7, 14, 0))
        assert (start, end) == (utc(2026, 3, 7, 13, 0), utc(2026, 3, 8, 12, 0))
        assert gcap.day_bounds({"day_start": "", "timezone": "UTC"}, utc(2026, 3, 7, 14, 0)) is None
        assert gcap.day_bounds({"day_start": "08:00"}, utc(2026, 3, 7, 7, 0))[0] == utc(2026, 3, 6, 8, 0)   # UTC default
        assert gcap.setting_problems({"timezone": "Mars/Base"}) and gcap.setting_problems({"day_start": "8am"})
        # The project's daily cap counts this budget day, not the last 24 h.
        p = make(env)
        now = utc(2026, 11, 1, 14, 0)          # 09:00 EST: the day began an hour ago
        p.set_config("budget.timezone", "America/New_York")
        p.set_config("budget.day_start", "08:00")
        p.db.spend("fake", 90.0, "task:1", ts=now - 2 * 3600)   # yesterday's budget day
        p.db.spend("fake", 30.0, "task:2", ts=now - 1800)
        g = bud.evaluate(p.db, p.config(), "fake", [], now)
        assert g.numbers["spent_today"] == 30.0 and g.level != "red", (g.level, g.reasons)
        assert g.numbers["day_end"] == utc(2026, 11, 2, 13, 0)
    finally:
        monkeypatch.delenv("TZ")
        time.tzset()


def test_the_global_daily_total_sums_this_machines_projects_on_the_same_account(env, tmp_path):
    p = make(env)
    from ttp import globalcap as gcap
    now = time.time()
    start, end = now - 3600, now + 3600
    p.db.spend("claude", 1.0, "task:1", account="acct-a")
    other = _other_project(tmp_path, "other")
    other.spend("claude", 2.0, "task:1", account="acct-a")
    other.spend("claude", 4.0, "task:2", account="")              # unknown account: counted (fail safe)
    other.spend("claude", 8.0, "task:3", account="acct-b")        # another account
    other.spend("codex", 16.0, "task:4", account="acct-a")        # another provider
    other.spend("claude", 32.0, "task:5", account="acct-a", ts=start - 60)   # before today
    other.x("INSERT INTO runs(role,provider,account,started,status,cost_usd) VALUES('worker','claude','acct-a',?,"
            "'running',0.5)", (now,))                              # running work as last priced
    _other_project(tmp_path, "elsewhere", host="otherhost").spend("claude", 64.0, "t", account="acct-a")
    t = gcap.total(p.db, "claude", start, end, now, account="acct-a")
    # A machine not heard from yet counts as stale; this machine never reads its projects' files.
    assert t["usd"] == 7.5 and t["local_projects"] == 2 and t["stale"] == ["otherhost"], t
    assert "2 tt-project projects on this machine" in t["includes"]
    assert "not your own sessions" in t["includes"]   # what the total does not see
    # The hook for other spend adds to the total and says so.
    gcap.add_other_source(lambda prov, acct, s, e: (2.5, "2 local sessions"))
    t = gcap.total(p.db, "claude", start, end, now + gcap.LOCAL_CACHE_S + 1, account="acct-a")
    assert t["usd"] == 10.0 and "2 local sessions" in t["includes"], t


def test_the_global_daily_total_counts_another_machine_fresh_and_then_stale(env, tmp_path, monkeypatch):
    p = make(env)
    from ttp import globalcap as gcap
    from ttp.project import register
    now = time.time()
    start, end = now - 3600, now + 3600
    register("far", {"host": "box2", "dir": "/srv/far"})
    key = gcap.account_key("claude", "acct-a")
    real_fetch, asked = gcap.fetch, []

    def fetch(target, s, e):
        asked.append(target)
        return {"host": "box2", "rows": [{"provider": "claude", "key": key, "usd": 50.0},
                                         {"provider": "claude", "key": gcap.account_key("claude", "x"), "usd": 9.0}],
                "projects": ["far"]}

    monkeypatch.setattr(gcap, "fetch", fetch)
    gcap.refresh(start, end, now)
    assert asked == ["box2"]
    t = gcap.total(p.db, "claude", start, end, now, account="acct-a")
    assert t["usd"] == 50.0 and t["stale"] == [] and t["remote_projects"] == 1, t
    gcap.refresh(start, end, now + 60)
    assert asked == ["box2"], "asked again before REFRESH_S"
    # The machine stops answering: its last total still counts, marked stale.
    monkeypatch.setattr(gcap, "fetch", lambda *a: (_ for _ in ()).throw(RuntimeError("ssh: timed out")))
    later = now + gcap.REFRESH_S + 1
    gcap.refresh(start, end, later)
    t = gcap.total(p.db, "claude", start, end, later, account="acct-a")
    assert t["usd"] == 50.0 and t["stale"] == ["box2"] and "(1 stale)" in t["includes"], t
    # An old answer is stale too; one from another budget day does not count.
    monkeypatch.setattr(gcap, "fetch", fetch)
    gcap.refresh(start, end, later, force=True)
    assert gcap.total(p.db, "claude", start, end, later, account="acct-a")["stale"] == []
    assert gcap.total(p.db, "claude", start, end, later + gcap.STALE_S + 1, account="acct-a")["stale"] == ["box2"]
    t = gcap.total(p.db, "claude", end, end + 86400, later, account="acct-a")
    assert t["usd"] == 0 and t["stale"] == ["box2"], t     # no answer for that day yet
    # The other machine answers with `ttp spend-today` over ssh in batch mode, no new tunnel.
    calls = []
    monkeypatch.setattr(gcap.subprocess, "run", lambda cmd, **kw: calls.append(cmd) or types.SimpleNamespace(
        returncode=0, stdout=json.dumps({"host": "box2", "rows": [], "projects": []}), stderr=""))
    real_fetch("box2", start, end)
    assert calls[0][:3] == ["ssh", "-o", "BatchMode=yes"] and "spend-today" in calls[0][-1], calls


def test_the_global_total_and_the_project_caps_count_spend_by_one_rule(env, tmp_path, monkeypatch):
    # Which ledger rows count as spend is decided in one place (db.counted_spend), so a change to
    # it applies to the project caps and the global daily total alike.
    p = make(env)
    from ttp import db as dbmod
    from ttp import globalcap as gcap
    now = time.time()
    p.db.spend("claude", 1.0, "task:1", account="acct-a", estimated=True)
    p.db.spend("claude", 2.0, "task:2", account="acct-a")
    _other_project(tmp_path, "other").spend("claude", 4.0, "task:1", account="acct-a")
    gcap._LOCAL.clear()
    rule = dbmod.counted_spend
    monkeypatch.setattr(dbmod, "counted_spend", lambda *a, **k: (lambda w: (w[0] + " AND estimated=0", w[1]))(rule(*a, **k)))
    assert p.db.spent_since(now - 3600) == 2.0 and p.db.spent_since(now - 3600, billed=True) == 2.0
    assert gcap.total(p.db, "claude", now - 3600, now + 3600, now, account="acct-a")["usd"] == 6.0


def _overview_project(tmp_path, name, version, host="testhost"):
    """A small project folder (settings, harness runtime version, database) registered as `ttp list` shows it."""
    from ttp.db import DB
    from ttp.project import FOLDER, register
    base = tmp_path / name / FOLDER
    (base / "harness" / "runtime" / "ttp").mkdir(parents=True)
    (base / "harness" / "project.json").write_text(json.dumps({"name": name, "budget": {"daily_usd": 50}}))
    (base / "harness" / "runtime" / "ttp" / "__init__.py").write_text(f'__version__ = "{version}"\n')
    register(name, {"host": host, "dir": str(tmp_path / name)})
    return base, DB(base / "state" / "project.db")


def _tree(root):
    """Every file under root with its mtime and content hash. A live database's -shm is SQLite's
    shared memory, where every reader (any `ttp` command too) records its read mark: only its size."""
    import hashlib
    return {str(f): (f.stat().st_size,) if f.name.endswith("-shm") else
            (f.stat().st_mtime_ns, hashlib.sha256(f.read_bytes()).hexdigest())
            for f in sorted(root.rglob("*")) if f.is_file()}


def test_overview_lists_every_project_and_never_modifies_them(env, tmp_path, capsys):
    from ttp import project
    from ttp.cli import main
    lib = project.HOME_DIR / "lib" / "current" / "runtime" / "ttp"
    lib.mkdir(parents=True)
    (lib / "__init__.py").write_text('__version__ = "0.9.0"\n')
    now = time.time()
    # Stopped: no daemon has run.
    _, a = _overview_project(tmp_path, "alpha", "0.9.0")
    a.spend("claude", 3.0, "task:1", account="acct")
    a.close()
    # Lagging, with a running daemon (this process) that keeps its database open.
    bb, b = _overview_project(tmp_path, "beta", "0.8.1")
    b.set_kv("daemon", {"pid": os.getpid(), "host": "testhost", "started": now})
    (bb / "state" / "heartbeat").write_text(json.dumps({"pid": os.getpid()}))
    b.x("INSERT INTO runs(role,provider,started,status) VALUES('worker','claude',?,'running')", (now,))
    # An open ask and a blocked task; its daemon's process is up but its heartbeat is old.
    cb, c = _overview_project(tmp_path, "gamma", "0.9.0")
    # Only the task the open ask names waits on the user; one held by the coordinator does not count.
    cid = c.add_task("needs a credential", "", kind="code")
    c.add_task("needs a workspace fix", "", kind="code")
    c.x("UPDATE tasks SET status='blocked', blocked_reason='workspace: worktree add failed'")
    c.post("out", f"Merge it? (#{cid})", kind="ask")
    c.set_kv("daemon", {"pid": os.getpid(), "host": "testhost", "started": now})
    hb = cb / "state" / "heartbeat"
    hb.write_text(json.dumps({"pid": os.getpid()}))
    os.utime(hb, (now - 3600, now - 3600))
    c.close()
    project.register("delta", {"host": "otherhost", "dir": "/srv/delta"})
    before = _tree(tmp_path / "alpha"), _tree(tmp_path / "beta"), _tree(tmp_path / "gamma")
    capsys.readouterr()
    main(["overview"])
    out = capsys.readouterr().out.splitlines()
    lines = {x.split("\t")[0]: x for x in out}
    assert "daemon stopped" in lines["alpha"] and "v0.9.0 ·" in lines["alpha"], out
    assert "today $3.00 of $50 cap" not in lines["alpha"] and "24h $3.00 of $50 cap" in lines["alpha"], out
    assert "daemon running" in lines["beta"] and "v0.8.1 (behind installed 0.9.0)" in lines["beta"], out
    assert "1 running" in lines["beta"] and "0 open asks" in lines["beta"], out
    assert "daemon stale (no tick for 60 min)" in lines["gamma"], out
    assert "1 open ask ·" in lines["gamma"] and "1 waiting on you" in lines["gamma"], out
    assert "remote, not checked" in lines["delta"], out
    assert out[-1].startswith("global daily cap $200 per 24h: claude $3.00 billed by this machine's 3 projects"), out
    main(["list", "--status"])
    assert capsys.readouterr().out.splitlines() == out
    # Nothing in the other projects was written, created or touched.
    after = _tree(tmp_path / "alpha"), _tree(tmp_path / "beta"), _tree(tmp_path / "gamma")
    assert [{k: (x.get(k), y.get(k)) for k in x.keys() | y.keys() if x.get(k) != y.get(k)} for x, y in zip(before, after)] == [{}] * 3
    b.close()


def test_overview_reads_ten_projects_in_under_two_seconds(env, tmp_path):
    from ttp import overview
    for i in range(10):
        _, db = _overview_project(tmp_path, f"proj{i}", "0.9.0")
        db.spend("claude", 1.0, "task:1")
        db.post("out", "Ship it?", kind="ask")
        db.close()
    t0 = time.monotonic()
    ov = overview.overview()
    assert time.monotonic() - t0 < 2.0
    assert len(ov["projects"]) == 10 and all(r["ok"] and r["asks"] == 1 for r in ov["projects"])


def test_web_api_overview_serves_the_projects_tab(env, tmp_path):
    from ttp import web
    p = make(env)
    _overview_project(tmp_path, "other", "0.9.0")[1].close()
    from ttp.project import register
    register("linked", {"host": "otherhost", "dir": "/srv/linked", "url": "https://example.invalid/linked"})
    port = _start_web(p)
    req = urllib.request.Request(f"http://127.0.0.1:{port}/api/overview", headers={"X-TTP-Token": web.token(p)})
