def test_a_drifting_price_table_raises_a_low_alert(env, monkeypatch):
    p = make(env)
    from ttp import localspend as ls
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    sent, asked = [], []
    monkeypatch.setattr(d, "alert", lambda key, text, severity="high", every_s=0: sent.append((key, severity)))
    monkeypatch.setattr(ls, "calibrate", lambda sid, usd: asked.append(sid) or 0.02)
    usage = types.SimpleNamespace(estimated=False, cost_usd=1.0, session_id="s1")
    d.cfg["budget"]["global_daily_usd"] = 0
    d._check_price_table({"provider": "claude"}, usage)
    assert asked == [] and sent == [], "checked without a global cap"
    d.cfg["budget"]["global_daily_usd"] = 100
    d._check_price_table({"provider": "fake"}, usage)
    d._check_price_table({"provider": "claude"}, types.SimpleNamespace(estimated=True, cost_usd=1.0, session_id="s1"))
    assert asked == []
    d._check_price_table({"provider": "claude"}, usage)
    assert asked == ["s1"] and sent == [("claude_price_table", "low")]
    monkeypatch.setattr(ls, "calibrate", lambda sid, usd: 0.005)
    d._check_price_table({"provider": "claude"}, usage)
    assert len(sent) == 1
    asked.clear()
    d._check_price_table({"provider": "claude", "note": json.dumps({"resumes": {"run": 1, "session": "s1"}})}, usage)
    assert asked == [], "a resumed run's log also holds the run it resumed"
    monkeypatch.setattr(ls, "calibrate", lambda sid, usd: asked.append(sid) or 0.005)
    d.gates = {"claude": types.SimpleNamespace(regime="windows")}
    d._check_price_table({"provider": "claude"}, usage)
    assert asked == [], "a plan run never counts toward the global cap"
    d.gates = {"claude": types.SimpleNamespace(regime="caps")}
    d._check_price_table({"provider": "claude"}, usage)
    assert asked == ["s1"]


@pytest.mark.parametrize("regimes,runs", [({"claude": "windows"}, False), ({"claude": "caps"}, True),
                                          ({"claude": "windows", "codex": "caps"}, True)])
def test_global_cap_background_work_runs_only_with_a_usage_billed_provider(env, monkeypatch, regimes, runs):
    """The global cap applies only to providers billed by usage: a project whose providers are all on
    plan windows asks no other machines and scans no local sessions, even with the cap on."""
    p = make(env)
    from ttp import budget as bud, globalcap as gcap, localspend as ls
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.cfg["budget"]["global_daily_usd"] = 200
    d.cfg["core_provider"] = "claude"
    if "codex" in regimes:
        p.db.add_task("other", "on codex", kind="work", tier="light", origin="user", provider="codex")
    real = bud.evaluate
    monkeypatch.setattr(bud, "evaluate", lambda db, cfg, prov, *a, **k: setattr(
        g := real(db, cfg, prov, *a, **k), "regime", regimes[prov]) or g)
    started = []
    monkeypatch.setattr(gcap, "refresh_async", lambda b, *a: started.append("refresh"))
    monkeypatch.setattr(ls, "scan_async", lambda b, *a: started.append("scan"))
    d.update_gates()
    assert set(d.gates) == set(regimes)
    assert started == (["refresh", "scan"] if runs else []), started


# Device-aware scheduling: fair `ttp lock` queue, device lock aliases, --probe, nested locks,
# `ttp detach` hand-offs and needs_device admission.
DEVICE_CFG = {"locks": ["device-a", "device-b"], "max_tasks": 2}


def _device_project(env, device=True):
    p = make(env)
    if device:
        p.set_config("device", DEVICE_CFG)
    return p


def _ttp_run(p, *args, env=None, cwd=None, timeout=30):
    e = {**os.environ, "TTP_PROJECT": str(p.base), **(env or {})}
    for var in ("TTP_RUN_DIR", "TTP_LOCKS_HELD", "TTP_DETACHED"):
        if var not in (env or {}):
            e.pop(var, None)
    return subprocess.run([sys.executable, str(TTP), *args], env=e, cwd=cwd or str(p.root),
                          capture_output=True, text=True, timeout=timeout)


def test_device_names_share_one_lock():
    sys.path.insert(0, str(RUNTIME))
    from ttp import locks as lk
    cfg = {"device": DEVICE_CFG}
    assert lk.canonical(cfg, "device-b") == "device-a" and lk.canonical(cfg, "device-a") == "device-a"
    assert lk.canonical(cfg, "builddir") == "builddir"
    assert lk.canonical({}, "device-b") == "device-b", "no device config: every name is its own lock"


def test_lock_queue_is_first_come_first_served(env, tmp_path):
    from ttp import locks as lk
    first = lk.enqueue(tmp_path, "r", "a")
    second = lk.enqueue(tmp_path, "r", "b")
    paths = lk.slot_paths(tmp_path, "r", 1)
    assert lk.take_in_turn(tmp_path, "r", second, paths, "b") is None   # not its turn, though free
    f = lk.take_in_turn(tmp_path, "r", first, paths, "a")
    assert f is not None
    lk.dequeue(first)
    assert lk.take_in_turn(tmp_path, "r", second, paths, "b") is None   # its turn, but held
    f.close()
    g = lk.take_in_turn(tmp_path, "r", second, paths, "b")
    assert g is not None
    g.close()
    lk.dequeue(second)


def test_lock_queue_gives_one_freed_slot_to_the_first_waiter(env, tmp_path):
    from ttp import locks as lk
    # Two slots, both held, two waiters; one slot frees. Only the first waiter may take it: a check
    # against the slot count (index < len(paths)) would let the second one jump the queue.
    paths = lk.slot_paths(tmp_path, "r", 2)
    h1 = lk.try_take(paths, "h1")
    h2 = lk.try_take(paths, "h2")
    assert h1 is not None and h2 is not None
    first = lk.enqueue(tmp_path, "r", "a")
    second = lk.enqueue(tmp_path, "r", "b")
    h1.close()
    assert lk.take_in_turn(tmp_path, "r", second, paths, "b") is None, "the first waiter is still waiting"
    f = lk.take_in_turn(tmp_path, "r", first, paths, "a")
    assert f is not None, "the first waiter gets the freed slot"
    lk.dequeue(first)
    assert lk.take_in_turn(tmp_path, "r", second, paths, "b") is None   # its turn, but none free
    f.close()
    h2.close()
    lk.dequeue(second)


def test_lock_queue_drops_a_dead_waiter_and_keeps_fifo_order(env, tmp_path):
    from ttp import locks as lk
    # A waiter that died (killed, or the host restarted) leaves its ticket file behind, unlocked.
    gone = subprocess.run([sys.executable, "-c", "import sys; sys.path.insert(0, sys.argv[1]); "
                           "from ttp import locks; print(locks.enqueue(sys.argv[2], 'r', 'gone'))",
                           str(RUNTIME), str(tmp_path)], capture_output=True, text=True, check=True)
    dead = pathlib.Path(gone.stdout.strip())
    assert dead.exists()
    mine = lk.enqueue(tmp_path, "r", "me")
    later = lk.enqueue(tmp_path, "r", "later")
    assert lk.queued(tmp_path, "r") == [mine, later]
    assert not dead.exists(), "the dead waiter's ticket is removed"
    paths = lk.slot_paths(tmp_path, "r", 1)
    assert lk.take_in_turn(tmp_path, "r", later, paths, "later") is None, "a later arrival waits its turn"
    f = lk.take_in_turn(tmp_path, "r", mine, paths, "me")
    assert f is not None, "the dead waiter ahead does not block the queue"
    f.close()
    lk.dequeue(mine)
    lk.dequeue(later)
    assert lk.queued(tmp_path, "r") == []


def test_lock_queue_ticket_stays_live_whatever_its_pid(env, tmp_path):
    from ttp import locks as lk
    # Liveness is the ticket's lock, not its pid: a ticket of this process named after a dead pid
    # (as after a reboot reused it) is still judged by whether its lock is held.
    holder = subprocess.Popen([sys.executable, "-c", "import sys, time; sys.path.insert(0, sys.argv[1]); "
                               "from ttp import locks; print(locks.enqueue(sys.argv[2], 'r', 'w'), flush=True); "
                               "time.sleep(60)", str(RUNTIME), str(tmp_path)], stdout=subprocess.PIPE, text=True)
    try:
        ticket = pathlib.Path(holder.stdout.readline().strip())
        assert lk.queued(tmp_path, "r") == [ticket]
    finally:
        holder.kill()
        holder.wait()
    assert lk.queued(tmp_path, "r") == []


def test_waited_counts_overlaps_once(env, tmp_path):
    from ttp import locks as lk
    lk.record_wait(tmp_path, "1", 100, 160)
    lk.record_wait(tmp_path, "2", 150, 200)
    lk.record_wait(tmp_path, "3", 300, 310)
    assert lk.waited(tmp_path, now=1000) == pytest.approx(110)


