    (run_dir / "run.json").write_text(json.dumps({"stall_s": 8}))
    held = lk.try_take(lk.slot_paths(p.state / "locks", "device-a", 1), "someone")
    t0 = time.time()
    r = _ttp_run(p, "lock", "--timeout", "2400", "device-b", "--", "true", env={"TTP_RUN_DIR": str(run_dir)})
