    proc = subprocess.Popen([sys.executable, str(TTP), "lock", "device-a", "--", "true"],
                            env={**os.environ, "TTP_PROJECT": str(p.base), "TTP_RUN_DIR": str(run_dir),
                                 "TTP_DETACHED": "1"})
