def test_in_run_lock_cap_holds_under_the_runs_agent_and_lifts_in_a_background_driver(env, tmp_path):
    p = _device_project(env)
    from ttp import locks as lk
    run_dir = p.runs / "9"
    run_dir.mkdir(parents=True)
    (run_dir / "run.json").write_text(json.dumps({"stall_s": 2}))
    (run_dir / "child.pid").write_text(f"{os.getpid()}\n")   # this test stands in for the run's agent
    held = lk.try_take(lk.slot_paths(p.state / "locks", "device-a", 1), "someone")
    try:
        r = _ttp_run(p, "lock", "device-b", "--", "true", env={"TTP_RUN_DIR": str(run_dir)})
        assert r.returncode == 75, "a lock under the run's agent keeps the cap"
        # A driver started with `nohup ... &` from the run (no `setsid`: macOS has none): its shell
        # exits, so it is re-parented.
        rc = tmp_path / "driver.rc"
        e = {**os.environ, "TTP_PROJECT": str(p.base), "TTP_RUN_DIR": str(run_dir), "TTP": str(TTP),
             "PY": sys.executable, "RC": str(rc)}
        e.pop("TTP_DETACHED", None)
        e.pop("TTP_LOCKS_HELD", None)
        shell = subprocess.Popen(["sh", "-c", 'nohup sh -c \'"$PY" "$TTP" lock device-b -- true; '
                                              'echo $? > "$RC"\' > /dev/null 2>&1 &'], env=e)
        assert shell.wait(timeout=10) == 0
        (run_dir / "child.pid").write_text(f"{shell.pid}\n")
        time.sleep(3)
        assert not rc.exists(), "the driver waits past half the run's stall limit"
    finally:
        held.close()
    _wait_for_path(rc, timeout=30)
    assert rc.read_text().strip() == "0"

def _wait_for_path(path, timeout=20):
    deadline = time.time() + timeout
    while time.time() < deadline and not path.exists():
        time.sleep(0.05)
    return path.exists()


def test_detach_needs_no_setsid_binary_and_gives_the_job_its_own_session(env, tmp_path):
    p = _device_project(env, device=False)
    run_dir = p.runs / "8"
    run_dir.mkdir(parents=True)
    # Only what the job's wrapper needs is on PATH; no `setsid`, as on macOS.
    bin_dir = tmp_path / "bin"
    bin_dir.mkdir()
    for tool in ("sh", "mv"):
        (bin_dir / tool).symlink_to(shutil.which(tool))
    out = tmp_path / "ids"
    probe = f"import os; open({str(out)!r}, 'w').write(f'{{os.getsid(0)}} {{os.getpgrp()}}')"
    r = _ttp_run(p, "detach", "job1", "--", sys.executable, "-c", probe,
                 env={"TTP_RUN_DIR": str(run_dir), "PATH": str(bin_dir)})
    assert r.returncode == 0, r.stderr
    rc = run_dir / "job1.rc"
    assert _wait_for_path(rc)
    assert rc.read_text().strip() == "0"
    leader = json.loads((run_dir / "detached.json").read_text())[0]["pid"]
    sid, pgrp = map(int, out.read_text().split())
    assert sid == pgrp == leader and sid != os.getsid(0), "the job leads a session of its own"


def test_detach_writes_rc_log_and_a_durable_registry(env):
    p = _device_project(env, device=False)
    run_dir = p.runs / "8"
    run_dir.mkdir(parents=True)
    r = _ttp_run(p, "detach", "job1", "--", "sh", "-c", "echo hi; exit 3", env={"TTP_RUN_DIR": str(run_dir)})
    assert r.returncode == 0, r.stderr
    rc = run_dir / "job1.rc"
    assert _wait_for_path(rc)
    assert rc.read_text().strip() == "3"
    assert (run_dir / "job1.log").read_text().strip() == "hi"
    jobs = json.loads((run_dir / "detached.json").read_text())
    assert jobs[0]["name"] == "job1" and jobs[0]["rc"] == str(rc.resolve())
    assert "detach --check" in r.stdout
    check = _ttp_run(p, "detach", "--check", str(rc))
    assert check.returncode == 4 and "job1: job finished rc=3" in check.stdout, "a failed job is no pass"
    again = _ttp_run(p, "detach", "job1", "--", "true", env={"TTP_RUN_DIR": str(run_dir)})
    assert again.returncode != 0, "a name is used once per run"


def test_a_detached_job_keeps_its_own_temp_dir_after_its_run_ends_and_it_goes_when_the_job_ends(env, tmp_path):
    """The reported failure: a fenced run's TMPDIR is its run's tmp dir, removed when the run ends,
    while its detached build still runs (a compiler lost its scratch partway through). The job gets
    a temp dir of its own, recorded under the project's state, kept until the job ends, then removed.
    A short one (shorttmp), so a socket a test binds beneath it stays within the AF_UNIX path limit."""
    from ttp import detach, runner, shorttmp
    p = _device_project(env, device=False)
    run_dir = p.runs / "8"
    (run_dir / "tmp").mkdir(parents=True)
    go, seen = tmp_path / "go", tmp_path / "seen"
    script = (f'while [ ! -e {go} ]; do sleep 0.05; done; echo "$TMPDIR $TMP $TEMP" >{seen}; '
              'echo scratch >"$TMPDIR/x.s" && cat "$TMPDIR/x.s"')
    tmp_env = {var: str(run_dir / "tmp") for var in ("TMPDIR", "TMP", "TEMP")}
    r = _ttp_run(p, "detach", "build", "--", "sh", "-c", script, env={"TTP_RUN_DIR": str(run_dir), **tmp_env})
    assert r.returncode == 0, r.stderr
    rc = run_dir / "build.rc"
    own = detach.scratch(rc)
    assert own.parent == p.state / detach.SCRATCH and own.is_dir()
    tmp = detach.tmp_dir(own)
    assert shorttmp.owned(tmp) and tmp.is_dir()
    runner.remove_tmp(run_dir, {"tmp_dir": str(run_dir / "tmp")})   # the run that started it ends
    assert not (run_dir / "tmp").exists()
    detach.tend(p)   # the sweep leaves a running job's dir alone
    assert own.is_dir()
    go.touch()
    assert _wait_for_path(rc)
    assert rc.read_text().strip() == "0", (run_dir / "build.log").read_text()
    assert seen.read_text().split() == [str(tmp)] * 3
    assert (run_dir / "build.log").read_text().strip() == "scratch"
    assert not own.exists() and not tmp.exists(), "removed once the job ended"


def test_the_daemon_sweeps_the_temp_dir_of_a_detached_job_killed_before_it_could_remove_it(env):
    from ttp import detach
    p = _device_project(env, device=False)
    run_dir = p.runs / "9"
    run_dir.mkdir(parents=True)
    r = _ttp_run(p, "detach", "long", "--", "sh", "-c", 'touch "$TMPDIR/in"; sleep 60',
                 env={"TTP_RUN_DIR": str(run_dir)})
    assert r.returncode == 0, r.stderr
    own = detach.scratch(run_dir / "long.rc")
    assert _wait_for_path(own / "path")
    tmp = detach.tmp_dir(own)
    assert _wait_for_path(tmp / "in")
    stray = p.state / detach.SCRATCH / "not-a-job"
    stray.mkdir()
    detach.sweep(p.state)
    assert own.is_dir() and stray.is_dir(), "a running job's dir, and what is not a job's, stay"
    pid = json.loads((run_dir / "detached.json").read_text())[0]["pid"]
    os.killpg(pid, signal.SIGKILL)
    assert _check_until_ended(p, run_dir / "long.rc").returncode == 4
    detach.tend(p)
    assert not own.exists() and not tmp.exists() and stray.is_dir()


def test_a_detached_job_gets_a_short_temp_dir_that_holds_a_unix_socket(env):
    from ttp import detach, shorttmp
    p = _device_project(env, device=False)
    run_dir = p.runs / "7"
    run_dir.mkdir(parents=True)
    code = ("import os, socket; t = os.environ['TMPDIR']; "
            "d = os.path.join(t, 'pytest-of-x', 'pytest-0', 'test_some_long_name0'); os.makedirs(d); "
            "socket.socket(socket.AF_UNIX).bind(os.path.join(d, 's.sock')); print(t)")
    r = _ttp_run(p, "detach", "sock", "--", sys.executable, "-c", code, env={"TTP_RUN_DIR": str(run_dir)})
    assert r.returncode == 0, r.stderr
    rc = run_dir / "sock.rc"
    assert _wait_for_path(rc)
    assert rc.read_text().strip() == "0", (run_dir / "sock.log").read_text()
    tmp = (run_dir / "sock.log").read_text().strip()
    assert shorttmp.owned(tmp), tmp
    assert not pathlib.Path(tmp).exists() and not detach.scratch(rc).exists(), "removed once the job ended"


def test_detach_check_waits_while_running_and_wakes_when_the_job_dies(env):
    p = _device_project(env, device=False)
    run_dir = p.runs / "9"
    run_dir.mkdir(parents=True)
    started = run_dir / "started"
    r = _ttp_run(p, "detach", "long", "--", "sh", "-c", f"touch {started}; sleep 60",
                 env={"TTP_RUN_DIR": str(run_dir)})
    assert r.returncode == 0, r.stderr
    assert _wait_for_path(started)
    rc = run_dir / "long.rc"
    check = _ttp_run(p, "detach", "--check", str(rc))
    assert check.returncode == 1 and "running" in check.stdout
    # Killed (or the host restarted): no .rc is ever written, and the check still ends the wait.
    pid = json.loads((run_dir / "detached.json").read_text())[0]["pid"]
    os.killpg(pid, signal.SIGKILL)
    deadline = time.time() + 20
    while time.time() < deadline and _ttp_run(p, "detach", "--check", str(rc)).returncode == 1:
        time.sleep(0.1)
    check = _ttp_run(p, "detach", "--check", str(rc))
    assert check.returncode == 4 and "gone without an exit code" in check.stdout
    assert not rc.exists()


def _check_until_ended(p, rc, timeout=None):
    deadline = time.time() + (timeout or _load_scaled(60))
    while time.time() < deadline and _ttp_run(p, "detach", "--check", str(rc)).returncode == 1:
        time.sleep(0.1)
    return _ttp_run(p, "detach", "--check", str(rc))


@pytest.mark.parametrize("box", ["pidns", "cgroup"])
def test_detach_from_a_sandboxed_command_is_queued_and_the_daemon_starts_it(env, box):
    """A command in a PID namespace or cgroup other than its run's may take everything it started
    along when it ends: the job is queued, reads as waiting, and the daemon starts it."""
    from ttp import detach, locks, push
    if not (push.pid_ns() if box == "pidns" else push.cgroup()):
        pytest.skip("no /proc")
    p = _device_project(env, device=False)
    run_dir = p.runs / "8"
    run_dir.mkdir(parents=True)
    other = {"TTP_PIDNS": "pid:[1]"} if box == "pidns" else {"TTP_CGROUP": "0::/elsewhere"}
    r = _ttp_run(p, "detach", "job1", "--", "sh", "-c", 'echo "hi $JOB_VAR"; exit 3',
                 env={"TTP_RUN_DIR": str(run_dir), "JOB_VAR": "there", "SOME_API_TOKEN": "s3cret", **other})
    assert r.returncode == 0 and "queued" in r.stdout, r
    rc = run_dir / "job1.rc"
    queue = list((p.state / detach.QUEUE).glob("*.json"))
    assert len(queue) == 1 and "s3cret" not in queue[0].read_text(), "secrets stay off disk"
    assert json.loads((run_dir / "detached.json").read_text())[0]["pid"] is None
    check = _ttp_run(p, "detach", "--check", str(rc))
    assert check.returncode == 1 and "queued for the daemon" in check.stdout, check
    assert not locks.job_ended(rc), "an exclusive task's resources stay held while its job waits"
    detach.tend(p)
    assert not list((p.state / detach.QUEUE).glob("*.json")) and not detach.queued(rc).exists()
    check = _check_until_ended(p, rc)
    assert check.returncode == 4 and "rc=3" in check.stdout, check
    assert (run_dir / "job1.log").read_text().strip() == "hi there"


def test_detach_inside_a_pid_namespace_that_ends_with_the_command_still_runs_the_job(env, tmp_path):
    """The reported failure, reproduced: a namespace that ends with the command kills what it started,
    so a job started in it never wrote a line. Queued, the daemon runs it to its exit code."""
    from ttp import detach, push
    unshare = shutil.which("unshare")
    if not (unshare and push.pid_ns()):
        pytest.skip("no unshare or /proc")
    box = [unshare, "--user", "--pid", "--fork", "--map-root-user", "--mount-proc"]
    if subprocess.run([*box, "true"], capture_output=True).returncode:
        pytest.skip("unprivileged PID namespaces are not allowed here")
    p = _device_project(env, device=False)
    run_dir = p.runs / "8"
    run_dir.mkdir(parents=True)
    e = {**os.environ, "TTP_PROJECT": str(p.base), "TTP_RUN_DIR": str(run_dir), "TTP_PIDNS": push.pid_ns()}
    # bare: as before, no run namespace to compare. Its job outlives a slow exit of `ttp detach` under
    # load, so only the namespace's end stops it.
    for name, pidns, nap in (("bare", "", 300), ("job", push.pid_ns(), 1)):
        r = subprocess.run([*box, sys.executable, str(TTP), "detach", name, "--", "sh", "-c", f"sleep {nap}; echo done; exit 5"],
                           env={**e, "TTP_PIDNS": pidns}, cwd=str(p.root), capture_output=True, text=True, timeout=240)   # ttp startup alone took >30 s at host load 187
        assert r.returncode == 0, r
    bare = _check_until_ended(p, run_dir / "bare.rc")
    assert "gone without an exit code (it " in bare.stdout and (run_dir / "bare.lost").exists(), bare
    assert _ttp_run(p, "detach", "--check", str(run_dir / "job.rc")).returncode == 1
    detach.tend(p)
    check = _check_until_ended(p, run_dir / "job.rc")
    assert check.returncode == 4 and "rc=5" in check.stdout, check
    assert (run_dir / "job.log").read_text().strip() == "done"


def test_a_detached_job_gone_without_an_exit_code_says_why(env, monkeypatch):
    from ttp import detach, locks
    p = _device_project(env, device=False)
    run_dir = p.runs / "8"
    run_dir.mkdir(parents=True)
    from ttp.runner import boot_id
    jobs = [{"name": n, "rc": str(run_dir / f"{n}.rc"), "log": str(run_dir / f"{n}.log"), "boot": b}
            for n, b in (("never", boot_id()), ("killed", boot_id()), ("reboot", "an-earlier-boot"))]
    (run_dir / "detached.json").write_text(json.dumps(jobs))
    detach.started(run_dir / "killed.rc").write_text("123\n")
    assert detach.state(run_dir / "never.rc") == ("lost", detach.lost(run_dir / "never.rc").read_text().strip())
    assert "never started" in detach.state(run_dir / "never.rc")[1]
    assert "killed after it started" in detach.state(run_dir / "killed.rc")[1]
    assert "host restarted" in detach.state(run_dir / "reboot.rc")[1]
    assert all(locks.job_ended(run_dir / f"{n}.rc") for n in ("never", "killed", "reboot"))
    # A job the daemon did not start in time is recorded as lost, never started late.
    monkeypatch.setenv("TTP_PIDNS", "pid:[1]")
    if not __import__("ttp.push", fromlist=["x"]).pid_ns():
        return
    r = _ttp_run(p, "detach", "late", "--", "true", env={"TTP_RUN_DIR": str(run_dir), "TTP_PIDNS": "pid:[1]"})
    assert r.returncode == 0 and "queued" in r.stdout, r
    q = next((p.state / detach.QUEUE).glob("*.json"))
    m = json.loads(q.read_text())
    m["queued"] -= detach.QUEUED_S + 60
    q.write_text(json.dumps(m))
    detach.tend(p)
    check = _ttp_run(p, "detach", "--check", str(run_dir / "late.rc"))
    assert check.returncode == 4 and "did not start it" in check.stdout, check
    assert not (run_dir / "late.log").exists() and not q.exists()


def _ssh_stub(tmp_path):
    """A local `ssh` on PATH: drops the options and the host and runs the remote command here, or
    fails like an unreachable host (exit 255) while $SSH_STUB_FAIL is set. No real host is used."""
    bin_dir = tmp_path / "sshbin"
    bin_dir.mkdir()
    (bin_dir / "ssh").write_text(
        "#!/bin/sh\n"
        "while [ $# -gt 0 ]; do case $1 in -o) shift 2;; -*) shift;; *) break;; esac; done\n"
        "host=$1; shift\n"
        "echo \"$host\" >>\"$SSH_STUB_LOG\"\n"
        "[ -n \"$SSH_STUB_FAIL\" ] && { echo \"ssh: connect to host $host: Connection refused\" >&2; exit 255; }\n"
        "exec sh -c \"$*\"\n")
    (bin_dir / "ssh").chmod(0o755)
    if not shutil.which("setsid"):   # macOS: the stub's "remote" is this host; a pass-through stands in
        (bin_dir / "setsid").write_text("#!/bin/sh\nexec \"$@\"\n")
        (bin_dir / "setsid").chmod(0o755)
    return {"PATH": f"{bin_dir}{os.pathsep}{os.environ['PATH']}", "SSH_STUB_LOG": str(tmp_path / "ssh.log"),
            "HOME": str(tmp_path / "home")}


def _kill_driver(pid):
    """Stop a stub-remote driver and its job: its whole group when setsid gave it one of its own."""
    try:
        os.killpg(pid, signal.SIGKILL) if os.getpgid(pid) == pid else os.kill(pid, signal.SIGKILL)
    except ProcessLookupError:
        pass


def _remote_probe(out):
    m = re.search(r'retry_when "(.*)"', out)
    assert m, out
    return shlex.split(m.group(1))


def test_detach_remote_runs_the_driver_over_ssh_and_its_check_reports_running_then_the_exit(env, tmp_path):
    p = _device_project(env, device=False)
    run_dir = p.runs / "21"
    run_dir.mkdir(parents=True)
    e = {**_ssh_stub(tmp_path), "TTP_RUN_DIR": str(run_dir)}
    go = tmp_path / "go"
    r = _ttp_run(p, "detach", "--remote", "box-a", "drv", "--", "sh", "-c",
                 f"echo hi; while [ ! -e {go} ]; do sleep 0.1; done; exit 3", env=e)
    assert r.returncode == 0, r.stderr
    remote = tmp_path / "home" / ".ttp-detach" / "21"   # the default folder, under the remote home
    for ext in ("pid", "boot", "start"):
        assert (remote / f"drv.{ext}").exists(), ext
    assert (remote / "drv.start").read_text().split()[0].isdigit()
    probe = _remote_probe(r.stdout)
    assert probe[1:] == ["detach", "--check", "--host", "box-a", str(remote / "drv")], probe
    assert "survives_reboot true" in r.stdout
    check = _ttp_run(p, *probe[1:], env=e)
    assert check.returncode == 1 and "running" in check.stdout, check.stdout
    assert not (run_dir / "detached.json").exists(), "the local job registry holds local jobs only"
    go.touch()
    assert _wait_for_path(remote / "drv.rc")
    check = _ttp_run(p, *probe[1:], env=e)
    assert check.returncode == 4 and "drv: job finished rc=3" in check.stdout, check.stdout
    assert (remote / "drv.log").read_text().strip() == "hi"
    assert set((tmp_path / "ssh.log").read_text().split()) == {"box-a"}
    again = _ttp_run(p, "detach", "--remote", "box-a", "drv", "--", "true", env=e)
    assert again.returncode != 0 and "already ran" in again.stderr + again.stdout


def test_detach_remote_check_sees_a_dead_pid_or_a_new_boot_as_gone_and_ssh_failure_as_255(env, tmp_path):
    p = _device_project(env, device=False)
    e = _ssh_stub(tmp_path)
    rdir = tmp_path / "remote"
    r = _ttp_run(p, "detach", "--remote", "box-b", "--dir", str(rdir), "long", "--", "sleep", "60", env=e)
    assert r.returncode == 0, r.stderr
    probe = _remote_probe(r.stdout)
    assert probe[-1] == str(rdir / "long")
    pid = int((rdir / "long.pid").read_text())
    try:
        assert _ttp_run(p, *probe[1:], env=e).returncode == 1
        # ssh failing keeps the task asleep (255), never reads as the driver being gone.
        down = _ttp_run(p, *probe[1:], env={**e, "SSH_STUB_FAIL": "1"})
        assert down.returncode == 255 and "ssh to box-b failed" in down.stdout, down.stdout
        assert _ttp_run(p, "detach", "--remote", "box-b", "--dir", str(rdir), "x", "--", "true",
                        env={**e, "SSH_STUB_FAIL": "1"}).returncode == 255
        # The host restarted: its boot_id changed, so the driver is gone even if a process holds its pid.
        boot = (rdir / "long.boot").read_text()
        assert boot.strip(), "the boot is recorded (boot_id, or kern.boottime without /proc)"
        (rdir / "long.boot").write_text("another-boot\n")
        gone = _ttp_run(p, *probe[1:], env=e)
        assert gone.returncode == 4 and "gone without an exit code" in gone.stdout, gone.stdout
        (rdir / "long.boot").write_text(boot)
        assert _ttp_run(p, *probe[1:], env=e).returncode == 1
    finally:
        _kill_driver(pid)
    # Killed: no .rc is ever written, and the check still ends the wait with 'gone', not a missing marker.
    deadline = time.time() + 20
    while time.time() < deadline and _ttp_run(p, *probe[1:], env=e).returncode == 1:
        time.sleep(0.1)
    gone = _ttp_run(p, *probe[1:], env=e)
    assert gone.returncode == 4 and "gone without an exit code (killed, or the host restarted)" in gone.stdout
    assert not (rdir / "long.rc").exists()
    # A pid now taken by another process (its start differs) is gone too.
    (rdir / "long.pid").write_text(f"{os.getpid()}\n")
    assert _ttp_run(p, *probe[1:], env=e).returncode == 4
    # Several jobs on one host: still waiting while any one runs; a path with .rc reads the same.
    r2 = _ttp_run(p, "detach", "--remote", "box-b", "--dir", str(rdir), "two", "--", "sleep", "60", env=e)
    pid2 = int((rdir / "two.pid").read_text())
    try:
        both = _ttp_run(p, "detach", "--check", "--host", "box-b", str(rdir / "long.rc"), str(rdir / "two"), env=e)
        assert both.returncode == 1 and "long: gone" in both.stdout and "two: running" in both.stdout, both.stdout
    finally:
        _kill_driver(pid2)
    assert r2.returncode == 0


def test_detach_remote_scripts_tell_a_reused_pid_and_a_reboot_without_proc(env, tmp_path):
    """A host without /proc (macOS): the driver's start comes from ps's lstart and the boot from
    kern.boottime, so a pid taken by another process or a restarted host never reads as running.
    Simulated here: /proc is pointed at a missing folder and a fake sysctl stands in."""
    from ttp import cli
    noproc, fake = str(tmp_path / "noproc") + "/", tmp_path / "fakebin"
    fake.mkdir()
    booted = tmp_path / "booted"
    booted.write_text("1700000000")
    _fake_sysctl(fake, booted, tmp_path / "uuid")
    start, check = (x.replace("/proc/", noproc) for x in (cli._REMOTE_START, cli._REMOTE_CHECK))
    assert "/proc/" not in start + check
    e = {**os.environ, "PATH": f"{fake}{os.pathsep}{os.environ['PATH']}"}
    if not shutil.which("setsid"):
        (fake / "setsid").write_text("#!/bin/sh\nexec \"$@\"\n")
        (fake / "setsid").chmod(0o755)
    rdir = tmp_path / "remote"

    def sh(script, *args):
        return subprocess.run(["sh", "-c", script, "sh", *map(str, args)], env=e, capture_output=True, text=True,
                              timeout=30).stdout.strip()
    out = sh(start, rdir, "job", "sleep", "60")
    assert out.startswith("started "), out
    pid = int((rdir / "job.pid").read_text())
    try:
        assert (rdir / "job.boot").read_text().strip() == "1700000000"
        assert (rdir / "job.start").read_text().split()[1:], "the start is recorded without /proc"
        assert sh(check, rdir / "job") == f"running {pid}"
        booted.write_text("1700099999")   # the host restarted
        assert sh(check, rdir / "job") == "boot"
        booted.write_text("1700000000")
        (rdir / "job.pid").write_text(f"{os.getpid()}\n")   # the pid now belongs to another process
        assert sh(check, rdir / "job") == "gone"
        (rdir / "job.pid").write_text(f"{pid}\n")
    finally:
        _kill_driver(pid)
    deadline = time.time() + 20
    while time.time() < deadline and sh(check, rdir / "job") != "gone":
        time.sleep(0.1)
    assert sh(check, rdir / "job") == "gone"
    # With kern.bootsessionuuid (macOS), the uuid is the boot: a stepped clock that moves kern.boottime is
    # no reboot, and a .boot an older version wrote with kern.boottime's seconds still names this boot.
    (tmp_path / "uuid").write_text("6A1C0E4B-0000-4000-8000-000000000001")
    out = sh(start, rdir, "job2", "sleep", "60")
    assert out.startswith("started "), out
    pid = int((rdir / "job2.pid").read_text())
    try:
        assert (rdir / "job2.boot").read_text().strip() == "6A1C0E4B-0000-4000-8000-000000000001"
        booted.write_text("1700000123")   # the calendar clock was stepped
        assert sh(check, rdir / "job2") == f"running {pid}"
        (rdir / "job2.boot").write_text("1700000123\n")   # recorded before the upgrade
        assert sh(check, rdir / "job2") == f"running {pid}"
        (rdir / "job2.boot").write_text("1699999999\n")   # an older boot's seconds
        assert sh(check, rdir / "job2") == "boot"
        (rdir / "job2.boot").write_text("6A1C0E4B-0000-4000-8000-000000000001\n")
        (tmp_path / "uuid").write_text("6A1C0E4B-0000-4000-8000-000000000002")   # the host restarted
        assert sh(check, rdir / "job2") == "boot"
    finally:
        _kill_driver(pid)


def _fake_sysctl(fake, booted, uuid):
    """A macOS-like `sysctl -n <key>`: kern.boottime from file `booted`, kern.bootsessionuuid from file
    `uuid` (an unknown key, as on older systems, while that file is missing)."""
    (fake / "sysctl").write_text(
        '#!/bin/sh\ncase $2 in\n'
        f'kern.boottime) echo "{{ sec = $(cat {booted}), usec = 4242 }} Tue Nov 14 22:13:20 2023" ;;\n'
        f'kern.bootsessionuuid) [ -e {uuid} ] || {{ echo "unknown oid" >&2; exit 1; }}; cat {uuid} ;;\n'
        '*) exit 1 ;;\nesac\n')
    (fake / "sysctl").chmod(0o755)


def test_macos_boot_id_prefers_bootsessionuuid_and_still_knows_the_boottime_seconds(env, tmp_path, monkeypatch):
    """kern.boottime moves when the clock is stepped, so the boot id is kern.bootsessionuuid where the host
    has it. A boot recorded by an older version as kern.boottime's seconds still reads as this boot, in the
    runner and the daemon, so an upgrade is never taken for a reboot."""
    from ttp import push, runner
    from ttp.daemon import Daemon
    p = make(env)
    fake, booted, uuid = tmp_path / "fakebin", tmp_path / "booted", tmp_path / "uuid"
    fake.mkdir()
    booted.write_text("1700000000")
    _fake_sysctl(fake, booted, uuid)
    monkeypatch.setenv("PATH", f"{fake}{os.pathsep}{os.environ['PATH']}")
    monkeypatch.setattr(runner, "BOOT_ID_FILE", tmp_path / "noproc" / "boot_id")
    # No uuid (an older macOS): kern.boottime's seconds, as before.
    assert runner.boot_id() == "1700000000" and runner.boot_ids() == ("1700000000", "1700000000")
    uuid.write_text("6A1C0E4B-0000-4000-8000-000000000001\n")
    assert runner.boot_id() == "6A1C0E4B-0000-4000-8000-000000000001"
    assert runner.boot_ids() == ("6A1C0E4B-0000-4000-8000-000000000001", "1700000000")
    assert runner.same_boot("1700000000") and runner.same_boot("6A1C0E4B-0000-4000-8000-000000000001")
    assert not runner.same_boot("1699999999") and not runner.same_boot("") and not runner.same_boot(None)
    assert "rebooted" not in push._dead_reason({"boot": "1700000000"})
    assert "rebooted" in push._dead_reason({"boot": "1699999999"})
    # A stepped clock moves kern.boottime but not the boot id.
    booted.write_text("1700000042")
    assert runner.boot_id() == "6A1C0E4B-0000-4000-8000-000000000001"
    # The daemon after an upgrade: a run, a pause until reboot and the last told boot recorded with the
    # seconds are this boot's; a run of an earlier boot is not.
    d = Daemon(p.base)
    assert d.boots == ("6A1C0E4B-0000-4000-8000-000000000001", "1700000042")
    assert d._this_boot("1700000042") and not d._this_boot("1700000000") and not d._this_boot(None)
    p.db.set_kv("paused", True)
    p.db.set_kv("pause_until_boot", {"boot": "1700000042", "since": time.time()})
    Daemon(p.base).tick()
    assert p.db.kv("paused"), "a pause until reboot recorded with the seconds is not lifted by an upgrade"


def _dev_task(p, labels=(), status="queued", title="t", spec=""):
    tid = p.db.add_task(title, spec, kind="code", tier="standard", priority=3, budget_usd=8.0, labels=list(labels))
    if status != "queued":
        p.db.update_task(tid, status=status)
    return p.db.task(tid)


