def test_devq_guard_accepts_function_keyword_handlers_and_tilde_netfs_prefixes(tmp_path, monkeypatch):
    from ttp import devq
    # `function name {` (no parens) is a handler too; the old pattern reported its trap missing.
    for defn in ("function stop { kill -- -$pg; }", "function stop() { kill -- -$pg; }", "stop() { kill -- -$pg; }"):
        assert devq._isolation_problem(f"{defn}\nsetsid x & pg=$!\ntrap stop EXIT TERM INT\n") == "", defn
    assert "a trap on EXIT" in devq._isolation_problem(
        "function stop { kill $pid; }\nsetsid x & pid=$!\ntrap stop EXIT TERM INT\n")
    # A '~' prefix (accepted by the config check) matches the expanded path it stands for.
    monkeypatch.setenv("HOME", str(tmp_path))
    resolved, pre = devq.resolve_local(os.path.expanduser("~/net/a"), ["~/net"])
    assert pre == f"{tmp_path}/net" and resolved == f"{tmp_path}/net/a"


# What a stuck task waits on (waits.wait_kind), and plain words for deferred probes -----------------

_BLOCK_REASONS = [
    ("dependency #7 failed", "coordinator", "waits on the coordinator: dependency #7 failed"),
    ("a dependency is not a task id", "coordinator", "waits on the coordinator: a dependency is not a task id"),
    ("task budget exhausted", "budget", "waits on budget: its task budget is used up"),
    ("its $5.00 budget is above the dollar cap", "budget", "waits on budget: its budget is above the dollar cap"),
    ("workspace: worktree add failed", "coordinator", "waits on the coordinator: a workspace fix: worktree add failed"),
    ("lost to a host reboot 3 times; it may be causing them", "coordinator",
     "waits on the coordinator: lost to a host reboot 3 times; it may be causing them"),
    ("push refused: the branch is protected", "coordinator", "waits on the coordinator: push refused: the branch is protected"),
    ("Which of the two layouts should the cache use?", "coordinator",
     "waits on the coordinator: Which of the two layouts should the cache use?"),
]


@pytest.mark.parametrize("reason,kind,text", _BLOCK_REASONS)
def test_status_and_web_say_what_a_blocked_task_waits_on(env, reason, kind, text):
    """Each blocked reason the daemon writes is the project's to move: the task is listed as stuck
    with plain words and an age, never under 'needs you', in `ttp status` and in /api/state."""
    from ttp.cli import status_text
    from ttp.web import state_payload
    p = make(env)
    tid = p.db.add_task("cache layout", "s", origin="user")
    p.db.update_task(tid, status="blocked", blocked_reason=reason)
    w = next(t for t in state_payload(p, p.db)["tasks"] if t["id"] == tid)["wait"]
    assert (w["kind"], w["text"]) == (kind, text) and w["age"] == "0.0h" and w["asks"] == [], w
    out = status_text(p)
    assert "stuck, the project is on it:" in out and f"  #{tid} 0.0h: cache layout — {text}" in out, out
    assert f"needs you (#{tid}" not in out, out


def test_a_task_an_open_ask_names_waits_on_the_user(env):
    from ttp.cli import status_text
    from ttp.web import state_payload
    p = make(env)
    tid = p.db.add_task("pick a vendor", "s", origin="user")
    other = p.db.add_task("other", "s", origin="user")
    p.db.update_task(tid, status="blocked", blocked_reason="needs a vendor choice")
    p.db.update_task(other, status="blocked", blocked_reason="dependency #99 failed")
    # #1 inside #10 or #100 does not count: only the exact id.
    ask = p.db.post("out", f"#{tid}: vendor A or B? (not #{tid}0)", chat=None, kind="ask", severity="high")
    st = state_payload(p, p.db)
    w = next(t for t in st["tasks"] if t["id"] == tid)["wait"]
    assert w["kind"] == "user" and w["text"] == f"waits on you: ask {ask}" and w["asks"] == [ask], w
    assert next(t for t in st["tasks"] if t["id"] == other)["wait"]["kind"] == "coordinator"
    out = status_text(p)
    assert f"  needs you (#{tid}, 0.0h): pick a vendor — waits on you: ask {ask}" in out, out
    assert f"  #{other} 0.0h: other — waits on the coordinator" in out, out
    # Answered, it is the coordinator's again.
    p.db.x("UPDATE messages SET handled=1 WHERE id=?", (ask,))
    assert f"needs you (#{tid}" not in status_text(p)


_UNTIL = 2_000_000_000


@pytest.mark.parametrize("anchor,kind,text", [
    ("ask", "user", None),
    (f"until:{_UNTIL}", "time", "waits until 2033-05-18 03:33 UTC"),   # the project's home zone (UTC in tests)
    ("when:test -f out/landed.marker", "resource", "waits on a check to pass"),
    ("when:landed:#41", "resource", "waits on #41 to land"),
    ("resource:board-a", "resource", "waits on board-a"),
])
def test_status_and_web_read_a_hold_anchor_by_its_kind(env, anchor, kind, text):
    """A coordinator hold (waits:ask/until/when/resource) shows what it waits on, not its free-text
    reason: an ask is the user's even when its text does not name the task, an until its time, a when
    plain words and never the probe."""
    from ttp.cli import status_text
    from ttp.web import state_payload
    p = make(env)
    tid = p.db.add_task("cache layout", "s", origin="user")
    if anchor == "ask":
        ask = p.db.post("out", "vendor A or B?", chat=None, kind="ask", severity="high")
        anchor, text = f"ask:{ask}", f"waits on you: ask {ask}"
    p.db.update_task(tid, status="blocked", blocked_reason="held by the coordinator: some free text",
                     labels=["kept", f"waits:{anchor}"])
    w = next(t for t in state_payload(p, p.db)["tasks"] if t["id"] == tid)["wait"]
    assert (w["kind"], w["text"]) == (kind, text) and w["age"] == "0.0h", w
    assert w["asks"] == ([ask] if kind == "user" else []), w
    assert "free text" not in w["text"] and "test -f" not in w["text"], w
    out = status_text(p)
    if kind == "user":
        assert f"  needs you (#{tid}, 0.0h): cache layout — {text}" in out, out
        assert "stuck, the project is on it:" not in out, out
    else:
        assert f"  #{tid} 0.0h: cache layout — {text}" in out and f"needs you (#{tid}" not in out, out


def test_wait_kind_label_wins_and_queued_holds_read_plainly():
    from ttp import waits
    from ttp.daemon import LOGGED_OUT_NOTE, NET_HELD_NOTE, PAUSED_NOTE
    t = {"id": 3, "status": "blocked", "updated": 100.0, "blocked_reason": "dependency #2 failed",
         "labels": json.dumps(["waits:resource:the lab board"])}
    asks = [{"id": 9, "ts": 50.0, "kind": "ask", "text": "about #3"}]
    assert waits.wait_kind(t, asks, now=3700.0)["text"] == "waits on the lab board"
    assert waits.wait_kind({**t, "labels": "[]"}, asks, now=3700.0)["age"] == "1.0h"   # from the ask
    assert waits.wait_kind({**t, "labels": '["waits:review:#12"]'}, [], 100.0)["text"] == "waits on a review: #12"
    assert waits.wait_kind({**t, "labels": '["waits:bogus:x"]'}, [], 100.0)["kind"] == "coordinator"
    assert waits.wait_kind({**t, "status": "review", "labels": "[]"}, [], 100.0)["kind"] == "review"
    for reason, kind in ((f"{PAUSED_NOTE} box: maintenance; it starts once resumed (`ttp resume x --resource box`)",
                          "resource"), (f"{LOGGED_OUT_NOTE} (claude); it starts once a login check passes", "user"),
                         (f"{NET_HELD_NOTE} waiting for claude's API host to resolve", "resource"),
                         ("waiting for the build box; its probe says not yet; next try 10:00", "resource"),
                         ("interrupted by `ttp stop --kill`; resumes", "time")):
        w = waits.wait_kind({**t, "status": "queued", "labels": "[]", "blocked_reason": reason}, [], 100.0)
        assert w["kind"] == kind and "`" not in w["text"] and "probe" not in w["text"], (reason, w)
    assert waits.wait_kind({**t, "status": "queued", "labels": "[]",
                            "blocked_reason": "waiting for the build box; its probe says not yet; next try 10:00"},
                           [], 100.0)["text"] == "waits on the build box"


def test_waiting_on_you_counts_only_blocked_tasks_that_truly_wait_on_the_user(env):
    """'waiting on you' in `ttp status`, the web app and `ttp overview` counts a blocked task only when
    it waits on an open ask, an explicit user mark or a resource the user paused; one that waits on
    the coordinator, a coordinator pause or an answered ask gets a neutral 'held' line instead."""
    from ttp import waits
    from ttp.cli import status_text
    from ttp.db import PAUSED_RESOURCES_KEY
    from ttp.globalcap import connect_ro
    from ttp.overview import _ReadOnly
    from ttp.web import health, state_payload
    p = make(env)
    now = time.time()
    p.db.x("INSERT INTO runs(role,provider,started,status) VALUES('worker','fake',?,'running')", (now,))
    ask = p.db.post("out", "Which layout should the cache use?", kind="ask", severity="high")
    answered = p.db.post("out", "Which board?", kind="ask")
    p.db.x("UPDATE messages SET handled=1 WHERE id=?", (answered,))
    p.db.set_kv(PAUSED_RESOURCES_KEY, {"box": {"reason": "maintenance", "since": now, "by": "user"},
                                       "rig": {"reason": "flaky", "since": now, "by": "coordinator"}})
    tasks = {
        "coordinator": ("workspace: worktree add failed", []),
        "open ask": ("", [f"waits:ask:{ask}"]),
        "user paused": ("", ["waits:resource:box"]),
        "user mark": ("", ["waits:user:a signature"]),
        "coordinator paused": ("", ["waits:resource:rig"]),
        "answered ask": ("", [f"waits:ask:{answered}"]),
        "unknown": ("something odd happened", []),
    }
    ids = {}
    for title, (reason, labels) in tasks.items():
        ids[title] = tid = p.db.add_task(title, "s", origin="user")
        p.db.x("UPDATE tasks SET status='blocked', blocked_reason=?, labels=? WHERE id=?",
               (reason, json.dumps(labels), tid))
    you, stuck = waits.blocked(p.db, now)
    assert {t["title"] for t in you} == {"open ask", "user paused", "user mark"}, [t["wait"] for t in you]
    assert {t["title"]: t["wait"]["kind"] for t in stuck} == {
        "coordinator": "coordinator", "coordinator paused": "resource", "answered ask": "coordinator",
        "unknown": "coordinator"}
    assert waits.held_line(stuck) == "held: 4 blocked task(s) (waiting on the coordinator 3, a resource 1)"
    assert waits.held_line([]) == ""

    h = health(p, p.db, now=now)
    assert h["waiting_on_user"] == 3 and h["held_blocked"] == 4, h
    p.db.x("UPDATE runs SET status='done'")
    h = health(p, p.db, now=now)
    assert "waiting on you: 3 blocked task(s), 1 open question(s)" in h["why_idle"], h["why_idle"]
    assert "held: 4 blocked task(s) (waiting on the coordinator 3, a resource 1)" in h["why_idle"], h["why_idle"]
    # The web board's task waits agree with the count.
    st = state_payload(p, p.db)
    board = {t["title"] for t in st["tasks"] if t["wait"] and t["wait"]["kind"] == "user"}
    assert board == {t["title"] for t in you}, board
    assert st["health"]["waiting_on_user"] == h["waiting_on_user"]
    # `ttp status` lists the same tasks under 'needs you', never the coordinator's.
    out = status_text(p)
    for title in ("open ask", "user paused", "user mark"):
        assert f"needs you (#{ids[title]}," in out, out
    for title in ("coordinator", "coordinator paused", "answered ask", "unknown"):
        assert f"needs you (#{ids[title]}," not in out, out
    # `ttp overview` counts through the same classifier over a read-only connection.
    conn = connect_ro(p.db.path)
    try:
        assert len(waits.blocked(_ReadOnly(conn), now)[0]) == 3
    finally:
        conn.close()


@pytest.mark.parametrize("why", [None, "the build lands on the branch"])
def test_a_deferred_task_shows_plain_words_never_its_probe(env, why):
    """start_when's shell text stays in the task's detail (and the coordinator's digest); status
    and the board say 'starts when <why>', or 'when a check passes' without one."""
    from ttp import coordinator as coord
    from ttp.cli import status_text
    from ttp.web import state_payload
    p = make(env)
    probe = "test -f out/landed.marker"
    a = {"type": "task_add", "title": "after landing", "spec": "s", "start_when": probe}
    assert coord.apply(p, [{**a, **({"why": why} if why else {})}]) == []
    tid = p.db.q("SELECT id FROM tasks WHERE title='after landing'")[0]["id"]
    want = f"starts when {why}" if why else "starts when a check passes"
    st = state_payload(p, p.db)
    t = next(t for t in st["tasks"] if t["id"] == tid)
    assert t["starts"] == want and t["start_when"] == probe and t["start_why"] == why, t
    out = status_text(p)
    assert f"  #{tid} deferred, {want}: after landing" in out and "landed.marker" not in out, out
    assert probe in coord.starts_text(p.db.task(tid))   # the coordinator still sees the probe
    # A later why alone re-words it; a new probe without one drops the old words.
    assert coord.apply(p, [{"type": "task_update", "id": tid, "why": "the release is tagged"}]) == []
    assert coord.starts_text(p.db.task(tid), plain=True) == "starts when the release is tagged"
    assert coord.apply(p, [{"type": "task_update", "id": tid, "start_when": "test -f other"}]) == []
    assert coord.starts_text(p.db.task(tid), plain=True) == "starts when a check passes"
    # Clearing the probe clears its words too.
    assert coord.apply(p, [{"type": "task_update", "id": tid, "start_when": "x", "why": "w"}]) == []
    assert coord.apply(p, [{"type": "task_update", "id": tid, "start_when": ""}]) == []
    assert not any(lb.startswith("start_why:") for lb in json.loads(p.db.task(tid)["labels"]))
    # A wait for another task's landing reads as such without a why.
    other = p.db.add_task("the change", "s", origin="user")
    assert coord.apply(p, [{"type": "task_update", "id": tid, "start_when": f"landed:#{other}"}]) == []
    assert coord.starts_text(p.db.task(tid), plain=True) == f"starts when #{other} lands"


def _hold_task(p, title="hold me"):
    tid = p.db.add_task(title, "spec", kind="work", tier="light", origin="user")
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    return tid


def test_a_hold_without_an_anchor_is_rejected_and_a_bad_anchor_too(env):
    p = make(env)
    from ttp import coordinator as coord
    tid = _hold_task(p)
    problems = coord.apply(p, [{"type": "task_update", "id": tid, "status": "blocked",
                                "text": "until the user confirms"}])
    assert len(problems) == 1 and "a hold needs `waits_on`" in problems[0] and "ask_user" in problems[0]
    assert "decide it yourself" in problems[0] and "until or when" in problems[0]
    assert p.db.task(tid)["status"] == "queued", "an unanchored hold was applied"
    for bad in ("ask:999", "later:soon", "until:2001-01-01T00:00", "resource:", "ask:new"):
        got = coord.apply(p, [{"type": "task_update", "id": tid, "status": "blocked", "waits_on": bad}])
        assert len(got) == 1 and "rejected" in got[0], bad
        assert p.db.task(tid)["status"] == "queued", bad
    got = coord.apply(p, [{"type": "task_update", "id": tid, "waits_on": "until:6h"}])
    assert "goes with status blocked" in got[0]
    # A daemon-made block stays as it is, and a text change on an anchored hold keeps its anchor.
    p.db.update_task(tid, status="blocked", blocked_reason="task budget exhausted")
    assert coord.apply(p, [{"type": "task_update", "id": tid, "status": "blocked", "waits_on": "until:6h",
                            "text": "after the window"}]) == []
    assert coord.apply(p, [{"type": "task_update", "id": tid, "status": "blocked", "text": "still"}]) == []
    assert p.db.task(tid)["blocked_reason"] == "still" and "waits:until:" in p.db.task(tid)["labels"]
    # Leaving blocked drops the anchor.
    assert coord.apply(p, [{"type": "task_update", "id": tid, "status": "queued"}]) == []
    assert "waits:" not in p.db.task(tid)["labels"]


def test_a_hold_on_this_turns_ask_points_at_it_and_is_undone_when_the_ask_is_rejected(env):
    p = make(env)
    from ttp import coordinator as coord
    tid = _hold_task(p)
    hold = {"type": "task_update", "id": tid, "status": "blocked", "text": "needs access", "waits_on": "ask:new"}
    ask = {"type": "ask_user", "text": "May I use the shared bucket for the results?", "blocking": "access",
           "recommendation": "yes"}
    assert coord.apply(p, [hold, ask]) == []
    aid = p.db.one("SELECT MAX(id) id FROM messages WHERE kind='ask'")["id"]
    assert f'"waits:ask:{aid}"' in p.db.task(tid)["labels"] and p.db.task(tid)["status"] == "blocked"
    tid2 = _hold_task(p, "second")
    assert coord.apply(p, [{"type": "ask_user", "text": "Which account pays for the run?", "blocking": "funds"},
                           {**hold, "id": tid2}]) == []
    aid2 = p.db.one("SELECT MAX(id) id FROM messages WHERE kind='ask'")["id"]
    assert f'"waits:ask:{aid2}"' in p.db.task(tid2)["labels"]
    tid3 = _hold_task(p, "third")
    got = coord.apply(p, [{**hold, "id": tid3}, {**ask, "blocking": "maybe"}])
    assert any("no ask_user of this turn went through" in x for x in got)
    t3 = p.db.task(tid3)
    assert t3["status"] == "queued" and t3["blocked_reason"] is None and "waits:" not in t3["labels"]


def test_each_hold_anchor_releases_its_task_once_it_is_over(env, tmp_path):
    p = make(env)
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    ask_t, until_t, res_t, when_t = (_hold_task(p, n) for n in ("ask", "until", "resource", "when"))
    flag = tmp_path / "go"
    assert coord.apply(p, [{"type": "ask_user", "text": "May I spend $40 on the long run?", "blocking": "spend"},
                           {"type": "task_update", "id": ask_t, "status": "blocked", "waits_on": "ask:new"},
                           {"type": "task_update", "id": until_t, "status": "blocked", "waits_on": "until:2h"},
                           {"type": "task_update", "id": res_t, "status": "blocked", "waits_on": "resource:board-a"},
                           {"type": "task_update", "id": when_t, "status": "blocked",
                            "waits_on": f"when:test -e {flag}"}]) == []
    coord.pause_resource(p, "board-a", True, "maintenance")
    d.sweep_holds()
    if when_t in d._probes:
        d._probes[when_t][0].wait(10)
    d.probe_waiting()
    d.sweep_holds()
    assert all(p.db.task(t)["status"] == "blocked" for t in (ask_t, until_t, res_t, when_t))
    aid = p.db.one("SELECT MAX(id) id FROM messages WHERE kind='ask'")["id"]
    assert coord.apply(p, [{"type": "resolve", "id": aid}]) == []
    p.db.update_task(until_t, labels=[f"waits:until:{time.time() - 1:.0f}"])
    coord.pause_resource(p, "board-a", False)
    flag.write_text("")
    d._probed.clear()
    d.sweep_holds()
    d._probes[when_t][0].wait(10)
    d.probe_waiting()
    d.sweep_holds()
    for t in (ask_t, until_t, res_t, when_t):
        task = p.db.task(t)
        assert task["status"] == "queued" and "waits:" not in task["labels"], task["title"]
    why = [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind='hold_released' ORDER BY id")]
    assert len(why) == 4 and any("ask #" in w for w in why) and any("when probe passed" in w for w in why)


def test_a_hold_anchor_never_outlives_its_hold(env):
    """A requeue by any path (here the web app's raw SQL) drops the anchor, so a later block for
    another reason is not released by it."""
    p = make(env)
    from ttp import coordinator as coord
    from ttp import web
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    tid = _hold_task(p)
    coord.pause_resource(p, "board-a", True, "maintenance")
    assert coord.apply(p, [{"type": "task_update", "id": tid, "status": "blocked",
                            "waits_on": "resource:board-a"}]) == []
    port = _start_web(p)
    req = urllib.request.Request(f"http://127.0.0.1:{port}/api/task/{tid}", method="POST",
                                 data=json.dumps({"status": "queued"}).encode(),
                                 headers={"X-TTP-Token": web.token(p), "Content-Type": "application/json"})
    for _ in range(50):
        try:
            with urllib.request.urlopen(req, timeout=2) as r:
                assert r.status == 200
            break
        except urllib.error.HTTPError:
            raise
        except OSError:
            time.sleep(0.1)
    t = p.db.task(tid)
    assert t["status"] == "queued" and "waits:" not in t["labels"]
    p.db.update_task(tid, status="blocked", blocked_reason="task budget exhausted")
    coord.pause_resource(p, "board-a", False)
    d.sweep_holds()
    t = p.db.task(tid)
    assert t["status"] == "blocked" and t["blocked_reason"] == "task budget exhausted"
    # Every other way off blocked, and every way to put an anchor on a task not blocked, drops it too.
    for leave in (lambda: p.db.update_task(tid, status="running"),
                  lambda: p.db.x("UPDATE tasks SET status='done' WHERE id=?", (tid,)),
                  lambda: p.db.update_task(tid, status="queued", labels=["kept", "waits:resource:board-a"])):
        p.db.update_task(tid, status="blocked", labels=["kept", "waits:resource:board-a"])
        assert "waits:" in p.db.task(tid)["labels"]
        leave()
        assert json.loads(p.db.task(tid)["labels"]) == ["kept"]
    p.db.update_task(tid, labels=["waits:until:1", "kept"])
    assert json.loads(p.db.task(tid)["labels"]) == ["kept"]
    new = p.db.add_task("born queued", "s", origin="user", labels=["waits:resource:board-a", "resource:board-a"])
    assert json.loads(p.db.task(new)["labels"]) == ["resource:board-a"]


def test_an_expired_ask_releases_its_hold(env):
    p = make(env)
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    tid = _hold_task(p)
    assert coord.apply(p, [{"type": "ask_user", "text": "May I delete the old artifacts?",
                            "blocking": "irreversible", "classify": "irreversible",
                            "least_disruptive": "move them to an archive; the archive is as full as the disk"},
                           {"type": "task_update", "id": tid, "status": "blocked", "waits_on": "ask:new"}]) == []
    p.db.x("UPDATE messages SET handled=1 WHERE kind='ask'")   # what expire_asks does to a due ask
    Daemon(p.base).sweep_holds()
    assert p.db.task(tid)["status"] == "queued"


def _setting_ask(p, text="May reviewed work land on main? That needs delivery.allow_protected_push_branch on."):
    p.db.x("INSERT INTO messages(ts,direction,kind,severity,text) VALUES(?,?,?,?,?)",
           (time.time(), "out", "ask", "high", text))
    return p.db.one("SELECT MAX(id) id FROM messages WHERE kind='ask'")["id"]


def _remote_origin(p):
    """A code repo with a remote, so a push branch on it is refused only by the setting."""
    subprocess.run(["git", "-C", str(p.root), "remote", "add", "origin", "https://example.invalid/r.git"], check=True)


def test_a_setting_hold_keeps_landing_tasks_off_workers_until_the_setting_is_on(env, monkeypatch):
    """While an open ask names delivery.allow_protected_push_branch (off), tasks that land with `ttp push`
    wait blocked, attempts untouched; everything else runs. Turning it on releases them all together."""
    from ttp import coordinator as coord
    from ttp import settinghold
    p = make(env)
    _remote_origin(p)
    p.set_config("delivery.push_branch", "origin/main")
    land = [p.db.add_task("Land the fix", "Fix it, then land on main with `ttp push --detach`.", kind="code",
                          tier="light", origin="user"),
            p.db.add_task("Push the batch", "Run ttp push in the worktree.", kind="work", tier="light",
                          origin="user")]
    other = [p.db.add_task("Fix docs", "Never run ttp push; do not land anything.", kind="code", tier="light",
                           origin="user"),
             p.db.add_task("Publish own", "Publish with `ttp push --own --detach`.", kind="code", tier="light",
                           origin="user"),
             p.db.add_task("Review it", "If it passes, push it with `ttp push`.", kind="review", tier="light",
                           origin="user")]
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    # No ask about it: nothing is held.
    _, started = _paused_dispatch(p, monkeypatch)
    assert len(started) == 5
    p.db.x("UPDATE tasks SET status='queued'")
    aid = _setting_ask(p)
    d, started = _paused_dispatch(p, monkeypatch)
    assert sorted(started) == sorted(p.db.task(t)["title"] for t in other), started
    for t in land:
        task = p.db.task(t)
        assert task["status"] == "blocked" and not task["attempts"], task
        assert task["blocked_reason"].startswith(settinghold.NOTE) and f"ask #{aid}" in task["blocked_reason"]
        assert f'"waits:ask:{aid}"' in task["labels"]
    # The digest shows the hold once, as one line, and not the held tasks' own rows.
    text = coord.digest(p, {}, [], [])
    lines = [ln for ln in text.splitlines() if "setting hold" in ln]
    assert len(lines) == 1 and f"#{land[0]}, #{land[1]}" in lines[0] and f"ask #{aid}" in lines[0], lines
    assert not any(ln.startswith(f"- #{land[0]} |") for ln in text.splitlines())
    # Still off, still asked: the sweep keeps them.
    d.sweep_holds()
    assert all(p.db.task(t)["status"] == "blocked" for t in land)
    p.set_config("delivery.allow_protected_push_branch", True)
    d.cfg = p.config()
    d.sweep_holds()
    for t in land:
        task = p.db.task(t)
        assert task["status"] == "queued" and task["blocked_reason"] is None and "waits:" not in task["labels"]
    why = [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind='hold_released'")]
    assert len(why) == 2 and all("allow_protected_push_branch was turned on" in w for w in why), why
    _, started = _paused_dispatch(p, monkeypatch)
    assert sorted(started) == ["Land the fix", "Push the batch"]


def test_a_setting_hold_ends_when_its_ask_is_resolved_and_follows_a_newer_ask(env, monkeypatch):
    from ttp import coordinator as coord
    from ttp import settinghold
    p = make(env)
    _remote_origin(p)
    p.set_config("delivery.push_branch", "origin/main")
    tids = [p.db.add_task(f"Land {n}", "land on main with `ttp push`", kind="code", tier="light", origin="user")
            for n in ("a", "b")]
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    first = _setting_ask(p)
    d, started = _paused_dispatch(p, monkeypatch)
    assert started == [] and all(p.db.task(t)["status"] == "blocked" for t in tids)
    # A second ask about it: resolving the first keeps them held, on the newer ask.
    second = _setting_ask(p, "Still need allow_protected_push_branch for the landing")
    assert coord.apply(p, [{"type": "resolve", "id": first}]) == []
    d.sweep_holds()
    for t in tids:
        task = p.db.task(t)
        assert task["status"] == "blocked" and f'"waits:ask:{second}"' in task["labels"], task
        assert f"ask #{second}" in task["blocked_reason"]
    assert coord.apply(p, [{"type": "resolve", "id": second}]) == []
    d.sweep_holds()
    assert all(p.db.task(t)["status"] == "queued" for t in tids)
    why = [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind='hold_released'")]
    assert len(why) == 2 and all("no open ask names" in w for w in why), why
    # A setting already on, or no push branch, holds nothing.
    third = _setting_ask(p)
    p.set_config("delivery.allow_protected_push_branch", True)
    _, started = _paused_dispatch(p, monkeypatch)
    assert len(started) == 2
    p.set_config("delivery.allow_protected_push_branch", False)
    p.set_config("delivery.push_branch", "")
    assert settinghold.active(p.db, p.config()) == {} and third


def test_setting_hold_reads_landing_specs():
    from ttp.settinghold import lands
    yes = ["land on origin/main with `ttp push`", "Then run ttp push --detach.", "Landing it on the push branch is next"]
    no = ["Never run ttp push.", "publish with `ttp push --own --detach`", "do not land anything",
          "the landed sha is reported", "plain spec"]
    for s in yes:
        assert lands({"kind": "code", "spec": s}), s
    for s in no:
        assert not lands({"kind": "code", "spec": s}), s
    assert not lands({"kind": "review", "spec": yes[0]})


@pytest.mark.parametrize("title,spec,held", [
    ("Fix ttp push retry on conflict", "", False),                       # a mention in a title
    ("Docs", "The README describes how `ttp push` works", False),        # prose
    ("Land it", "When reviewed, push with `ttp push --detach`.\nno_push: review only", False),
    ("Publish", "Publish with `ttp push --detach --own`", False),        # --own after another flag
    ("Check the plan lands on time", "", False),
    ("Docs", "Never, under any circumstances at all, run ttp push", False),
    ("Docs", "Don't, whatever happens, push it with `ttp push`.", False),
    ("Ship", "When reviewed, push with `ttp push --detach`", True),
    ("Ship", "Land #12 on the push branch", True),
    ("Ship", "Land #12 on `origin/main` once checks pass", True),
    ("Ship", "Steps:\n- fix it\n- `ttp push --detach`", True),
    ("Ship", "Never skip the tests.\nThen run ttp push.", True),       # a negation in an earlier sentence
    ("Ship", "no_push: false\nRun ttp push.", True),
])
def test_setting_hold_holds_only_landing_instructions(title, spec, held):
    from ttp.settinghold import lands
    assert lands({"kind": "code", "title": title, "spec": spec}, "origin/main") is held


def test_setting_hold_applies_only_to_a_push_branch_the_setting_refuses(env, tmp_path):
    """An open ask naming the setting holds landing tasks only while `ttp push` would refuse the push
    branch with it off and let it through with it on: main/master, or the remote's default branch as
    the code repo last fetched it (local git only). An ordinary branch holds nothing."""
    from ttp import settinghold
    p = make(env)
    _setting_ask(p)
    for branch, held in (("origin/feature", False), ("owner/feature", False), ("origin/main", True),
                         ("master", True)):
        p.set_config("delivery.push_branch", branch)
        assert bool(settinghold.active(p.db, p.config())) is held, branch
        task = {"kind": "code", "title": "Ship", "spec": "When reviewed, push with `ttp push --detach`"}
        assert bool(settinghold.refused_by(task, settinghold.active(p.db, p.config()), p.config())) is held
    # The remote's default branch, from the local refs/remotes/<remote>/HEAD (no network).
    repo = tmp_path / "code"
    repo.mkdir()
    for cmd in (["init", "-q", "-b", "trunk"], ["remote", "add", "origin", "https://example.invalid/r.git"],
                ["commit", "-q", "--allow-empty", "-m", "x"], ["update-ref", "refs/remotes/origin/trunk", "HEAD"],
                ["symbolic-ref", "refs/remotes/origin/HEAD", "refs/remotes/origin/trunk"]):
        subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", *cmd], check=True)
    p.set_config("delivery.push_branch", "origin/trunk")
    assert settinghold.active(p.db, p.config(), repo) and not settinghold.active(p.db, p.config())
    p.set_config("delivery.push_branch", "origin/feature")
    assert not settinghold.active(p.db, p.config(), repo)
    assert "no longer refuses" in settinghold.over(p.config(), "delivery.allow_protected_push_branch", {}, repo)


def test_setting_setup_question_fires_once_per_setting_state(env):
    """A charter granting pushes to the push branch, while delivery.allow_protected_push_branch is off and
    refuses that branch and no ask names it, makes the daemon itself raise one ask (blocking restriction)
    naming the setting: not again on later ticks or after a restart, again only for a new wording. The
    setting stays off, and the open ask holds landing tasks."""
    from ttp import coordinator as coord
    from ttp import prguard, settinghold
    from ttp.daemon import Daemon
    p = make(env)
    _remote_origin(p)
    p.set_config("delivery.push_branch", "origin/main")
    base = p.charter_path.read_text()

    def asked():
        return [m for m in p.db.q("SELECT * FROM messages WHERE kind='ask' AND direction='out' ORDER BY id")]
    # No such charter line: nothing.
    Daemon(p.base).sweep_holds()
    assert asked() == []
    p.charter_path.write_text(base + "\n- Reviewed changes are pushed to main without per-push approval.\n")
    d = Daemon(p.base)
    d.sweep_holds()
    d.sweep_holds()
    Daemon(p.base).sweep_holds()   # a restart
    got = asked()
    assert len(got) == 1 and "delivery.allow_protected_push_branch" in got[0]["text"], got
    assert "origin/main" in got[0]["text"] and got[0]["ref"] == f"{prguard.BLOCKING_REF}restriction"
    assert got[0]["severity"] == "high" and not got[0]["handled"]
    assert settinghold.SETUP_EVENT not in coord.EFFORT_EVENT_TRIGGERS   # asked already: no high-effort turn
    ev = p.db.q("SELECT * FROM events WHERE kind=?", (settinghold.SETUP_EVENT,))
    assert len(ev) == 1 and f"#{got[0]['id']}" in ev[0]["text"] and ev[0]["severity"] == "low"
    assert not p.config()["delivery"].get("allow_protected_push_branch")   # never turned on by itself
    assert settinghold.active(p.db, p.config(), p.root) == {"delivery.allow_protected_push_branch": got[0]["id"]}
    # A new wording is a new grant: asked once more once the first ask is answered.
    p.db.x("UPDATE messages SET handled=1 WHERE kind='ask'")
    p.charter_path.write_text(base + "\n- Pushes to main need no approval.\n")
    Daemon(p.base).sweep_holds()
    assert len(asked()) == 2
    # An open ask naming the setting records the new wording unasked; answering it does not re-ask.
    p.charter_path.write_text(base + "\n- Pushing to main needs no approval from the user.\n")
    Daemon(p.base).sweep_holds()
    p.db.x("UPDATE messages SET handled=1 WHERE kind='ask'")
    Daemon(p.base).sweep_holds()
    assert len(asked()) == 2
    # The setting on or an ordinary push branch raises nothing.
    p.charter_path.write_text(base + "\n- Main gets pushes without asking anyone.\n")
    p.set_config("delivery.allow_protected_push_branch", True)
    Daemon(p.base).sweep_holds()
    p.set_config("delivery.allow_protected_push_branch", False)
    p.set_config("delivery.push_branch", "origin/feature")
    Daemon(p.base).sweep_holds()
    assert len(asked()) == 2


@pytest.mark.parametrize("line,grants", [
    ("Pushes to main are fine without asking anyone.", True),
    ("Reviewed changes are pushed to main without per-push approval.", True),
    ("Pushing to main is allowed.", True),
    ("You may push reviewed work straight to main.", True),
    ("Work lands on the push branch; pushing there is OK.", True),
    ("Never push to main without approval.", False),
    ("Do not push to main.", False),
    ("Pushing to main is not allowed.", False),
    ("Pushing to main isn't allowed.", False),
    ("You may push to main only after I approve.", False),
    ("Push to main is allowed unless CI is red.", False),
    ("Pushing reviewed changes to the feature branch is allowed.", False),
    ("Main is the default.", False),
    ("Pushing to main can break CI for everyone.", False),
    ("We can also push to main.", True),
])
def test_charter_grant_wording(line, grants):
    """A grant is a push to main, master, the default or the push branch that needs no approval, or is
    allowed in plain words with no negation or condition; a prohibition or another branch never is."""
    from ttp.settinghold import charter_says_no_approval
    assert bool(charter_says_no_approval(line, "origin/main")) is grants


def test_brief_grant_is_applied_without_asking(env):
    """A grant in the verbatim Brief is the user's own word on record: the first tick after setup turns
    delivery.allow_protected_push_branch on itself, says so in one low alert quoting it, and closes an
    open ask about the setting instead of raising one."""
    from ttp import grants, settinghold
    from ttp.daemon import Daemon
    p = make(env)
    _remote_origin(p)
    p.set_config("delivery.push_branch", "origin/main")
    mid = _setting_ask(p)
    p.charter_path.write_text("# x — charter\n\n## Brief (verbatim from the user)\nBuild the thing. Pushing to "
                              "main is allowed.\n\n## Goals\nShip it.\n")
    Daemon(p.base).sweep_holds()
    Daemon(p.base).sweep_holds()   # a restart: nothing more
    assert p.config()["delivery"]["allow_protected_push_branch"] is True
    assert p.db.q("SELECT id FROM messages WHERE kind='ask' AND handled=0") == []
    assert p.db.one("SELECT handled FROM messages WHERE id=?", (mid,))["handled"] == 1
    alerts = p.db.q("SELECT * FROM messages WHERE kind='alert' AND text LIKE '%allow_protected_push_branch%'")
    assert len(alerts) == 1 and alerts[0]["severity"] == "low"
    assert "Pushing to main is allowed." in alerts[0]["text"] and "the Brief" in alerts[0]["text"]
    assert f"#{mid}" in alerts[0]["text"]
    assert len(p.db.q("SELECT id FROM events WHERE kind=?", (grants.APPLIED,))) == 1
    assert not p.db.q("SELECT id FROM events WHERE kind=?", (grants.EVENT,))
    assert not settinghold.active(p.db, p.config(), p.root)


def _policies_line(p, line, user_text=None, provenance=None):
    """Add `line` to the charter's Policies as the coordinator does, logged in CHARTER.history.md, in a
    turn carrying a user message `user_text` (None: a turn of its own)."""
    from ttp import ends
    said = ""
    if user_text is not None:
        mid = p.db.post("in", user_text, chat="c", kind="user", provenance=provenance)
        said = f", user message #{mid}"
    p.charter_path.write_text(p.charter_path.read_text().replace("## Policies\n", f"## Policies\n\n{line}\n", 1))
    hist = p.harness / ends.CHARTER_HISTORY
    old = hist.read_text() if hist.exists() else "# Charter history\n"
    hist.write_text(old + f"\n### Added to Policies (2026-10-01{said}, turn 7)\n{line}\n")


def _grant_events(p, kind=None):
    from ttp import grants
    return p.db.q("SELECT * FROM events WHERE kind=? ORDER BY id", (kind or grants.EVENT,))


def test_charter_grants_matching_the_config_raise_nothing(env):
    """The template's 'Auto-merge repositories: none.', a listed repo the config already auto-merges, and
    a push grant for an ordinary branch that pushing already allows: no change, no event, no ask."""
    from ttp import grants
    from ttp.daemon import Daemon
    p = make(env)
    Daemon(p.base).sweep_holds()
    assert grants.checks(p.config(), p.charter_path.read_text()) == []
    p.set_config("delivery.auto_merge_repos", ["acme/widgets"])
    p.set_config("delivery.push_branch", "origin/feature")
    _policies_line(p, "- Auto-merge repositories: acme/widgets.\n- Pushes to the push branch need no approval.")
    Daemon(p.base).sweep_holds()
    assert grants.checks(p.config(), p.charter_path.read_text(), p.root) == []
    assert _grant_events(p) == [] and _grant_events(p, grants.APPLIED) == []
    assert p.db.q("SELECT id FROM messages WHERE kind='ask'") == []


@pytest.mark.parametrize("user_text,provenance", [("auto-merge acme/widgets", None), (None, None), ("hi", "system")])
def test_auto_merge_line_from_any_source_is_reported_never_applied(env, user_text, provenance):
    """A Policies auto-merge line, whether logged with the user's message, written by the coordinator on
    its own, or in a turn whose only message the harness posted, never changes delivery.auto_merge_repos
    (only the coordinator's config_set in the user's turn does): one keyed mismatch defect across ticks
    and restarts, no alert, no grant_applied event, nothing asked, no bookkeeping."""
    from ttp import coordinator as coord
    from ttp import grants
    from ttp.daemon import Daemon
    p = make(env)
    _policies_line(p, "- Auto-merge repositories: acme/widgets.", user_text, provenance)
    d = Daemon(p.base)
    d.sweep_holds()
    d.sweep_holds()
    Daemon(p.base).sweep_holds()
    assert p.config()["delivery"]["auto_merge_repos"] == []
    ev = _grant_events(p)
    assert len(ev) == 1 and "auto_merge_repos" in ev[0]["text"] and "Not an ask" in ev[0]["text"]
    assert "report-only" in ev[0]["text"]
    assert coord.EFFORT_EVENT_TRIGGERS[grants.EVENT] == "conflict"
    assert p.db.q("SELECT id FROM messages WHERE kind='ask'") == []
    assert _grant_events(p, grants.APPLIED) == []
    assert p.db.q("SELECT id FROM messages WHERE kind='alert' AND text LIKE '%auto_merge_repos%'") == []
    assert grants.AUTO_MERGE not in (p.db.kv(grants.APPLIED_KV) or {})


@pytest.mark.parametrize("line", [None, "- Auto-merge repositories: none.", "- Auto-merge repositories: acme/a.",
                                  "- Auto-merge repositories: acme/a, acme/b, acme/c."])
def test_existing_auto_merge_config_is_never_removed_or_re_added(env, line):
    """A config that auto-merges [acme/a, acme/b] keeps exactly that across ticks and restarts, whatever
    the charter lists (nothing, none, fewer or more repos, on the user's word): never narrowed, widened or
    re-added after the user edits it; a mismatch is one defect per state, a match or no line none."""
    from ttp import grants
    from ttp.daemon import Daemon
    p = make(env)
    p.charter_path.write_text(p.charter_path.read_text().replace("- Auto-merge repositories: none.\n", ""))
    assert "Auto-merge repositories" not in p.charter_path.read_text()
    p.set_config("delivery.auto_merge_repos", ["acme/a", "acme/b"])
    if line:
        _policies_line(p, line, "set auto-merge")
    for _ in range(2):
        Daemon(p.base).sweep_holds()
    assert p.config()["delivery"]["auto_merge_repos"] == ["acme/a", "acme/b"]
    assert len(_grant_events(p)) == (1 if line else 0), _grant_events(p)
    p.set_config("delivery.auto_merge_repos", ["acme/a"])   # the user narrows it: a tick never puts acme/b back
    for _ in range(2):
        Daemon(p.base).sweep_holds()
    assert p.config()["delivery"]["auto_merge_repos"] == ["acme/a"]
    assert len(_grant_events(p)) == {None: 0, "- Auto-merge repositories: acme/a.": 1}.get(line, 2), _grant_events(p)
    assert _grant_events(p, grants.APPLIED) == []
    assert p.db.q("SELECT id FROM messages WHERE kind IN ('ask', 'alert') AND text LIKE '%auto_merge%'") == []


def test_grant_refused_by_the_charter_or_config_is_a_defect(env):
    """A grant the user's word covers is still not applied when the charter also forbids it, or the
    config auto-merges more than the charter lists: one defect each, no ask (not even the setup
    question), nothing set. 'Never force-push' forbids nothing."""
    from ttp import grants
    from ttp.daemon import Daemon
    p = make(env)
    _remote_origin(p)
    p.set_config("delivery.push_branch", "origin/main")
    p.set_config("delivery.push_allowed", False)
    p.set_config("delivery.auto_merge_repos", ["acme/other"])
    _policies_line(p, "- Pushes to main need no approval.\n- Auto-merge repositories: acme/widgets.\n"
                      "- Never push to main.", "ok")
    Daemon(p.base).sweep_holds()
    Daemon(p.base).sweep_holds()
    d = p.config()["delivery"]
    assert d["push_allowed"] is False and not d.get("allow_protected_push_branch")
    assert d["auto_merge_repos"] == ["acme/other"]
    keys = sorted(t for e in _grant_events(p) for t in (grants.PUSH, grants.PROTECTED, grants.AUTO_MERGE)
                  if f"grants {t} " in e["text"])
    assert keys == sorted([grants.PUSH, grants.PROTECTED, grants.AUTO_MERGE]), _grant_events(p)
    assert p.db.q("SELECT id FROM messages WHERE kind='ask'") == []
    assert not grants.forbidden("Never force-push to main.", "origin/main")


