def test_memory_never_claims_a_rejected_config_change(env):
    """A memory_add naming a setting whose config_set the same turn was rejected says in the entry that
    the change is not in effect (whatever the action order); one naming nothing rejected is kept as is."""
    from ttp import coordinator as coord
    p = make(env)
    probs = coord.apply(p, [
        {"type": "memory_add", "text": "Enabled allow_protected_push_branch: reviewed work lands on main now.",
         "title": "push to main on"},
        {"type": "config_set", "key": "delivery.allow_protected_push_branch", "value": True},
        {"type": "memory_add", "text": "The daily review runs at 09:00.", "title": "review time"}], turn=7)
    assert any("needs the user's approval" in x for x in probs), probs
    assert not p.config()["delivery"].get("allow_protected_push_branch")
    entries = {f.name: f.read_text() for f in p.memory_dir.glob("*.md")}
    on = next(t for n, t in entries.items() if "push-to-main-on" in n)
    assert "Not in effect: config_set delivery.allow_protected_push_branch was rejected" in on
    assert "setting is unchanged" in on
    other = next(t for n, t in entries.items() if "review-time" in n)
    assert "Not in effect" not in other
    # In a user turn the change goes through, and the memory stays as written.
    coord.apply(p, [{"type": "config_set", "key": "delivery.allow_protected_push_branch", "value": True},
                    {"type": "memory_add", "text": "delivery.allow_protected_push_branch is on, by the user's yes.",
                     "title": "user turned it on"}], user_turn=True, turn=8)
    assert p.config()["delivery"]["allow_protected_push_branch"] is True
    assert "Not in effect" not in next(f for f in p.memory_dir.glob("*user-turned-it-on*.md")).read_text()


def test_a_review_with_a_push_step_runs_review_only_while_a_setting_hold_stands(env):
    from ttp import prompts
    p = make(env)
    _remote_origin(p)
    p.set_config("delivery.push_branch", "origin/main")
    review = p.db.add_task("Review #5", "Review it. If it passes, push it with `ttp push`.", kind="review",
                           tier="light", origin="user")
    plain = p.db.add_task("Review #6", "Review it and report.", kind="review", tier="light", origin="user")

    def line(tid):
        text = prompts.worker_task(p, p.db.task(tid), str(p.root), None)
        return "Review only: do not run `ttp push`" in text, text
    assert not line(review)[0]   # no ask open: no hold
    aid = _setting_ask(p)
    has, text = line(review)
    assert has and f"ask #{aid}" in text and "hand off `blocked`" in text and \
        "naming delivery.allow_protected_push_branch" in text, text
    assert not line(plain)[0]
    p.set_config("delivery.allow_protected_push_branch", True)
    assert not line(review)[0]


def test_tasks_a_worker_handed_off_blocked_on_the_setting_join_its_hold_and_are_released_with_it(env):
    """A blocked task with no anchor whose hand-off names the held setting is anchored to the open ask
    and released with the rest: when the setting turns on, or when the ask is resolved."""
    from ttp import coordinator as coord
    from ttp import settinghold
    from ttp.daemon import Daemon
    from ttp.db import dump_result
    p = make(env)
    _remote_origin(p)
    p.set_config("delivery.push_branch", "origin/main")
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    ids = {n: p.db.add_task(f"Task {n}", "fix it", kind="code", tier="light", origin="user")
           for n in ("reason", "summary", "other", "anchored")}

    def block():
        p.db.update_task(ids["reason"], status="blocked",
                         blocked_reason="ttp push refused: delivery.allow_protected_push_branch is off")
        p.db.update_task(ids["summary"], status="blocked", blocked_reason="need the user's word",
                         result=dump_result({"status": "blocked",
                                             "summary": "Reviewed head abc; allow_protected_push_branch is off."}))
        p.db.update_task(ids["other"], status="blocked", blocked_reason="needs a credential")
        p.db.update_task(ids["anchored"], status="blocked", labels=json.dumps(["waits:until:9999999999"]),
                         blocked_reason="allow_protected_push_branch is off; waiting a day")
    block()
    d = Daemon(p.base)
    d.sweep_holds()   # no ask names it: nothing joins
    assert all("waits:ask" not in (p.db.task(t)["labels"] or "") for t in ids.values())
    for resolve_by in ("setting", "ask"):
        aid = _setting_ask(p)
        d.sweep_holds()
        for n in ("reason", "summary"):
            t = p.db.task(ids[n])
            assert t["status"] == "blocked" and f'"waits:ask:{aid}"' in t["labels"], t
            assert settinghold.held_key(t) and "Handed off:" in t["blocked_reason"], t
        assert "waits:" not in (p.db.task(ids["other"])["labels"] or "")
        assert "waits:until" in p.db.task(ids["anchored"])["labels"]
        lines = [ln for ln in coord.digest(p, {}, [], []).splitlines() if "setting hold" in ln]
        assert len(lines) == 1 and f"#{ids['reason']}, #{ids['summary']}" in lines[0], lines
        if resolve_by == "setting":
            p.set_config("delivery.allow_protected_push_branch", True)
            d.cfg = p.config()
        else:
            assert coord.apply(p, [{"type": "resolve", "id": aid}]) == []
        d.sweep_holds()
        for n in ("reason", "summary"):
            assert p.db.task(ids[n])["status"] == "queued", (resolve_by, p.db.task(ids[n]))
        assert p.db.task(ids["other"])["status"] == "blocked"
        why = [e["text"] for e in p.db.q("SELECT text FROM events WHERE kind='hold_released'")]
        assert len(why) == (2 if resolve_by == "setting" else 4), why
        assert ("was turned on" if resolve_by == "setting" else "no open ask names") in why[-1], why
        p.set_config("delivery.allow_protected_push_branch", False)
        d.cfg = p.config()
        p.db.x("UPDATE messages SET handled=1 WHERE kind='ask'")
        block()


def test_stale_holds_raise_one_trigger_per_new_set_and_legacy_holds_count(env):
    p = make(env)
    from ttp import anchors
    from ttp import coordinator as coord
    from ttp import unblock
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    now = time.time()
    legacy = _hold_task(p, "legacy hold")
    p.db.update_task(legacy, status="blocked", blocked_reason="until the user confirms")
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (now - 20 * 3600, legacy))
    fresh = _hold_task(p, "fresh hold")
    p.db.update_task(fresh, status="blocked", blocked_reason="needs a look")
    anchored = _hold_task(p, "anchored")
    p.db.update_task(anchored, status="blocked", labels=[f"waits:until:{now + 3600:.0f}"])
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (now - 30 * 3600, anchored))

    def stale_events():
        return p.db.q("SELECT * FROM events WHERE kind=?", (anchors.STALE_EVENT,))
    d.sweep_holds()
    d.sweep_holds()
    evs = stale_events()
    assert len(evs) == 1 and f"#{legacy} legacy hold" in evs[0]["text"] and f"#{fresh} " not in evs[0]["text"]
    assert evs[0]["status"] == "queued"
    labels, _ = coord.effort_triggers(p.db, p.config(), [evs[0]["id"]], None)
    assert anchors.TRIGGER in labels
    # A spec edit does not make the old hold look new.
    assert coord.apply(p, [{"type": "task_update", "id": legacy, "spec": "more detail"}]) == []
    d.sweep_holds()
    assert len(stale_events()) == 1
    # A user message after a hold makes it stale too: a new set, one more trigger.
    p.db.post("in", "the board is back", chat="c1")
    d.sweep_holds()
    d.sweep_holds()
    evs = stale_events()
    assert len(evs) == 2 and f"#{fresh} fresh hold" in evs[1]["text"] and "the user wrote since" in evs[1]["text"]
    # A set that only shrinks raises nothing; the anchored hold never counts.
    p.db.update_task(fresh, status="cancelled")
    d.sweep_holds()
    assert len(stale_events()) == 2 and all(f"#{anchored} " not in e["text"] for e in stale_events())
    line = next(x for x in unblock.lines(p.db) if x.startswith("holds with no anchor"))
    assert line.endswith(f"1: #{legacy} 20.0 h")


def test_a_replayed_free_text_hold_13h_old_with_no_ask_gives_exactly_one_trigger(env):
    p = make(env)
    from ttp import anchors
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    tid = _hold_task(p, "deploy after confirmation")
    # The hold as an older release let the coordinator make it: free text, no ask, no end.
    p.db.update_task(tid, status="blocked", blocked_reason="blocked until the user confirms the deploy")
    p.db.x("UPDATE tasks SET updated=? WHERE id=?", (time.time() - 13 * 3600, tid))
    assert not p.db.one("SELECT id FROM messages WHERE kind='ask' AND handled=0")
    d = Daemon(p.base)
    for _ in range(5):
        d.sweep_holds()
    evs = p.db.q("SELECT * FROM events WHERE kind=?", (anchors.STALE_EVENT,))
    assert len(evs) == 1 and f"#{tid} deploy after confirmation (held 13.0h" in evs[0]["text"]
    labels, _ = coord.effort_triggers(p.db, p.config(), [e["id"] for e in evs], None)
    assert labels.count(anchors.TRIGGER) == 1
    assert "anchored" not in labels
    Daemon(p.base).sweep_holds()   # a restarted daemon does not raise it again
    assert len(p.db.q("SELECT id FROM events WHERE kind=?", (anchors.STALE_EVENT,))) == 1


def test_live_check_judges_codex_steer_by_the_hook_its_run_got(env, monkeypatch, tmp_path):
    # Codex has no fixed steer_hook: a build with hooks on gets ttp.hook per run, so the steer check
    # passes or fails on what the run did; without hooks it stays unsupported.
    from ttp import live
    worker, _, _ = _codex_hooks(monkeypatch, tmp_path)
    prov, argv = worker()
    assert not getattr(prov, "steer_hook", False) and live.hook_used(argv)
    st = lambda **kw: live.judge(prov, _live_ev(**kw))["steer"][0]
    assert st(hook_used=True) == "pass" and st(hook_used=True, steer_delivered=False) == "fail"
    assert st(hook_used=False) == "unsupported"
    off, _, _ = _codex_hooks(monkeypatch, tmp_path, features="hooks  stable  false\n")
    assert not live.hook_used(off()[1])


def test_command_watcher_output_is_parsed_per_line():
    from ttp import daemon
    out = daemon._observations('starting\n{"text": "a down", "severity": "high"}\n{bad json\n'
                               '{"text": "b ok"}\ntail one\ntail two\n')
    assert out == [{"text": "starting"}, {"text": "a down", "severity": "high"}, {"text": "{bad json"},
                   {"text": "b ok"}, {"text": "tail one\ntail two"}]
    assert daemon._observations("just\nplain") == [{"text": "just\nplain"}]
    assert daemon._observations("") == []


def test_normalize_masks_compound_and_decimal_durations():
    from ttp import screen
    for a, b in [("up 18h52m", "up 3h07m"), ("in 1d2h", "in 4d11h"), ("took 3m20s", "took 1m5s"),
                 ("1.5h ago", "0.25h ago"), ("wait 250ms", "wait 12ms")]:
        assert screen.normalize(a) == screen.normalize(b), a
    assert screen.normalize("host03 t48 gpu1") == "host03 t48 gpu1"


def _fake_ttp(tmp_path, rc, out):
    """A `ttp` on an absolute path that prints `out` and exits `rc` (a devq probe's verdict)."""
    b = tmp_path / "fakebin"
    b.mkdir(exist_ok=True)
    (b / "ttp").write_text(f"#!/bin/sh\necho '{out}'\nexit {rc}\n")
    (b / "ttp").chmod(0o755)
    return str(b / "ttp")


def _reprobe(d, tid):
    """Run its probe again ahead of its timer (as every PROBE_EVERY_S)."""
    d._probed.pop(tid, None)
    d.p.db.update_task(tid, not_before=time.time() + 900)
    _settle_probe(d, tid)


def test_a_devq_probe_finding_its_runner_down_restarts_it_model_free_and_the_task_sleeps_on(env, tmp_path):
    from ttp import waitheal
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    d.cfg.setdefault("device", {})["runner_restarts_per_day"] = 2
    calls = []
    d._devq_start = lambda runner: (calls.append(runner), (0, "started runner"))[1]
    probe = f"{_fake_ttp(tmp_path, 3, 'r1-1: queued, but no runner is alive (runner down)')} devq probe r1 r1-1"
    tid = _due_waiting_task(p, probe)
    _settle_probe(d, tid)
    assert calls == ["r1"] and not _ready(p, tid), "restarted, and the task sleeps on (exit 3 is not yet)"
    ev = p.db.q("SELECT * FROM events WHERE kind='devq_runner_restarted'")
    assert len(ev) == 1 and ev[0]["status"] == "handled" and ev[0]["task"] == tid
    assert not p.db.q("SELECT id FROM runs"), "no model run"
    _reprobe(d, tid)
    assert calls == ["r1"], "at most once per 10 min per runner"
    st = p.db.kv(waitheal.RUNNER_RESTARTS_KEY)
    p.db.set_kv(waitheal.RUNNER_RESTARTS_KEY, {"r1": {**st["r1"], "last": time.time() - 601}})
    _reprobe(d, tid)
    assert calls == ["r1", "r1"]
    st = p.db.kv(waitheal.RUNNER_RESTARTS_KEY)
    p.db.set_kv(waitheal.RUNNER_RESTARTS_KEY, {"r1": {**st["r1"], "last": time.time() - 601}})
    _reprobe(d, tid)
    assert calls == ["r1", "r1"], "the day's cap"
    fix = p.db.q("SELECT * FROM tasks WHERE kind='harness' AND title LIKE 'Fix device runner r1:%'")
    assert len(fix) == 1 and "2 restarts today" in fix[0]["title"]
    assert p.db.one("SELECT COUNT(*) n FROM messages WHERE ref='devq_runner:r1' AND severity='low'")["n"] == 1
    _reprobe(d, tid)
    assert len(p.db.q("SELECT id FROM tasks WHERE kind='harness'")) == 1 and not _ready(p, tid)


def test_a_runner_restart_failing_twice_posts_one_low_line_and_queues_one_fix_task(env, tmp_path):
    from ttp import waitheal
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    d._devq_start = lambda runner: (1, "health gate failed")
    tid = _due_waiting_task(p, f"{_fake_ttp(tmp_path, 3, 'no runner is alive')} devq probe r2 r2-1")
    for i in range(3):
        if i:
            st = p.db.kv(waitheal.RUNNER_RESTARTS_KEY)
            p.db.set_kv(waitheal.RUNNER_RESTARTS_KEY, {"r2": {**st["r2"], "last": time.time() - 601}})
        _reprobe(d, tid)
        lines = p.db.one("SELECT COUNT(*) n FROM messages WHERE ref='devq_runner:r2'")["n"]
        assert lines == (0 if i == 0 else 1), i
    fix = p.db.q("SELECT * FROM tasks WHERE kind='harness'")
    assert len(fix) == 1 and "health gate failed" in fix[0]["spec"] and f"#{tid}" in fix[0]["spec"]
    assert not _ready(p, tid)


def test_an_outside_user_probe_stays_not_yet_and_restarts_nothing(env, tmp_path):
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    calls = []
    d._devq_start = lambda runner: (calls.append(runner), (0, ""))[1]
    tid = _due_waiting_task(p, f"{_fake_ttp(tmp_path, 1, 'an outside device user still runs')} devq probe r3 r3-1")
    _settle_probe(d, tid)
    assert not calls and not _ready(p, tid)
    # Exit 3 from any other probe is not a runner down: the probe is broken and wakes its task.
    tid2 = _due_waiting_task(p, f"{_fake_ttp(tmp_path, 3, 'x')} devq probe r3 r3-1 && true")
    _settle_probe(d, tid2)
    assert not calls and d._probe_rc[tid2][0] == 3


def _never(p, tid):
    return p.db.q("SELECT * FROM events WHERE kind='probe_never_passes' AND task=?", (tid,))


def test_probes_that_can_never_pass_are_flagged_once_per_wait(env, tmp_path):
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    assert coord.EFFORT_EVENT_TRIGGERS["probe_never_passes"] == "stuck"
    missing = _due_waiting_task(p, "no-such-command-xyz --check")
    _settle_probe(d, missing)
    ev = _never(p, missing)
    assert len(ev) == 1 and "not found (exit 127)" in ev[0]["text"] and ev[0]["status"] == "queued"
    assert "no-such-command-xyz" in ev[0]["text"] and f"set-when {missing}" in ev[0]["text"]
    gone = _due_waiting_task(p, f"test -e {p.runs}/99999/done")
    (p.runs / "88888").mkdir(parents=True, exist_ok=True)
    live = _due_waiting_task(p, f"test -e {p.runs}/88888/done")
    for t in (gone, live):
        _settle_probe(d, t)
        _reprobe(d, t)
    assert len(_never(p, gone)) == 1 and "99999" in _never(p, gone)[0]["text"]
    assert not _never(p, live), "a missing marker in a live run dir is the normal wait"
    unknown = _due_waiting_task(p, f"{_fake_ttp(tmp_path, 1, 'j: unknown to the runner in /x')} devq probe r j")
    _settle_probe(d, unknown)
    assert len(_never(p, unknown)) == 1 and "unknown to its runner" in _never(p, unknown)[0]["text"]


def test_a_probe_that_exits_0_wakes_its_task_and_is_never_flagged(env, tmp_path):
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    # devq's own probe exits 0 for a job unknown to its runner: the task wakes, with no extra event.
    unknown = _due_waiting_task(p, f"{_fake_ttp(tmp_path, 0, 'j: unknown to the runner in /x')} devq probe r j")
    _settle_probe(d, unknown)
    assert _ready(p, unknown) and not _never(p, unknown)
    # The same for any probe that passes, even one naming a run dir that is gone.
    gone = _due_waiting_task(p, f"test -e {p.runs}/99999/done || true")
    _settle_probe(d, gone)
    assert _ready(p, gone) and not _never(p, gone)


def test_wait_stale_shows_the_gate_and_flags_same_output_while_a_named_task_has_ended(env):
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    other = p.db.add_task("build", "s", kind="work", tier="light", origin="user")
    p.db.update_task(other, status="done")
    probe = f"echo 'still waiting on #{other}'; exit 1"
    tid = _due_waiting_task(p, probe, since_ago=30000)
    _settle_probe(d, tid)
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()   # its timer runs out on a fresh not yet past the cap
    stale = p.db.q("SELECT * FROM events WHERE kind='wait_stale' AND task=?", (tid,))
    assert len(stale) == 1 and f"Blocking gate: {probe}" in stale[0]["text"]
    assert f"last output: still waiting on #{other}" in stale[0]["text"] and "keeps sleeping" in stale[0]["text"]
    assert not _never(p, tid), "the same output only just started"
    text, _, pr = d._probe_out[tid]
    d._probe_out[tid] = (text, time.time() - 22000, pr)
    d._flag_never_passes(p.db.task(tid), probe, 1, text, stale=True)   # as at its next wait_stale check
    ev = _never(p, tid)
    assert len(ev) == 1 and f"#{other} (done)" in ev[0]["text"] and not _ready(p, tid)


def test_a_start_when_that_waits_for_hours_on_a_device_resource_raises_one_event(env):
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    p = make(env)
    d = Daemon(p.base)
    assert coord.EFFORT_EVENT_TRIGGERS["start_resource_stale"] == "resource"
    old = time.time() - 4 * 3600
    dev = p.db.add_task("run", "s", kind="work", tier="light", origin="user",
                        labels=["start_when:false", f"deferred_since:{old}", "resource:device"])
    plain = p.db.add_task("run", "s", kind="work", tier="light", origin="user",
                          labels=["start_when:false", f"deferred_since:{old}", "resource:disk"])
    fresh = p.db.add_task("run", "s", kind="work", tier="light", origin="user",
                          labels=["start_when:false", f"deferred_since:{time.time()}", "exclusive:serving"])
    for _ in range(2):
        for t in (dev, plain, fresh):
            d._start_verdict(p.db.task(t), 1, time.time())
    ev = p.db.q("SELECT * FROM events WHERE kind='start_resource_stale'")
    assert [e["task"] for e in ev] == [dev] and "device" in ev[0]["text"] and "Blocking gate: false" in ev[0]["text"]
    d.cfg["waiting"]["start_resource_stale_s"] = 0
    d._start_verdict(p.db.task(fresh), 1, time.time() + 5 * 3600)
    assert len(p.db.q("SELECT * FROM events WHERE kind='start_resource_stale'")) == 1, "0 turns it off"


# Heal checks (runtime/ttp/heal.py) ----------------------------------------------------------------
def _heal_setup(env, **block):
    from ttp import daemon as dm
    from ttp import schedule as sched
    p = make(env)
    up = p.root / "svc-up"
    heal_block = {"check": f"test -e {up}", "fix": f"touch {up}", "grace_s": 0, "settle_s": 0, **block}
    sched.upsert(p.db, "svc", "command", "5m", payload={"heal": heal_block})
    return p, dm.Daemon(p.base), up


def _heal_spec(p):
    from ttp import heal
    return heal.of(json.loads(p.db.one("SELECT payload FROM schedules WHERE name='svc'")["payload"]))


def test_heal_block_is_validated_in_the_file_and_schedule_set(env):
    from ttp import heal
    from ttp import schedule as sched
    with pytest.raises(ValueError, match="needs `check`"):
        heal.validate({"fix": "x"})
    with pytest.raises(ValueError, match="unknown key"):
        heal.validate({"check": "true", "unit": "x"})
    with pytest.raises(ValueError, match="needs `unit`"):
        heal.validate({"preset": "systemd"})
    s = heal.validate({"preset": "systemd", "unit": "w.service", "user": True, "host": "box-a"})
    assert s["fix"] == "ssh -o BatchMode=yes box-a 'systemctl --user restart w.service'" and s["max_fixes"] == 3
    ok = [{"name": "svc", "kind": "command", "every": "5m", "payload": {"heal": {"check": "true"}}}]
    assert sched.parse_file(json.dumps(ok))
    with pytest.raises(ValueError, match="only a command schedule"):
        sched.parse_file(json.dumps([dict(ok[0], kind="llm")]))
    with pytest.raises(ValueError, match="grace_s"):
        sched.parse_file(json.dumps([dict(ok[0], payload={"heal": {"check": "true", "grace_s": -1}})]))
    p = make(env)
    from ttp import coordinator as coord
    coord.apply(p, [{"type": "schedule_set", "name": "svc", "kind": "command", "every": "5m",
                             "heal": {"check": "true", "fix": "true"}}])
    assert json.loads(p.db.one("SELECT payload FROM schedules WHERE name='svc'")["payload"])["heal"]["fix"] == "true"


def test_heal_dead_service_is_fixed_without_coordinator_turns_or_asks(env):
    from ttp import daemon as dm
    from ttp import heal
    p, d, up = _heal_setup(env)
    p.db.x("UPDATE schedules SET next_run=0 WHERE name='svc'")
    fp, events = dm.wake_fingerprint(p, {}), p.db.one("SELECT COUNT(*) n FROM events")["n"]
    tasks, msgs = p.db.q("SELECT id, status FROM tasks"), p.db.one("SELECT COUNT(*) n FROM messages")["n"]
    d.run_schedules()
    assert up.exists() and heal.state(p.db, "svc")["phase"] == "settling"
    assert p.db.one("SELECT next_run FROM schedules WHERE name='svc'")["next_run"] <= time.time()
    d.run_schedules()   # the settle recheck
    row = p.db.one("SELECT last_status FROM schedules WHERE name='svc'")
    assert row["last_status"] == "fixed (1 today)"
    assert heal.state(p.db, "svc")["status"] == "healthy"
    assert p.db.q("SELECT id, status FROM tasks") == tasks, p.db.q("SELECT id, title, origin FROM tasks")
    assert p.db.one("SELECT COUNT(*) n FROM messages")["n"] == msgs + 1   # the info line only
    assert not p.db.q("SELECT id FROM messages WHERE kind IN ('ask','alert')")
    assert p.db.one("SELECT COUNT(*) n FROM events")["n"] == events
    assert not p.db.q("SELECT id FROM runs WHERE role='coordinator'")
    assert dm.wake_fingerprint(p, {}) == fp
    info = p.db.q("SELECT text, severity FROM messages WHERE kind='info'")
    assert len(info) == 1 and info[0]["severity"] == "low" and "Self-healed svc" in info[0]["text"]
    assert heal.digest_lines(p.db, 0) == ["## Self-healed (nothing to do): fixed svc, 1 today"]
    assert heal.line(p.db) == "health: 1 ok, 1 fixed today, 0 failing"


def test_heal_grace_unknown_and_broken_check_never_fix(env):
    from ttp import heal
    p, d, up = _heal_setup(env, grace_s=300)
    spec, now = _heal_spec(p), time.time()
    assert heal.run(d, "svc", spec, now) == ("unhealthy (0 s, grace 300 s)", now + 300)
    assert heal.run(d, "svc", spec, now + 100)[0] == "unhealthy (100 s, grace 300 s)" and not up.exists()
    for rc, status in ((75, "ok (unknown, rc 75)"), (255, "ok (unknown, rc 255)")):
        assert heal.run(d, "svc", dict(spec, check=f"exit {rc}"), now + 400) == (status, None)
    assert heal.run(d, "svc", dict(spec, check="exit 2"), now + 400)[0].startswith("error: heal check exited 2")
    assert not up.exists() and heal.summary(p.db)["unknown"] == 1
    up.touch()
    assert heal.run(d, "svc", spec, now + 500) == ("ok (healthy)", None)   # healthy clears, no fix recorded
    st = heal.state(p.db, "svc")
    assert st["status"] == "healthy" and "since" not in st and "unknown_since" not in st
    assert heal.fixed_today(p.db) == 0
    up.unlink()
    assert heal.run(d, "svc", spec, now + 600)[0] == "unhealthy (0 s, grace 300 s)"   # a new stint


def test_heal_cap_then_one_self_fix_task_then_outage_alert_that_clears(env):
    from ttp import alerts, heal
    p, d, up = _heal_setup(env, max_fixes=2, window_h=1)
    spec, now = _heal_spec(p), time.time()
    for i in range(2):   # it dies again after each fix
        assert heal.run(d, "svc", spec, now + i * 10)[0] == "unhealthy (fixed; rechecking)"
        assert heal.run(d, "svc", spec, now + i * 10 + 1)[0] == "fixed (%d today)" % (i + 1)
        up.unlink()
    status, _ = heal.run(d, "svc", spec, now + 30)
    assert "cap" in status and not up.exists()
    t = p.db.one("SELECT * FROM tasks WHERE origin='daemon'")
    assert t["priority"] == 1 and json.loads(t["labels"]) == ["heal:svc"] and "test -e" in t["spec"]
    assert heal.run(d, "svc", spec, now + 40)[0] == f"unhealthy (self-fix task #{t['id']} open)"
    assert p.db.one("SELECT COUNT(*) n FROM tasks WHERE origin='daemon'")["n"] == 1
    assert not p.db.q("SELECT id FROM messages WHERE kind='alert'")
    p.db.update_task(t["id"], status="failed")
    assert "alerted" in heal.run(d, "svc", spec, now + 50)[0]
    heal.run(d, "svc", spec, now + 60)
    al = p.db.q("SELECT * FROM messages WHERE kind='alert'")
    assert len(al) == 1 and al[0]["severity"] == "high" and al[0]["ref"] == "heal:svc"
    assert alerts.holds(p.db, "heal:svc", now, now + 60)
    assert p.db.one("SELECT COUNT(*) n FROM tasks WHERE origin='daemon'")["n"] == 1
    up.touch()
    assert heal.run(d, "svc", spec, now + 70)[0] == "ok (healthy)"
    assert [e["key"] for e in alerts.sweep(p.db)] == ["heal:svc"]
    assert "passes again" in p.db.one("SELECT text FROM messages WHERE kind='resolved'")["text"]


def _heal_to_self_fix_failed(p, d, up, spec, now):
    """Drive the check (no fix) to its self-fix task, then fail that task."""
    from ttp import heal
    assert "it has no fix" in heal.run(d, "svc", spec, now)[0]
    tid = heal.state(p.db, "svc")["task"]
    p.db.update_task(tid, status="failed")
    return tid


def test_heal_escalate_user_alerts_and_coordinator_observes_once_per_episode(env):
    from ttp import heal
    p, d, up = _heal_setup(env, fix=None)
    spec, now = _heal_spec(p), time.time()
    assert heal.escalate_to(d, spec) == "user"
    tid = _heal_to_self_fix_failed(p, d, up, spec, now)
    assert "alerted" in heal.run(d, "svc", spec, now + 10)[0]
    assert [a["ref"] for a in p.db.q("SELECT ref FROM messages WHERE kind='alert'")] == ["heal:svc"]
    assert not p.db.q("SELECT id FROM events WHERE fingerprint LIKE 'heal:%'")
    up.touch()
    heal.run(d, "svc", spec, now + 20)
    up.unlink()
    p.db.x("DELETE FROM messages WHERE kind='alert'")

    co = dict(spec, escalate="coordinator")
    t0 = now + 100
    tid2 = _heal_to_self_fix_failed(p, d, up, co, t0)
    assert tid2 != tid
    for i in range(3):   # repeated runs in one episode add nothing
        assert "coordinator told" in heal.run(d, "svc", co, t0 + 10 + i)[0]
    ev = p.db.q("SELECT * FROM events WHERE fingerprint LIKE 'heal:%'")
    assert len(ev) == 1 and ev[0]["kind"] == "observation" and ev[0]["severity"] == "high"
    assert ev[0]["status"] == "queued" and ev[0]["fingerprint"] == f"heal:svc:{t0:.0f}" and "svc" in ev[0]["text"]
    assert not p.db.q("SELECT id FROM messages WHERE kind='alert'"), "coordinator mode alerted the user"
    st = heal.state(p.db, "svc")
    st.pop("observed")   # a lost state flag still finds the episode's event
    heal._save(p.db, "svc", st)
    heal.run(d, "svc", co, t0 + 20)
    assert len(p.db.q("SELECT id FROM events WHERE fingerprint LIKE 'heal:%'")) == 1

    up.touch()   # healthy ends the episode; the next one is told again
    heal.run(d, "svc", co, t0 + 30)
    up.unlink()
    t1 = t0 + 200
    _heal_to_self_fix_failed(p, d, up, co, t1)
    heal.run(d, "svc", co, t1 + 10)
    fps = [e["fingerprint"] for e in p.db.q("SELECT fingerprint FROM events WHERE fingerprint LIKE 'heal:%' ORDER BY id")]
    assert fps == [f"heal:svc:{t0:.0f}", f"heal:svc:{t1:.0f}"]
    assert not p.db.q("SELECT id FROM messages WHERE kind='alert'")


@pytest.mark.parametrize("change", ["coordinator", "project_default", "known_fault", "finding_known_fault"])
@pytest.mark.parametrize("run_check", [False, True])
def test_heal_config_change_closes_an_existing_user_alert(env, change, run_check):
    from ttp import alerts, heal
    from ttp.web import attention
    finding = change == "finding_known_fault"
    p, d, up = _heal_setup(env, fix=None, outage=finding,
                          check="echo 'ttp-heal: not-outage'; exit 1" if finding else "exit 1")
    spec, now = _heal_spec(p), time.time()
    _heal_to_self_fix_failed(p, d, up, spec, now)
    heal.run(d, "svc", spec, now + 1)
    assert len(attention(p.db, now + 1)) == 1
    payload = json.loads(p.db.one("SELECT payload FROM schedules WHERE name='svc'")["payload"])
    if change == "project_default":
        p.set_config("heal.escalate", "coordinator")
        d.cfg = p.config()
    else:
        payload["heal"]["escalate" if change == "coordinator" else "known_fault"] = (
            "coordinator" if change == "coordinator" else "vendor bug")
        p.db.x("UPDATE schedules SET payload=? WHERE name='svc'", (json.dumps(payload),))
    # Readers hide it immediately, even before the next scheduled check or daemon sweep.
    assert attention(p.db, now + 2) == []
    if run_check:
        heal.run(d, "svc", _heal_spec(p), now + 2)
    alerts.sweep(p.db, now + 3)
    ep = _episodes(p, "heal:svc")[0]
    assert ep["cleared"] and ("coordinator" if change in ("coordinator", "project_default") else "known_fault") in ep["cleared_why"]
    assert heal.state(p.db, "svc")["status"] == "unhealthy", "closing a user alert does not repair the check"
    resolved = p.db.q("SELECT text FROM messages WHERE kind='resolved'")
    assert len(resolved) == 1 and "passes again" not in resolved[0]["text"]
    for dt in (4, 5):
        heal.run(d, "svc", _heal_spec(p), now + dt)
        alerts.sweep(p.db, now + dt)
    assert len(p.db.q("SELECT id FROM messages WHERE kind='resolved'")) == 1
    assert len(_episodes(p, "heal:svc")) == 1
    if change in ("coordinator", "project_default"):
        assert len(p.db.q("SELECT id FROM events WHERE fingerprint LIKE 'heal:%'")) == 1
    else:
        assert not {"task", "escalated", "alerted", "observed"} & set(heal.state(p.db, "svc"))


@pytest.mark.parametrize("unknown", [False, True])
def test_heal_known_fault_does_not_close_a_real_outage_alert(env, unknown):
    from ttp import alerts, heal
