def test_machine_change_ledger_add_list_overdue_and_close(env, capsys):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp.cli import main
    p = make(env)
    mm.add("box-a", tags="device")
    now = time.time()
    with pytest.raises(ValueError, match="give an end"):
        ml.add_change("box-a", "drop-in", "rm it", "demo")
    with pytest.raises(ValueError, match="no machine"):
        ml.add_change("box-z", "drop-in", "rm it", "demo", expires="2h")
    main(["machines", "change", "add", "box-a", "disabled auto power cycle for a soak", "--undo",
          "enable-power-cycle", "--expires", "2h", "--by", "demo"])
    assert "recorded #1 box-a: disabled auto power cycle for a soak (by demo; undo: `enable-power-cycle`" \
        in capsys.readouterr().out
    probe = ml.add_change("box-a", "paused the queue", "resume-queue", "demo", until_probe="exit 0", now=now)
    assert probe["expires"] == pytest.approx(now + ml.PROBE_END_S)
    main(["machines", "change", "list"])
    out = capsys.readouterr().out
    assert "#1 box-a" in out and "#2 box-a: paused the queue" in out and "OVERDUE" not in out
    main(["machines", "change", "add", "box-a", "power-cycled the tray", "--undo", "none", "--expires", "1h",
          "--by", "demo", "--expect", "down", "--expect", "fp-tray"])
    assert "expects down, fp-tray)" in capsys.readouterr().out and ml.changes()[2]["expects"] == ["down", "fp-tray"]
    assert "expects" not in ml.changes()[0], "no --expect, no expects: the change explains no alert"
    ml.close_change(3, "test", "demo")
    first = ml.changes()[0]
    assert ml.overdue(first, now + 3 * 3600).startswith("expired") and not ml.overdue(first, now)
    assert ml.overdue(probe, now + ml.PROBE_END_S + 1).startswith("expired")
    # The until-probe runs in the daemon of the project that made the entry; exit 0 makes it overdue.
    other = ml.Probes(type("P", (), {"name": "else", "root": p.root})())
    other.tick(now)
    assert not other._procs, "another project's daemon runs only its own entries' probes"
    probes = ml.Probes(p)
    probes.tick(now)
    proc = probes._procs[2][0]
    proc.wait(timeout=10)
    probes.tick(now + 1)
    assert ml.overdue(ml.changes()[1], now + 1) == "its until-probe passed"
    main(["machines", "change", "close", "2", "--why", "resumed", "--by", "demo"])
    assert [c["id"] for c in ml.changes()] == [1]
    assert ml.changes(open_only=False)[1]["closed_why"] == "resumed"
    with pytest.raises(SystemExit):
        main(["machines", "change", "close", "2"])


def test_machine_change_edit_corrects_an_open_entry_in_place(env, capsys):
    """`ttp machines change edit <id>` corrects an open entry's text, undo command or end in place: same id,
    alias, author and creation time, an edit trail with the old values; a new end drops its overdue pages.
    It refuses unknown or closed ids, a power cycle's undo or end, and an edit that changes nothing."""
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp.cli import main
    make(env)
    mm.add("box-a", tags="device")
    now = time.time()
    first = ml.add_change("box-a", "drop-in", "rm it", "alpha", expires="1h", now=now - 7200)
    ml.add_change("box-a", "second", "undo-2", "alpha", expires="2h", now=now)
    main(["machines", "change", "edit", "1", "--undo", "rm /etc/x.conf && reload", "--by", "beta"])
    assert "edited #1 box-a: drop-in (by alpha; undo: `rm /etc/x.conf && reload`" in capsys.readouterr().out
    c = ml.changes()[0]
    assert (c["id"], c["alias"], c["by"], c["added"]) == (1, "box-a", "alpha", first["added"])
    assert c["edits"][0]["by"] == "beta" and c["edits"][0]["was"] == {"undo": "rm it"}
    ml.edit_change(1, "beta", what="drop-in for a soak", now=now)
    c = ml.changes()[0]
    assert c["what"] == "drop-in for a soak" and c["edits"][1] == {"at": now, "by": "beta", "was": {"what": "drop-in"}}
    # Overdue and paged: a new end starts afresh, without the old pages or probe result.
    with ml._locked():
        doc = ml._read(ml.LEDGER, {})
        doc["changes"][0].update(page={"stage": 1}, probe_passed=now)
        ml._write(ml.LEDGER, doc)
    assert ml.overdue(ml.changes()[0], now)
    ml.edit_change(1, "beta", expires="3h", now=now)
    c = ml.changes()[0]
    assert c["expires"] == pytest.approx(now + 3 * 3600) and "page" not in c and "probe_passed" not in c
    assert not ml.overdue(c, now) and c["edits"][2]["was"]["expires"] == pytest.approx(now - 3600)
    ml.edit_change(1, "beta", until_probe="test -e /tmp/done", now=now)
    c = ml.changes()[0]
    assert c["probe"] == "test -e /tmp/done" and c["expires"] == pytest.approx(now + ml.PROBE_END_S)
    assert c["edits"][3]["was"]["probe"] is None
    with pytest.raises(ValueError, match="nothing to change"):
        ml.edit_change(1, "beta", what="drop-in for a soak", until_probe="test -e /tmp/done", now=now + 60)
    with pytest.raises(ValueError, match="say what to change"):
        ml.edit_change(1, "beta")
    with pytest.raises(ValueError, match="cannot be empty"):
        ml.edit_change(1, "beta", undo="  ")
    with pytest.raises(ValueError, match="no machine change #9"):
        ml.edit_change(9, "beta", undo="x")
    ml.close_change(2, "undone")
    with pytest.raises(ValueError, match="#2 is closed"):
        ml.edit_change(2, "beta", undo="x")
    for bad in (["9", "--undo", "x"], ["2", "--undo", "x"], ["1", "--what", "drop-in for a soak"],
                ["1", "--expires", "1h", "--until-probe", "true"]):
        with pytest.raises(SystemExit):
            main(["machines", "change", "edit", *bad])
    pc = ml.add_power_cycle("box-a", "1h", "alpha", "firmware", now=now)
    with pytest.raises(ValueError, match="planned power cycle"):
        ml.edit_change(pc["id"], "beta", expires="2h")
    assert ml.edit_change(pc["id"], "beta", what="power-cycle intent: new firmware")["kind"] == ml.POWER_CYCLE
    assert [c["id"] for c in ml.changes()] == [1, pc["id"]] and ml._read(ml.LEDGER, {})["next"] == pc["id"] + 1


def test_an_edited_machine_change_overdue_again_pages_afresh_and_a_stale_probe_pass_is_ignored(env, monkeypatch):
    """A new end from `machine change edit` starts a new page episode: once it passes too, the overdue
    page has a new id, so the maker gets a new event rather than a duplicate of the delivered one. A
    probe started before an edit changed the probe does not count as the new probe passing."""
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp.daemon import Daemon
    alpha = make(env, "alpha")
    mm.add("box-a", tags="device")
    now = time.time()
    ml.add_change("box-a", "drop-in", "rm it", "alpha", expires="1h", now=now - 7200)
    d = Daemon(alpha.base)
    first = ml.route(now, able=lambda n: (True, ""), claimer="alpha")
    assert [x["kind"] for x in first] == ["machine_change_overdue"]
    assert d._machine_page(first[0], now)
    ml.delivered(first[0])
    ml.edit_change(1, "alpha", expires="1h", now=now + 60)
    assert ml.route(now + 120, able=lambda n: (True, "")) == []
    second = ml.route(now + 60 + 3601, able=lambda n: (True, ""), claimer="alpha")
    assert [x["kind"] for x in second] == ["machine_change_overdue"] and second[0]["id"] != first[0]["id"]
    assert d._machine_page(second[0], now + 3700)
    assert alpha.db.one("SELECT COUNT(*) n FROM events WHERE kind='machine_change_overdue'")["n"] == 2
    # A probe still running from before an edit to another probe: its pass is not the new probe's.
    ml.edit_change(1, "alpha", until_probe="true", now=now + 3700)
    probes = ml.Probes(alpha, log=lambda s: None)
    probes.tick(now + 3800)
    assert 1 in probes._procs
    ml.edit_change(1, "alpha", until_probe="test -e /nonexistent-ttp-probe", now=now + 3801)
    probes._procs[1][0].wait(10)
    probes._probed[1] = now + 3900   # not due again yet
    probes.tick(now + 3900)
    assert "probe_passed" not in ml.changes()[0], "the old probe's pass does not end the edited probe"


def test_a_planned_power_cycle_tells_running_workers_on_the_machine_to_hand_off_once(env, tmp_path, capsys,
                                                                                    monkeypatch):
    """`ttp machines change add <alias> "<why>" --power-cycle-at <t>` records a power-cycle intent (no
    undo, expects down only around T, never overdue, closes itself after). Shortly before T the daemon tells each running
    worker on that machine (a task resource on it, or every worker when it is this host), once, through
    its steer.md, to commit and hand off; workers elsewhere and runs outside the window hear nothing."""
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp.cli import main
    from ttp.daemon import Daemon
    p = make(env)
    mm.add("box-a", tags="device")
    mm.add("box-b", tags="device")
    for bad in (["--undo", "x"], ["--expires", "2h"]):
        with pytest.raises(SystemExit):
            main(["machines", "change", "add", "box-a", "firmware update", "--power-cycle-at", "1h", "--by", "demo", *bad])
    with pytest.raises(SystemExit):
        main(["machines", "change", "add", "box-a", "drop-in", "--expires", "1h", "--by", "demo"])
    capsys.readouterr()
    now = time.time()
    main(["machines", "change", "add", "box-a", "firmware update", "--power-cycle-at", "1h", "--by", p.name])
    assert "power-cycle intent, at " in capsys.readouterr().out
    c = ml.changes()[0]
    at = c["at"]
    assert c["kind"] == ml.POWER_CYCLE and c["expects"] == ["down"] and at == pytest.approx(now + 3600, abs=60)
    assert not ml.overdue(c, at + 10 * 86400), "a power cycle has nothing to undo: never overdue"
    on_a = p.db.add_task("device job", "s", kind="code", origin="user", labels=["resource:box-a-device"])
    on_b = p.db.add_task("other box", "s", kind="code", origin="user", labels=["resource:box-b-device"])
    runs = {}
    for t in (on_a, on_b):
        (tmp_path / str(t)).mkdir()
        runs[t] = p.db.x("INSERT INTO runs(task,role,started,status,dir) VALUES(?,?,?,?,?)",
                         (t, "worker", now, "running", str(tmp_path / str(t))))
    steer = {t: tmp_path / str(t) / "steer.md" for t in runs}
    monkeypatch.setattr(mm, "here", lambda known=None: None)
    d = Daemon(p.base)
    d.power_cycle_notices(at - ml.POWER_CYCLE_LEAD_S - 60)
    assert not any(f.exists() for f in steer.values()), "not yet: too early"
    d.power_cycle_notices(at - 120)
    d.power_cycle_notices(at - 60)
    text = steer[on_a].read_text()
    assert text.count("## Update") == 1, "told once"
    assert "box-a is to be power-cycled at" in text and f"machine change #{c['id']}" in text \
        and "hand off before then" in text
    assert not steer[on_b].exists(), "a worker on another machine is not told"
    monkeypatch.setattr(mm, "here", lambda known=None: ("box-a", {}))
    d.power_cycle_notices(at - 30)
    assert "this host is to be power-cycled" in steer[on_b].read_text(), "on this host every worker is told"
    assert steer[on_a].read_text().count("## Update") == 1
    ml.Probes(p).tick(at + ml.POWER_CYCLE_AFTER_S + 1)
    assert not ml.changes(), "the intent closes itself once its time is past"
    assert ml.changes(open_only=False)[0]["closed_why"] == "the planned power cycle is past"


def test_a_power_cycle_intent_quiets_a_down_only_in_its_window(env):
    """A power-cycle intent expects its machine down only from POWER_CYCLE_LEAD_S before T until its end:
    days before the cycle, or after it when nobody closed the entry, a down pages as usual (quiet_reason)
    and raises the coordinator (_known_case). Any daemon closes an intent past its end, not only the maker's."""
    from ttp import coordinator as coord
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    p = make(env)
    mm.add("box-a", tags="device")
    now = time.time()
    c = ml.add_power_cycle("box-a", "3d", "gone-project", "firmware", now=now)
    at, end = c["at"], c["expires"]
    down = {"alias": "box-a", "condition": "down", "seen_by": []}
    data = json.dumps({"machine": "box-a", "condition": "down"})
    eid = p.db.x("INSERT INTO events(ts,source,kind,fingerprint,severity,text,data,status) "
                 "VALUES(?,?,?,?,?,?,?,?)", (now, "daemon", "observation", "fp-down", "high", "x", data, "queued"))
    r = p.db.one("SELECT * FROM events WHERE id=?", (eid,))

    def quiet(t):
        return ml.quiet_reason(down, t)[0].startswith("expected from machine change")

    def known(t):
        return "expects it" in coord._known_case(p.db, r, 0, t)
    for t, want in ((now + 3600, False), (at - ml.POWER_CYCLE_LEAD_S - 1, False), (at - 60, True), (at, True),
                    (end - 1, True), (end + 1, False), (end + 30 * 86400, False)):
        assert (quiet(t), known(t)) == (want, want), (t - at, want)
    ml.Probes(p).tick(end + 1)
    assert not ml.changes(), "a daemon of another project closes the intent once it is past"


def _ledger_writer(home, n, k):
    from ttp import machine_ledger as ml
    for i in range(k):
        ml.add_change("box-a", f"change {n}.{i}", "undo", f"p{n}", expires="1h")


def test_machine_ledger_keeps_every_entry_from_concurrent_writers(env):
    import multiprocessing
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    mm.add("box-a", tags="device")
    ctx = multiprocessing.get_context("fork")
    procs = [ctx.Process(target=_ledger_writer, args=(env["home"], n, 10)) for n in range(4)]
    for pr in procs:
        pr.start()
    for pr in procs:
        pr.join(60)
        assert pr.exitcode == 0
    got = ml.changes()
    assert len(got) == 40 and sorted(c["id"] for c in got) == list(range(1, 41))
    assert {c["what"] for c in got} == {f"change {n}.{i}" for n in range(4) for i in range(10)}


def test_a_long_machine_condition_goes_to_its_owner_then_the_fallback_then_the_user(env):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    from ttp import upstream
    from ttp.daemon import Daemon
    alpha = make(env, "alpha")
    mm.add("box-a", tags="device")
    t0 = time.time()
    assert ml.report("gamma", "box-a", "down", "no answer to ssh", now=t0)
    assert not ml.report("gamma", "box-z", "down", now=t0)
    assert ml.route(t0 + 2 * 3600, able=lambda n: (True, "")) == [], "no owner set: nothing is routed"
    mm.set_recovery("box-a", owner="alpha", fallback="beta")
    t0 += 2 * 3600
    ml.report("gamma", "box-a", "down", "no answer to ssh", now=t0)
    ml.report("delta", "box-a", "down", now=t0 + 60)
    able = {"alpha": (False, "its daemon is stopped"), "beta": (False, "it is paused")}
    pages = ml.route(t0 + 120, able=able.get)
    assert [x["target"] for x in pages] == ["alpha"] and pages[0]["kind"] == "machine_condition"
    assert "box-a down" in pages[0]["text"] and "gamma, delta" in pages[0]["text"]
    assert ml.route(t0 + 180, able=able.get) == [], "a claimed page goes to one daemon"
    assert ml.delivered(pages[0]) and not ml.delivered(pages[0])
    assert ml.route(t0 + 180 + ml.UNAVAILABLE_S - 60, able=able.get) == [], "a delivered page is sent once"
    pages = ml.route(t0 + 180 + ml.UNAVAILABLE_S, able=able.get)
    assert [x["target"] for x in pages] == ["beta"] and "alpha cannot act: its daemon is stopped" in pages[0]["text"]
    ml.delivered(pages[0])
    ml.report("gamma", "box-a", "down", now=t0 + 3000)
    assert ml.route(t0 + 3000, able=able.get) == []
    pages = ml.route(t0 + 3000 + ml.UNAVAILABLE_S, able=able.get)
    assert [x["target"] for x in pages] == [ml.USER]
    ml.delivered(pages[0])
    assert ml.route(t0 + 3000 + 2 * ml.UNAVAILABLE_S, able=able.get) == []
    # Delivered: a high note in the owner's inbox from this daemon, an event at home, an outage alert.
    d = Daemon(alpha.base)
    d._machine_page({"target": "beta", "kind": "machine_condition", "key": "machine:box-a:down",
                     "alias": "box-a", "text": "Machine box-a down."}, t0)
    note = [json.loads(ln) for ln in upstream.path().read_text().splitlines()][-1]
    assert (note["to"], note["from"], note["severity"], note["project"]) == ("beta", "daemon", "high", "alpha")
    assert "from the daemon of alpha" in upstream._event(note)[1]
    d._machine_page({"target": "alpha", "kind": "machine_condition", "key": "machine:box-a:down",
                     "alias": "box-a", "text": "Machine box-a down."}, t0)
    ev = alpha.db.one("SELECT * FROM events WHERE kind='machine_condition'")
    assert ev["severity"] == "high" and ev["status"] == "queued"
    from ttp import coordinator as coord
    assert coord.EFFORT_EVENT_TRIGGERS["machine_condition"] == "resource"
    d._machine_page({"target": ml.USER, "kind": "machine_condition", "key": "machine:box-a:down",
                     "alias": "box-a", "text": "Machine box-a down."}, t0)
    assert "Outage: Machine box-a down." in alpha.db.one("SELECT text FROM alerts WHERE key='machine:box-a:down'")["text"]
    # A clear, or nobody reporting it for CONDITION_GONE_S, ends it.
    ml.report("gamma", "box-a", "down", cleared=True)
    assert ml.conditions() == {}
    ml.report("gamma", "box-a", "held", now=t0)
    ml.route(t0 + ml.CONDITION_GONE_S, able=able.get)
    assert ml.conditions() == {}
    # A command watcher's observation with `machine` and `condition` reports it.
    d._machine_condition({"machine": "box-a", "condition": "held", "grace_s": 60}, "hold never recovers")
    got = ml.conditions()["box-a:held"]
    assert (got["seen_by"], got["grace_s"], got["text"]) == (["alpha"], 60.0, "hold never recovers")


def test_can_act_reads_another_projects_state_without_writing_it(env):
    from ttp import machine_ledger as ml
    beta = make(env, "beta")
    db = beta.base / "state" / "project.db"
