def test_a_los_angeles_project_on_a_utc_box_shows_pdt_or_pst_in_every_surface(env, utc_box):
    """The process runs on UTC, the project's home zone is America/Los_Angeles: ttp status, the web
    app's JSON and its client-side clock, alert and wait texts and the coordinator's digest (what its
    chat replies are written from) all show Pacific time with its abbreviation, never UTC."""
    import shutil
    from ttp import alerts, anchors, waits, web
    from ttp import coordinator as coord
    from ttp.cli import status_text
    from ttp.db import host_line
    p = make(env)
    p.set_config("home_timezone", "America/Los_Angeles")
    db, now = p.db, time.time()
    pac = re.compile(r"\d\d:\d\d P[DS]T")
    db.set_kv("coordinator_failures", 2)
    db.set_kv("coordinator_backoff_until", now + 600)
    db.set_kv("limited:fake", {"until": now + 900, "note": "logged out"})
    tid = db.add_task("measure on a board", "needs a board", kind="work", tier="light", origin="user",
                      not_before=now + 1200)
    # ttp status: the clock in the head line, retry and pause times.
    out = status_text(p)
    for need in ("retry at", "fake paused until", "next try"):
        line = next(ln for ln in out.splitlines() if need in ln)
        assert pac.search(line.split(need, 1)[1]) and " UTC" not in line, line
    # The web app's JSON: the zone it formats in, and the lines the daemon writes for it.
    h = web.health(p, db, now=now)
    assert h["zone"] == "America/Los_Angeles" and web.state_payload(p, db)["project"]["zone"] == h["zone"]
    assert pac.search(h["why_idle"].split("next try", 1)[1]), h["why_idle"]
    assert pac.search(web.gate_detail({"regime": "windows", "numbers": {"window": "5h", "utilization": 4,
                                       "resets_at": now + 3600, "limit": 90}}, now, p))
    db.set_kv(alerts.BREAKER + "fake", {"open": True, "opened": now - 600, "next_check": now + 600})
    line = web.breaker_lines(db, now, p)[0]["line"]
    assert len(pac.findall(line)) == 2 and " UTC" not in line, line
    assert web.at(now + 60, now).endswith("UTC")    # no zone given: UTC, never the box's or a guess
    assert pac.search(host_line([{"ts": now - 60, "lost": []}], p))
    # Alert and wait texts with clock times.
    w = waits.wait_kind({"id": tid, "status": "blocked", "labels": json.dumps([f"waits:time:{now + 900:.0f}"]),
                         "blocked_reason": "", "updated": now}, [], now, p)
    assert re.search(r"P[DS]T$", w["text"]), w
    assert re.search(r"P[DS]T$", anchors.describe("until", str(now + 900), p))
    db.x("UPDATE tasks SET labels=? WHERE id=?", (json.dumps(coord.defer_labels(now + 3600, None)), tid))
    db.x("UPDATE tasks SET not_before=? WHERE id=?", (now + 3600, tid))
    assert pac.search(coord.starts_text(db.task(tid), now, plain=True, where=p))
    # The coordinator's digest, which its chat replies are written from, is stamped in the home zone.
    head = coord.digest(p, {}, [], []).splitlines()[0]
    assert re.match(r"# STATE at \d{4}-\d\d-\d\d \d\d:\d\d P[DS]T ", head), head
    # The web app formats on the client in the zone the daemon sends, not the browser's.
    js = (RUNTIME / "ttp" / "web" / "app.js").read_text()
    assert "toLocaleTimeString" not in js and "toLocaleString" not in js
    assert "ZONE = (st.project && st.project.zone)" in js
    node = shutil.which("node")
    if node:
        block = js[js.index("let ZONE"):js.index("\n", js.index("const at = "))]
        r = subprocess.run([node, "-e", block + "\nZONE = 'America/Los_Angeles';"
                            f"console.log(at({now + 60}), '|', at({now + 3 * 86400}))"],
                           capture_output=True, text=True, timeout=60, env={**os.environ, "TZ": "UTC"})
        assert r.returncode == 0, r.stderr
        assert re.fullmatch(r"\d\d:\d\d P[DS]T \| \w{3},? \d\d:\d\d P[DS]T\n", r.stdout), r.stdout


def test_run_notes_memory_ends_sweep_spend_and_deploy_times_use_the_home_zone_on_a_utc_box(env, utc_box, monkeypatch):
    """On a UTC box, a Los Angeles project's user-facing times carry PDT/PST, never UTC or 'Z': the run
    notes people read live (ttp note, notify, push and lock lines), a temporary memory's end in the
    prompts, the blocker sweep's deferred reason (digest and daily review), the account spend window
    and the deploy-behind alert after a push."""
    from datetime import datetime, timezone as dt_timezone
    from types import SimpleNamespace
    from ttp import cli, deploy, ends, push, sweep, timefmt
    from ttp import coordinator as coord
    pac = re.compile(r"\d\d:\d\d(:\d\d)? P[DS]T")
    p = make(env)
    p.set_config("home_timezone", "America/Los_Angeles")
    summer = datetime(2026, 7, 1, 12, 0, tzinfo=dt_timezone.utc).timestamp()
    # The formatter for live lines: the project in the environment, else UTC.
    assert timefmt.clock({"TTP_PROJECT": str(p.base)}, now=summer) == "05:00:00 PDT"
    monkeypatch.delenv("TTP_PROJECT", raising=False)
    assert timefmt.clock({}, now=summer) == "12:00:00 UTC"
    # Run notes: ttp note, ttp notify and a push's own note.
    run = env["home"] / "run-tz"
    run.mkdir(parents=True)
    monkeypatch.setenv("TTP_RUN_DIR", str(run))
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    cli.cmd_note(SimpleNamespace(text="milestone", to=None))
    cli.cmd_notify(SimpleNamespace(text="please review", severity="low"))
    push.run_note("pushed")
    notes = (run / "progress.md").read_text().splitlines()
    assert len(notes) == 3 and all(re.match(r"\d\d:\d\d:\d\d P[DS]T ", ln) for ln in notes), notes
    # A temporary memory's end, as the prompts show it; the file keeps its UTC stamp.
    end = {"expires": summer}
    assert ends.describe(end) == "ends 2026-07-01T12:00Z"
    assert ends.describe(end, p) == "ends 2026-07-01 05:00 PDT"
    (p.memory_dir / "fact-tz.md").write_text("---\nkind: fact\n" + ends.front_matter(end) + "---\nA box is lent out.\n")
    [line] = [e["line"] for e in p._memory_entries() if e["name"] == "fact-tz"]
    assert line.endswith("(ends 2026-07-01 05:00 PDT)") and "Z)" not in line, line
    # The blocker sweep's deferred reason, in the digest's settings and the daily review's project.
    now = time.time()
    tid = p.db.add_task("later", "spec", kind="work", not_before=now + 3600)
    p.db.x("UPDATE tasks SET labels=? WHERE id=?", (json.dumps(coord.defer_labels(now + 3600, None)), tid))
    for where in (p, p.config()):
        [item] = [i for i in sweep.items(p.db, now, where) if i["task"] == tid]
        assert item["reason"].startswith("starts after ") and pac.search(item["reason"]), item
        assert " UTC" not in item["reason"]
    assert "sweep.review_lines(db, where=self.p)" in (RUNTIME / "ttp" / "daemon.py").read_text()
    # A coordinator update in a run's steer.md (which workers quote) is stamped in the home zone.
    rd = p.runs / "9999"
    rd.mkdir(parents=True)
    coord._append_update(rd / "steer.md", "use the other board", "1.0")
    assert re.search(r"^## Update \d{4}-\d\d-\d\d \d\d:\d\d P[DS]T \(turn 1\.0\)$",
                     (rd / "steer.md").read_text(), re.M), (rd / "steer.md").read_text()
    # The deploy-behind alert an after_push's verdict raises.
    sent = []
    deploy._alert(p, {"name": "demo", "target": "9.9.9", "since": summer}, "behind", "files behind", summer + 7200,
                  alert=lambda key, text, **k: sent.append(text))
    assert "behind since 2026-07-01 05:00 PDT" in sent[0] and " UTC" not in sent[0], sent
    # The account spend window: the budget's zone, never the box's.
    monkeypatch.setattr(cli, "load_account_settings", lambda: {"budget": {"timezone": "America/Los_Angeles"}})
    import ttp.globalcap as gcap
    monkeypatch.setattr(gcap, "answer", lambda *a, **k: {"host": "h", "projects": [], "rows": [], "errors": []})
    out = io.StringIO()
    with contextlib.redirect_stdout(out):
        cli.cmd_spend_today(SimpleNamespace(receive=False, since=summer, until=None, json=False))
    assert out.getvalue().rstrip().endswith("since 2026-07-01 05:00 PDT"), out.getvalue()


def test_machine_ledger_and_pause_end_times_show_the_home_zone_on_a_utc_box(env, utc_box, monkeypatch):
    """Machine conditions ('since ...'), change and outage ends, and resource pause ends are in the
    home zone with its abbreviation: the project's when one is in hand, else the one in TTP_PROJECT."""
    from datetime import datetime, timezone as dt_timezone
    from ttp import ends, pauseends
    from ttp import machine_ledger as ml
    p = make(env)
    p.set_config("home_timezone", "America/Los_Angeles")
    summer = datetime(2026, 7, 1, 12, 0, tzinfo=dt_timezone.utc).timestamp()
    assert ends.shown(summer, p) == "2026-07-01 05:00 PDT"
    change = {"id": 1, "alias": "box", "what": "a drop-in", "undo": "rm it", "by": "t", "expires": summer}
    assert ml.change_line(change, summer + 60, p).endswith("ends 2026-07-01 05:00 PDT) OVERDUE: expired "
                                                          "2026-07-01 05:00 PDT")
    line = ml.outage_line("box", {"until": summer, "why": "maintenance"}, p)
    assert "until 2026-07-01 05:00 PDT" in line and "Z" not in line.split("(")[0], line
    assert pauseends.describe({"until": summer}, p) == "ends 2026-07-01 05:00 PDT"
    # No project in hand (a CLI line, the machine view): the project in the environment.
    monkeypatch.setenv("TTP_PROJECT", str(p.base))
    assert ends.shown(summer) == "2026-07-01 05:00 PDT"
    assert pauseends.describe({"until": summer}) == "ends 2026-07-01 05:00 PDT"
    src = (RUNTIME / "ttp" / "machine_ledger.py").read_text() + (RUNTIME / "ttp" / "pauseends.py").read_text()
    assert "ends.stamp(" not in src, "user-facing ledger and pause times go through ends.shown"


def test_mute_heal_and_lock_holder_times_show_the_home_zone_on_a_utc_box(env, utc_box):
    """Mute lines and their end summary, a heal check's self-fix task and lock holders (local and
    shared) are in the project's home zone with its abbreviation, never the box's UTC."""
    from types import SimpleNamespace
    from ttp import heal, locks, shared
    from ttp import screen as scr
    pac = re.compile(r"\d\d:\d\d P[DS]T")
    p = make(env)
    p.set_config("home_timezone", "America/Los_Angeles")
    now = time.time()
    scr.mute(p.db, "watcher:hw", "held", 1, now=now - 3600)
    with p.db.tx():
        [m] = p.db.kv(scr.MUTES_KEY)
        m.update(count=2, last_at=now - 600)
        p.db.set_kv(scr.MUTES_KEY, [m])
    line = scr.mute_line(m, now, p)
    assert pac.search(line.split("last at", 1)[1]) and " UTC" not in line, line
    assert scr.expire_mutes(p.db, now + 60, where=p)
    ended = p.db.one("SELECT text FROM events WHERE text LIKE 'mute ended:%'")["text"]
    assert pac.search(ended.split("last at", 1)[1]) and " UTC" not in ended, ended
    heal._escalate(SimpleNamespace(p=p), "svc", {"check": "false", "fix": "true"},
                   {"since": now - 7200, "last_rc": 1}, now, "the fix exited 1")
    spec = p.db.one("SELECT spec FROM tasks WHERE title LIKE 'Self-fix: heal check svc%'")["spec"]
    assert re.search(r"Unhealthy since \d{4}-\d\d-\d\d \d\d:\d\d P[DS]T\.", spec), spec
    assert "exit 75 (known outage, unknown) is the expected end state" in spec, spec
    assert "do not try to force a pass" in spec, spec
    p.set_config("shared_resources", ["board"])
    slots = {"own": p.state / "locks" / "dev.0.lock", "shared": shared.root() / "board" / "board.0.lock"}
    held = []
    try:
        for path in slots.values():
            path.parent.mkdir(parents=True, exist_ok=True)
            held.append(locks.try_take([path], "task #3 (run 9)", "x"))
        assert all(held)
        assert re.fullmatch(r"task #3 \(run 9\) since \d\d:\d\d P[DS]T", locks.holders([slots["own"]], p)[0])
        for who in shared.held(p) + locks.held(p.state / "locks", p):
            assert pac.search(who) and " UTC" not in who, who
        assert len(shared.held(p)) == 2, shared.held(p)
    finally:
        for f in held:
            if f:
                f.close()


def test_push_queue_backoff_shows_the_home_zone_on_a_utc_box(env, monkeypatch, utc_box):
    from ttp import pushq
    s = _pq(env, monkeypatch)
    _pq_review(s, priority=1)
    s.p.set_config("home_timezone", "America/Los_Angeles")
    now = time.time()
    s.p.db.set_kv(pushq.KV, {"backoff_until": now + 600})
    rows, why = pushq.due(s.p, now)
    assert rows == [] and re.fullmatch(r"backing off until \d\d:\d\d P[DS]T", why), why


def test_the_stall_observation_shows_the_home_zone_on_a_utc_box(env, monkeypatch, utc_box):
    p, d, now, check = _stall_setup(env, monkeypatch)
    p.set_config("home_timezone", "America/Los_Angeles")
    p.db.add_task("ready but never started", "s", kind="work", tier="light", origin="coordinator")
    p.db.x("UPDATE tasks SET created=?", (now - 6 * 3600,))
    check(now)
    [e] = check(now + 3 * 3600)
    assert re.search(r"last worker run started: \d{4}-\d\d-\d\d \d\d:\d\d P[DS]T\)", e["text"]), e["text"]


def test_a_remote_project_made_from_a_workstation_gets_the_workstations_zone(env, monkeypatch, capsys):
    """Workstation in America/Los_Angeles, box on UTC: the project there gets the workstation's zone."""
    from ttp import cli, machines, weblink
    monkeypatch.setenv("TTP_TEST_LOCAL_TZ", "America/Los_Angeles")
    monkeypatch.setattr(cli, "ship_runtime", lambda host: "~/.tt-project/lib/current/bin/ttp")
    monkeypatch.setattr(cli, "load_secrets", lambda: {})
    monkeypatch.setattr(machines, "push", lambda host: "machines: none")
    sent = []
    monkeypatch.setattr(cli.subprocess, "run", lambda argv, **k: sent.append(argv) or subprocess.CompletedProcess(
        argv, 0, "created far\n", None))
    monkeypatch.setattr(cli, "remote_web", lambda name, entry, out: ("web app: ok", 0))
    cli.main(["new", "far", "--host", "box", "--dir", "/srv/far"])
    remote = sent[-1][-1]
    assert "--home-tz America/Los_Angeles --home-from testhost" in remote, remote
    # What that command does on the box, whose own zone is UTC.
    monkeypatch.undo()
    monkeypatch.setenv("TTP_TEST_LOCAL_TZ", "UTC")
    monkeypatch.setattr(cli, "_wait_for_daemon", lambda p, timeout=20: None)
    monkeypatch.setattr(weblink, "local", lambda p, url: ("web app: ok", 0))
    cli.main(["new", "far", "--dir", str(env["repo"]), "--provider", "fake", "--no-service",
              "--home-tz", "America/Los_Angeles", "--home-from", "laptop"])
    from ttp.project import Project
    raw = Project(env["repo"]).raw_config()
    assert (raw["home_timezone"], raw["home_timezone_from"]) == ("America/Los_Angeles", "laptop")
    assert Project(env["repo"]).config()["budget"]["timezone"] == "America/Los_Angeles"


def test_a_remote_project_made_from_an_ssh_login_records_no_servers_zone(env, monkeypatch, capsys):
    """`ttp new --host` typed in an ssh login on a server sends no zone (the server's is not the user's);
    the box gives the project the fallback zone set by no machine, so no spend push moves it, and the
    workstation's next connect sets it."""
    from ttp import cli, machines, project, weblink
    from ttp import timefmt as tf
    monkeypatch.setenv("TTP_TEST_LOCAL_TZ", "Asia/Tokyo")   # the server the user is ssh'd into
    monkeypatch.setenv("SSH_CONNECTION", "10.0.0.1 1 10.0.0.2 22")
    monkeypatch.setattr(cli, "ship_runtime", lambda host: "~/.tt-project/lib/current/bin/ttp")
    monkeypatch.setattr(cli, "load_secrets", lambda: {})
    monkeypatch.setattr(machines, "push", lambda host: "machines: none")
    sent = []
    monkeypatch.setattr(cli.subprocess, "run", lambda argv, **k: sent.append(argv) or subprocess.CompletedProcess(
        argv, 0, "created far\n", None))
    monkeypatch.setattr(cli, "remote_web", lambda name, entry, out: ("web app: ok", 0))
    cli.main(["new", "far", "--host", "box", "--dir", "/srv/far"])
    remote = sent[-1][-1]
    assert "--home-tz" not in remote and "--home-from" not in remote, remote
    # What that command does on the box (zone UTC), also under ssh, with the account's zone set there.
    monkeypatch.undo()
    monkeypatch.setenv("TTP_TEST_LOCAL_TZ", "UTC")
    monkeypatch.setenv("SSH_CONNECTION", "10.0.0.2 1 10.0.0.3 22")
    monkeypatch.setattr(cli, "_wait_for_daemon", lambda p, timeout=20: None)
    monkeypatch.setattr(weblink, "local", lambda p, url: ("web app: ok", 0))
    project.set_account_setting("budget.timezone", "America/New_York")
    cli.main(["new", "far", "--dir", str(env["repo"]), "--provider", "fake", "--no-service"])
    from ttp.project import Project
    p = Project(env["repo"])
    raw = p.raw_config()
    assert raw["home_timezone"] == "America/New_York" and "home_timezone_from" not in raw, raw
    assert not tf.follow_push(p, "UTC", "testhost") and not tf.follow_push(p, "Asia/Tokyo", "server")
    assert p.raw_config()["home_timezone"] == "America/New_York"
    # The workstation's next connect sets it.
    monkeypatch.delenv("SSH_CONNECTION")
    cli.main(["connect", "far", "--home-tz", "America/Los_Angeles", "--home-from", "laptop"])
    raw = p.raw_config()
    assert (raw["home_timezone"], raw["home_timezone_from"]) == ("America/Los_Angeles", "laptop")


def _home_feed(p):
    return [m["text"] for m in p.db.q("SELECT text FROM messages WHERE direction='out' AND text LIKE 'Home time zone%'")]


def test_connect_from_a_workstation_in_a_new_zone_moves_the_home_zone_and_logs_it_once(env, monkeypatch, capsys):
    from ttp import cli, weblink
    p = make(env)
    monkeypatch.setattr(weblink, "local", lambda p, url: ("web app: ok", 0))
    cli.main(["connect", "demo", "--home-tz", "Asia/Tokyo", "--home-from", "laptop"])
    cli.main(["connect", "demo", "--home-tz", "Asia/Tokyo", "--home-from", "laptop"])
    raw = p.raw_config()
    assert (raw["home_timezone"], raw["home_timezone_from"]) == ("Asia/Tokyo", "laptop")
    assert _home_feed(p) == ["Home time zone UTC -> Asia/Tokyo (ttp connect from laptop)."]
    # An invalid zone changes nothing; a connect typed in an ssh login here keeps the workstation's zone.
    cli.main(["connect", "demo", "--home-tz", "Mars/Base", "--home-from", "laptop"])
    monkeypatch.setenv("SSH_CONNECTION", "10.0.0.1 1 10.0.0.2 22")
    cli.main(["connect", "demo"])
    assert p.raw_config()["home_timezone"] == "Asia/Tokyo" and len(_home_feed(p)) == 1
    # Typed on this machine's own desk, outside ssh: this machine's zone.
    monkeypatch.delenv("SSH_CONNECTION")
    monkeypatch.setenv("TTP_TEST_LOCAL_TZ", "Europe/Berlin")
    cli.main(["connect", "demo"])
    assert p.raw_config()["home_timezone"] == "Europe/Berlin" and len(_home_feed(p)) == 2


def test_remote_connect_sends_the_workstations_zone_and_an_older_runtime_still_connects(env, monkeypatch, capsys):
    from ttp import cli
    monkeypatch.setenv("TTP_TEST_LOCAL_TZ", "America/Los_Angeles")
    monkeypatch.setattr(cli, "flush_outbox", lambda name, entry: None)
    monkeypatch.setattr(cli, "remote_web", lambda name, entry, out: ("web app: ok", 0))
    seen = []

    def old_runtime(entry, argv, capture=False):
        seen.append(argv)
        if "--home-tz" in argv:
            return subprocess.CompletedProcess(argv, 2, "", "ttp: error: unrecognized arguments: --home-tz")
        return subprocess.CompletedProcess(argv, 0, "chat: c1\n", "")
    monkeypatch.setattr(cli, "_ssh", old_runtime)
    assert cli.connect_remote("far", {"host": "box", "dir": "/srv/far"}, ["connect", "far"]) == 0
    assert seen == [["connect", "far", "--home-tz", "America/Los_Angeles", "--home-from", "testhost"], ["connect", "far"]]


def test_remote_connect_from_an_ssh_login_sends_no_zone_and_keeps_the_projects(env, monkeypatch, capsys):
    """A user ssh'd into one box who connects to a project on another sends that box's zone (a
    server's), so nothing: the project's zone and the machine that set it stay as they are."""
    from ttp import cli
    p = make(env)
    p.set_config("home_timezone", "America/Los_Angeles")
    p.set_config("home_timezone_from", "laptop")
    monkeypatch.setenv("SSH_CLIENT", "10.0.0.1 1 22")
    monkeypatch.setattr(cli, "flush_outbox", lambda name, entry: None)
    monkeypatch.setattr(cli, "remote_web", lambda name, entry, out: ("web app: ok", 0))
    seen = []

    from ttp import weblink
    monkeypatch.setattr(weblink, "local", lambda p, url: ("web app: ok", 0))

    def box(entry, argv, capture=False):   # the project's machine runs `ttp connect` with what it was sent
        seen.append(argv)
        monkeypatch.delenv("SSH_CLIENT")   # there, outside this login
        monkeypatch.setenv("SSH_CONNECTION", "10.0.0.1 1 10.0.0.2 22")   # it runs under ssh on that box
        cli.main(argv)
        return subprocess.CompletedProcess(argv, 0, "chat: c1\n", "")
    monkeypatch.setattr(cli, "_ssh", box)
    assert cli.connect_remote(p.name, {"host": "box", "dir": str(p.root)}, ["connect", p.name]) == 0
    assert seen == [["connect", p.name]]
    raw = p.raw_config()
    assert (raw["home_timezone"], raw["home_timezone_from"]) == ("America/Los_Angeles", "laptop")
    assert _home_feed(p) == []


def test_a_spend_push_moves_the_home_zone_only_of_projects_its_sender_set(env, monkeypatch, capsys):
    from ttp import cli
    from ttp import globalcap as gcap
    p = make(env)
    p.set_config("home_timezone_from", "laptop")
    from ttp.cli import bootstrap
    from ttp.project import register
    repo2 = env["tmp"] / "repo2"
    subprocess.run(["git", "clone", "-q", str(env["repo"]), str(repo2)], check=True)
    q = bootstrap(repo2, "other", "Another project.", "fake")
    register("other", {"host": "testhost", "dir": str(q.root)})
    q.set_config("home_timezone_from", "server2")
    now = time.time()
    rec = json.loads(_spend_record("laptop", [(now - 3600, now + 3600, 1.0)]))
    stream = (json.dumps({**rec, "tz": "America/Los_Angeles"}) + "\n").encode()
    monkeypatch.setattr(sys, "stdin", type("S", (), {"buffer": io.BytesIO(stream)})())
    with pytest.raises(SystemExit) as e:
        cli.main(["spend-today", "--receive", "--via", "lap"])
    ack = json.loads(capsys.readouterr().out)
    assert e.value.code == 0 and ack == {"accepted": 1, "pulls": False}, ack
    assert p.raw_config()["home_timezone"] == "America/Los_Angeles"
    assert _home_feed(p) == ["Home time zone UTC -> America/Los_Angeles (from laptop)."]
    assert q.raw_config()["home_timezone"] == "UTC" and _home_feed(q) == []
    assert gcap._valid_push({**rec, "tz": "Mars/Base"}, now)["tz"] is None


