def test_sweep_action_records_one_validated_outcome_per_item(env):
    p = make(env)
    from ttp import coordinator as coord, sweep
    db = p.db
    t = db.add_task("blocked")
    db.update_task(t, status="blocked", blocked_reason="x")
    probs = coord.apply(p, [
        {"type": "sweep", "id": t, "outcome": "still_blocked", "until": "Accepted-evidence addendum only; retain blocked status",
         "start_after": "6h"},
        {"type": "sweep", "id": t, "outcome": "still_blocked", "until_probe": "test -e /tmp/x"},
        {"type": "sweep", "id": t, "outcome": "human_indispensable"},
        {"type": "sweep", "id": t, "outcome": "maybe"},
        {"type": "sweep", "outcome": "retired"},
        {"type": "sweep", "id": 9999, "outcome": "retired"}])
    assert len(probs) == 6 and db.kv(sweep.OUTCOMES_KEY) is None
    assert "re-checkable condition" in probs[0] and "start_after" in probs[1] and "`why`" in probs[2]
    assert coord.apply(p, [{"type": "sweep", "id": t, "outcome": "still_blocked",
                            "until": "the vendor sends the signed key", "start_after": "6h"},
                           {"type": "sweep", "resource": "rig", "outcome": "human_indispensable",
                            "why": "only the owner can reseat the card"}]) == []
    outs = db.kv(sweep.OUTCOMES_KEY)
    assert outs[f"task:{t}"]["outcome"] == "still_blocked" and outs[f"task:{t}"]["next"] > time.time() + 5 * 3600
    assert outs["resource:rig"]["why"] == "only the owner can reseat the card"


def test_blocker_sweep_carries_and_flags_items_left_without_an_outcome(env):
    p = make(env)
    from ttp import coordinator as coord, sweep
    db, cfg, now = p.db, p.config(), time.time()
    a, b, c = (db.add_task(n) for n in ("no outcome", "answered", "next check passed"))
    for t in (a, b, c):
        db.update_task(t, status="blocked", blocked_reason="r")
    sweep.start(db, cfg, "every 6h", now - 7 * 3600)
    db.x("UPDATE events SET status='handled'")
    assert coord.apply(p, [{"type": "sweep", "id": b, "outcome": "still_blocked", "until_probe": "test -e /x",
                            "start_after": "1d"},
                           {"type": "sweep", "id": c, "outcome": "still_blocked", "until_probe": "test -e /y",
                            "start_after": "1h"}]) == []
    eid = sweep.start(db, cfg, "every 6h", now + 2 * 3600)
    flags = db.kv(sweep.STATE_KEY)["flags"]
    assert flags == {f"task:{a}": "no outcome at the last sweep", f"task:{c}": "its next check is due"}
    text = coord.digest(p, {}, [eid], [])
    lines = [ln for ln in text.splitlines() if ln.startswith("- #")]
    assert "FLAG: no outcome at the last sweep" in lines[0] or "FLAG: no outcome at the last sweep" in lines[1]
    assert f"#{b} " in lines[2] and "FLAG" not in lines[2]           # flagged items come first
    assert "last re-check" in next(ln for ln in lines if ln.startswith(f"- #{b} ")) and "until test -e /x" in text


def test_blocker_sweep_flags_a_reblock_loop_and_a_spec_addendum_while_blocked(env):
    p = make(env)
    from ttp import sweep
    db, cfg, now = p.db, p.config(), time.time()
    a = db.add_task("re-blocked")
    db.update_task(a, status="blocked", blocked_reason="needs evidence")
    _sweep_ev(db, a, "task_blocked", f"#{a} re-blocked: needs evidence (run 41, 3 h)", now - 7200)
    _sweep_ev(db, a, "task_blocked", f"#{a} re-blocked: needs evidence (run 57, 1 h)", now - 600)
    b = db.add_task("addended", spec="do the thing")
    db.update_task(b, status="blocked", blocked_reason="waits on a decision")
    c = db.add_task("moved on")
    db.update_task(c, status="blocked", blocked_reason="first")
    _sweep_ev(db, c, "task_blocked", f"#{c} moved on: first", now - 7200)
    _sweep_ev(db, c, "task_blocked", f"#{c} moved on: second", now - 600)
    sweep.start(db, cfg, "every 6h", now)
    loops = db.kv(sweep.STATE_KEY)["loops"]
    assert list(loops) == [f"task:{a}"] and loops[f"task:{a}"].startswith(sweep.LOOP)
    db.update_task(b, spec="do the thing\n\nAccepted-evidence addendum only; retain blocked status")
    db.x("UPDATE events SET status='handled'")
    sweep.start(db, cfg, "every 6h", now + 7 * 3600)
    loops = db.kv(sweep.STATE_KEY)["loops"]
    assert loops[f"task:{b}"] == f"{sweep.LOOP} (spec changed while it stayed blocked)" and f"task:{c}" not in loops


def test_the_daily_review_lists_items_stuck_over_6h_with_their_sweep_outcome(env):
    p = make(env)
    from ttp import coordinator as coord, sweep
    from ttp import daemon as dm
    db, now = p.db, time.time()
    old = db.add_task("old block")
    db.update_task(old, status="blocked", blocked_reason="needs the vendor's key")
    _sweep_ev(db, old, "task_blocked", f"#{old} old block: needs the vendor's key", now - 10 * 3600)
    new = db.add_task("new block")
    db.update_task(new, status="blocked", blocked_reason="fresh")
    _sweep_ev(db, new, "task_blocked", f"#{new} new block: fresh", now - 3600)
    assert coord.apply(p, [{"type": "sweep", "id": old, "outcome": "human_indispensable",
                            "why": "only the vendor can issue it"}]) == []
    lines = sweep.review_lines(db, now)
    assert lines == [f"#{old} old block: blocked 10.0h: needs the vendor's key; sweep: human_indispensable 0.0h ago"]
    d = dm.Daemon(p.base)
    d.cfg = p.config()
    s = {"name": "daily-review", "budget_usd_day": None, "last_run": None, "description": "review"}
    assert d._schedule_llm(s, {}) == "queued"
    spec = db.one("SELECT spec FROM tasks WHERE origin='schedule'")["spec"]
    assert f"Stuck longer than 6h, with the blocker sweep's outcome:\n- #{old} old block: blocked 10.0h" in spec
    db.x("DELETE FROM tasks")
    assert sweep.review_lines(db, now) == ["nothing stuck longer than 6h"]


def test_blocker_sweep_age_of_a_coordinator_block_survives_a_spec_addendum(env):
    """A block the coordinator set (task_update, no task_blocked event) keeps its age after a spec
    addendum or any other update, so the daily review still lists it as stuck over 6h."""
    p = make(env)
    from ttp import coordinator as coord, sweep
    db = p.db
    t = db.add_task("coordinator block", spec="do the thing")
    db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    assert coord.apply(p, [{"type": "task_update", "id": t, "status": "blocked", "text": "until the rig is back",
                            "waits_on": "when:test -e /nonexistent-rig-marker"}]) == []
    assert db.task(t)["status"] == "blocked"
    assert not db.q("SELECT id FROM events WHERE task=? AND kind='task_blocked'", (t,))
    then = time.time() - 20 * 3600
    db.x("UPDATE tasks SET updated=? WHERE id=?", (then, t))
    assert sweep.due(db, p.config(), then + 60) == "every 6h"       # the daemon's minute check sees it
    now = time.time()
    db.update_task(t, spec="do the thing\n\nAddendum: accepted evidence only; retain blocked status")
    [i] = sweep.items(db, now)
    assert round(i["age_s"] / 3600) == 20
    assert any(ln.startswith(f"#{t} coordinator block: blocked 20.0h") for ln in sweep.review_lines(db, now))
    sweep.start(db, p.config(), "every 6h", now)                    # a sweep keeps it too
    db.update_task(t, blocked_reason="still no rig")
    assert round(sweep.items(db, now + 3600)[0]["age_s"] / 3600) == 21
    db.x("UPDATE tasks SET updated=NULL WHERE id=?", (t,))
    db.set_kv(sweep.STATE_KEY, {})                                   # no source at all: unknown, not 0
    [i] = sweep.items(db, now)
    assert i["age_s"] is None and sweep._dur(i["age_s"]) == "unknown"


def test_blocker_sweep_ages_a_reblocked_task_from_its_second_block(env):
    """Blocked, requeued and blocked again: the age starts at the second block, also for a coordinator
    block whose first-seen time predates the requeue."""
    p = make(env)
    from ttp import sweep
    db, now = p.db, time.time()
    a = db.add_task("re-blocked")
    db.update_task(a, status="blocked", blocked_reason="first")
    _sweep_ev(db, a, "task_blocked", f"#{a} re-blocked: first", now - 10 * 3600)
    _sweep_ev(db, a, "task_requeued", f"#{a} requeued", now - 5 * 3600)
    _sweep_ev(db, a, "task_blocked", f"#{a} re-blocked: second", now - 2 * 3600)
    b = db.add_task("run then re-blocked")
    db.update_task(b, status="blocked", blocked_reason="first")
    _sweep_ev(db, b, "task_blocked", f"#{b} run then re-blocked: first", now - 10 * 3600)
    db.x("INSERT INTO runs(task,role,status,started) VALUES(?,?,?,?)", (b, "worker", "done", now - 4 * 3600))
    _sweep_ev(db, b, "task_blocked", f"#{b} run then re-blocked: second", now - 3 * 3600)
    c = db.add_task("coordinator re-block")
    db.update_task(c, status="blocked", blocked_reason="first")
    db.x("UPDATE tasks SET updated=? WHERE id=?", (now - 10 * 3600, c))
    sweep.remember(db, sweep.items(db, now - 9 * 3600))               # first seen blocked 10 h ago
    _sweep_ev(db, c, "task_requeued", f"#{c} requeued", now - 5 * 3600)
    db.x("UPDATE tasks SET updated=? WHERE id=?", (now - 1 * 3600, c))  # blocked again by the coordinator
    d = db.add_task("event block, then coordinator re-block")
    db.update_task(d, status="blocked", blocked_reason="first")
    _sweep_ev(db, d, "task_blocked", f"#{d} event block: first", now - 10 * 3600)
    _sweep_ev(db, d, "task_requeued", f"#{d} requeued", now - 5 * 3600)
    db.x("UPDATE tasks SET updated=? WHERE id=?", (now - 1 * 3600, d))  # blocked again, no task_blocked event
    ages = {i["task"]: round(i["age_s"] / 3600, 1) for i in sweep.items(db, now)}
    assert ages == {a: 2.0, b: 3.0, c: 1.0, d: 1.0}


def test_blocker_sweep_refreshes_a_first_seen_time_stale_from_an_unobserved_requeue(env):
    """Requeued and blocked again by the coordinator with no sweep in between: the next remember()
    replaces the first-seen time from before the requeue, so a later addendum does not reset the age."""
    p = make(env)
    from ttp import sweep
    db, now = p.db, time.time()
    t = db.add_task("coordinator re-block, unobserved")
    db.update_task(t, status="blocked", blocked_reason="first")
    db.x("UPDATE tasks SET updated=? WHERE id=?", (now - 10 * 3600, t))
    sweep.remember(db, sweep.items(db, now - 9 * 3600))               # first seen blocked 10 h ago
    _sweep_ev(db, t, "task_requeued", f"#{t} requeued", now - 5 * 3600)
    db.x("UPDATE tasks SET updated=? WHERE id=?", (now - 3 * 3600, t))  # blocked again, never seen queued
    sweep.remember(db, sweep.items(db, now - 2 * 3600))
    db.x("UPDATE tasks SET updated=? WHERE id=?", (now - 60, t))        # a later spec addendum
    [i] = sweep.items(db, now)
    assert round(i["age_s"] / 3600, 1) == 3.0


def _app_server_log(env):
    f = env["tmp"] / "fakecli" / "app_server.jsonl"
    return [json.loads(x) for x in f.read_text().splitlines()] if f.exists() else []


def test_a_codex_task_pin_is_checked_against_the_session_before_the_agent_starts(env, monkeypatch):
    """A pinned Codex task asks the app-server which model and effort its session resolves (an
    ephemeral thread, no turn) with the run's own overrides, records them, and then runs."""
    done = {"status": "done", "summary": "ok"}
    p, run, task, argv, _ = _cli_run(env, monkeypatch, "codex", _codex_events(*_codex_turn("all done")), result=done,
                                     pin={"model": "pinned-model-1", "effort": "xhigh"})
    assert argv[argv.index("-m") + 1] == "pinned-model-1" and "model_reasoning_effort=xhigh" in argv
    asked = _app_server_log(env)
    started = [a for a in asked if "argv" in a]
    assert len(started) == 1, "one session check before the run"
    server = started[0]["argv"]
    assert 'model="pinned-model-1"' in server and "model_reasoning_effort=xhigh" in server
    assert not any(a.startswith(("hooks.", "developer_instructions=")) for a in server)
    req = [a["request"] for a in asked if "request" in a][0]
    assert req["method"] == "thread/start" and req["params"]["ephemeral"] is True
    assert req["params"]["cwd"] == str(env["repo"])
    assert run["status"] == "ok" and task["status"] == "done"
    note = json.loads(run["note"])
    assert {k: note["session"][k] for k in ("model", "effort")} == {"model": "pinned-model-1", "effort": "xhigh"}
    assert note["session"]["verification"] == "verified"
    spec = json.loads((p.runs / str(run["id"]) / "run.json").read_text())
    assert spec["pin"] == {"model": "pinned-model-1", "effort": "xhigh"}
    assert (spec["session"]["model"], spec["session"]["effort"]) == ("pinned-model-1", "xhigh")


@pytest.mark.parametrize("session, wrong", [({"reasoningEffort": "high"}, "effort high (pinned xhigh)"),
                                            ({"model": "other-model"}, "model other-model (pinned pinned-model-1)")])
def test_a_codex_session_that_does_not_honour_the_pin_is_refused_before_any_spend(env, monkeypatch, session, wrong):
    p, run, task, argv, _ = _cli_run(env, monkeypatch, "codex", _codex_events(*_codex_turn("all done")),
                                     pin={"model": "pinned-model-1", "effort": "xhigh"}, session=session)
    assert argv is None and not (env["tmp"] / "fakecli" / "argv.json").exists(), "codex exec must never start"
    exit_info = json.loads((p.runs / str(run["id"]) / "exit.json").read_text())
    assert exit_info["launched"] is False and exit_info["model_turn_started"] is False
    assert exit_info["refused"] == "model_mismatch" and wrong in exit_info["error"]
    assert run["status"] == "failed" and run["cost_usd"] == 0 and task["spent_usd"] == 0, "no spend is estimated"
    note = json.loads(run["note"])
    assert note["refused"] == "model_mismatch" and note["not_waste"] == "refused"
    assert note["session"]["model"] == session.get("model", "pinned-model-1")
    assert task["status"] == "blocked" and task["attempts"] == 0, "a retry would resolve the same: no attempt"
    assert wrong in task["blocked_reason"]
    ev = p.db.one("SELECT * FROM events WHERE kind='task_blocked' AND task=?", (task["id"],))
    assert ev and ev["status"] == "queued" and "pin" in ev["text"]


def test_an_unpinned_codex_task_never_asks_the_app_server(env, monkeypatch):
    done = {"status": "done", "summary": "ok"}
    _, run, task, _, _ = _cli_run(env, monkeypatch, "codex", _codex_events(*_codex_turn("all done")), result=done,
                                  session={"model": "anything-else"})
    assert _app_server_log(env) == [] and run["status"] == "ok" and task["status"] == "done"
    assert "session" not in json.loads(run["note"] or "{}")


def test_a_pinned_run_whose_session_cannot_be_checked_goes_ahead_unverified(env, monkeypatch):
    done = {"status": "done", "summary": "ok"}
    p, run, task, argv, _ = _cli_run(env, monkeypatch, "codex", _codex_events(*_codex_turn("all done")), result=done,
                                     pin={"effort": "xhigh"}, session="exit")
    assert argv and run["status"] == "ok" and task["status"] == "done"
    assert "error" in json.loads(run["note"])["session"], "the run record says the pin went unverified"
    assert json.loads(run["note"])["session"]["verification"] == "unverifiable"
    assert "could not verify" in (p.runs / str(run["id"]) / "runner.log").read_text()


def test_strict_project_pin_verification_blocks_without_spend_or_retry(env, monkeypatch):
    def strict(p):
        cfg = p.raw_config()
        cfg.setdefault("runner", {})["pin_verify"] = "strict"
        p.config_path.write_text(json.dumps(cfg))

    p, run, task, argv, _ = _cli_run(env, monkeypatch, "codex", _codex_events(*_codex_turn("all done")),
                                     pin={"effort": "xhigh"}, session="exit", before=strict)
    assert argv is None, "strict verification must refuse before codex exec starts"
    assert run["cost_usd"] == 0 and task["spent_usd"] == 0 and task["attempts"] == 0
    assert task["status"] == "blocked" and "could not verify" in task["blocked_reason"]
    assert task["not_before"] is None
    note = json.loads(run["note"])
    assert note["refused"] == "pin_unverified" and note["not_waste"] == "refused"
    assert note["session"]["verification"] == "unverifiable"
    assert note["session"]["pin_verify"] == "strict"
    run_dir = p.runs / str(run["id"])
    exit_info = json.loads((run_dir / "exit.json").read_text())
    assert exit_info["launched"] is False and exit_info["model_turn_started"] is False
    assert json.loads(task["result"])["status"] == "blocked"
    assert not (run_dir / "tmp").exists()


@pytest.mark.parametrize("pin, session, refused, reason", [
    ({"effort": "high", "pin_verify": "strict"}, "exit", "pin_unverified", "could not verify"),
    ({"model": "pinned-model-1", "effort": "xhigh"}, {"model": "other-model"}, "model_mismatch",
     "model other-model (pinned pinned-model-1)"),
])
def test_a_refused_pin_on_a_resumed_run_blocks_instead_of_starting_fresh(env, monkeypatch, pin, session, refused,
                                                                         reason):
    p, run, task, argv, _ = _cli_run(env, monkeypatch, "codex", _codex_events(*_codex_turn("all done")),
                                     help_text=CODEX_EXEC_HELP, pin=pin, session=session, resume=THREAD,
                                     note={"resumes": {"run": 1, "session": THREAD}})
    assert argv is None and not (env["tmp"] / "fakecli" / "argv.json").exists(), "codex exec must never start"
    assert run["status"] == "failed" and run["cost_usd"] == 0 and task["spent_usd"] == 0
    note = json.loads(run["note"])
    assert note["refused"] == refused and note["not_waste"] == "refused", "the refusal is kept, not a resume"
    assert task["status"] == "blocked" and task["attempts"] == 0 and task["not_before"] is None
    assert reason in task["blocked_reason"]
    assert json.loads(task["result"])["status"] == "blocked"
    ev = p.db.one("SELECT * FROM events WHERE kind='task_blocked' AND task=?", (task["id"],))
    assert ev and ("requeue" in ev["text"])
    assert not p.db.one("SELECT * FROM events WHERE kind='task_requeued' AND task=?", (task["id"],)), \
        "a refused pin must not fall back to a fresh start"


@pytest.mark.parametrize("provider, project_mode, task_mode, runs", [
    ("codex", "lenient", "strict", False),
    ("codex", "strict", "lenient", True),
    ("cursor", "lenient", "strict", False),
    ("cursor", "strict", "lenient", True),
])
def test_task_pin_verification_overrides_project_policy(env, monkeypatch, provider, project_mode, task_mode, runs):
    p, run, task, argv, _ = _cli_run(
        env, monkeypatch, provider, _codex_events(*_codex_turn("done")) if provider == "codex" else "",
        result={"status": "done", "summary": "ok"}, pin={"effort": "high", "pin_verify": task_mode},
        session="exit", before=lambda p: p.set_config("runner.pin_verify", project_mode))
    assert bool(argv) is runs
    assert task["status"] == ("done" if runs else "blocked")
    assert task["attempts"] == (1 if runs else 0)
    note = json.loads(run["note"])
    assert note["session"]["pin_verify"] == task_mode
    assert note["session"]["verification"] == "unverifiable"
