    base = _git_out(p.root, "rev-parse", "HEAD").strip()
    checks = push.check_list([{"run": "python3 -m pytest tests/test_absent.py",
                              "if_exists": "tests/test_absent.py", "if_changed": ["src/**", "tests/**"]}])
    _commit_files(p.root, {"README.md": "docs\n"}, "docs")
