    for rc, text in [(0, output), (1, diagnostic.format(head="a" * 40)),
                     (1, "selector assertion failed"), (1, "byte-equivalent tree; checks passed previously")]:
        assert push.applicability_failure(p.root, head, check, rc, text) is None


