def _deploy_catch_up(base, db, version, commit, now):
    """The project's merge landed `version` at `commit` and its daemon ticked on it at `now`."""
    rt = base / 'harness' / 'runtime' / 'ttp'
    (rt / '__init__.py').write_text(f'__version__ = "{version}"\n')
    (rt / 'SOURCE_COMMIT').write_text(commit + '\n')
    for f in ('__init__.py', 'SOURCE_COMMIT'):
        os.utime(rt / f, (now - 100, now - 100))
    db.x("UPDATE tasks SET status='done'")
    hb = base / 'state' / 'heartbeat'
    data = json.loads(hb.read_text())
    data['receipt'].update(version=version, commit=commit)
    hb.write_text(json.dumps(data))
    os.utime(base / 'state' / 'tick_done', (now, now))


def _deploy_pager(p, pages=None):
    """A daemon.alert stand-in posting through `p` (the project whose tick holds the transaction)."""
    pages = [] if pages is None else pages

    def page(key, text, severity, **_):
        pages.append((key, text, severity))
        p.db.post('out', text, kind='alert', ref=key, severity=severity)
    return pages, page


@pytest.mark.parametrize('fault', ['stopped', 'upgrade_error'])
def test_after_push_deploy_fault_while_pending_alerts_at_next_probe(env, tmp_path, fault):
    from ttp import alerts, deploy, overview, release
    from ttp.project import Project
    p = make(env)
    _deploy_lib('0.5.0')
    _, db = _deploy_project(tmp_path, 'alpha', '0.4.9')
    db.add_task(release.UPGRADE_TASK_TITLE, 'merge', kind='harness')
    now = time.time()
    assert deploy.record(p, overview.deployed(names=['alpha']), now)['rc'] == 0
    due = p.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0']['due']
    pages, page = _deploy_pager(p)
    deploy.tick(p, page, now + 1)
    assert not pages
    if fault == 'stopped':
        db.set_kv('daemon', {'pid': 0, 'host': 'testhost'})
    else:
        db.set_kv(release.KV_AUTO, {'key': f'0.5.0 {DEPLOY_C[:12]}', 'outcome': 'failed',
                                    'why': 'runtime import failed'})
    t = now + 1 + deploy.PROBE_S
    p = Project(p.base)                          # the reporting daemon restarted meanwhile
    pages, page = _deploy_pager(p, pages)
    deploy.tick(p, page, t)
    assert t < due and len(pages) == 1 and pages[0][0] == 'deploy-behind:alpha'
    assert ('daemon stopped' if fault == 'stopped' else 'runtime import failed') in pages[0][1]
    p = Project(p.base)
    pages, page = _deploy_pager(p, pages)
    for i in (2, 3):
        deploy.tick(p, page, now + 1 + deploy.PROBE_S * i)
    assert len(pages) == 1, 'one alert per condition, also across restarts'
    assert alerts.holds(p.db, 'deploy-behind:alpha', now, t)
    if fault == 'stopped':
        db.set_kv('daemon', {'pid': os.getpid(), 'host': 'testhost'})
    else:
        db.set_kv(release.KV_AUTO, {})
    t = now + 1 + deploy.PROBE_S * 4
    deploy.tick(p, page, t)
    assert [e['key'] for e in alerts.sweep(p.db, now=t)] == ['deploy-behind:alpha']
    rec = p.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0']
    assert rec['due'] == due and rec['outcome'] == 'pending' and len(rec['history']) == 1
    deploy.tick(p, page, due + 1)
    assert len(pages) == 2 and 'missed takeover' in pages[1][1], 'the merge deadline is still watched'


def _fake_takeovers(monkeypatch, deploy, catch_up=None):
    """deploy.launch_takeover stand-in: records (name, task) and runs a process that exits at once;
    `catch_up(name)` is called as the takeover's upgrade when given."""
    launched = []
    def launch(p, name, task):
        launched.append((name, task))
        if catch_up:
            catch_up(name)
        return subprocess.Popen([sys.executable, "-c", "pass"])
    monkeypatch.setattr(deploy, "launch_takeover", launch)
    return launched


def _restart_reporting_daemon(p, deploy):
    """The reporting daemon restarts (or the host reboots): a new Project and none of the old children."""
    from ttp.project import Project
    for child in deploy._children.values():
        child.wait()
    deploy._children.clear()
    return Project(p.base)


def test_a_missed_takeover_is_taken_over_by_the_host_after_a_restart(env, tmp_path, monkeypatch):
    """Replays a missed takeover: a project's upgrade was pending on a merge held by a harness task that
    stayed open and active; the takeover time passed with a daemon restart in between, and the deploy
    check only paged 'missed takeover': nothing ran the host-side takeover. Now the first probe past the
    deadline runs `ttp upgrade <name> --take-over-from <task>` and the check closes once the project's own
    daemon reports the release, with no page."""
    from ttp import deploy, overview, release
    p = make(env)
    _deploy_lib('0.5.0')
    base, db = _deploy_project(tmp_path, 'alpha', '0.4.9')
    tid = db.add_task(release.UPGRADE_TASK_TITLE, 'merge', kind='harness')
    db.update_task(tid, status='waiting')            # still open, and active: never stale on its own
    now = time.time()
    report = overview.deployed(names=['alpha'])
    report['projects'][0]['takeover_at'] = now + 1
    assert deploy.record(p, report, now)['rc'] == 0
    due = p.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0']['due']
    def upgraded(name):
        _deploy_catch_up(base, db, '0.5.0', DEPLOY_C, due + 30)
    launched = _fake_takeovers(monkeypatch, deploy, upgraded)
    p = _restart_reporting_daemon(p, deploy)
    pages, page = _deploy_pager(p)
    deploy.tick(p, page, due + 1)                   # overdue on the first tick after the restart
    assert launched == [('alpha', tid)] and not pages
    rec = p.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0']
    assert rec['outcome'] == 'pending' and not rec.get('closed')
    p = _restart_reporting_daemon(p, deploy)        # restarted again while the takeover ran
    pages, page = _deploy_pager(p, pages)
    deploy.tick(p, page, due + 1 + deploy.PROBE_S)
    rec = p.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0']
    assert rec['closed'] and not pages and launched == [('alpha', tid)]
    assert p.db.kv(deploy.TAKEOVERS) == {}


def test_a_takeover_that_does_not_bring_the_daemon_up_is_retried_then_paged_once(env, tmp_path, monkeypatch):
    """The takeover is verified by the project's own daemon receipt, retried a bounded number of times,
    and paged only once every try ended with the project still behind."""
    from ttp import deploy, overview, release
    p = make(env)
    p.set_config('home_timezone', 'America/Los_Angeles')
    _deploy_lib('0.5.0')
    _, db = _deploy_project(tmp_path, 'alpha', '0.4.9')
    tid = db.add_task(release.UPGRADE_TASK_TITLE, 'merge', kind='harness')
    now = time.time()
    report = overview.deployed(names=['alpha'])
    report['projects'][0]['takeover_at'] = now + 1
    deploy.record(p, report, now)
    due = p.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0']['due']
    launched = _fake_takeovers(monkeypatch, deploy)
    pages, page = _deploy_pager(p)
    t = due + 1
    while len(launched) < deploy.TAKEOVER_TRIES or not pages:
        deploy.tick(p, page, t)
        for child in deploy._children.values():
            child.wait()
        t += deploy.PROBE_S
        assert t < due + deploy.TAKEOVER_TRIES * (deploy.TAKEOVER_SETTLE_S + 3 * deploy.PROBE_S), 'bounded'
    assert launched == [('alpha', tid)] * deploy.TAKEOVER_TRIES
    assert len(pages) == 1 and 'missed takeover' in pages[0][1] and 'takeover tried 3 times' in pages[0][1]
    for i in range(3):
        deploy.tick(p, page, t + i * deploy.PROBE_S)
    assert len(launched) == deploy.TAKEOVER_TRIES and len(pages) == 1


def test_a_project_stuck_across_releases_is_one_alert_tracking_the_newest(env, tmp_path):
    """Replays alerts #469-#476: a project stuck behind release after release got one alert per release.
    It is one ongoing alert per project, updated in place with the newest release it misses, that clears
    once its own daemon reports the release; two stuck projects are two alerts; the after_push failure of
    each deploy sends none of its own."""
    from ttp import alerts, deploy, overview, pushq
    p = make(env)
    p.set_config('home_timezone', 'America/Los_Angeles')
    _deploy_lib('0.4.9')
    a_base, a_db = _deploy_project(tmp_path, 'alpha', '0.4.8')
    _deploy_project(tmp_path, 'beta', '0.4.8')
    pages, page = _deploy_pager(p)
    now = time.time()
    versions = [f'0.5.{i}' for i in range(6)]
    for i, v in enumerate(versions):
        t = now + 10 * i
        _deploy_lib(v)
        started = t - 5
        assert deploy.record(p, overview.deployed(names=['alpha', 'beta']), t)['rc'] == 1
        p.db.x("INSERT INTO push_batches(id,marker,target,started) VALUES(?,?,?,?)",
               (f'batch-{v}', 'marker', 'origin/topic', started))
        pushq._after(p, {'id': f'batch-{v}'}, {'pushed_sha': DEPLOY_C, 'version': v, 'after_push': {
            'exit': 1, 'started': started, 'ended': t}}, 'failed', lambda *a, **k: pages.append(a), t)
        deploy.tick(p, page, t + 1)
        deploy.tick(p, page, t + 1 + deploy.PROBE_S)
        out = p.db.q("SELECT ref,text FROM messages WHERE kind='alert' ORDER BY id")
        assert [m['ref'] for m in out] == ['deploy-behind:alpha', 'deploy-behind:beta'], (v, out)
        assert all(f'tt-project {v} ' in m['text'] for m in out), out
        assert all(f'tt-project {old} ' not in m['text'] for m in out for old in versions[:i])
        live = p.db.q("SELECT key,text FROM alerts WHERE cleared IS NULL ORDER BY id")
        assert [a['key'] for a in live] == ['deploy-behind:alpha', 'deploy-behind:beta']
        assert all(f'tt-project {v} ' in a['text'] and 'behind since' in a['text'] for a in live)
        open_checks = [r for r in p.db.kv(deploy.CHECKS).values() if not r.get('closed')]
        assert sorted((r['name'], r['target']) for r in open_checks) == [('alpha', v), ('beta', v)]
        assert {r['since'] for r in open_checks} == {now}, 'behind since its first missed release'
    assert not pages, 'no new page per release, and no after_push alert of its own'
    t = now + 10 * len(versions)
    _deploy_catch_up(a_base, a_db, versions[-1], DEPLOY_C, t)
    assert not alerts.holds(p.db, 'deploy-behind:alpha', now, t)
    assert alerts.holds(p.db, 'deploy-behind:beta', now, t)
    assert [e['key'] for e in alerts.sweep(p.db, now=t)] == ['deploy-behind:alpha']
    deploy.tick(p, page, t)
    assert not pages and [a['key'] for a in p.db.q("SELECT key FROM alerts WHERE cleared IS NULL")] == \
        ['deploy-behind:beta']


def test_a_daemon_that_never_restarts_onto_new_releases_is_one_alert(env, tmp_path):
    """Files reach each release but the daemon keeps running the old code: each release set a fresh restart
    deadline, the failed check was superseded, its alert cleared and a new one opened after the wait. The
    earlier restart deadline is kept, so it is one alert, updated in place, never cleared in between."""
    from ttp import alerts, deploy, overview
    p = make(env)
    base, _ = _deploy_project(tmp_path, 'alpha', '0.5.0', running='0.4.9')
    pages, page = _deploy_pager(p)
    now = time.time()
    versions = [f'0.5.{i}' for i in range(5)]
    for i, v in enumerate(versions):
        t = now + 3600 * i
        (base / 'harness' / 'runtime' / 'ttp' / '__init__.py').write_text(f'__version__ = "{v}"\n')
        _deploy_lib(v)
        deploy.record(p, overview.deployed(names=['alpha']), t)
        alerts.sweep(p.db, now=t)
        deploy.tick(p, page, t + deploy.RESTART_WAIT_S + 400)
        alerts.sweep(p.db, now=t + deploy.RESTART_WAIT_S + 400)
    rows = p.db.q("SELECT key,text,cleared FROM alerts WHERE key='deploy-behind:alpha'")
    assert len(rows) == 1 and rows[0]['cleared'] is None, rows
    assert f'tt-project {versions[-1]} ' in rows[0]['text']
    assert not p.db.q("SELECT text FROM messages WHERE text LIKE '%Cleared%'")
    assert len(pages) == 1


def test_a_stuck_project_alert_pages_again_only_when_it_gets_worse(env, tmp_path):
    """Checks kept per release (by an earlier version) collapse onto the newest; a daemon that goes down is
    news (a high page under the same key), a later release is an in-place update of it."""
    from ttp import deploy, overview
    p = make(env)
    _deploy_lib('0.5.0')
    _, db = _deploy_project(tmp_path, 'alpha', '0.4.8')
    pages, page = _deploy_pager(p)
    now = time.time()
    deploy.record(p, overview.deployed(names=['alpha']), now)
    _deploy_lib('0.5.1')
    deploy.record(p, overview.deployed(names=['alpha']), now + 10)
    checks = p.db.kv(deploy.CHECKS)
    assert checks['deploy:alpha:0.5.0']['superseded'] == '0.5.1'
    for rec in checks.values():   # as kept before: every release's check still open
        rec.pop('closed', None)
        rec.pop('superseded', None)
    p.db.set_kv(deploy.CHECKS, checks)
    db.set_kv('daemon', {'pid': 0, 'host': 'testhost'})
    deploy.tick(p, page, now + 20)
    assert [(k, s) for k, _, s in pages] == [('deploy-behind:alpha', 'high')]
    assert 'tt-project 0.5.1 ' in pages[0][1]
    assert [k for k, r in p.db.kv(deploy.CHECKS).items() if not r.get('closed')] == ['deploy:alpha:0.5.1']
    _deploy_lib('0.5.2')
    deploy.record(p, overview.deployed(names=['alpha']), now + 30)
    deploy.tick(p, page, now + 31)
    assert len(pages) == 1
    ep = p.db.one("SELECT * FROM alerts WHERE cleared IS NULL")
    assert ep['severity'] == 'high' and 'tt-project 0.5.2 ' in ep['text']
    assert 'tt-project 0.5.2 ' in p.db.one("SELECT text FROM messages WHERE id=?", (ep['message'],))['text']


def _paused_behind(tmp_path, name='gamma'):
    """A registered project, paused, one release behind, whose template merge task is queued and never ran."""
    from ttp import release
    base, db = _deploy_project(tmp_path, name, '0.4.9')
    tid = db.add_task(release.UPGRADE_TASK_TITLE, 'merge', kind='harness')
    db.x("UPDATE tasks SET created=?, updated=? WHERE id=?", (time.time() - 3600, time.time() - 3600, tid))
    db.set_paused(True)
    return base, db, tid


def test_a_paused_projects_deferred_takeover_is_one_low_note_and_upgrades_when_resumed(env, tmp_path):
    """Replays a paused project behind a release: its merge task could never run, the host-side takeover
    exited 75 on every try, no takeover.log was under its own logs, and after_push paged 'missed takeover'
    for every release. Now the paused project is taken over at once; a takeover that defers (exit 75) is
    logged in that project's own logs/takeover.log, gets one low note and no page and is not retried, and
    once the project is resumed its own upgrade runs and the check closes."""
    from ttp import deploy, overview, project
    p = make(env)
    _deploy_lib('0.5.0')
    ttp = project.HOME_DIR / 'lib' / 'current' / 'bin' / 'ttp'
    ttp.parent.mkdir(parents=True, exist_ok=True)
    ttp.write_text("import sys\nprint('upgrade not applied: gamma paused; upgrades when resumed')\nsys.exit(75)\n")
    base, db, tid = _paused_behind(tmp_path)
    now = time.time()
    report = deploy.record(p, overview.deployed(names=['gamma']), now)
    assert report['rc'] == 0 and report['projects'][0]['outcome'] == 'pending'
    rec = p.db.kv(deploy.CHECKS)['deploy:gamma:0.5.0']
    assert rec['takeover_at'] <= now + 1, "a paused project's merge task cannot run: no 6 h wait"
    pages, page = _deploy_pager(p)
    t = rec['due'] + 1
    for _ in range(40):                                  # well past every try and settle time
        deploy.tick(p, page, t)
        for child in deploy._children.values():
            child.wait()
        t += deploy.PROBE_S
    log = base / 'state' / 'logs' / 'takeover.log'
    text = log.read_text()
    assert text.count(f'ttp upgrade gamma --take-over-from {tid}') == 1, 'tried once, not retried while paused'
    assert 'takeover ended: exit 75 (deferred' in text and 'gamma paused; upgrades when resumed' in text
    notes = p.db.q("SELECT severity, text FROM messages WHERE direction='out' AND text LIKE '%upgrades when resumed%'")
    assert len(notes) == 1 and notes[0]['severity'] == 'low'
    assert not pages and not p.db.q('SELECT * FROM alerts') and not deploy.holds(p.db, '0.5.0', t)
    assert p.db.kv(deploy.CHECKS)['deploy:gamma:0.5.0']['outcome'] == 'pending'
    assert not (p.logs / 'takeover.log').exists()
    db.set_paused(False)                                 # resumed: its own merge task takes the upgrade on
    deploy.tick(p, page, t)
    rec = p.db.kv(deploy.CHECKS)['deploy:gamma:0.5.0']
    assert rec['outcome'] == 'pending' and rec['due'] >= t + deploy.RESUME_GRACE_S - 1 and not pages
    assert 'gamma was resumed' in log.read_text()
    _deploy_catch_up(base, db, '0.5.0', DEPLOY_C, t + 600)
    deploy.tick(p, page, t + 700)
    assert p.db.kv(deploy.CHECKS)['deploy:gamma:0.5.0']['closed'] and not pages
    assert len(p.db.q("SELECT id FROM messages WHERE direction='out' AND text LIKE '%upgrades when resumed%'")) == 1


def test_a_paused_project_upgraded_by_the_takeover_closes_and_stays_paused(env, tmp_path, monkeypatch):
    """The files-only takeover of a paused project lands the release (its daemon restarts, still paused):
    the check closes with no page and no pause note, and the end is in the project's takeover log."""
    from ttp import deploy, overview
    p = make(env)
    _deploy_lib('0.5.0')
