def test_after_push_deploy_new_commit_of_same_version_retargets_the_check(env, tmp_path):
    from ttp import alerts, deploy, overview, release
    from ttp.project import Project
    p = make(env)
    _deploy_lib('0.5.0')
    base, db = _deploy_project(tmp_path, 'alpha', '0.4.9')
    db.add_task(release.UPGRADE_TASK_TITLE, 'merge', kind='harness')
    now = time.time()
    assert deploy.record(p, overview.deployed('0.5.0', DEPLOY_C, names=['alpha']), now)['rc'] == 0
    pages, page = _deploy_pager(p)
    db.set_kv('daemon', {'pid': 0, 'host': 'testhost'})
    deploy.tick(p, page, now + 1)
    assert len(pages) == 1
    db.set_kv('daemon', {'pid': os.getpid(), 'host': 'testhost'})
    newer = '123456789abcdef01234'
    again = Project(p.base)
    assert deploy.record(again, overview.deployed('0.5.0', newer, names=['alpha']), now + 10)['rc'] == 0
    rec = again.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0']
    assert rec['commit'] == newer and rec['outcome'] == 'pending' and len(rec['history']) == 1
    assert not alerts.holds(p.db, 'deploy:alpha:0.5.0', now, now + 10)
    deploy.record(again, overview.deployed('0.5.0', newer, names=['alpha']), now + 20)
    assert again.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0'] == rec, 'a true retry keeps its deadline'
    _deploy_catch_up(base, db, '0.5.0', newer, now + 30)
    deploy.tick(Project(p.base), page, now + 30)
    rec = p.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0']
    assert rec['closed'] and len(pages) == 1
    assert not alerts.holds(p.db, 'deploy:alpha:0.5.0', now, rec['due'] + 1)
    deploy.tick(p, page, rec['due'] + 1)
    assert len(pages) == 1, 'no missed-takeover alert for a release that arrived'


def test_after_push_deploy_recovered_daemon_returns_to_owned_pending(env, tmp_path):
    from ttp import alerts, deploy, overview, release
    from ttp.project import Project
    p = make(env)
    _deploy_lib('0.5.0')
    _, db = _deploy_project(tmp_path, 'alpha', '0.4.9')
    db.add_task(release.UPGRADE_TASK_TITLE, 'merge', kind='harness')
    db.set_kv('daemon', {'pid': 0, 'host': 'testhost'})
    now = time.time()
    assert deploy.record(p, overview.deployed(names=['alpha']), now)['rc'] == 1
    due = p.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0']['due']
    assert due > now + 3600
    db.set_kv('daemon', {'pid': os.getpid(), 'host': 'testhost'})
    again = Project(p.base)
    for t in (now + 60, now + 120):         # the coordinator's retry, after a restart
        result = deploy.record(again, overview.deployed(names=['alpha']), t)
        assert result['rc'] == 0 and result['projects'][0]['outcome'] == 'pending'
    assert len(p.db.q("SELECT * FROM messages WHERE kind='alert'")) == 1
    assert [e['key'] for e in alerts.sweep(p.db, now=now + 120)] == ['deploy-behind:alpha']
    rec = p.db.kv(deploy.CHECKS)['deploy:alpha:0.5.0']
    assert rec['due'] == due and len(rec['history']) == 1 and not rec.get('alerted')
    pages, page = _deploy_pager(again)
    deploy.tick(again, page, now + 180)
    assert not pages
    deploy.tick(again, page, due + 1)
    assert len(pages) == 1 and 'missed takeover' in pages[0][1]


# Health evidence ends coordinator pauses, fenced against a changed pause.
HEALTH_END = {"heal": "svc", "healthy_n": 3, "clean_s": 1800}   # the end health_end() gives check `svc`


def _health_pause(env, *, shared=False, by="coordinator", every_s=900, end=None):
    from ttp import coordinator as coord
    p, d, up = _heal_setup(env, resource="board")
    p.db.x("UPDATE schedules SET every_s=? WHERE name='svc'", (every_s,))   # results stay fresh 2 * every_s
    up.touch()
    if shared:
        p.set_config("shared_resources", ["board"])
    if by == "user":
        coord.pause_resource(p, "board", True, by="user", end={"end_when": dict(HEALTH_END)})
    else:   # the coordinator's pause of a heal-checked resource gets the health end by itself
        assert coord.apply(p, [{"type": "resource_pause", "resource": "board", "paused": True, **(end or {})}]) == []
    return p, d, up


@pytest.mark.parametrize("shared", [False, True])
def test_health_pause_lifts_once_and_wakes_waiters_and_sweep(env, shared):
    from ttp import heal, sweep
    p, d, _ = _health_pause(env, shared=shared)
    now = time.time()
    tid = p.db.add_task("use board", "s", labels=["resource:board"])
    p.db.update_task(tid, status="queued", not_before=now + 9000,
                     result=json.dumps({"status": "waiting", "waiting_for": "board",
                                        "retry_when": "ttp lock --probe board"}))
    for dt in (0, 900):
        heal.run(d, "svc", _heal_spec(p), now + dt)
        d.check_pause_ends()
        assert "board" in p.db.paused_resources()
    heal.run(d, "svc", _heal_spec(p), now + 1800)
    d.check_pause_ends()
    d.check_pause_ends()
    assert "board" not in p.db.paused_resources()
    assert p.db.task(tid)["not_before"] is None
    assert [s["why"] for s in p.db.kv(sweep.SIGNAL_KEY)] == ["pause ended: board"]
    events = p.db.q("SELECT * FROM events WHERE kind='pause_ended'")
    assert len(events) == 1 and events[0]["source"] == "daemon"
    assert "svc" in events[0]["text"] and "3" in events[0]["text"]
    assert not p.db.q("SELECT * FROM events WHERE kind='pause_end_due'")


@pytest.mark.parametrize("rc", [1, 75, 255])
def test_health_pause_failure_or_unknown_resets_clean_window(env, monkeypatch, rc):
    from ttp import heal
    p, d, _ = _health_pause(env)
    now = time.time()
    verdict = [0]
    monkeypatch.setattr(heal, "check", lambda *a: (verdict[0], "result"))
    for dt, code in [(0, 0), (900, 0), (1200, rc), (1800, 0), (2700, 0), (3600, 0)]:
        verdict[0] = code
        heal.run(d, "svc", _heal_spec(p), now + dt)
        d.check_pause_ends()
        assert ("board" in p.db.paused_resources()) == (dt < 3600)


def test_health_pause_restart_keeps_count_and_ticks_do_not_replay_results(env):
    from ttp import heal
    from ttp.daemon import Daemon
    p, d, _ = _health_pause(env)
    assert p.db.paused_resources()["board"]["end_when"] == HEALTH_END
    now = time.time()
    heal.run(d, "svc", _heal_spec(p), now)
    for _ in range(4):
        d.check_pause_ends()
    assert "board" in p.db.paused_resources()
    heal.run(d, "svc", _heal_spec(p), now + 900)
    restarted = Daemon(p.base)
    heal.run(restarted, "svc", _heal_spec(p), now + 1800)
    restarted.check_pause_ends()
    assert "board" not in p.db.paused_resources()


