    cli.main(['checks', '--detach', '--fresh', '--', command])
    assert _wait_precheck(run) == '0'
    replacement = pathlib.Path(cli._read_checks_pid(run)['check_report_dir'])
    assert replacement != output and (replacement / 'x').read_text() == 'report\n'


