def test_ssh_auth_failed_gets_a_reboot_home_hint_and_other_failures_do_not(capsys):
    from ttp import cli, machines
    denied = "user@host: Permission denied (publickey).\n"
    assert machines.auth_failed_hint("ssh: connect to host x port 22: Connection timed out") == ""
    assert machines.auth_failed_hint(None) == ""
    hint = machines.auth_failed_hint(denied)
    assert "If the host rebooted" in hint and "one possible cause" in hint and "authorized_keys" in hint and "console" in hint
    assert "rebooted 1.0 h ago. One possible cause" in machines.auth_failed_hint(denied, booted_at=1000.0, now=1000.0 + 3600)
    assert "If the host rebooted" in machines.auth_failed_hint(denied, booted_at=1.0, now=1.0 + 86400)
    cli._unreachable({"host": "box"}, denied)
    assert "authorized_keys" in capsys.readouterr().err
    cli._unreachable({"host": "box"}, "Connection refused")
    assert "authorized_keys" not in capsys.readouterr().err


def test_a_task_reference_to_a_missing_task_is_rejected_and_reaches_the_coordinator(env, monkeypatch):
    """start_when landed:#<id>, a `ttp landed --task <id>` probe, a hold's when probe and depends_on that
    name no task in this project are refused per action, and the refusal reaches the next digest."""
    from types import SimpleNamespace
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    p = make(env)
    ok = p.db.add_task("the change", "s", origin="user")
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    before = p.db.one("SELECT COUNT(*) n FROM tasks")["n"]
    cases = [({"start_when": "landed:#0"}, "start_when landed:#0 names no task in this project"),
             ({"start_when": "landed:#987654"}, "names no task in this project (no task #987654)"),
             ({"start_when": "ttp landed --task 0 && test -f x"}, "(no task #0)"),
             ({"start_when": "ttp landed --task=abc"}, "(no task #abc)"),
             ({"depends_on": [0]}, "depends_on #0 names no task in this project"),
             ({"depends_on": [-3]}, "depends_on #-3 names no task in this project"),
             ({"depends_on": [987654]}, "no task #987654")]
    for extra, why in cases:
        problems = coord.apply(p, [{"type": "task_add", "title": "after it", "spec": "s", **extra},
                                   {"type": "task_add", "title": f"fine {why}", "spec": "s"}])
        assert len(problems) == 1 and problems[0].startswith('task_add: "after it": ') and why in problems[0], \
            (extra, problems)
        assert "use an existing task id or drop" in problems[0], problems
    assert not p.db.q("SELECT id FROM tasks WHERE title='after it'"), "a rejected task_add created a task"
    assert p.db.one("SELECT COUNT(*) n FROM tasks")["n"] == before + len(cases), "the rest of the batch was lost"
    for bad in ("landed:#-1", "landed:#x"):   # not a task id at all: the format check refuses it
        assert coord.apply(p, [{"type": "task_add", "title": "after it", "spec": "s", "start_when": bad}])
    # task_update: a re-deferral, a hold's when probe and depends_on.
    tid = p.db.add_task("later", "s", origin="user")
    for upd, why in (({"start_when": "landed:#0"}, f"#{tid} rejected: start_when landed:#0 names no task"),
                     ({"status": "blocked", "waits_on": "when:landed:#424242"}, "(no task #424242)"),
                     ({"depends_on": [0]}, "names no task in this project")):
        problems = coord.apply(p, [{"type": "task_update", "id": tid, "priority": 1, **upd}])
        assert len(problems) == 1 and why in problems[0], (upd, problems)
        assert p.db.task(tid)["priority"] == 3 and p.db.task(tid)["status"] == "queued", "a rejected update was applied"
    # An existing id still passes, in both forms.
    assert coord.apply(p, [{"type": "task_update", "id": tid, "start_when": f"landed:#{ok}", "depends_on": [ok]}]) == []
    assert coord.apply(p, [{"type": "task_add", "title": "waits ok", "spec": "s", "start_when": f"landed:#{ok}",
                            "depends_on": [ok]}]) == []
    assert coord.starts_text(p.db.task(tid), plain=True, db=p.db) == f"starts when #{ok} lands"
    # The refusal comes back to the coordinator in its next digest.
    d = Daemon(p.base)
    d.update_gates()
    bad = SimpleNamespace(structured={"actions": [{"type": "task_add", "title": "ghost wait", "spec": "s",
                                                   "start_when": "landed:#0"}], "summary": ""},
                          error="", final_text="")
    d._finish_coordinator({"dir": "x"}, bad, "ok", {})
    digest = coord.digest(p, {}, [], [])
    assert 'task_add: "ghost wait": start_when landed:#0 names no task in this project' in digest, digest
    # The CLI's paths take the same check.
    from ttp.cli import set_when
    with pytest.raises(ValueError, match="names no task in this project"):
        set_when(p.db, tid, "landed:#0", p)
    waiting = p.db.add_task("waiting one", "s", origin="user", result=None)
    p.db.update_task(waiting, result=json.dumps({"status": "waiting", "retry_when": "true"}))
    with pytest.raises(ValueError, match=r"retry_when ttp landed --task 0 names no task"):
        set_when(p.db, waiting, "ttp landed --task 0", p)
    assert "ttp landed --task" in set_when(p.db, waiting, f"ttp landed --task {ok}", p)


def test_a_task_already_waiting_on_a_missing_task_is_flagged_once_and_shown_broken(env):
    """State from before the check: the daemon raises one event per task, does not run the probe, `ttp landed`
    says it cannot tell, and status and the web app show the task as broken, not as a plan."""
    from ttp import coordinator as coord
    from ttp import landed
    from ttp.cli import status_text
    from ttp.daemon import Daemon
    from ttp.web import state_payload
    p = make(env)
    tid = p.db.add_task("ghost wait", "s", origin="user",
                        labels=coord.defer_labels(None, "landed:#0"))
    held = p.db.add_task("ghost hold", "s", origin="user")
    p.db.update_task(held, status="blocked", labels=json.dumps(["waits:when:ttp landed --task 77777"]))
    fine = p.db.add_task("fine wait", "s", origin="user", labels=coord.defer_labels(None, f"landed:#{held}"))
    d = Daemon(p.base)
    for _ in range(2):
        d.reconcile_tasks()
    ev = p.db.q("SELECT task, text, status FROM events WHERE kind='missing_task_ref' ORDER BY task")
    assert [e["task"] for e in ev] == [tid, held], ev
    assert "waits on #0, which does not exist" in ev[0]["text"] and ev[0]["status"] == "queued"
    assert "waits on #77777, which does not exist" in ev[1]["text"]
    assert coord.EFFORT_EVENT_TRIGGERS["missing_task_ref"] == "stuck"
    started = []
    d._start_probe = lambda tid_, probe, now, what="retry_when": (started.append(tid_),
                                                                   d._probe_rc.__setitem__(tid_, (1, now, probe)))
    d.probe_deferred(time.time())
    assert tid not in started and fine in started, started
    assert landed.check(p, p.root, None, 0)[0] == landed.CANNOT, "a probe on a missing task said 'not yet'"
    t = next(t for t in state_payload(p, p.db)["tasks"] if t["id"] == tid)
    assert t["starts"] == "broken: waits on #0, which does not exist", t
    out = status_text(p)
    assert f"  #{tid} broken: waits on #0, which does not exist: ghost wait" in out, out
    assert "starts when #0 lands" not in out
    assert "broken: waits on #0, which does not exist (start_when: landed:#0)" in coord.digest(p, {}, [], [])


def test_coordinator_cache_distinguishes_zero_partial_full_and_unknown(env):
    from ttp import budget as bud, audit
    from ttp.cli import status_text
    p = make(env)
    now = time.time()
    for fresh, read, write, metadata in (
        (100, 0, 0, {'complete': True, 'requests': 1}),
        (50, 50, 0, {'complete': True, 'requests': 1}),
        (0, 100, 0, {'complete': True, 'requests': 1}),
        (100, 0, 0, {'complete': False, 'requests': None}),
        (0, 0, 0, {'complete': True, 'requests': 1}),
        (100, 0, 0, None),
    ):
        note = {'cache_telemetry': metadata} if metadata is not None else {}
        p.db.x("INSERT INTO runs(role,provider,started,ended,status,cost_usd,input_tokens,cache_read_tokens,"
               "cache_write_tokens,note) VALUES('coordinator','claude',?,?,'ok',0.1,?,?,?,?)",
               (now - 60, now, fresh, read, write, json.dumps(note)))
    s = bud.coordinator_cache(p.db, now)['24h']
    assert s['turns'] == 6 and s['known_turns'] == 3
    # The turn with no cache_telemetry at all is from before the field existed: legacy, not missing.
    assert s['states'] == {'zero': 1, 'partial': 1, 'full': 1, 'missing': 2, 'legacy': 1}
    assert s['miss_turns'] == 1 and s['hit_pct'] == 50
    assert s['raw_tokens'] == {'input_tokens': 350, 'cache_read_tokens': 150, 'cache_write_tokens': 0}
    assert s['requests_unknown_turns'] == 2
    for text in (status_text(p), '\n'.join(audit.lines(p.db, now, p=p))):
        assert 'zero 1' in text and 'partial 1' in text and 'full 1' in text
        assert 'missing 2 (unknown), legacy 1 (before telemetry)' in text
        assert 'request count unknown for 2 turns' in text, "some turns carry a request count"


def test_coordinator_cache_line_drops_request_clause_when_no_turn_counts_requests():
    from ttp import budget as bud

    def row(requests):
        return {'note': json.dumps({'cache_telemetry': {'complete': True, 'requests': requests}}),
                'input_tokens': 10, 'cache_read_tokens': 90, 'cache_write_tokens': 0, 'cost_usd': 0.1}
    none = bud.coordinator_cache_line(bud._cache_summary([row(None), row(None)]))
    assert 'request count' not in none and 'legacy' not in none
    some = bud.coordinator_cache_line(bud._cache_summary([row(None), row(3)]))
    assert some.endswith('; request count unknown for 1 turns')
    assert 'request count' not in bud.coordinator_cache_line(bud._cache_summary([row(2)]))


def test_web_app_shows_the_servers_coordinator_cache_line_as_is(env):
    """The CLI, the daily review and the web app word the cache status once, on the server: the web
    payload carries coordinator_cache_line() per window and app.js shows it without rebuilding it."""
    from ttp import budget as bud
    from ttp.web import state_payload
    p = make(env)
    now = time.time()
    recorded = {'cache_telemetry': {'complete': True, 'requests': None}}   # Claude counts no requests
    for fresh, read, note in ((10, 90, recorded), (100, 0, recorded), (100, 0, {})):
        p.db.x("INSERT INTO runs(role,provider,started,ended,status,cost_usd,input_tokens,cache_read_tokens,"
               "cache_write_tokens,note) VALUES('coordinator','claude',?,?,'ok',0.1,?,?,0,?)",
               (now - 600, now - 500, fresh, read, json.dumps(note)))
    cache = state_payload(p, p.db)['budget']['coordinator_cache']
    for window in ('24h', '3d', '7d'):
        assert cache[window]['line'] == bud.coordinator_cache_line(bud.coordinator_cache(p.db, now)[window])
    line = cache['24h']['line']
    assert 'request count unknown' not in line, line
    # The turn from before the field existed is counted as legacy, not dropped from the counts.
    assert 'missing 0 (unknown), legacy 1 (before telemetry)' in line, line
    js = '\n'.join(f.read_text() for f in sorted((RUNTIME / 'ttp' / 'web').glob('*.js')))
    assert 'cache.line' in js
    for wording in ('token hit', 'request count unknown', '<50% read', 'before telemetry'):
        assert wording not in js, f"the web app rebuilds the server's cache wording: {wording!r}"


def test_cache_telemetry_backfill_rebuilds_old_turns_from_output_and_marks_the_rest_legacy(env):
    from ttp import budget as bud
    from ttp.providers.claude import Claude
    p = make(env)
    now = time.time()
    usage = {'input_tokens': 40, 'cache_read_input_tokens': 900, 'cache_creation_input_tokens': 60}
    ids = []
    for fresh, read, write, output in ((40, 900, 60, True),     # tokens match its output: filled
                                       (40, 800, 60, True),     # stored tokens differ: legacy
                                       (40, 900, 60, False)):   # output gone: legacy
        rid = p.db.x("INSERT INTO runs(role,provider,started,ended,status,cost_usd,input_tokens,"
                     "cache_read_tokens,cache_write_tokens,note) VALUES('coordinator','claude',?,?,'ok',0.1,"
                     "?,?,?,'{}')", (now - 600, now - 500, fresh, read, write))
        ids.append(rid)
        if output:
            d = p.runs / str(rid)
            d.mkdir(parents=True, exist_ok=True)
            (d / 'output.jsonl').write_text(json.dumps({'type': 'result', 'usage': usage, 'num_turns': 1}) + '\n')
    before = bud.coordinator_cache(p.db, now)['24h']
    assert before['states']['legacy'] == 3 and before['states']['missing'] == 0
    assert bud.backfill_cache_telemetry(p.db, p.runs, now) == {'filled': 1, 'legacy': 2}
    notes = [json.loads(p.db.one("SELECT note FROM runs WHERE id=?", (i,))['note'])['cache_telemetry'] for i in ids]
    parsed = Claude().parse(p.runs / str(ids[0]) / 'output.jsonl')
    assert (parsed.input_tokens, parsed.cache_read_tokens, parsed.cache_write_tokens) == (40, 900, 60)
    assert notes[0]['complete'] is True and notes[0]['backfilled'] is True
    assert notes[1]['source'] == notes[2]['source'] == 'legacy'
    after = bud.coordinator_cache(p.db, now)['24h']
    assert after['states'] == {'zero': 0, 'partial': 1, 'full': 0, 'missing': 0, 'legacy': 2}
    assert after['hit_pct'] == 90
    # Idempotent: a second pass finds nothing to do and changes no row.
    snapshot = [p.db.one("SELECT note FROM runs WHERE id=?", (i,))['note'] for i in ids]
    assert bud.backfill_cache_telemetry(p.db, p.runs, now) == {'filled': 0, 'legacy': 0}
    assert [p.db.one("SELECT note FROM runs WHERE id=?", (i,))['note'] for i in ids] == snapshot


