# quiet outages: known, under repair, owned by a person or ticket, paused, or needed by no open work ---------

def _quiet_box(env, owner="alpha", fallback="beta"):
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    alpha = make(env, owner)
    mm.add("box-a", tags="device")
    mm.set_recovery("box-a", owner=owner, fallback=fallback)
    never = {owner: (False, "its daemon is stopped"), fallback: (False, "it is paused")}
    return alpha, ml, never.get


def _walk(ml, able, t0, cond="down", steps=8):
    """Route the condition through every step of its chain, gamma still seeing it; returns the targets
    paged, in order."""
    got = []
    for i in range(steps):
        t = t0 + i * (ml.UNAVAILABLE_S + 60)
        ml.report("gamma", "box-a", cond, now=t)
        for page in ml.route(t, able=able):
            ml.delivered(page)
            got.append(page["target"])
    return got


def test_a_known_outage_pages_nobody_and_shows_in_the_daily_review(env, capsys):
    from ttp.cli import main
    alpha, ml, able = _quiet_box(env)
    main(["machines", "outage", "box-a", "tray swap in progress", "--expires", "3d", "--by", "alpha"])
    assert "box-a: known outage until" in capsys.readouterr().out
    t0 = time.time() + 2 * 3600
    ml.report("gamma", "box-a", "down", "no answer to ssh", now=t0 - 2 * 3600)
    ml.report("gamma", "box-a", "down", now=t0)
    assert _walk(ml, able, t0) == [], "no owner, fallback or user page while the outage is known"
    assert not ml.condition_open("box-a:down", now=t0 + 7 * (ml.UNAVAILABLE_S + 60)), "the user's alert clears"
    lines = ml.review_lines(alpha, now=t0 + 60)
    assert len(lines) == 1 and "box-a down" in lines[0] and "not paged: known outage" in lines[0]
    assert "tray swap in progress" in lines[0] and "gamma" in lines[0]
    assert ml.review_lines(alpha, now=t0 + ml.REVIEW_S + 8 * ml.UNAVAILABLE_S) == [], "a day later it is gone"
    main(["machines", "outage"])
    assert "tray swap in progress" in capsys.readouterr().out
    # Once it is cleared, an outage nobody explained escalates again, from the owner.
    main(["machines", "outage", "box-a", "--clear"])
    t1 = t0 + 5 * ml.UNAVAILABLE_S
    ml.report("gamma", "box-a", "down", now=t1)
    assert _walk(ml, able, t1) == ["alpha", "beta", ml.USER]


def test_an_outage_owned_by_a_person_or_ticket_pages_nobody(env, capsys):
    from ttp.cli import main
    alpha, ml, able = _quiet_box(env)
    with pytest.raises(SystemExit):
        main(["machines", "outage", "box-a", "board replacement"])   # no end: refused
    main(["machines", "outage", "box-a", "board replacement", "--owner", "hardware ticket", "--expires", "2d"])
    assert "owner: hardware ticket" in capsys.readouterr().out
    t0 = time.time()
    ml.report("gamma", "box-a", "down", now=t0)
    assert _walk(ml, able, t0 + 3600) == []
    c = ml.conditions()["box-a:down"]
    assert "owned by hardware ticket" in c["page"]["quiet"]
    assert "owned by hardware ticket" in ml.review_lines(alpha)[0]


def test_an_outage_says_what_it_covers_for_watchers(env, capsys):
    """[note e98d24284dafd149] `--covers` stores the parts an outage explains, shown in the list, the
    JSON and `ttp machines status`; a record without it stays valid and covers the whole machine."""
    import json as _json
    from ttp.cli import main
    alpha, ml, able = _quiet_box(env)
    with pytest.raises(SystemExit):
        main(["machines", "outage", "box-a", "tray swap", "--covers", "tray,toaster", "--expires", "1d"])
    assert "toaster" in capsys.readouterr().err and "box-a" not in ml.outages()
    main(["machines", "outage", "box-a", "tray swap", "--covers", "Fabric, tray", "--covers", "tray",
          "--expires", "1d"])
    assert "covers: tray, fabric" in capsys.readouterr().out
    assert ml.outages()["box-a"]["covers"] == ["tray", "fabric"]
    main(["machines", "outage", "--json"])
    got = _json.loads(capsys.readouterr().out)
    assert got["box-a"]["covers"] == ["tray", "fabric"] and got["box-a"]["why"] == "tray swap"
    main(["machines", "outage"])
    assert "covers: tray, fabric" in capsys.readouterr().out
    main(["machines", "status", "box-a", "--json"])
    assert _json.loads(capsys.readouterr().out)[0]["outage"]["covers"] == ["tray", "fabric"]
    main(["machines", "status", "box-a"])
    assert "covers: tray, fabric" in capsys.readouterr().out
    # Without --covers the record has no field, reads and quiets as before.
    main(["machines", "outage", "box-a", "fan repair", "--expires", "1d"])
    assert "covers" not in capsys.readouterr().out and "covers" not in ml.outages()["box-a"]
    main(["machines", "outage", "box-a", "--json"])
    assert "covers" not in _json.loads(capsys.readouterr().out)["box-a"]
    t0 = time.time()
    ml.report("gamma", "box-a", "down", now=t0)
    assert _walk(ml, able, t0 + 3600) == []


def test_a_known_fault_or_an_expected_change_stops_the_escalation(env):
    alpha, ml, able = _quiet_box(env)
    t0 = time.time()
    ml.report("gamma", "box-a", "held", now=t0, known="vendor firmware bug, repair is not ours")
    assert _walk(ml, able, t0 + 3600, "held") == ["alpha"], "the owner hears once; nobody else is paged"
    assert "known fault: gamma: vendor firmware bug" in ml.review_lines(alpha)[0]
    ml.report("gamma", "box-a", "held", cleared=True)
    ml.add_change("box-a", "disabled auto power cycle for a soak", "enable it", "gamma", expires="1d",
                  expects=["down"], now=t0)
    ml.report("gamma", "box-a", "down", now=t0)
    assert _walk(ml, able, t0 + 3600) == [], "a down the open change expects pages nobody"


def test_an_outage_no_open_work_needs_escalates_no_further_until_work_needs_it(env):
    alpha, ml, able = _quiet_box(env)
    gamma = _second_project(env, "gamma")
    t0 = time.time()
    ml.report("gamma", "box-a", "down", now=t0)
    assert _walk(ml, able, t0 + 3600) == ["alpha"]
    assert "not paged: no open work uses it" in ml.review_lines(alpha)[0]
    assert not ml.condition_open("box-a:down", now=t0 + 3600)
    # Open work on the machine: the escalation resumes from the step it reached.
    gamma.db.add_task("run the soak", labels=["resource:box-a-device"])
    t1 = t0 + 5 * ml.UNAVAILABLE_S
    ml.report("gamma", "box-a", "down", now=t1)
    assert _walk(ml, able, t1) == ["beta", ml.USER]


def test_an_unexplained_outage_that_open_work_needs_still_pages_the_user(env):
    alpha, ml, able = _quiet_box(env)
    gamma = _second_project(env, "gamma")
    gamma.db.add_task("run the soak", labels=["exclusive:box-a"])
    t0 = time.time()
    ml.report("gamma", "box-a", "down", now=t0)
    assert _walk(ml, able, t0 + 3600) == ["alpha", "beta", ml.USER]
    assert ml.condition_open("box-a:down", now=t0 + 3600) and ml.review_lines(alpha) == []


@pytest.mark.parametrize("by", ["coordinator", "user"])
def test_an_outage_whose_resource_its_project_paused_escalates_no_further(env, by):
    alpha, ml, able = _quiet_box(env)
    gamma = _second_project(env, "gamma")
    gamma.db.add_task("run the soak", labels=["resource:box-a-device"])
    gamma.db.set_kv("paused_resources", {"box-a-device": {"reason": "box out", "since": time.time(), "by": by}})
    t0 = time.time()
    ml.report("gamma", "box-a", "down", now=t0)
    assert _walk(ml, able, t0 + 3600) == ["alpha"]
    why = ml.conditions()["box-a:down"]["page"]["quiet"]
    assert why == ("the user paused gamma box-a-device" if by == "user"
                   else "no open work uses it (paused: gamma box-a-device)")


def test_a_shared_pause_on_the_machine_never_pages_the_user(env):
    from ttp import shared
    alpha, ml, able = _quiet_box(env)
    shared.update_pause("box-a", lambda v: {"reason": "box out", "since": time.time(), "by": "coordinator",
                                            "project": "gamma"})
    t0 = time.time()
    ml.report("gamma", "box-a", "down", now=t0)   # gamma is not readable here: it counts as needing it
    assert _walk(ml, able, t0 + 3600) == ["alpha"]
    assert "paused for every project: shared box-a" in ml.conditions()["box-a:down"]["page"]["quiet"]


def test_the_last_step_pages_the_reporters_coordinator_when_its_heal_check_escalates_there(env):
    alpha, ml, able = _quiet_box(env)
    t0 = time.time()
    ml.report("gamma", "box-a", "down", now=t0, escalate="coordinator")
    ml.report("delta", "box-a", "down", now=t0, escalate="user")
    assert _walk(ml, able, t0 + 3600) == ["alpha", "beta", "gamma"]
    ml.report("gamma", "box-a", "down", now=t0 + 3600, escalate="user")
    assert ml.conditions()["box-a:down"].get("escalate_by") == {}


def test_an_outage_check_whose_resource_is_paused_neither_escalates_nor_reports_the_machine(env):
    from ttp import heal
    from ttp import machine_ledger as ml
    from ttp import machines as mm
    mm.add("box-a", tags="device")
    p, d, up = _heal_setup(env, resource="box-a-device", outage=True, fix=None, grace_s=0)
    spec, now = _heal_spec(p), time.time()
    p.db.set_kv("paused_resources", {"box-a-device": {"reason": "box out", "since": now, "by": "coordinator"}})
    for dt in (0, 3600, 3 * heal.OUTAGE_S):
        assert heal.run(d, "svc", spec, now + dt) == ("unhealthy (box-a-device paused: not escalated)", None)
    dark = dict(spec, check="exit 255")
    p.db.set_kv(heal.STATE_KEY + "svc", {})
    for dt in (0, 2 * heal.OUTAGE_S):
        heal.run(d, "svc", dark, now + dt)
    assert ml.conditions() == {}
    assert not p.db.q("SELECT id FROM tasks WHERE origin='daemon'")
    assert not p.db.q("SELECT id FROM messages WHERE kind='alert'")
    # The pause lifted: the same outage escalates and reports the machine down.
    p.db.set_kv("paused_resources", {})
    assert "paused" not in heal.run(d, "svc", spec, now + 3 * heal.OUTAGE_S + 60)[0]
    assert "box-a:down" in ml.conditions()


def _paused_outage_setup(env, pause):
    from ttp import heal
    from ttp import machines as mm
    mm.add("box-a", tags="device")
    p, d, up = _heal_setup(env, resource="box-a-device", outage=True, fix=None, grace_s=0)
    spec, now = _heal_spec(p), time.time()
    p.db.set_kv("paused_resources", {"box-a-device": {"since": now, **pause}})
    return p, d, spec, now, heal


def _pause_asks(p):
    return p.db.q("SELECT fingerprint, severity, text FROM events WHERE fingerprint LIKE 'heal:svc:paused:%'")


@pytest.mark.parametrize("pause", [{"reason": "box out", "by": "user"},
                                   {"reason": "svc down: vendor repair", "by": "coordinator"},
                                   {"reason": "waiting on SVC repair", "by": "coordinator", "project": "gamma"}])
def test_an_outage_under_a_user_pause_or_one_naming_the_check_stays_silent_for_the_whole_pause(env, pause):
    from ttp import machine_ledger as ml
    p, d, spec, now, heal = _paused_outage_setup(env, pause)
    for dt in (0, heal.PAUSED_QUIET_S, 2 * heal.PAUSED_QUIET_S, 7 * 86400):
        assert heal.run(d, "svc", spec, now + dt) == ("unhealthy (box-a-device paused: not escalated)", None)
    assert _pause_asks(p) == [] and ml.conditions() == {}
    assert not p.db.q("SELECT id FROM messages WHERE kind IN ('alert', 'ask')")
    assert "box-a-device" in p.db.paused_resources()


@pytest.mark.parametrize("project", [None, "gamma"])
def test_an_outage_under_a_pause_for_another_reason_asks_the_coordinator_once_after_the_cap(env, project):
    from ttp import machine_ledger as ml
    pause = {"reason": "firmware soak", "by": "coordinator", **({"project": project} if project else {})}
    p, d, spec, now, heal = _paused_outage_setup(env, pause)
    quiet = heal.PAUSED_QUIET_S
    for dt in (0, quiet / 2, quiet - 60):
        assert heal.run(d, "svc", spec, now + dt)[0] == "unhealthy (box-a-device paused: not escalated)"
    assert _pause_asks(p) == []
    assert heal.run(d, "svc", spec, now + quiet)[0] == "unhealthy (box-a-device paused: coordinator asked)"
    for dt in (quiet + 1800, 3 * quiet, 7 * 86400):   # the same stretch: nothing more
        heal.run(d, "svc", spec, now + dt)
    asks = _pause_asks(p)
    assert len(asks) == 1 and asks[0]["text"].startswith(
        "Outage of box-a-device under a pause set for firmware soak for 6 h: is the pause still right?")
    assert ml.conditions() == {}, "no machine-ledger down report while paused"
    assert not p.db.q("SELECT id FROM tasks WHERE origin='daemon'")
    assert not p.db.q("SELECT id FROM messages WHERE kind IN ('alert', 'ask')"), "never the user"
    assert "box-a-device" in p.db.paused_resources(), "the pause is never lifted here"
    # The pause lifted: the same outage gets its normal handling and reports the machine down.
    p.db.set_kv("paused_resources", {})
    assert "paused" not in heal.run(d, "svc", spec, now + 7 * 86400 + 60)[0]
    assert "box-a:down" in ml.conditions()
    assert "pause_asked" not in heal.state(p.db, "svc")


def test_an_outage_under_a_pause_for_another_reason_follows_the_projects_quiet_cap(env):
    p, d, spec, now, heal = _paused_outage_setup(env, {"reason": "firmware soak", "by": "coordinator"})
    d.cfg["heal"] = {**(d.cfg.get("heal") or {}), "paused_quiet_s": 3600}
    for dt in (0, 3599):
        assert heal.run(d, "svc", spec, now + dt)[0] == "unhealthy (box-a-device paused: not escalated)"
    assert heal.run(d, "svc", spec, now + 3600)[0] == "unhealthy (box-a-device paused: coordinator asked)"
    assert "for 1 h" in _pause_asks(p)[0]["text"]


def test_an_on_pass_cmd_waiting_for_its_running_run_keeps_an_expired_task_asleep(env, monkeypatch, tmp_path):
    """A probe that passes while the run that named the on_pass_cmd still runs defers the command; a task
    whose timer already ran out must not be left ready for a model run, and the wait is logged once."""
    p = make(env)
    from ttp import daemon as dmod
    d = dmod.Daemon(p.base)
    tid, _ = _on_pass_cmd_task(p, tmp_path, "exit 0")
    run = p.db.one("SELECT id FROM runs WHERE task=?", (tid,))["id"]
    p.db.x("UPDATE runs SET status='running', ended=NULL WHERE id=?", (run,))
    task = p.db.task(tid)
    now = time.time()
    p.db.update_task(tid, not_before=now - 60)
    for _ in range(3):
        assert d._start_on_pass(p.db.task(tid), now) is True
    assert tid not in d._on_pass
    assert p.db.task(tid)["not_before"] >= now + dmod.PROBE_EVERY_S - 1
    assert not _ready(p, tid), "a model run must not start while its on_pass_cmd waits"
    assert (p.logs / "daemon.log").read_text().count(f"on_pass_cmd waits for run {run} to finish") == 1
    assert task["status"] == "queued"


def test_start_after_accepts_a_space_and_the_home_zone_abbreviation(env):
    from datetime import datetime, timezone
    from ttp import coordinator
    tz, now = "America/Los_Angeles", datetime(2026, 10, 13, 12, 0, tzinfo=timezone.utc).timestamp()
    want = datetime(2026, 10, 13, 23, 0, tzinfo=timezone.utc).timestamp()
    assert coordinator.parse_start_after("2026-10-13 16:00 PDT", now=now, tz=tz) == want
    assert coordinator.parse_start_after("2026-10-13 16:00", now=now, tz=tz) == want
    assert coordinator.parse_start_after("2026-12-01 16:00 pst", now=now, tz=tz) == \
        datetime(2026, 12, 2, 0, 0, tzinfo=timezone.utc).timestamp()
    with pytest.raises(ValueError, match=r"2026-10-13T16:00-07:00"):
        coordinator.parse_start_after("2026-10-13 16:00 EDT", now=now, tz=tz)
    with pytest.raises(ValueError, match=r"2026-10-13T16:00-07:00"):
        coordinator.parse_start_after("2026-10-13 16:00 PST", now=now, tz=tz)


def test_archiving_a_named_directory_of_many_files_takes_linear_time(tmp_path, monkeypatch):
    # A hand-off that named a directory of ~300k files kept a daemon's first tick busy for hours:
    # store() and _split() looked each file up in lists of all of them. 200k names stay well under a
    # few seconds with set lookups; the list scans took minutes.
    from ttp import archive
    n = 200_000
    named = [f"tmp/out/{i:06d}.txt" for i in range(n)]
    others = [f"build/{i:06d}.o" for i in range(n // 2)] + named[: n // 2]
    monkeypatch.setattr(archive, "files_of", lambda root, rels: named if rels == ["tmp/out"] else others)
    monkeypatch.setattr(archive, "sha256", lambda f, progress=None: "0" * 64)
    t0 = time.monotonic()
    with monkeypatch.context() as m:
        m.setattr(pathlib.Path, "lstat", lambda self: types.SimpleNamespace(st_size=1))
        named_files, keep, dropped, sizes = archive._split(tmp_path, ["tmp/out"], ["build"], cap_mb=0.05)
    assert len(named_files) == n and len(keep) == n + 50_000 and len(dropped) == n // 2 - 50_000
    new = archive._entries(tmp_path, keep + dropped, sizes, set(named_files), set(dropped), set(), "files.tar.gz")
    assert time.monotonic() - t0 < 20
    assert sum(e["named"] for e in new) == n and sum(e["stored"] == "dropped" for e in new) == len(dropped)
    assert all(e["archive"] == "files.tar.gz" for e in new if e["stored"] == "tar")


def test_a_tick_step_that_blocks_is_logged_with_every_threads_stack_and_alerted(env, monkeypatch):
    import ttp.daemon as dm
    p = make(env)
    d = dm.Daemon(p.base)
    d.cfg = p.config()
    monkeypatch.setattr(dm, "TICK_OVERRUN_S", 0.3)

    def step_that_blocks():   # a step stuck in a call with no timeout, still telling the watchdogs it moves
        for _ in range(20):
            time.sleep(0.05)
            d._progress()
    d.lift_boot_pause = step_that_blocks
    d._watch_ticks(every_s=0.05)
    try:
        d.tick()
        d._tick_ended()
    finally:
        d.stopping = True
    daemon_log = (p.logs / "daemon.log").read_text()
    assert "tick overrun: running 0 min, in step step_that_blocks" in daemon_log
    stacks = (p.state / dm.STACKS_FILE).read_text()
    assert "in step step_that_blocks" in stacks and "step_that_blocks" in stacks.split("in step", 1)[1].split("\n", 1)[1]
    told = p.db.one("SELECT * FROM messages WHERE kind='alert' AND ref='tick-overrun'")
    assert told and "in step step_that_blocks" in told["text"] and dm.STACKS_FILE in told["text"]
    # Once per tick: a later look at the same tick and a quick next tick add nothing.
    assert d.check_overrun(time.monotonic() + 3600) is None
    d._tick_began = d._moved = time.monotonic()
    assert d.check_overrun() is None
    d._tick_ended()
    assert len(p.db.q("SELECT id FROM messages WHERE kind='alert' AND ref='tick-overrun'")) == 1


def test_a_tick_step_blocked_without_progress_leaves_its_stacks_before_the_watchdogs_restart(env, monkeypatch):
    import ttp.daemon as dm
    p = make(env)
    d = dm.Daemon(p.base)
    d.cfg = p.config()
    # The stall dump (plus one watch interval) comes before the watchdogs restart a daemon whose last
    # seen progress (throttled to PROGRESS_EVERY_S) is WATCHDOG_S old; the long-tick dump does not.
    assert dm.TICK_STALL_S + 30 < dm.WATCHDOG_S - dm.PROGRESS_EVERY_S < dm.TICK_OVERRUN_S
    monkeypatch.setattr(dm, "TICK_STALL_S", 0.3)
    seen = {}

    def step_stuck_silently():   # a subprocess or lock wait with no timeout: never calls _progress
        time.sleep(1.0)
        stacks = p.state / dm.STACKS_FILE
        seen["stacks"] = stacks.read_text() if stacks.exists() else ""
    d.lift_boot_pause = step_stuck_silently
    d._watch_ticks(every_s=0.05)
    try:
        d.tick()
        d._tick_ended()
    finally:
        d.stopping = True
    assert "no progress for 0 min" in seen["stacks"] and "in step step_stuck_silently" in seen["stacks"]
    assert "step_stuck_silently" in seen["stacks"].split("in step", 1)[1].split("\n", 1)[1]
    assert seen["stacks"].count("--- ") == 1   # once per stall, not once per watch interval
    assert "tick stalled: " in (p.logs / "daemon.log").read_text()
    told = p.db.one("SELECT * FROM messages WHERE kind='alert' AND ref='tick-overrun'")
    assert told and "without progress" in told["text"] and "step_stuck_silently" in told["text"]


def test_both_signals_and_the_tick_overrun_dump_write_to_the_one_stacks_file(env):
    import ttp.daemon as dm
    p = make(env)
    stacks = p.state / dm.STACKS_FILE
    stacks.write_text("x" * (dm.STACKS_MAX_BYTES + 1))
    d = dm.Daemon(p.base)
    d.cfg = p.config()
    f = dm.register_stack_dump(p.state)
    assert f and stacks.with_name(stacks.name + ".1").stat().st_size > dm.STACKS_MAX_BYTES   # rotated
    try:
        for sig in (signal.SIGUSR1, signal.SIGUSR2):
            os.kill(os.getpid(), sig)
            time.sleep(0.2)
        d._tick_began = d._moved = time.monotonic() - dm.TICK_OVERRUN_S - 1
        o = d.check_overrun()
        assert o and o["stacks"] == str(stacks)
        f.flush()
        text = stacks.read_text()
        assert text.count("Current thread") == 3 and "tick stalled" in text
        assert not (p.logs / "tick-stacks.log").exists()
    finally:
        import faulthandler
        faulthandler.unregister(signal.SIGUSR1)
        faulthandler.unregister(signal.SIGUSR2)


def test_a_host_sleep_during_a_tick_is_no_overrun(env, monkeypatch):
    import ttp.daemon as dm
    p = make(env)
    d = dm.Daemon(p.base)
    d.cfg = p.config()
    real = time.time
    d.tick()   # a real tick: it started on the monotonic clock
    d._tick_began = d._moved = time.monotonic()
    monkeypatch.setattr(dm.time, "time", lambda: real() + 3 * 3600)   # the wall clock jumps; monotonic did not
    assert d.check_overrun() is None
    d._tick_ended()
    assert not (p.state / dm.STACKS_FILE).exists()
    assert not p.db.q("SELECT id FROM messages WHERE kind='alert' AND ref='tick-overrun'")


def _verified_checks_repo(env, tmp_path, monkeypatch):
    """A worktree whose project checks are one unscoped check and one scoped to src/**, each counting
    its runs, with a push target at the first commit so the scope compares with it."""
    p, repo, run, git = _checks_repo(env, tmp_path, monkeypatch)
    whole, scoped = tmp_path / "whole", tmp_path / "scoped"
    p.set_config("delivery.push_checks", [f"sh -c 'echo x >> {whole}'",
                                          {"run": f"sh -c 'echo x >> {scoped}'", "if_changed": "src/**"}])
    p.set_config("delivery.push_branch", "origin/proj")
    subprocess.run([*git, "remote", "add", "origin", str(tmp_path / "none.git")], check=True)
    subprocess.run([*git, "update-ref", "refs/remotes/origin/proj", "HEAD"], check=True)
    ran = lambda f: len(f.read_text().splitlines()) if f.exists() else 0
    return p, repo, run, git, lambda: (ran(whole), ran(scoped))


def _commit_in(git, repo, name, text):
    path = repo / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text)
    subprocess.run([*git, "add", name], check=True)
    subprocess.run([*git, "commit", "-qm", name], check=True)
    return subprocess.run([*git, "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()


def test_a_continuation_checks_only_the_commits_after_its_inherited_marker(env, tmp_path, monkeypatch, capsys):
    from ttp import cli, push, verified
    p, repo, run, git, counts = _verified_checks_repo(env, tmp_path, monkeypatch)
    first = p.db.add_task("first hop", kind="code")
    nxt = p.db.add_task("next hop", kind="code", labels=[f"continues:{first}"])
    monkeypatch.setenv("TTP_TASK", str(first))
    marked = _commit_in(git, repo, "src/a.py", "a = 1\n")
    cli.main(["checks"])
    assert counts() == (1, 1)
    assert verified.own(p.db, first, "checks")["sha"] == marked
    # The next hop inherits the marker: its commit touches nothing under src/**, so the scoped check is
    # verified through the marker; the unscoped one covers the whole tree and runs again.
    monkeypatch.setenv("TTP_TASK", str(nxt))
    monkeypatch.setenv("TTP_RUN_ID", "42")
    head = _commit_in(git, repo, "notes.txt", "notes\n")
    capsys.readouterr()
    cli.main(["checks"])
    out = capsys.readouterr().out
    assert counts() == (2, 1), out
    assert f"verified through {marked[:12]} (#{first}'s checks)" in out
    rec = json.loads((run / "checks.json").read_text())
    assert rec["passed"] is True and rec["verified_through"] == marked and len(rec["verified"]) == 1
    # Its own marker carries the verified check on, so the hop after it can skip it too.
    assert len(verified.own(p.db, nxt, "checks")["commands"]) == 2
    # The push gate never reads the marker: the scoped check still applies to the pushed head.
    todo, _ = push.applicable(repo, head, push.check_list(p.config()["delivery"]["push_checks"]),
                              lambda m: None, "origin/proj")
    assert len(todo) == 2
    # A rerun on the same head by the same task (e.g. the daemon's pre-started checks) reuses what is
    # known: the scoped check through its own marker at HEAD, the unscoped one through its recorded pass.
    capsys.readouterr()
    cli.main(["checks"])
    out = capsys.readouterr().out
    assert counts() == (2, 1), out
    assert "(recorded)" in out
    # --fresh runs every check again.
    cli.main(["checks", "--fresh"])
    assert counts() == (3, 2)
    # The first hop's own rerun on its head still hits its recorded pass of every check.
    monkeypatch.setenv("TTP_TASK", str(first))
    subprocess.run([*git, "checkout", "-q", marked], check=True)
    cli.main(["checks"])
    assert counts() == (3, 2)
    subprocess.run([*git, "checkout", "-q", "-"], check=True)
    monkeypatch.setenv("TTP_TASK", str(nxt))
    # A commit after the marker under src/** runs the scoped check again.
    _commit_in(git, repo, "src/b.py", "b = 1\n")
    cli.main(["checks"])
    assert counts() == (4, 3)


def test_checks_fresh_ignores_an_inherited_marker_at_an_ancestor(env, tmp_path, monkeypatch, capsys):
    from ttp import cli
    p, repo, run, git, counts = _verified_checks_repo(env, tmp_path, monkeypatch)
    first = p.db.add_task("first hop", kind="code")
    nxt = p.db.add_task("next hop", kind="code", labels=[f"continues:{first}"])
    monkeypatch.setenv("TTP_TASK", str(first))
    marked = _commit_in(git, repo, "src/a.py", "a = 1\n")
    cli.main(["checks"])
    assert counts() == (1, 1)
    # The next hop's head is a descendant of the marker: --fresh still runs the scoped check again.
    monkeypatch.setenv("TTP_TASK", str(nxt))
    _commit_in(git, repo, "notes.txt", "notes\n")
    capsys.readouterr()
    cli.main(["checks", "--fresh"])
    out = capsys.readouterr().out
    assert counts() == (2, 2), out
    assert f"verified through {marked[:12]}" not in out


def test_a_rewritten_history_falls_back_to_full_verification(env, tmp_path, monkeypatch, capsys):
    from ttp import cli, prompts, verified
    p, repo, run, git, counts = _verified_checks_repo(env, tmp_path, monkeypatch)
    first = p.db.add_task("first hop", kind="code")
    nxt = p.db.add_task("next hop", kind="code", labels=[f"continues:{first}"])
    monkeypatch.setenv("TTP_TASK", str(first))
    marked = _commit_in(git, repo, "src/a.py", "a = 1\n")
    cli.main(["checks"])
    assert counts() == (1, 1)
    line = prompts.verified_line(p, p.db.task(nxt), str(repo))
    assert f"verified through {marked[:12]}" in line and f"git log {marked[:12]}..HEAD" in line
    # The marker's commit is rewritten away (an amend of its message only, as a rebase would): not an
    # ancestor any more, though nothing under src/** changed, so only the fallback reruns the scoped check.
    subprocess.run([*git, "commit", "-q", "--amend", "-m", "src/a.py, reworded"], check=True)
    _commit_in(git, repo, "notes.txt", "notes\n")
    monkeypatch.setenv("TTP_TASK", str(nxt))
    capsys.readouterr()
    cli.main(["checks"])
    out = capsys.readouterr().out
    assert counts() == (2, 2), "a marker that is no longer an ancestor still skipped a check"
    assert "no longer an ancestor" in out and "full verification" in out
    assert "verified" not in json.loads((run / "checks.json").read_text())
    line = prompts.verified_line(p, p.db.task(nxt), str(repo))
    assert "no longer an ancestor" in line and "Verify the whole change" in line
    # A task that continues nothing gets no marker line.
    assert prompts.verified_line(p, p.db.task(first), str(repo)) == ""
    assert verified.scope(p.db, p.db.task(first), repo, marked) is None


def test_a_passing_review_marks_the_reviewed_head_for_the_tasks_that_continue_it(env, tmp_path, monkeypatch):
    from ttp import coordinator as coord, verified
    from ttp.daemon import Daemon
    p, repo, run, git, counts = _verified_checks_repo(env, tmp_path, monkeypatch)
    monkeypatch.setattr(p, "root", repo)
    d = Daemon(p.base)
    d.p = p
    code = p.db.add_task("first hop", kind="code")
    review = p.db.add_task(f"Review #{code}: first hop", kind="review", depends_on=[code],
                           labels=[f"auto_review:{code}"])
    reviewed = _commit_in(git, repo, "src/a.py", "a = 1\n")
    extra = {}
    d._mark_verified(p.db.task(review), {"entries": [{"branch": "b", "head": reviewed}]}, extra)
    assert extra["verified_through"] == reviewed
    assert verified.own(p.db, code, "review") == {**verified.own(p.db, code, "review"), "sha": reviewed,
                                                   "review": review, "kind": "review"}
    # A fix that continues the review inherits the reviewed head: its review covers only what came after.
    fix = p.db.add_task("fix", kind="code", labels=[f"continues:{review}"])
    head = _commit_in(git, repo, "src/b.py", "b = 1\n")
    line = d._verified_review_line(p.db.task(fix), head)
    assert f"verified through {reviewed[:12]} (#{code}'s review)" in line
    assert f"git log {reviewed[:12]}..{head[:12]}" in line and "push checks still run in full" in line
    # Rewritten: the review covers the whole change.
    subprocess.run([*git, "reset", "-q", "--hard", "HEAD~2"], check=True)
    head = _commit_in(git, repo, "src/c.py", "c = 1\n")
    assert "review the whole change" in d._verified_review_line(p.db.task(fix), head)
    # A code task with no lineage has no marker line; the hand-off line shows the marker.
    assert d._verified_review_line(p.db.task(code), head) == ""
    p.db.update_task(review, status="done", result=json.dumps({"summary": "passed", **extra}))
    assert f"verified through {reviewed[:12]}" in coord.digest(p, {}, [], []).split("## Recently finished")[1]


def test_failover_review_lines_say_when_a_logout_ended(env):
    """A logged-out cause whose breaker closed since shows its end and the task's status; an open one keeps 'no known end'."""
    from ttp import alerts, failover
    p = make(env)
    now = time.time()
    tid = p.db.add_task("long job", "Run it.", kind="work", tier="standard", provider="claude")
    line = (f"#{tid} long job: left running on claude, which cannot start new work (logged out) with no known end; "
            "a later run of it moves unless its pin is required")
    p.db.x("INSERT INTO events(ts,source,kind,severity,text,status,task) VALUES(?,?,?,?,?,?,?)",
           (now - 5 * 3600, "daemon", failover.KIND, "low", line, "handled", tid))
    p.db.set_kv(alerts.BREAKER + "claude", {"open": True, "opened": now - 6 * 3600})
    assert failover.review_lines(p.db, now, where="America/Los_Angeles") == [line]
    p.db.set_kv(alerts.BREAKER + "claude", {"open": False, "opened": now - 6 * 3600, "closed": now - 3.5 * 3600})
    p.db.update_task(tid, status="done")
    got = failover.review_lines(p.db, now, where="America/Los_Angeles")[0]
    assert "no known end" not in got and "(ended " in got and "lasted 2.5 h)" in got, got
    assert got.endswith(f"#{tid} is now done") and (" PDT, " in got or " PST, " in got), got


# ssh-preflight @<resource> and stale harness git locks ----------------------------------------------
def _fake_preflight_ssh(tmp_path, up: set[str]) -> dict:
    """A stand-in ssh on PATH: logs its target, exits 0 for hosts in `up`, 255 for others."""
    bindir = tmp_path / "fakebin"
    bindir.mkdir(exist_ok=True)
    log = tmp_path / "ssh.log"
    ups = " ".join(sorted(up))
    (bindir / "ssh").write_text(
        "#!/bin/sh\nwhile [ $# -gt 0 ]; do case \"$1\" in -o) shift 2;; *) break;; esac; done\n"
        f"echo \"$1\" >> {shlex.quote(str(log))}\n"
        f"for h in {ups}; do [ \"$h\" = \"$1\" ] && exit 0; done\n"
        "echo \"ssh: connect to host $1 port 22: No route to host\" >&2\nexit 255\n")
    (bindir / "ssh").chmod(0o755)
    return {"PATH": f"{bindir}:{os.environ['PATH']}", "_log": log}


def test_hostmap_resolves_a_resource_from_config_and_leaves_a_plain_host_alone():
    sys.path.insert(0, str(RUNTIME))
    from ttp import hostmap
    cfg = {"device": {"locks": ["dev-a", "dev-b"], "hosts": {"dev-a": "boxA", "build": " boxB "},
                      "runners": {"dev-a": {"host": "boxR"}, "r2": {"host": "boxC"}, "local": {}}}}
    assert hostmap.resolve(cfg, "boxZ") == "boxZ", "a plain host is probed as it is"
    assert hostmap.resolve(cfg, "@dev-a") == "boxA", "device.hosts wins over a runner of the same name"
    assert hostmap.resolve(cfg, "@dev-b") == "boxA", "a device lock name finds the name it shares the lock with"
    assert hostmap.resolve(cfg, "@build") == "boxB"
    assert hostmap.resolve(cfg, "@r2") == "boxC", "a runner's host counts"
    with pytest.raises(KeyError) as e:
        hostmap.resolve(cfg, "@nope")
    assert "'nope'" in e.value.args[0] and "@build" in e.value.args[0] and "@local" not in e.value.args[0]
    with pytest.raises(KeyError):
        hostmap.resolve({}, "@dev-a")
    assert hostmap.problems({"device": {"hosts": ["boxA"]}}) == ["device.hosts: not a table of resource names to hosts"]
    assert hostmap.problems({"device": {"hosts": {"a": "", "b": 3, "c": "-oProxy", "d": "@e", "ok": "boxA"}}}) == [
        "device.hosts.a: '' is not a host name", "device.hosts.b: 3 is not a host name",
        "device.hosts.c: '-oProxy' is not a host name", "device.hosts.d: '@e' is not a host name"]
    from ttp.project import config_problems
    assert "device.hosts: not a table of resource names to hosts" in config_problems({"device": {"hosts": "x"}})


def test_ssh_preflight_follows_a_resource_to_its_current_host(env, tmp_path):
    p = make(env)
    fake = _fake_preflight_ssh(tmp_path, {"boxA", "boxB"})
    run = lambda *a: _ttp_run(p, "ssh-preflight", *a, env={"PATH": fake["PATH"]})
    r = run("boxA")
    assert r.returncode == 0 and "boxA reachable" in r.stdout, r.stderr
    r = run("boxQ")
    assert r.returncode == 255 and "No route to host" in r.stderr
    # Unknown resource: exit 2 (the probe is broken, so the task wakes), naming what the map has.
    r = run("@dev")
    assert r.returncode == 2 and "no host for resource 'dev'" in r.stderr and "known: none" in r.stderr
    p.set_config("device", {"hosts": {"dev": "boxQ"}})
    r = run("@dev")
    assert r.returncode == 255 and "boxQ (@dev) not reachable" in r.stderr
    # The resource moved: the same probe now reaches the new box.
    p.set_config("device.hosts.dev", "boxB")
    r = run("@dev")
    assert r.returncode == 0 and "boxB (@dev) reachable" in r.stdout, r.stderr
    assert fake["_log"].read_text().split() == ["boxA", "boxQ", "boxQ", "boxB"]
    # Found from the working directory too, as retry_when probes run in the project root.
    e = {k: v for k, v in os.environ.items() if k not in ("TTP_PROJECT", "TTP_RUN_DIR")}
    r = subprocess.run([sys.executable, str(TTP), "ssh-preflight", "@dev"], cwd=str(p.root),
                       env={**e, "PATH": fake["PATH"]}, capture_output=True, text=True, timeout=30)
    assert r.returncode == 0, r.stderr


def test_ssh_preflight_forces_strict_host_keys_and_classifies_ssh_failures(env, tmp_path):
    """Strict host keys and no shared connection whatever the user's ssh config says; ssh's own
    failures exit 10 (host key), 11 (auth) or 255 (unreachable; 12 with --classified)."""
    p = make(env)
    bindir = tmp_path / "fakebin"
    bindir.mkdir()
    log = tmp_path / "ssh-args.log"
    (bindir / "ssh").write_text(
        "#!/bin/sh\n"
        f"echo \"$*\" >> {shlex.quote(str(log))}\n"
        "for a; do h=$a; done; for a; do [ \"$a\" = true ] && break; h=$a; done\n"
        "case \"$h\" in\n"
        "  up) exit 0;;\n"
        "  changed) echo '@@@ WARNING: REMOTE HOST IDENTIFICATION HAS CHANGED! @@@' >&2;"
        " echo 'Host key verification failed.' >&2; exit 255;;\n"
        "  unknown) echo 'No ED25519 host key is known for unknown and you have requested strict checking.' >&2;"
        " echo 'Host key verification failed.' >&2; exit 255;;\n"
        "  noauth) echo 'user@noauth: Permission denied (publickey,password).' >&2; exit 255;;\n"
        "  remote1) exit 1;;\n"
        "  *) echo \"ssh: connect to host $h port 22: Connection timed out\" >&2; exit 255;;\n"
        "esac\n")
    (bindir / "ssh").chmod(0o755)
    path = f"{bindir}:{os.environ['PATH']}"
    run = lambda *a: _ttp_run(p, "ssh-preflight", *a, env={"PATH": path})
    r = run("up")
    assert r.returncode == 0 and "up reachable" in r.stdout, r.stderr
    args = log.read_text().splitlines()[0].split()
    for opt in ("BatchMode=yes", "StrictHostKeyChecking=yes", "ControlMaster=no", "ControlPath=none"):
        assert opt in args and args[args.index(opt) - 1] == "-o", (opt, args)
    assert args[-2:] == ["up", "true"]
    for host, rc, says in (("changed", 10, "host key not verified"), ("unknown", 10, "host key not verified"),
                           ("noauth", 11, "authentication failed"), ("gone", 255, "not reachable")):
        r = run(host)
        assert r.returncode == rc and f"{host} {says}" in r.stderr and f"(exit {rc})" in r.stderr, \
            (host, r.returncode, r.stderr)
        r = run(host, "--classified")
        assert r.returncode == (12 if rc == 255 else rc), (host, r.returncode, r.stderr)
    # A remote command's own exit is not ssh failing: kept as it is.
    assert run("remote1").returncode == 1
    # Through a resource too; the default 255 is what keeps a waiting retry_when asleep.
    p.set_config("device", {"hosts": {"dev": "changed", "far": "gone"}})
    r = run("@dev")
    assert r.returncode == 10 and "changed (@dev) host key not verified" in r.stderr, r.stderr
    from ttp import daemon, hostmap
    assert run("@far").returncode == hostmap.UNREACHABLE_RC in daemon.NOT_YET_RCS
    assert not {hostmap.HOST_KEY_RC, hostmap.AUTH_RC} & set(daemon.NOT_YET_RCS)
    assert run("@far", "--classified").returncode == 12
    # A timeout or a missing ssh is unreachable too.
    assert hostmap.classify(255, "") == 255 and hostmap.classify(255, "", classified=True) == 12
    assert hostmap.classify(0, "Host key verification failed.") == 0


def test_worker_prompt_says_to_probe_a_mapped_resource_by_name(env):
    p = make(env)
    from ttp.prompts import worker_features
    task = {"id": 1, "kind": "code", "title": "t", "spec": "s"}
    assert "hostmap" not in worker_features(p, task)
    p.set_config("device", {"hosts": {"dev": "boxA"}})
    assert "hostmap" in worker_features(p, task)
    src = (RUNTIME.parent / "template" / "prompts" / "worker.md").read_text()
    from ttp.prompts import feature_blocks, _hostmap_line
    assert "ttp ssh-preflight @<resource>" in feature_blocks(src, {"hostmap", "wait"})
    assert "ttp ssh-preflight" not in feature_blocks(src, {"wait"})
    assert _hostmap_line(p.config()).startswith("resource hosts (probe with `ttp ssh-preflight @<resource>`")
    assert "@dev (on boxA)" in _hostmap_line(p.config()) and _hostmap_line({}) == ""


def _harness_lock(repo: pathlib.Path, rel: str, age_s: float) -> pathlib.Path:
    path = repo / ".git" / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("")
    t = time.time() - age_s
    os.utime(path, (t, t))
    return path


def test_stale_git_locks_are_cleared_but_live_or_young_ones_kept(tmp_path):
    sys.path.insert(0, str(RUNTIME))
    from ttp import gitlocks
    repo = tmp_path / "harness"
    subprocess.run(["git", "init", "-q", str(repo)], check=True)
    old = _harness_lock(repo, "index.lock", 3600)
    ref = _harness_lock(repo, "refs/heads/main.lock", 3600)
    young = _harness_lock(repo, "HEAD.lock", 30)
    obj = _harness_lock(repo, "objects/pack/x.lock", 3600)
    # A git process running in the repository may hold them: nothing is removed.
    me = os.getpid()
    other = subprocess.Popen(["sleep", "30"], cwd=str(repo))
    try:
        procs = [(other.pid, "git commit -q")]
        removed, held = gitlocks.clear(repo, 600, procs=procs)
        assert removed == [] and held == [other.pid] and old.exists() and ref.exists()
        # A git process naming the repository holds it too, wherever it runs.
        assert gitlocks.clear(repo, 600, procs=[(me, f"git -C {repo.resolve()} add x")])[1] == [me]
    finally:
        other.kill()
        other.wait()
    assert gitlocks.clear(repo, 0, procs=[]) == ([], []), "0 turns it off"
    # A git process that ended, a git process elsewhere, or another program does not.
    gone = subprocess.Popen(["true"])
    gone.wait()
    removed, held = gitlocks.clear(repo, 600, procs=[(me, "python3 x"), (gone.pid, "git status"),
                                                     (me, f"git log {tmp_path / 'other'}")])
    assert held == [] and sorted(removed) == sorted([old, ref])
    assert young.exists(), "a lock younger than the threshold is kept"
    assert obj.exists(), "object store locks are left alone"
    assert not old.exists() and not ref.exists()
    kept = sorted(x.relative_to(repo / ".git" / gitlocks.KEEP_DIR).parts[1:]
                  for x in (repo / ".git" / gitlocks.KEEP_DIR).rglob("*.lock"))
    assert kept == [("index.lock",), ("refs", "heads", "main.lock")], "moved aside, never deleted"
    # What was moved aside is never a candidate again.
    assert gitlocks.clear(repo, 600, procs=[]) == ([], [])


def test_a_git_lock_a_process_has_open_is_never_stale(tmp_path):
    if not pathlib.Path("/proc/self/fd").is_dir():
        pytest.skip("open files are read from /proc")
    sys.path.insert(0, str(RUNTIME))
    from ttp import gitlocks
    repo = tmp_path / "harness"
    subprocess.run(["git", "init", "-q", str(repo)], check=True)
    lock = _harness_lock(repo, "index.lock", 3600)
    holder = subprocess.Popen([sys.executable, "-c", "import sys,time; f=open(sys.argv[1]); time.sleep(30)",
                               str(lock)])
    try:
        deadline = time.time() + 10
        while str(lock) not in gitlocks._open_fds(holder.pid) and time.time() < deadline:
            time.sleep(0.05)
        removed, held = gitlocks.clear(repo, 600, procs=[(holder.pid, "python3 holder")])
        assert removed == [] and held == [holder.pid] and lock.exists()
    finally:
        holder.kill()
        holder.wait()
    assert gitlocks.clear(repo, 600, procs=[])[0] == [lock]


def test_daemon_sweep_moves_a_stale_harness_git_lock_aside_and_logs_it(env):
    p = make(env)
    from ttp import gitlocks
    from ttp.daemon import Daemon
    gdir = gitlocks.git_dir(p.harness)
    assert gdir is not None
    lock = _harness_lock(gdir.parent, "index.lock", 3600)
    d = Daemon(p.base)
    assert not hasattr(d, "clear_git_locks"), "one cleaner: the harness sweep"
    d.heal_harness_git()
    assert not lock.exists() and list((gdir / gitlocks.KEEP_DIR).rglob("index.lock"))
    assert "moved stale lock file(s) aside" in _daemon_log_text(p)
    ev = p.db.one("SELECT severity,text FROM events WHERE kind='git_lock_cleared'")
    assert ev["severity"] == "low" and "index.lock" in ev["text"]
    # Off when the threshold is 0.
    lock = _harness_lock(gdir.parent, "index.lock", 3600)
    p.set_config("harness_git.stale_lock_s", 0)
    assert p.clear_stale_git_locks() == [] and lock.exists()


def test_stale_git_lock_setting_reads_the_old_watchdog_key_only_when_the_new_one_is_unset(env):
    p = make(env)
    from ttp import gitlocks
    from ttp.project import unknown_key_hint
    assert gitlocks.settings({}) == gitlocks.settings(p.config()) == 600
    assert gitlocks.settings({"watchdog": {"stale_git_lock_s": 0}}) == 0
    assert gitlocks.settings({"watchdog": {"stale_git_lock_s": 1200}}) == 1200
    assert gitlocks.settings({"harness_git": {"stale_lock_s": 900}, "watchdog": {"stale_git_lock_s": 0}}) == 900
    assert gitlocks.settings({"harness_git": {"stale_lock_s": "x"}}) == 600
    assert unknown_key_hint("harness_git.stale_lock_s") is None
    assert unknown_key_hint("watchdog.stale_git_lock_s") is None, "the old key stays quiet"
    # The old key still turns it off for both callers.
    lock = _harness_lock(gitlocks.git_dir(p.harness).parent, "index.lock", 3600)
    p.set_config("watchdog.stale_git_lock_s", 0)
    assert p.clear_stale_git_locks() == [] and lock.exists()
    p.set_config("harness_git.stale_lock_s", 600)
    assert p.clear_stale_git_locks() == ["index.lock"] and not lock.exists()


def test_a_plain_task_done_waits_for_company_even_with_an_idle_slot(env):
    p = make(env)
    from ttp import coordinator as coord
    from ttp.daemon import Daemon
    p.db.x("UPDATE events SET status='handled'")
    p.db.x("UPDATE tasks SET status='done'")
    p.set_config("budget.max_parallel_workers", 2)
    d = Daemon(p.base)
    d.gates = {}
    now = time.time()
    done = p.db.add_task("finished", "s", status="done")
    ev = {"ts": now - 10, "kind": "task_done", "severity": "normal", "task": done}
    assert d._batch_hold([ev], now), "a plain hand-off with idle slots and no queued work waits for batch_s"
    assert not d._batch_hold([ev], now + 400), "batch_s still bounds the wait"
    assert not d._batch_hold([dict(ev, severity="high")], now)
    assert not d._batch_hold([dict(ev, task=None)], now)
    # A proposed follow-up is work the turn could queue into the idle slot.
    fid = p.db.x("INSERT INTO events(ts,source,kind,severity,text,status,task) VALUES(?,?,?,?,?,?,?)",
                 (now, f"task:{done}", "followup_proposed", "normal", "f", "queued", done))
    assert not d._batch_hold([ev], now)
    p.db.x("UPDATE events SET status='handled' WHERE id=?", (fid,))
    assert d._batch_hold([ev], now)
    # A live task depending on it, or a waiting parent, may need the turn now.
    dep = p.db.add_task("next", "s", status="waiting")
    p.db.x("UPDATE tasks SET depends_on=? WHERE id=?", (json.dumps([done]), dep))
    assert not d._batch_hold([ev], now)
    p.db.update_task(dep, status="done")
    assert d._batch_hold([ev], now)
    parent = p.db.add_task("parent", "s", status="waiting")
    p.db.x("UPDATE tasks SET parent=? WHERE id=?", (parent, done))
    assert not d._batch_hold([ev], now)
    p.db.update_task(parent, status="done")
    assert d._batch_hold([ev], now)
    # Normal upstream notes and info observations batch; they do not take the idle-slot hold.
    assert coord.batchable("upstream_note", "normal") and coord.batchable("observation", "info")
    assert not coord.batchable("upstream_note", "high") and not coord.batchable("task_done", "info")
    note = {"ts": now - 10, "kind": "upstream_note", "severity": "normal", "task": None}
    assert not d._batch_hold([ev, note], now)


def test_a_mute_that_ended_with_nothing_muted_or_by_its_probe_settles_without_a_turn(env):
    p = make(env)
    from ttp import screen as scr
    now = time.time()

    def ended():
        return [(e["text"], e["status"]) for e in
                p.db.q("SELECT text, status FROM events WHERE text LIKE 'mute ended:%' ORDER BY id")]
    scr.mute(p.db, "watcher:hw", "dropped", 1, now=now - 7200)
    scr.expire_mutes(p.db, now)
    [(text, status)] = ended()
    assert "no observations" in text and status == "handled", (text, status)
    # Observations were muted: the summary still goes to a turn.
    scr.mute(p.db, "watcher:hw", "dropped", 1, now=now - 7200)
    with p.db.tx():
        [m] = p.db.kv(scr.MUTES_KEY)
        m.update(count=3, last_at=now - 600)
        p.db.set_kv(scr.MUTES_KEY, [m])
    scr.expire_mutes(p.db, now)
    assert ended()[-1][1] == "queued" and "3 observations" in ended()[-1][0]
    # Ended by its end_when probe (the recovery condition passed): settled, whatever it counted.
    scr.mute(p.db, "watcher:hw", "held", 6, now=now, end_when="true")
    with p.db.tx():
        [m] = p.db.kv(scr.MUTES_KEY)
        m.update(count=2, last_at=now)
        p.db.set_kv(scr.MUTES_KEY, [m])
    assert scr.end_mute(p.db, "watcher:hw", "held", "true", "probe `true` passed", now=now + 1)
    assert ended()[-1][1] == "handled" and "2 observations" in ended()[-1][0]


def test_wait_stale_skips_a_bare_time_gate_until_its_epoch_passes(env):
    p = make(env)
    from ttp import daemon as dmod
    assert dmod.time_gate('test "$(date +%s)" -ge 1760000000') == 1760000000
    assert dmod.time_gate('[ $(date +%s) -gt 5 ]') == 6 and dmod.time_gate('[[ "$(date +%s)" -ge "7" ]]') == 7
    assert dmod.time_gate('test "$(date +%s)" -ge 1 && test -e x') is None and dmod.time_gate("exit 1") is None
    d = dmod.Daemon(p.base)
    ahead = int(time.time()) + 3 * 3600
    tid = _due_waiting_task(p, f'test "$(date +%s)" -ge {ahead}', since_ago=6 * 3600 + 60)
    _settle_probe(d, tid)
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()
    assert not p.db.q("SELECT id FROM events WHERE task=? AND kind IN ('wait_stale', 'probe_never_passes')", (tid,))
    assert not _ready(p, tid) and p.db.task(tid)["not_before"] > time.time() + 200, "it sleeps on, no busy loop"
    # A gate that is more than the clock is still raised past the cap.
    tid = _due_waiting_task(p, f'test "$(date +%s)" -ge {ahead} && exit 1', since_ago=6 * 3600 + 60)
    _settle_probe(d, tid)
    p.db.update_task(tid, not_before=time.time() - 1)
    d.probe_waiting()
    assert p.db.q("SELECT id FROM events WHERE task=? AND kind='wait_stale'", (tid,))


def test_blocker_sweep_carries_a_valid_not_yet_due_still_blocked_forward_until_the_item_changes(env):
    p = make(env)
    from ttp import coordinator as coord, sweep
    db, cfg, now = p.db, p.config(), time.time()
    a, b = db.add_task("waits on a repair"), db.add_task("no outcome yet")
    for t in (a, b):
        db.update_task(t, status="blocked", blocked_reason="r")
    sweep.start(db, cfg, "every 6h", now - 7 * 3600)
    db.x("UPDATE events SET status='handled'")
    assert coord.apply(p, [{"type": "sweep", "id": a, "outcome": "still_blocked", "until_probe": "test -e /x",
                            "start_after": "2d"}]) == []
    eid = sweep.start(db, cfg, "every 6h", now)
    state = db.kv(sweep.STATE_KEY)
    assert state["carried"] == [f"task:{a}"] and f"task:{a}" not in state["flags"]
    assert "1 carried forward" in db.one("SELECT text FROM events WHERE id=?", (eid,))["text"]
    assert "CARRIED (no action)" in coord.digest(p, {}, [eid], [])
    text = "\n".join(sweep.digest_lines(db, [eid], now))
    [line_a] = [ln for ln in text.splitlines() if ln.startswith(f"- #{a} ")]
    assert "CARRIED (no action)" in line_a and "until test -e /x" in line_a and "FLAG" not in line_a
    assert "CARRIED" not in next(ln for ln in text.splitlines() if ln.startswith(f"- #{b} "))
    # The header names the start_after format and both required still_blocked fields.
    assert "1 CARRIED" in text and "per item not marked CARRIED" in text
    assert "both required" in text and "AND `start_after`" in text and "2026-10-05T09:00" in text
    # The next sweep carries it again, without a flag for "no outcome at the last sweep".
    db.x("UPDATE events SET status='handled'")
    sweep.start(db, cfg, "every 6h", now + 7 * 3600)
    assert db.kv(sweep.STATE_KEY)["carried"] == [f"task:{a}"]
    assert f"task:{a}" not in db.kv(sweep.STATE_KEY)["flags"]
    # An interval sweep where every item is carried is skipped.
    db.update_task(b, status="done")
    db.x("UPDATE events SET status='handled'")
    assert sweep.due(db, cfg, now + 14 * 3600) is None
    # A changed item (new reason) needs a fresh outcome.
    db.update_task(a, blocked_reason="a different reason")
    assert sweep.due(db, cfg, now + 14 * 3600) == "every 6h"
    sweep.start(db, cfg, "every 6h", now + 14 * 3600)
    assert db.kv(sweep.STATE_KEY)["carried"] == []
    assert db.kv(sweep.STATE_KEY)["flags"] == {f"task:{a}": "no outcome at the last sweep"}


